/// Ensure git/claude hook files are executable. Called from scaffolder
/// write paths so freshly-scaffolded hooks don't trigger git's "hook was
/// ignored because not executable" warning.
/// trace:BUG-21 | ai:claude
fn ensure_executable_if_hook(rel_path: &std::path::Path, full_path: &std::path::Path) {
    let s = rel_path.to_string_lossy();
    let is_hook =
        s.starts_with(".git/hooks/") || s.starts_with(".claude/hooks/") || s.ends_with(".sh");
    if !is_hook {
        return;
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        if let Ok(meta) = std::fs::metadata(full_path) {
            let mut p = meta.permissions();
            p.set_mode(0o755);
            let _ = std::fs::set_permissions(full_path, p);
        }
    }
    #[cfg(not(unix))]
    {
        let _ = full_path; // no-op on non-unix
    }
}

/// Resolve the description from one of three sources: inline `--description`,
/// `--description-from-file PATH`, or `--description-stdin`. The CLI struct
/// already enforces mutual exclusion via `conflicts_with_all`; here we just
/// fetch the content from the right source. Returns `Ok(None)` when no
/// source is set (caller falls back to empty / interactive prompt).
/// trace:BUG-17 | ai:claude
fn resolve_description(
    description: &Option<String>,
    description_from_file: &Option<std::path::PathBuf>,
    description_stdin: bool,
) -> Result<Option<String>> {
    if let Some(d) = description {
        return Ok(Some(d.clone()));
    }
    if let Some(path) = description_from_file {
        let body = std::fs::read_to_string(path)
            .with_context(|| format!("failed to read description from {}", path.display()))?;
        return Ok(Some(body));
    }
    if description_stdin {
        use std::io::Read;
        let mut body = String::new();
        std::io::stdin()
            .read_to_string(&mut body)
            .context("failed to read description from stdin")?;
        return Ok(Some(body));
    }
    Ok(None)
}

pub(crate) fn parse_requirement_type(s: &str) -> Result<RequirementType> {
    match s.to_lowercase().as_str() {
        "functional" | "fr" => Ok(RequirementType::Functional),
        "non-functional" | "nonfunctional" | "nfr" => Ok(RequirementType::NonFunctional),
        "system" | "sr" => Ok(RequirementType::System),
        "user" | "ur" => Ok(RequirementType::User),
        // Workflow type: a proposed change. trace:TASK-716 | ai:claude
        "change-request" | "changerequest" | "change" | "cr" => Ok(RequirementType::ChangeRequest),
        "bug" => Ok(RequirementType::Bug),
        "epic" => Ok(RequirementType::Epic),
        "story" => Ok(RequirementType::Story),
        "task" => Ok(RequirementType::Task),
        "spike" => Ok(RequirementType::Spike),
        "sprint" => Ok(RequirementType::Sprint),
        "folder" => Ok(RequirementType::Folder),
        "meta" => Ok(RequirementType::Meta),
        // Docs-layer types (FR-1-074). Aliases match the type prefix used
        // in agreed-id format (`PRIN`, `VIS`, `CON`, `ADR`, `TERM`).
        // trace:FR-1-074 | ai:claude
        "principle" | "prin" => Ok(RequirementType::Principle),
        "vision" | "vis" => Ok(RequirementType::Vision),
        "constraint" | "con" => Ok(RequirementType::Constraint),
        "decision" | "adr" => Ok(RequirementType::Decision),
        "term" | "glossary" => Ok(RequirementType::Term),
        // trace:STORY-104 | ai:claude
        "doc" | "documentation" => Ok(RequirementType::Doc),
        _ => anyhow::bail!("Unknown requirement type: {}", s),
    }
}

#[cfg(test)]
mod parse_requirement_type_tests {
    use super::*;

    /// `--type doc` and `--type documentation` both resolve to
    /// `RequirementType::Doc`. Aliases keep the user-facing surface tolerant
    /// to spell-outs, matching the precedent set by `--type adr`/`decision`.
    /// trace:STORY-104 | ai:claude
    #[test]
    fn parses_doc_aliases() {
        assert_eq!(parse_requirement_type("doc").unwrap(), RequirementType::Doc);
        assert_eq!(parse_requirement_type("DOC").unwrap(), RequirementType::Doc);
        assert_eq!(
            parse_requirement_type("documentation").unwrap(),
            RequirementType::Doc
        );
    }

    /// Drift guard (TASK-716): every `RequirementType` variant must have a
    /// canonical lowercase string that `parse_requirement_type` round-trips.
    /// The `match` below is exhaustive, so adding a new variant to the enum
    /// without wiring it into the CLI parser fails to compile here — keeping
    /// the documented/user-facing type list from silently drifting behind the
    /// model (the 13-vs-19 drift this test was filed to prevent).
    /// trace:TASK-716 | ai:claude
    #[test]
    fn every_requirement_type_variant_round_trips() {
        use aida_core::models::RequirementType::*;
        // One representative variant per arm; the exhaustive match means a new
        // enum variant forces a compile error until it is added here.
        let all = [
            Functional,
            NonFunctional,
            System,
            User,
            ChangeRequest,
            Bug,
            Epic,
            Story,
            Task,
            Spike,
            Sprint,
            Folder,
            Meta,
            Principle,
            Vision,
            Constraint,
            Decision,
            Term,
            Doc,
        ];
        assert_eq!(all.len(), 19, "RequirementType is expected to have 19 variants; update docs (CLAUDE.md, --type help, MCP schema) and this guard when it changes");
        // Exhaustiveness check: maps each variant to its canonical CLI token.
        // The compiler enforces every variant is covered.
        for variant in all {
            let token = match &variant {
                Functional => "functional",
                NonFunctional => "non-functional",
                System => "system",
                User => "user",
                ChangeRequest => "change-request",
                Bug => "bug",
                Epic => "epic",
                Story => "story",
                Task => "task",
                Spike => "spike",
                Sprint => "sprint",
                Folder => "folder",
                Meta => "meta",
                Principle => "principle",
                Vision => "vision",
                Constraint => "constraint",
                Decision => "decision",
                Term => "term",
                Doc => "doc",
            };
            assert_eq!(
                parse_requirement_type(token).unwrap(),
                variant,
                "type token {token:?} must parse back to its variant"
            );
        }
    }
}

/// Initialize distributed mode using an orphan branch + worktree.
/// This is the default for single-repo projects.
/// Store lives at .aida-store/ (worktree of orphan branch 'aida-store').
/// BUG-446 / TASK-686: immediate-child directories of `cwd` that are their OWN
/// project — a nested git repo (a `.git` directory, or a `.git` file =
/// gitlink/submodule worktree) OR an AIDA project (a child `.aida/` dir) — and
/// are NOT registered submodules. A non-empty result means `cwd` is a
/// workspace-/parent-of-projects, not a single project.
///
/// We deliberately test for a child's own `.git`/`.aida` entry rather than
/// calling `git_ops::is_git_repo` (which shells out to `git rev-parse`): from
/// inside `cwd` — itself a git repo by the time this runs — `rev-parse`
/// resolves to `cwd`'s git-dir for EVERY subdirectory, so it would flag plain
/// subdirs too. Dotted children (`.git`, `.aida-store`, …) and
/// `.gitmodules`-declared submodules are intentional and excluded.
///
/// TASK-686 added the child-`.aida/` arm: a parent of AIDA projects that aren't
/// all plain git repos (the `~/ai/` case — ~80 children) would otherwise slip
/// the guard and leave a scaffold every child inherits via ancestor CLAUDE.md.
/// trace:BUG-446 trace:TASK-686 | ai:claude
fn unmanaged_nested_projects(cwd: &std::path::Path) -> Vec<String> {
    let submodule_paths = gitmodule_child_paths(cwd);
    let mut found = Vec::new();
    let Ok(entries) = std::fs::read_dir(cwd) else {
        return found;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().to_string();
        if name.starts_with('.') || submodule_paths.contains(&name) {
            continue;
        }
        if path.join(".git").exists() || path.join(".aida").is_dir() {
            found.push(name);
        }
    }
    found.sort();
    found
}

/// First path component of each `path = …` entry in the top-level `.gitmodules`
/// — enough to exclude an immediate-child submodule directory from the
/// workspace-of-projects guard. trace:BUG-446 | ai:claude
fn gitmodule_child_paths(cwd: &std::path::Path) -> std::collections::HashSet<String> {
    let mut paths = std::collections::HashSet::new();
    let Ok(content) = std::fs::read_to_string(cwd.join(".gitmodules")) else {
        return paths;
    };
    for line in content.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("path") {
            if let Some(value) = rest.split('=').nth(1) {
                if let Some(first) = value.trim().split('/').next() {
                    if !first.is_empty() {
                        paths.insert(first.to_string());
                    }
                }
            }
        }
    }
    paths
}

/// What to do when `aida init` runs in a directory that isn't a git repo yet.
/// trace:STORY-552 | ai:claude
#[derive(Debug, PartialEq, Eq)]
enum GitInitDecision {
    /// Run `git init` without asking (explicit `--git-init`).
    Yes,
    /// Offer interactively (TTY, no flag).
    Prompt,
    /// Keep the safe bail+recipe (non-interactive, no flag — don't
    /// silently git-init in scripts).
    Bail,
}

/// Decide how to handle a non-git folder at the front of init. `--git-init`
/// always wins; otherwise prompt at a TTY and bail elsewhere. Pure so it can be
/// unit-tested without a terminal. trace:STORY-552 | ai:claude
fn git_init_decision(git_init_flag: bool, at_tty: bool) -> GitInitDecision {
    if git_init_flag {
        GitInitDecision::Yes
    } else if at_tty {
        GitInitDecision::Prompt
    } else {
        GitInitDecision::Bail
    }
}

#[allow(clippy::too_many_arguments)]
fn handle_init_distributed_worktree(
    force: bool,
    no_skills: bool,
    agent: &str,
    no_hooks: bool,
    verbose: bool,
    name: Option<&str>,
    git_init: bool,
    // BUG-570: forwarded to the bootstrap-clone path so `--commit-scaffold`
    // can opt into a deliberate scaffold commit on a clone. trace:BUG-570
    commit_scaffold: bool,
    // STORY-652: friendly node name for the auto-acquire at init time. None →
    // computed default (`<host>-<user>-<seq>`); at a TTY we prompt with the
    // default pre-filled. trace:STORY-652
    node_name: Option<&str>,
) -> Result<()> {
    use aida_core::git_ops;

    let cwd = std::env::current_dir()?;
    let aida_dir = cwd.join(".aida");
    let worktree_dir = ".aida-store";
    let branch_name = "aida-store";

    // STORY-552: complete the onboarding funnel at the FRONT. A new user in a
    // fresh folder who hasn't run `git init` shouldn't have to learn the recipe
    // and re-run init — that blocked first state is confusing. At a TTY, offer
    // to `git init` here; with --git-init, do it non-interactively. Otherwise
    // keep the clean bail+recipe (don't silently git-init in scripts — that's a
    // surprising side effect). The orphan-store machinery's "ensure at least one
    // commit" step below then creates HEAD if the freshly-init'd repo is empty,
    // and the BUG-446 workspace guard still runs AFTER this. trace:STORY-552 | ai:claude
    if !git_ops::is_git_repo(&cwd) {
        let at_tty = std::io::stdin().is_terminal() && std::io::stdout().is_terminal();
        let do_init = match git_init_decision(git_init, at_tty) {
            GitInitDecision::Yes => true,
            GitInitDecision::Bail => false,
            GitInitDecision::Prompt => prompt_yes_no(
                "No git repository here — initialize one with `git init`? [Y/n] ",
                true,
            )
            .unwrap_or(false),
        };

        if do_init {
            git_ops::init(&cwd)?;
            println!("  {} a git repository here", "Created".green());
        } else {
            anyhow::bail!(
                "Not a git repository. Run 'git init' first (or pass --git-init), or use --sibling for a separate repo."
            );
        }
    }

    // BUG-446: refuse to initialize over a workspace-of-projects. A fresh
    // `aida init` (no `.aida/config.toml` yet) whose directory contains nested,
    // non-submodule git repos would capture the whole tree as untracked entries
    // (nested repos becoming gitlinks) and root the orphan store at the
    // workspace level — every `aida` command from a future project subdirectory
    // would then climb UP to this workspace-wide store. Gate on not-yet-init'd
    // so re-running in a set-up project (handled below) keeps its own message;
    // bypass with --force. trace:BUG-446 | ai:claude
    if !force && !aida_dir.join("config.toml").exists() {
        let nested = unmanaged_nested_projects(&cwd);
        if !nested.is_empty() {
            let preview = nested
                .iter()
                .take(5)
                .cloned()
                .collect::<Vec<_>>()
                .join(", ");
            let more = if nested.len() > 5 {
                format!(", … (+{} more)", nested.len() - 5)
            } else {
                String::new()
            };
            anyhow::bail!(
                "This directory looks like a workspace of projects, not a single project: \
                 it contains {} child {} ({}{}).\n\n\
                 `aida init` here would capture the entire tree and root the requirement \
                 store at the workspace level — every `aida` command from a project \
                 subdirectory would then operate on this workspace-wide store, and every \
                 child would inherit this scaffold's CLAUDE.md via ancestor lookup.\n\n\
                 Run `aida init` inside an actual project directory instead, \
                 or pass --force to initialize here anyway.",
                nested.len(),
                if nested.len() == 1 {
                    "project (git repo or AIDA project)"
                } else {
                    "projects (git repos or AIDA projects)"
                },
                preview,
                more,
            );
        }
    }

    // Post-clone detection (EPIC-1-052 Phase 4): if origin already has the
    // aida-store branch and the local worktree is missing, the user just
    // cloned an existing AIDA project. Bootstrap as a clone — fetch the
    // orphan, set up the worktree, run scaffolding, prompt for node id.
    // This wins over the "already initialized" check below because some
    // projects (notably AIDA itself) track .aida/config.toml in main.
    // trace:EPIC-1-052 Phase 4 | ai:claude
    let worktree_present = cwd.join(worktree_dir).exists();
    if !force && !worktree_present && git_ops::remote_branch_exists(&cwd, "origin", branch_name) {
        return handle_init_post_clone(
            &cwd,
            worktree_dir,
            branch_name,
            no_skills,
            agent,
            no_hooks,
            verbose,
            commit_scaffold,
            node_name,
        );
    }

    // Check if already initialized
    if aida_dir.join("config.toml").exists() && !force {
        // TASK-623: don't dead-end at "already initialized" when the store is
        // attached but this clone never acquired its own node id. That happens
        // when a read command auto-attached the worktree (TASK-621) and the
        // user then runs `aida init` to finish setup — or when a clone's
        // node-id step soft-failed (BUG-429). Route back through the post-clone
        // bootstrap, which is idempotent for the already-done parts (worktree
        // present → no-op, scaffolding force=false → skips existing) and runs
        // the node-id setup. Reliable now that node.toml is strictly per-clone
        // (BUG-430): a missing `.aida-store/.aida/node.toml` means no id yet.
        // trace:TASK-623 | ai:claude
        let node_configured = cwd
            .join(worktree_dir)
            .join(".aida")
            .join("node.toml")
            .exists();
        if worktree_present
            && !node_configured
            && git_ops::remote_branch_exists(&cwd, "origin", branch_name)
        {
            eprintln!(
                "{} store is attached but this clone has no node id yet — finishing setup.",
                "Note:".dimmed()
            );
            return handle_init_post_clone(
                &cwd,
                worktree_dir,
                branch_name,
                no_skills,
                agent,
                no_hooks,
                verbose,
                commit_scaffold,
                node_name,
            );
        }
        eprintln!(
            "{} AIDA distributed mode is already initialized (.aida/config.toml exists).",
            "!".yellow()
        );
        eprintln!("  Use {} to reinitialize.", "--force".bold());
        eprintln!("  To refresh just the scaffolding (CLAUDE.md, .claude/skills/, hooks),");
        eprintln!("  use `aida scaffold apply --force` instead — preserves your store.");
        return Ok(());
    }

    // --force on a populated store would silently wipe N requirements and reseed
    // an empty store with just META prompts. Surface that loudly: count what
    // would be lost and require the user to type "reset" to acknowledge.
    if force {
        let existing_store = cwd.join(worktree_dir);
        if let Some(count) = count_requirements_in_store(&existing_store) {
            if count > 0 && !confirm_destructive_reset(count, &existing_store)? {
                return Ok(());
            }
        }
    }

    println!("{}", "Setting up AIDA in this project…".bold());
    println!();

    // Ensure there's at least one commit on main (worktree requires it)
    let has_commits = git_ops::head_sha(&cwd).is_ok();
    if !has_commits {
        // Create an initial commit so worktree can be added
        std::fs::write(cwd.join(".gitkeep"), "")?;
        git_ops::add(&cwd, &[".gitkeep"])?;

        let git_name =
            git_ops::git_config_get("user.name").unwrap_or_else(|_| "AIDA User".to_string());
        let git_email =
            git_ops::git_config_get("user.email").unwrap_or_else(|_| "aida@localhost".to_string());
        git_ops::configure_user(&cwd, &git_name, &git_email)?;
        git_ops::commit(&cwd, "chore: initial commit")?;
    }

    // Create orphan branch + worktree
    let store_path = git_ops::create_store_worktree(&cwd, worktree_dir, branch_name)?;
    // Setup-detail (orphan branch / node id / forge) is plumbing a newcomer
    // doesn't need to see — surface it only under --verbose. trace:TASK-725
    if verbose {
        println!(
            "  {} orphan branch '{}' with worktree at {}",
            "Created".green(),
            branch_name,
            worktree_dir
        );
    }

    // Configure git user in worktree
    let git_name = git_ops::git_config_get("user.name").unwrap_or_else(|_| "AIDA User".to_string());
    let git_email =
        git_ops::git_config_get("user.email").unwrap_or_else(|_| "aida@localhost".to_string());
    git_ops::configure_user(&store_path, &git_name, &git_email)?;

    // Initialize the git backend
    let backend = aida_core::GitBackend::new(&store_path)?;
    let mut store = aida_core::models::RequirementsStore::new();
    // Project name: explicit --name wins; otherwise default to the cwd
    // basename ("/home/joe/projects/tzconv" → "tzconv"). trace:BUG-25
    let project_name = name
        .map(|s| s.to_string())
        .or_else(|| {
            cwd.file_name()
                .and_then(|n| n.to_str())
                .map(|s| s.to_string())
        })
        .unwrap_or_default();
    if !project_name.is_empty() {
        store.name = project_name.clone();
        store.title = project_name;
    }
    seed_meta_requirements(&mut store)?;
    backend.save(&store)?;
    if verbose {
        println!(
            "  {} {}",
            "Created".green(),
            format!("{}/metadata.yaml", worktree_dir).white().bold()
        );
    }

    // Create initial commit on the orphan branch
    git_ops::add(&store_path, &["metadata.yaml"])?;
    std::fs::create_dir_all(store_path.join("objects"))?;
    std::fs::write(store_path.join("objects/.gitkeep"), "")?;
    git_ops::add(&store_path, &["objects/.gitkeep"])?;
    git_ops::add(&store_path, &["objects"])?;
    git_ops::commit(&store_path, "chore: initialize AIDA distributed store")?;

    // Auto-push to origin/<branch_name> if origin exists, so subsequent
    // node-acquire / db-sync work without a manual `git push -u`. Skipped
    // silently when there's no origin (single-machine projects) or when
    // the push fails (offline, auth, etc.) — failure isn't fatal here.
    // trace:BUG-23 trace:TASK-421 | ai:claude
    //
    // BUG-559 root-cause prevention (TASK-844): the orphan-store push below is
    // the FIRST push to a fresh origin. A forge that adopts the first-pushed
    // branch as its default (GitLab's push-to-create) would therefore make the
    // orphan `aida-store` the project default — breaking fresh-clone checkout
    // (the clone checks out the internal YAML store as code). Prevent that two
    // ways, both gated on the origin being EMPTY (a real push-to-create) so we
    // never change behavior for an existing repo:
    //   (a) push the CODE branch (main/master) FIRST, before the orphan store,
    //       so the forge adopts main as default. Guardrail: only when the code
    //       branch exists and has commits (it always does here — init creates an
    //       initial commit above — but the pure `decide_init_push_plan` keeps the
    //       conservative-fallback contract explicit and testable).
    //   (b) after the first real push, explicitly set the remote default branch
    //       to the code branch via the forge API (`gh repo edit` / `glab api`),
    //       belt-and-suspenders for forges/CLIs that don't honor push order.
    // GitHub already defaults to main via repo-create, so (a) is harmless there;
    // (b) is a no-op reassert. Live end-to-end verification against GitHub +
    // GitLab is a manual maintainer step. trace:TASK-844 trace:BUG-559 | ai:claude
    if git_ops::has_remote(&cwd, "origin") {
        // The code branch is the main-repo's current branch (orphan-worktree
        // creation didn't switch it). Push-to-create = origin has no heads yet.
        let code_branch = git_ops::current_branch(&cwd).ok();
        let origin_empty = git_ops::remote_has_no_heads(&cwd, "origin");
        // Init guarantees the code branch carries at least an initial commit by
        // this point, so HEAD resolves; the pure decider still encodes the
        // "must have commits" guardrail explicitly. trace:TASK-844
        let code_branch_has_commits = git_ops::head_sha(&cwd).is_ok();
        let plan = decide_init_push_plan(code_branch.as_deref(), code_branch_has_commits);

        // (a) On an empty origin, push the code branch first so the forge adopts
        //     it as default rather than the orphan store.
        if origin_empty {
            if let InitPushPlan::CodeBranchFirst(cb) = &plan {
                let out = std::process::Command::new("git")
                    .arg("-C")
                    .arg(&cwd)
                    .args(["push", "-u", "origin", cb])
                    .output();
                match out {
                    Ok(o) if o.status.success() => {
                        println!("  {} pushed code branch to origin/{}", "Done".green(), cb);
                    }
                    _ => {
                        eprintln!(
                            "  {} could not push code branch to origin/{} \
                             (run `git push -u origin {}` later)",
                            "Note:".dimmed(),
                            cb,
                            cb
                        );
                    }
                }
            }
        }

        // The orphan-store push (unchanged behavior).
        let push_result = std::process::Command::new("git")
            .arg("-C")
            .arg(&store_path)
            .args(["push", "-u", "origin", branch_name])
            .output();
        match push_result {
            Ok(out) if out.status.success() => {
                println!(
                    "  {} pushed orphan branch to origin/{}",
                    "Done".green(),
                    branch_name
                );
            }
            _ => {
                eprintln!(
                    "  {} could not push orphan branch to origin/{} \
                     (run `git -C {} push -u origin {}` later)",
                    "Note:".dimmed(),
                    branch_name,
                    worktree_dir,
                    branch_name
                );
            }
        }

        // (b) Explicitly assert the forge default branch = the code branch, so
        //     even a forge/CLI that ignores push order ends up correct. Only on
        //     a push-to-create (empty origin) and only when we know the code
        //     branch; best-effort (a missing forge CLI / auth just no-ops).
        if origin_empty {
            if let InitPushPlan::CodeBranchFirst(cb) = &plan {
                let kind = crate::forge::resolve_forge_kind(&cwd);
                let project_ref = crate::forge::origin_url(&cwd)
                    .as_deref()
                    .and_then(crate::forge::project_path_of);
                if let Some(argv) = kind.set_default_branch_cmd(cb, project_ref.as_deref()) {
                    if let Some((prog, args)) = argv.split_first() {
                        let out = std::process::Command::new(prog).args(args).output();
                        if let Ok(o) = out {
                            if o.status.success() {
                                println!("  {} set forge default branch to {}", "Done".green(), cb);
                            }
                        }
                    }
                }
            }
        }
    }

    // Auto-acquire a node id for this clone so nodes.toml has the entry
    // from day one (instead of relying on the implicit-node-1 fallback).
    // Runs whether or not origin exists: when there's no remote, the
    // registration commit lives on the local orphan branch and gets
    // uploaded by the next `aida push`. Without this the solo user can't
    // get their preferred node id (e.g. JM from prefs) without first
    // adding a remote — exactly the kind of friction kernel should hide.
    // trace:EPIC-9 Story 1, BUG-40 | ai:claude
    let has_origin = git_ops::has_remote(&cwd, "origin");
    {
        let hn = hostname();
        // Prefer email from `git config user.email`; fall back to
        // `~/.aida/preferences.toml`. trace:STORY-44 | ai:claude
        let prefs = aida_core::UserPreferences::load().unwrap_or_default();
        let email = git_ops::git_config_get("user.email")
            .ok()
            .or_else(|| prefs.email.clone());

        // STORY-44: try the preferred id first; on collision the kernel's
        // suggest_free_node_id helper picks the next free `<pref><N>` and
        // we auto-accept (init is non-interactive and the alternative is a
        // bad first impression). Without a preference, fall back to the
        // pre-EPIC-9 sequential numeric path.
        let requested_id: Option<String> = match prefs.preferred_node_id.as_deref() {
            Some(pref) => match git_ops::suggest_free_node_id(&store_path, pref) {
                Ok(git_ops::NodeIdProbe::Free) => Some(pref.to_string()),
                Ok(git_ops::NodeIdProbe::Taken { suggested }) => {
                    println!(
                        "  {} preferred node id '{}' is already taken — using '{}' instead",
                        "Note:".dimmed(),
                        pref,
                        suggested
                    );
                    Some(suggested)
                }
                Err(_) => None,
            },
            None => None,
        };

        // STORY-652: capture the owner $USER string + resolve the friendly
        // node name. The seq used for the default-name preview is the
        // requested id when known, else the registry's predicted next id; if
        // the user accepts the default we pass None so core stamps the name
        // with the actually-assigned id. trace:STORY-652 | ai:claude
        let owner_user = current_user_id(None);
        let predicted_seq = requested_id.clone().unwrap_or_else(|| {
            aida_core::node::NodeRegistry::load(&store_path.join("registry").join("nodes.toml"))
                .map(|r| r.next_node_id())
                .unwrap_or_else(|_| "1".to_string())
        });
        let resolved_name = resolve_node_name(node_name, &hn, &owner_user, &predicted_seq)?;
        let default_name = aida_core::node::default_node_name(&hn, &owner_user, &predicted_seq);
        let identity = git_ops::NodeIdentity {
            name: if resolved_name == default_name {
                None
            } else {
                Some(resolved_name)
            },
            user: Some(owner_user.clone()),
        };
        match git_ops::register_node_full_identity(
            &store_path,
            requested_id,
            1,
            &hn,
            email.clone(),
            identity,
        ) {
            Ok(new_id) => {
                let suffix = if has_origin {
                    ""
                } else {
                    " (local; will sync on next `aida push`)"
                };
                if verbose {
                    println!(
                        "  {} acquired node id {} (hostname={}, email={}){}",
                        crate::glyph(crate::glyphs::Glyph::Check).green(),
                        new_id,
                        hn,
                        email.as_deref().unwrap_or("-"),
                        suffix
                    );
                }
                // FR-271: at init time, force the new-project default
                // (Global) explicitly. Reading config.toml here would
                // return PerType because we haven't written the config
                // yet (it's written further down in the init flow).
                if let Ok(blocks) = auto_allocate_initial_blocks_with_scope(
                    &store_path,
                    &new_id,
                    &hn,
                    email.as_deref(),
                    aida_core::IdCounterScope::Global,
                ) {
                    if !blocks.is_empty() && verbose {
                        println!(
                            "  {} auto-allocated {} initial block{}",
                            crate::glyph(crate::glyphs::Glyph::Check).green(),
                            blocks.len(),
                            if blocks.len() == 1 { "" } else { "s" }
                        );
                    }
                }
            }
            Err(e) => {
                eprintln!(
                    "  {} could not auto-acquire node id: {}. Run `aida node acquire` later.",
                    "Note:".dimmed(),
                    e
                );
            }
        }
    }

    // Add .aida-store and runtime shims to .gitignore on main branch.
    // trace:BUG-71 | ai:claude
    add_aida_gitignore_entries(&cwd, worktree_dir)?;

    // Create .aida/config.toml
    std::fs::create_dir_all(&aida_dir)?;
    let config_content = format!(
        "# AIDA distributed mode configuration\n\
         [deployment]\n\
         mode = \"distributed\"\n\
         store_path = \"{}\"\n\
         store_type = \"worktree\"\n\
         branch = \"{}\"\n\
         \n\
         [store.sync]\n\
         # Auto-push store commits after local writes. Values: manual,\n\
         # session-end, per-write, periodic. `periodic` is reserved until\n\
         # aida-worker (EPIC-30) ships.\n\
         auto_push = \"manual\"\n\
         \n\
         # trace:EPIC-1-052 Phase 2 | ai:claude\n\
         # How `aida add` chooses between agreed-id blocks and node-aware ids:\n\
         #   node-aware-only      — never use blocks; always FR-<NODE>-<SEQ>\n\
         #   blocks-then-fallback — try block first; fall through silently (default)\n\
         #   blocks-only          — error if no block is allocated for the type\n\
         #\n\
         # counter_scope (FR-271):\n\
         #   global               — single counter shared across all types (default for new projects)\n\
         #                          → FR-1, BUG-2, EPIC-3, ... ids globally unique by number\n\
         #   per-type             — separate counter per type prefix (legacy default)\n\
         #                          → FR-1, BUG-1, EPIC-1, ... each type starts fresh\n\
         [id_format]\n\
         policy = \"blocks-then-fallback\"\n\
         counter_scope = \"global\"\n\
         \n\
         # trace:TASK-281 | ai:claude\n\
         # Auto-claim a fresh block when aggregate remaining IDs drop below\n\
         # threshold. On by default (threshold 20, size 100). Opt out with:\n\
         #   [block_allocation]\n\
         #   auto_claim = false\n\
         # Per-type override (e.g. larger BUG blocks):\n\
         #   [block_allocation.bug]\n\
         #   auto_claim_threshold = 50\n\
         #   auto_claim_size = 200\n",
        worktree_dir, branch_name
    );
    // EPIC-35: scaffold the [forge] section with the auto-detected provider.
    let config_content = config_content + &forge::init_forge_config_section(&cwd);
    // TASK-304: scaffold the [ultraplan] cadence block (mode = on-demand).
    let config_content = config_content + init_ultraplan_config_section();
    // Commented [intake] example block (defaults are safe; discoverability only).
    // trace:TASK-760 | ai:claude
    let config_content = config_content + init_intake_config_section();
    // STORY-714/TASK-985: warm-pool ON by default (escape hatches documented).
    let config_content = config_content + init_worktree_pool_config_section();
    std::fs::write(aida_dir.join("config.toml"), &config_content)?;

    // STORY-511: surface the auto-detected forge so the operator sees the
    // inference instead of having to read .aida/config.toml. EPIC-35 init UX.
    if verbose {
        let (_, msg) = forge::init_forge_detection_message(&cwd);
        println!(
            "  {} {}",
            crate::glyph(crate::glyphs::Glyph::Check).green(),
            msg
        );
    }

    // Create docs/plans/ for plan archive (per CLAUDE.md convention).
    std::fs::create_dir_all(cwd.join("docs/plans"))?;
    ensure_plan_template_scaffold(&cwd.join("docs/plans"), force)?;

    // Run the shared workflow scaffolding (skills, hooks, mcp, codex).
    let storage_label = format!(
        "{}{}your specs live here (git-tracked, synced with your code)",
        worktree_dir.white().bold(),
        " ".repeat(20),
    );
    complete_init_scaffolding(
        &cwd,
        &store,
        agent,
        no_skills,
        no_hooks,
        force,
        std::path::PathBuf::from(worktree_dir),
        &storage_label,
        verbose,
        // Genuinely-new first-init: commit the scaffolding as before (BUG-570
        // suppression applies only to the bootstrap-clone path).
        false,
    )?;

    // Sharing + teammate onboarding are real, but premature for a solo
    // newcomer with no remote yet — surface them under --verbose (and they're
    // re-surfaced contextually when there IS an origin). trace:TASK-725
    if verbose {
        println!();
        println!("  {}:", "Push code + store together".bold());
        println!(
            "    {}                        push your branch and the spec store in one go",
            "aida push".cyan()
        );
        println!();
        println!("  {}:", "Onboard a teammate".bold());
        println!("    {}    they clone normally", "git clone <repo>".cyan());
        println!(
            "    {}            then `aida init` attaches the shared specs automatically",
            "aida init".cyan()
        );
    }
    println!();

    Ok(())
}

/// Bootstrap an AIDA clone: the user just `git clone`d a repo whose origin
/// already has the `aida-store` orphan branch, and they're running `aida init`
/// to set the project up locally. We fetch the orphan, attach a worktree,
/// run scaffolding, and prompt for node-id acquisition.
/// trace:EPIC-1-052 Phase 4 | ai:claude
#[allow(clippy::too_many_arguments)]
fn handle_init_post_clone(
    cwd: &std::path::Path,
    worktree_dir: &str,
    branch_name: &str,
    no_skills: bool,
    agent: &str,
    no_hooks: bool,
    verbose: bool,
    // BUG-570: opt-in `--commit-scaffold` to deliberately commit the locally
    // written scaffold files on a clone. Default false → leave them uncommitted
    // so a clone never pushes a scaffold dump to the shared default branch.
    // trace:BUG-570 | ai:claude
    commit_scaffold: bool,
    // STORY-652: friendly node name for the clone's node acquisition. None →
    // computed default; prompted at a TTY. trace:STORY-652
    node_name: Option<&str>,
) -> Result<()> {
    use aida_core::git_ops;

    println!(
        "{} Detected existing AIDA store on origin/{} — bootstrapping clone...",
        "".cyan().bold(),
        branch_name
    );

    // Fetch + create local tracking branch for the orphan — UNLESS the
    // worktree is already attached. A read command may have auto-attached it
    // (TASK-621), which already created the local `aida-store` branch and
    // checked it out; re-fetching `branch:branch` into a checked-out branch
    // errors ("refusing to fetch into branch ... checked out"), and
    // create_store_worktree would no-op anyway. So when `aida init` is
    // re-run on an auto-attached clone to finish node-id setup (TASK-623),
    // skip straight past the worktree steps. trace:TASK-623 | ai:claude
    let store_path = if cwd.join(worktree_dir).exists() {
        cwd.join(worktree_dir)
    } else {
        git_ops::fetch_branch_into_local(cwd, "origin", branch_name)?;
        println!(
            "  {} fetched origin/{} into local {}",
            "Done".green(),
            branch_name,
            branch_name
        );
        let sp = git_ops::create_store_worktree(cwd, worktree_dir, branch_name)?;
        println!(
            "  {} worktree at {} → {}",
            "Done".green(),
            worktree_dir,
            branch_name
        );
        sp
    };

    // Configure git user in the worktree (so future commits attribute correctly)
    let git_name = git_ops::git_config_get("user.name").unwrap_or_else(|_| "AIDA User".to_string());
    let git_email =
        git_ops::git_config_get("user.email").unwrap_or_else(|_| "aida@localhost".to_string());
    git_ops::configure_user(&store_path, &git_name, &git_email)?;

    // Add .aida-store/ and runtime shims to root .gitignore (idempotent).
    // trace:BUG-71 | ai:claude
    if add_aida_gitignore_entries(cwd, worktree_dir)? {
        println!(
            "  {} updated {}",
            "Done".green(),
            ".gitignore".white().bold()
        );
    }

    // Write .aida/config.toml — same contents as a fresh init
    let aida_dir = cwd.join(".aida");
    std::fs::create_dir_all(&aida_dir)?;
    let config_content = format!(
        "# AIDA distributed mode configuration\n\
         [deployment]\n\
         mode = \"distributed\"\n\
         store_path = \"{}\"\n\
         store_type = \"worktree\"\n\
         branch = \"{}\"\n\
         \n\
         [store.sync]\n\
         # Auto-push store commits after local writes. Values: manual,\n\
         # session-end, per-write, periodic. `periodic` is reserved until\n\
         # aida-worker (EPIC-30) ships.\n\
         auto_push = \"manual\"\n\
         \n\
         # trace:EPIC-1-052 Phase 2 | ai:claude\n\
         # How `aida add` chooses between agreed-id blocks and node-aware ids:\n\
         #   node-aware-only      — never use blocks; always FR-<NODE>-<SEQ>\n\
         #   blocks-then-fallback — try block first; fall through silently (default)\n\
         #   blocks-only          — error if no block is allocated for the type\n\
         #\n\
         # counter_scope (FR-271):\n\
         #   global               — single counter shared across all types (default for new projects)\n\
         #                          → FR-1, BUG-2, EPIC-3, ... ids globally unique by number\n\
         #   per-type             — separate counter per type prefix (legacy default)\n\
         #                          → FR-1, BUG-1, EPIC-1, ... each type starts fresh\n\
         [id_format]\n\
         policy = \"blocks-then-fallback\"\n\
         counter_scope = \"global\"\n\
         \n\
         # trace:TASK-281 | ai:claude\n\
         # Auto-claim a fresh block when aggregate remaining IDs drop below\n\
         # threshold. On by default (threshold 20, size 100). Opt out with:\n\
         #   [block_allocation]\n\
         #   auto_claim = false\n\
         # Per-type override (e.g. larger BUG blocks):\n\
         #   [block_allocation.bug]\n\
         #   auto_claim_threshold = 50\n\
         #   auto_claim_size = 200\n",
        worktree_dir, branch_name
    );
    // EPIC-35: scaffold the [forge] section with the auto-detected provider.
    let config_content = config_content + &forge::init_forge_config_section(cwd);
    // TASK-304: scaffold the [ultraplan] cadence block (mode = on-demand).
    let config_content = config_content + init_ultraplan_config_section();
    // Commented [intake] example block (defaults are safe; discoverability only).
    // trace:TASK-760 | ai:claude
    let config_content = config_content + init_intake_config_section();
    // STORY-714/TASK-985: warm-pool ON by default (escape hatches documented).
    let config_content = config_content + init_worktree_pool_config_section();
    std::fs::write(aida_dir.join("config.toml"), &config_content)?;
    println!(
        "  {} {}",
        "Done".green(),
        ".aida/config.toml".white().bold()
    );
    // STORY-511: surface the auto-detected forge (EPIC-35 init UX).
    {
        let (_, msg) = forge::init_forge_detection_message(cwd);
        println!("  {} {}", "Done".green(), msg);
    }

    // docs/plans/ for plan archive (post-clone attach: never overwrite).
    std::fs::create_dir_all(cwd.join("docs/plans"))?;
    ensure_plan_template_scaffold(&cwd.join("docs/plans"), false)?;

    // Run scaffolding (CLAUDE.md, .claude/, hooks, etc.)
    // Load the store via GitBackend just for scaffolding metadata.
    let backend = aida_core::GitBackend::new(&store_path)?;
    let store = backend
        .load()
        .unwrap_or_else(|_| aida_core::models::RequirementsStore::new());
    let storage_label = format!(
        "{}{}your specs live here (git-tracked, synced with your code)",
        worktree_dir.white().bold(),
        " ".repeat(20),
    );
    complete_init_scaffolding(
        cwd,
        &store,
        agent,
        no_skills,
        no_hooks,
        false, // force
        std::path::PathBuf::from(worktree_dir),
        &storage_label,
        verbose,
        // BUG-570: bootstrap-clone → suppress the scaffold commit by default.
        // Only `--commit-scaffold` opts into a deliberate code-branch commit.
        // trace:BUG-570 | ai:claude
        !commit_scaffold,
    )?;

    // Prompt the user to acquire a node id. Auto-allocate happens inside
    // `aida node acquire` per Phase 3; we just wire up the same code path.
    println!();
    println!("{}", "Node identity setup".cyan().bold());
    println!("  This clone needs a unique node id to issue requirement IDs without colliding");
    println!("  with other clones. Acquire one now? (Recommended.)");

    let acquire_now = prompt_yes_no("Acquire a node id for this clone? [Y/n] ", true)?;
    if !acquire_now {
        println!();
        println!(
            "  {} You can run {} later — until then, this clone will share node id 1's namespace.",
            "Note:".yellow().bold(),
            "aida node acquire".cyan()
        );
        return Ok(());
    }

    let hn = hostname();
    // Prefer email from `git config user.email`; fall back to user prefs.
    // trace:STORY-44 | ai:claude
    let prefs = aida_core::UserPreferences::load().unwrap_or_default();
    let email = git_ops::git_config_get("user.email")
        .ok()
        .or_else(|| prefs.email.clone());
    let requested_id: Option<String> = match prefs.preferred_node_id.as_deref() {
        Some(pref) => match git_ops::suggest_free_node_id(&store_path, pref) {
            Ok(git_ops::NodeIdProbe::Free) => Some(pref.to_string()),
            Ok(git_ops::NodeIdProbe::Taken { suggested }) => {
                // Leading newline because this often fires immediately after
                // the user types `y` to the "Acquire? [Y/n] " prompt — without
                // it the Note butts up against the prompt's trailing space.
                println!(
                    "\n  {} preferred node id '{}' is taken — using '{}' instead",
                    "Note:".dimmed(),
                    pref,
                    suggested
                );
                Some(suggested)
            }
            Err(_) => None,
        },
        None => None,
    };
    let id_label = match &requested_id {
        Some(id) => format!("id={}", id),
        None => "next available id".to_string(),
    };
    println!();
    println!(
        "Acquiring node ({}; hostname={}, email={})...",
        id_label,
        hn,
        email.as_deref().unwrap_or("-")
    );
    // STORY-652: owner $USER + friendly node name. trace:STORY-652
    let owner_user = current_user_id(None);
    let predicted_seq = requested_id.clone().unwrap_or_else(|| {
        aida_core::node::NodeRegistry::load(&store_path.join("registry").join("nodes.toml"))
            .map(|r| r.next_node_id())
            .unwrap_or_else(|_| "1".to_string())
    });
    let resolved_name = resolve_node_name(node_name, &hn, &owner_user, &predicted_seq)?;
    let default_name = aida_core::node::default_node_name(&hn, &owner_user, &predicted_seq);
    let identity = git_ops::NodeIdentity {
        name: if resolved_name == default_name {
            None
        } else {
            Some(resolved_name)
        },
        user: Some(owner_user.clone()),
    };
    let new_id = match git_ops::register_node_full_identity(
        &store_path,
        requested_id,
        1, // user_id placeholder — see Phase 1 commit message
        &hn,
        email.clone(),
        identity,
    ) {
        Ok(id) => {
            println!(
                "  {} Acquired node id {} for this clone.",
                "".green().bold(),
                id
            );
            id
        }
        // BUG-429: by here the store worktree is already attached + scaffolded
        // and the onboarding task is enqueued — only node-id acquisition
        // failed (transient registry contention, or an unreachable/rejecting
        // remote). Don't abort the whole clone-init as a hard error with a
        // bare "Error:" that reads as "nothing worked": the clone is usable
        // for reads right now, and only collision-free ID issuance for WRITES
        // needs the node id. Warn, point at the retry, and return Ok —
        // consistent with the auto-acquire path's soft-handling above.
        // trace:BUG-429 | ai:claude
        Err(e) => {
            eprintln!();
            eprintln!(
                "  {} Store attached, but node-id acquisition failed: {}",
                "Warning:".yellow().bold(),
                e
            );
            eprintln!(
                "  The clone is ready to read (list / show / findings / queue). Before issuing"
            );
            eprintln!(
                "  new IDs (`aida add`), run `{}` to claim a collision-free node id.",
                "aida node acquire".cyan()
            );
            eprintln!();
            eprintln!(
                "{} AIDA clone bootstrap complete (node-id pending).",
                "".green().bold()
            );
            return Ok(());
        }
    };

    // Auto-allocate initial blocks for the common types (Phase 3).
    // trace:FR-1-073 | ai:claude
    match auto_allocate_initial_blocks(&store_path, &new_id, &hn, email.as_deref()) {
        Ok(blocks) if !blocks.is_empty() => {
            println!(
                "  Auto-allocated {} block{}: {}",
                blocks.len(),
                if blocks.len() == 1 { "" } else { "s" },
                blocks.join(", ")
            );
        }
        Ok(_) => {}
        Err(e) => {
            eprintln!(
                "  {} Could not auto-allocate initial blocks: {}. \
                 Run `aida db block claim --type <T> --size 100` per type to retry.",
                "Warning:".yellow().bold(),
                e
            );
        }
    }

    println!();
    println!("{} AIDA clone bootstrap complete.", "".green().bold());
    Ok(())
}

/// Read y/n from stdin with a default. Treats empty input as the default,
/// any 'y'/'yes' as true, anything else as false.
fn prompt_yes_no(prompt: &str, default_yes: bool) -> Result<bool> {
    use std::io::Write;
    print!("{}", prompt);
    std::io::stdout().flush()?;
    let mut answer = String::new();
    std::io::stdin().read_line(&mut answer)?;
    let trimmed = answer.trim().to_ascii_lowercase();
    if trimmed.is_empty() {
        return Ok(default_yes);
    }
    Ok(matches!(trimmed.as_str(), "y" | "yes"))
}

/// Initialize distributed mode using a sibling repo.
/// For multi-repo workspaces where multiple code repos share one store.
fn handle_init_distributed_sibling(
    registry_remote: Option<&str>,
    force: bool,
    attach: bool,
    store_path_arg: Option<&str>,
    no_skills: bool,
    agent: &str,
    no_hooks: bool,
    verbose: bool,
    name: Option<&str>,
) -> Result<()> {
    use aida_core::git_ops;

    let cwd = std::env::current_dir()?;
    let aida_dir = cwd.join(".aida");
    // BUG-608/STORY-676: the store is a separate repo at an explicit relative (or
    // absolute) path. `--sibling` defaults it to `../aida-store` — a TRUE SIBLING
    // of the code repo (not nested: a nested store can't be reached by a second
    // repo). `store_rel` is what lands in config.toml (resolved relative to the
    // project root, == cwd here); `store_dir` is its absolute form for git ops.
    // trace:BUG-608 trace:STORY-676 | ai:claude
    let store_rel = store_path_arg.unwrap_or("../aida-store");
    let store_dir = {
        let p = std::path::Path::new(store_rel);
        if p.is_absolute() {
            p.to_path_buf()
        } else {
            cwd.join(p)
        }
    };

    // Check if already initialized
    if aida_dir.join("node.toml").exists() && !force {
        eprintln!(
            "{} AIDA distributed mode is already initialized (.aida/node.toml exists).",
            "!".yellow()
        );
        eprintln!("  Use {} to reinitialize.", "--force".bold());
        eprintln!("  To refresh just the scaffolding (CLAUDE.md, .claude/skills/, hooks),");
        eprintln!("  use `aida scaffold apply --force` instead — preserves your store.");
        return Ok(());
    }

    // --force on a populated store would silently wipe N requirements. Same
    // guard as the worktree path: count + require typed confirmation.
    if force {
        if let Some(count) = count_requirements_in_store(&store_dir) {
            if count > 0 && !confirm_destructive_reset(count, &store_dir)? {
                return Ok(());
            }
        }
    }

    // BUG-610 / STORY-674: decide create-vs-attach-vs-refuse for an existing
    // populated store. The fresh-init path below re-seeds META and
    // `backend.save()`s a new store, which DELETES whatever was there (silent
    // data loss, verified: a second repo's init wiped the first's spec).
    //   --force   → deliberate wipe (guarded above)
    //   --attach  → JOIN the existing shared store (multi-repo): config + cache
    //               only, store untouched. The shared dispenser serializes id
    //               allocation across repos, so no separate node id is needed.
    //   neither   → refuse rather than destroy.
    // trace:BUG-610 trace:STORY-674 | ai:claude
    let existing_count = count_requirements_in_store(&store_dir).unwrap_or(0);
    let mut force = force;
    let mut attaching = attach && existing_count > 0 && !force;
    if existing_count > 0 && !force && !attach {
        let interactive = std::io::stdin().is_terminal() && std::io::stdout().is_terminal();
        if interactive {
            // STORY-675: a store already exists at the target path — instead of a
            // flat refusal, OFFER to join it (the multi-repo case is the common
            // one). Join routes through the STORY-674 attach path; "create new"
            // requires the same typed confirmation as --force. trace:STORY-675
            eprintln!(
                "{} A store already exists at {} with {} requirement(s).",
                "!".yellow(),
                store_dir.display(),
                existing_count
            );
            eprintln!("  Almost certainly a shared store another repo created. What now?");
            eprintln!(
                "  {} [{}] Join it — attach this repo to the existing store (recommended)",
                crate::glyph(crate::glyphs::Glyph::Bullet),
                "j".green().bold()
            );
            eprintln!(
                "  {} [{}] Create new — WIPE and re-initialize ({} requirement(s) lost)",
                crate::glyph(crate::glyphs::Glyph::Bullet),
                "c".red().bold(),
                existing_count
            );
            eprintln!(
                "  {} [{}] Abort (default)",
                crate::glyph(crate::glyphs::Glyph::Bullet),
                "a".bold()
            );
            eprint!("  Choose [j/c/a]: ");
            use std::io::Write;
            let _ = std::io::stderr().flush();
            let mut input = String::new();
            std::io::stdin().read_line(&mut input)?;
            match input.trim().to_lowercase().as_str() {
                "j" | "join" => attaching = true,
                "c" | "create" | "new" => {
                    if !confirm_destructive_reset(existing_count, &store_dir)? {
                        return Ok(());
                    }
                    force = true;
                }
                _ => {
                    eprintln!("Aborted.");
                    return Ok(());
                }
            }
        } else {
            // Non-TTY: never silently overwrite. Refuse with the actionable
            // flags (BUG-610) and abort (non-zero exit, no post-setup).
            eprintln!(
                "{} A store already exists at {} with {} requirement(s).",
                "!".yellow(),
                store_dir.display(),
                existing_count
            );
            eprintln!("  Re-initializing would DELETE them — this is almost certainly a shared");
            eprintln!("  sibling store another repo created. Refusing to overwrite it.");
            eprintln!(
                "  {} To ATTACH this repo to the existing store (multi-repo): re-run with {}.",
                crate::glyph(crate::glyphs::Glyph::Bullet),
                "--attach".bold()
            );
            eprintln!(
                "  {} To WIPE and re-initialize the store: re-run with {}.",
                crate::glyph(crate::glyphs::Glyph::Bullet),
                "--force".bold()
            );
            anyhow::bail!(
                "refused to re-initialize the existing store at {} (pass --attach to join, or --force to wipe)",
                store_dir.display()
            );
        }
    }

    if attaching {
        println!(
            "{}",
            format!("Attaching to existing store at {} ...", store_dir.display()).bold()
        );
        println!();
    } else {
        println!("{}", "Initializing AIDA in distributed mode...".bold());
        println!();

        // Create the local git-backed store directory
        if !store_dir.exists() {
            std::fs::create_dir_all(&store_dir)?;
        }

        // Initialize git repo if not already
        if !git_ops::is_git_repo(&store_dir) {
            git_ops::init(&store_dir)?;
            println!(
                "  {} git repository in {}",
                "Created".green(),
                format!("{store_rel}/").white().bold()
            );
        }
    }

    // STORY-674: attach must NOT touch the shared store. It builds only a
    // minimal in-memory store (project name → scaffolding/CLAUDE.md title) and
    // skips the whole store-write path (configure/remote/seed/save/commit/
    // register). Create builds+seeds+saves a fresh store. Both yield `store`
    // for the shared scaffolding below. trace:STORY-674 | ai:claude
    let store = if attaching {
        let mut s = aida_core::models::RequirementsStore::new();
        let pn = name.map(|s| s.to_string()).or_else(|| {
            std::env::current_dir()
                .ok()
                .and_then(|p| p.file_name().and_then(|n| n.to_str()).map(str::to_string))
        });
        if let Some(pn) = pn {
            if !pn.is_empty() {
                s.name = pn.clone();
                s.title = pn;
            }
        }
        s
    } else {
        // Configure git user from global git config or defaults
        let git_name =
            git_ops::git_config_get("user.name").unwrap_or_else(|_| "AIDA User".to_string());
        let git_email =
            git_ops::git_config_get("user.email").unwrap_or_else(|_| "aida@localhost".to_string());
        git_ops::configure_user(&store_dir, &git_name, &git_email)?;

        // Add remote if specified
        if let Some(remote) = registry_remote {
            // Check if remote already exists
            let has_remote = std::process::Command::new("git")
                .current_dir(&store_dir)
                .args(["remote", "get-url", "origin"])
                .output()
                .map(|o| o.status.success())
                .unwrap_or(false);

            if !has_remote {
                std::process::Command::new("git")
                    .current_dir(&store_dir)
                    .args(["remote", "add", "origin", remote])
                    .output()?;
                println!("  {} remote: {}", "Added".green(), remote.white().bold());
            }
        }

        // Initialize the git backend (creates objects/ and metadata.yaml)
        let backend = aida_core::GitBackend::new(&store_dir)?;
        let mut store = aida_core::models::RequirementsStore::new();
        // Project name from --name or cwd basename. trace:BUG-25 | ai:claude
        let project_name = name
            .map(|s| s.to_string())
            .or_else(|| {
                std::env::current_dir()
                    .ok()
                    .and_then(|p| p.file_name().and_then(|n| n.to_str()).map(str::to_string))
            })
            .unwrap_or_default();
        if !project_name.is_empty() {
            store.name = project_name.clone();
            store.title = project_name;
        }
        seed_meta_requirements(&mut store)?;
        backend.save(&store)?;
        println!(
            "  {} {}",
            "Created".green(),
            format!("{store_rel}/metadata.yaml").white().bold()
        );
        println!(
            "  {} {}",
            "Created".green(),
            format!("{store_rel}/objects/").white().bold()
        );

        // Create initial commit
        git_ops::add(&store_dir, &["metadata.yaml"])?;
        std::fs::create_dir_all(store_dir.join("objects"))?;
        // Create a .gitkeep so objects/ is tracked
        std::fs::write(store_dir.join("objects/.gitkeep"), "")?;
        git_ops::add(&store_dir, &["objects/.gitkeep"])?;

        // Create .gitignore for node-local files
        let gitignore_content = "# Node-local state (not shared)\n.aida/\n*.lock\n";
        std::fs::write(store_dir.join(".gitignore"), gitignore_content)?;
        git_ops::add(&store_dir, &[".gitignore"])?;

        git_ops::commit(&store_dir, "chore: initialize AIDA distributed store")?;

        // If we have a remote, push the initial commit and register the node
        if registry_remote.is_some() {
            let branch = git_ops::current_branch(&store_dir).unwrap_or_else(|_| "main".to_string());

            // Push initial commit
            match git_ops::push(&store_dir, "origin", &branch) {
                Ok(true) => {
                    println!("  {} initial commit to remote", "Pushed".green(),);
                }
                Ok(false) => {
                    // Remote has content — pull first then push
                    git_ops::pull_rebase(&store_dir, "origin", &branch)?;
                    git_ops::push(&store_dir, "origin", &branch)?;
                    println!("  {} with remote and pushed", "Synced".green(),);
                }
                Err(e) => {
                    eprintln!("  {} Failed to push to remote: {}", "Warning:".yellow(), e);
                    eprintln!(
                        "  You can push later with: cd {} && git push -u origin {}",
                        store_rel, branch
                    );
                }
            }

            // Register this node
            let hostname = hostname::get()
                .map(|h| h.to_string_lossy().to_string())
                .unwrap_or_else(|_| "unknown".to_string());

            match git_ops::register_node(&store_dir, 1, &hostname) {
                Ok(node_id) => {
                    println!(
                        "  {} node {} ({})",
                        "Registered".green(),
                        node_id.to_string().white().bold(),
                        hostname
                    );
                }
                Err(e) => {
                    eprintln!("  {} Node registration failed: {}", "Warning:".yellow(), e);
                    eprintln!("  You can register later when the remote is available.");
                }
            }
        } else {
            println!();
            println!("  {} No --registry-remote specified.", "Note:".yellow());
            println!("  The store is local-only until you add a remote:");
            println!("    cd {store_rel} && git remote add origin <url>");
            println!("    aida init --distributed --registry-remote <url>");
        }
        store
    };

    // Create .aida/ config in the project root (not the store)
    std::fs::create_dir_all(&aida_dir)?;
    let config_content = format!(
        "# AIDA distributed mode configuration\n\
         [deployment]\n\
         mode = \"distributed\"\n\
         # STORY-676: a separate store repo at this path (relative to the project\n\
         # root, or absolute); code repos pointing at the same path share a store.\n\
         store_path = \"{store_rel}\"\n\
         store_type = \"sibling\"\n\
         \n"
    ) + "[store.sync]\n\
         # Auto-push store commits after local writes. Values: manual,\n\
         # session-end, per-write, periodic. `periodic` is reserved until\n\
         # aida-worker (EPIC-30) ships.\n\
         auto_push = \"manual\"\n\
         \n\
         # trace:EPIC-1-052 Phase 2 | ai:claude\n\
         # How `aida add` chooses between agreed-id blocks and node-aware ids:\n\
         #   node-aware-only      — never use blocks; always FR-<NODE>-<SEQ>\n\
         #   blocks-then-fallback — try block first; fall through silently (default)\n\
         #   blocks-only          — error if no block is allocated for the type\n\
         [id_format]\n\
         policy = \"blocks-then-fallback\"\n\
         \n\
         # trace:TASK-281 | ai:claude\n\
         # Auto-claim a fresh block when aggregate remaining IDs drop below\n\
         # threshold. On by default (threshold 20, size 100). Opt out with:\n\
         #   [block_allocation]\n\
         #   auto_claim = false\n\
         # Per-type override (e.g. larger BUG blocks):\n\
         #   [block_allocation.bug]\n\
         #   auto_claim_threshold = 50\n\
         #   auto_claim_size = 200\n";
    // TASK-304: scaffold the [ultraplan] cadence block (mode = on-demand).
    let config_content = config_content.to_string() + init_ultraplan_config_section();
    // Commented [intake] example block (defaults are safe; discoverability only).
    // trace:TASK-760 | ai:claude
    let config_content = config_content + init_intake_config_section();
    // STORY-714/TASK-985: warm-pool ON by default (escape hatches documented).
    let config_content = config_content + init_worktree_pool_config_section();
    std::fs::write(aida_dir.join("config.toml"), &config_content)?;

    // Create docs/plans/ for plan archive (per CLAUDE.md convention).
    std::fs::create_dir_all(cwd.join("docs/plans"))?;
    ensure_plan_template_scaffold(&cwd.join("docs/plans"), force)?;

    // Run the shared workflow scaffolding (skills, hooks, mcp, codex).
    let storage_label = format!(
        "{}{}Git-canonical store (separate store repo at {})",
        format!("{store_rel}/").white().bold(),
        " ".repeat(20),
        store_rel
    );
    complete_init_scaffolding(
        &cwd,
        &store,
        agent,
        no_skills,
        no_hooks,
        force,
        std::path::PathBuf::from("aida-store"),
        &storage_label,
        verbose,
        // Genuinely-new sibling first-init: commit scaffolding as before (no
        // bootstrap-clone path here). trace:BUG-570
        false,
    )?;

    println!();
    if attaching {
        // trace:STORY-674 | ai:claude
        println!(
            "  {} Attached to existing store at {} ({} requirement(s)). Run {} to see them.",
            crate::glyph(crate::glyphs::Glyph::Check).green(),
            store_dir.display(),
            existing_count,
            "aida list".cyan()
        );
    } else {
        println!("  {}:", "Push code + store together".bold());
        println!(
            "    {}                        push your branch and the orphan store in one go",
            "aida push".cyan()
        );
    }
    println!();

    Ok(())
}

/// Get a git config value from the global config.
fn _git_config_get_global(key: &str) -> Result<String> {
    let output = std::process::Command::new("git")
        .args(["config", "--global", key])
        .output()?;
    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        anyhow::bail!("git config {} not set", key)
    }
}

fn handle_server_command(cmd: &ServerCommand, server_addr: Option<&str>) -> Result<()> {
    let server_addr = server_addr.ok_or_else(|| {
        anyhow::anyhow!(
            "Server address required. Use --server flag or set AIDA_SERVER environment variable."
        )
    })?;

    #[cfg(feature = "remote")]
    {
        // Create a tokio runtime for async operations
        let rt = tokio::runtime::Runtime::new()?;

        match cmd {
            ServerCommand::Status => {
                rt.block_on(client::get_server_status(server_addr))?;
            }
            ServerCommand::List {
                status,
                feature,
                limit,
            } => {
                rt.block_on(client::list_requirements(
                    server_addr,
                    status.as_deref(),
                    feature.as_deref(),
                    *limit,
                ))?;
            }
            ServerCommand::Get { id } => {
                rt.block_on(client::get_requirement(server_addr, id))?;
            }
            ServerCommand::Ping => {
                rt.block_on(client::ping_server(server_addr))?;
            }
        }
        Ok(())
    }

    #[cfg(not(feature = "remote"))]
    {
        let _ = cmd; // suppress unused warning
        let _ = server_addr;
        anyhow::bail!(
            "Remote server support is not enabled. \
            Build with: cargo build -p aida-cli --features remote"
        )
    }
}

fn add_requirement_interactive(storage: &Storage) -> Result<()> {
    // Load existing requirements
    let mut store = storage.load()?;

    // Prompt user for requirement details
    let requirement = crate::prompts::prompt_new_requirement(&mut store)?;
    let id = requirement.id;

    // Get prefixes for ID generation
    let feature_prefix = store
        .get_feature_by_name(&requirement.feature)
        .map(|f| f.prefix.clone());
    let type_prefix = store.get_type_prefix(&requirement.req_type);

    // Add the requirement with auto-assigned ID based on configuration
    store.add_requirement_with_id(
        requirement,
        feature_prefix.as_deref(),
        type_prefix.as_deref(),
    );
    storage.save(&store)?;

    // Get the added requirement to show its ID
    let added_req = store
        .get_requirement_by_id(&id)
        .expect("Just added requirement");

    println!("{}", "Requirement added successfully!".green());
    println!("UUID: {}", id);
    if let Some(spec_id) = &added_req.spec_id {
        println!("ID: {}", spec_id.green());
    }

    Ok(())
}

// why: command-dispatch fn whose params mirror distinct CLI flags; bundling into a struct adds indirection without clarifying the call sites.
#[allow(clippy::too_many_arguments)]
fn add_requirement_cli(
    storage: &Storage,
    title: &Option<String>,
    description: &Option<String>,
    status_str: &Option<String>,
    priority_str: &Option<String>,
    type_str: &Option<String>,
    owner: &Option<String>,
    feature: &Option<String>,
    tags_str: &Option<String>,
    prefix: &Option<String>,
    parent: &Option<String>,
    force_parent: bool,
) -> Result<()> {
    // Load existing requirements
    let mut store = storage.load()?;

    // Check required fields
    let title = match title {
        Some(t) => t.clone(),
        None => anyhow::bail!("Title is required. Use --title to specify a title."),
    };

    let description = match description {
        Some(d) => d.clone(),
        None => String::new(),
    };

    // Validate parent exists if specified
    let parent_uuid = if let Some(parent_id) = parent {
        let uuid = parse_requirement_id(parent_id, &store)?;
        // BUG-64: terminal-status guard. Refuse to file a new child
        // under a Completed/Rejected parent unless --force-parent.
        // trace:BUG-64 | ai:claude
        if !force_parent {
            let pr = store
                .get_requirement_by_id(&uuid)
                .ok_or_else(|| anyhow::anyhow!("parent {} not found", parent_id))?;
            if is_terminal_status(&pr.status) {
                anyhow::bail!(
                    "parent {} is {} — adding new children to a closed parent is usually a mistake. \
                     Pass `--force-parent` to override.",
                    pr.spec_id.as_deref().unwrap_or(parent_id),
                    pr.status,
                );
            }
        }
        Some(uuid)
    } else {
        None
    };

    // Create a requirement with basic data
    let mut requirement = Requirement::new(title, description);

    // Set optional fields
    if let Some(status) = status_str {
        requirement.status = parse_status(status)?;
    }

    // TASK-647 (ADR-3): advisor-gate the production of approved+ specs. A
    // non-advisor, non-TTY caller (headless agent, drain/auto capture) can
    // only file `draft`; a requested approved+ status is downgraded with a
    // one-line triage notice. Advisor role or an interactive human is
    // unaffected. trace:TASK-647 | ai:claude
    let intake_downgraded_from =
        if status_requires_advisor_authority(&requirement.status) && !has_advisor_authority() {
            let from = requirement.status;
            requirement.status = RequirementStatus::Draft;
            Some(from)
        } else {
            // BUG-498: an approved+ status that was NOT downgraded means the
            // caller exercised advisor authority — if that authority came from
            // an `AIDA_SESSION_ROLE=advisor` prefix rather than a seated role,
            // nudge them to seat it. trace:BUG-498 | ai:claude
            if status_requires_advisor_authority(&requirement.status) {
                maybe_hint_advisor_seat();
            }
            None
        };

    if let Some(priority) = priority_str {
        requirement.priority = parse_priority(priority)?;
    }

    if let Some(req_type) = type_str {
        requirement.req_type = parse_type(req_type)?;
    }

    // Set owner: use explicit value, AIDA_AUTHOR env var, or system username
    requirement.owner = owner.clone().unwrap_or_else(get_default_author);

    if let Some(feature_val) = feature {
        requirement.feature = feature_val.clone();
    }

    if let Some(tags) = tags_str {
        let tag_set: HashSet<String> = tags
            .split(',')
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect();
        requirement.tags = tag_set;
    }

    // Set prefix override if specified
    if let Some(prefix_val) = prefix {
        requirement
            .set_prefix_override(prefix_val)
            .map_err(|e| anyhow::anyhow!(e))?;
    }

    let id = requirement.id;

    // Get prefixes for ID generation
    let feature_prefix = store
        .get_feature_by_name(&requirement.feature)
        .map(|f| f.prefix.clone());
    let type_prefix = store.get_type_prefix(&requirement.req_type);

    // Add the requirement with auto-assigned ID based on configuration
    store.add_requirement_with_id(
        requirement,
        feature_prefix.as_deref(),
        type_prefix.as_deref(),
    );

    // Add parent relationship if specified.
    //
    // BUG-58: previously stored `(child, Parent, parent)` with
    // bidirectional=false, which is doubly broken:
    //   1. Relationship type is "I am X to target", so Parent on the
    //      child says "I AM the parent of <parent>" — backwards.
    //   2. Without bidirectional=true, the parent never gets the inverse
    //      Parent edge pointing at the child, so `rel list <parent>`
    //      didn't show its new child.
    // Fix: store `Child` on the source (child) pointing at the parent,
    // bidirectional so the parent gets the matching `Parent` edge.
    // Matches the convention already used by the git-canonical add
    // path (FR-215). trace:BUG-58 | ai:claude
    if let Some(parent_id) = parent_uuid {
        store
            .add_relationship(&id, RelationshipType::Child, &parent_id, true)
            .map_err(|e| anyhow::anyhow!("Failed to add parent relationship: {}", e))?;
    }

    storage.save(&store)?;

    // Get the added requirement to show its ID
    let added_req = store
        .get_requirement_by_id(&id)
        .expect("Just added requirement");

    println!("{}", "Requirement added successfully!".green());
    println!("UUID: {}", id);
    if let Some(spec_id) = &added_req.spec_id {
        println!("ID: {}", spec_id.green());
    }

    // TASK-647 (ADR-3): tell the caller their requested status was held for
    // triage. Quiet and non-fatal — the spec is filed, just as draft.
    if let Some(from) = intake_downgraded_from {
        eprintln!(
            "{} filed as {} (requested {} needs advisor authority) — queued for advisor triage.",
            "ℹ".cyan(),
            "draft".yellow(),
            from.to_string().to_lowercase().dimmed()
        );
    }

    // Show parent relationship if created
    if let Some(parent_id_str) = parent {
        println!("Parent: {}", parent_id_str.cyan());
    }

    Ok(())
}

/// TASK-527: match one `--tags` filter token against a spec's tag set, with
/// prefix-glob support. A trailing `*` (`aida:queue:*`) matches any tag starting
/// with the literal prefix, plus the bare prefix without its trailing `:` (so
/// `aida:queue:*` also matches an exact `aida:queue` tag). Without `*` it's the
/// existing exact membership test. Comma-OR composition happens at the caller.
/// trace:TASK-527 | ai:claude
fn tag_filter_matches(filter: &str, tags: &std::collections::HashSet<String>) -> bool {
    if let Some(prefix) = filter.strip_suffix('*') {
        let bare = prefix.strip_suffix(':').unwrap_or(prefix);
        tags.iter().any(|t| t.starts_with(prefix) || t == bare)
    } else {
        tags.contains(filter)
    }
}

#[cfg(test)]
mod task_527_tag_glob_tests {
    use super::*;
    use std::collections::HashSet;

    fn tags(v: &[&str]) -> HashSet<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    /// TASK-527: `prefix:*` matches the surface; exact still works; neither
    /// over-matches a sibling.
    #[test]
    fn prefix_glob_and_exact_filtering() {
        let t = tags(&["aida:queue:work", "aida:status"]);
        assert!(
            tag_filter_matches("aida:queue:*", &t),
            "prefix glob matches leaf"
        );
        assert!(tag_filter_matches("aida:status", &t), "exact still matches");
        assert!(!tag_filter_matches("aida:db:*", &t), "non-matching surface");
        assert!(
            !tag_filter_matches("aida:stat", &t),
            "exact is not substring"
        );

        // `aida:queue:*` also matches an exact bare `aida:queue` tag…
        assert!(tag_filter_matches("aida:queue:*", &tags(&["aida:queue"])));
        // …but the `:*` form does not over-match a sibling surface.
        assert!(!tag_filter_matches(
            "aida:queue:*",
            &tags(&["aida:queuewatch"])
        ));
    }
}

fn list_requirements(
    storage: &Storage,
    status: &Option<String>,
    priority: &Option<String>,
    req_type: &Option<String>,
    feature: &Option<String>,
    tags: &Option<String>,
) -> Result<()> {
    // Load requirements
    let store = storage.load()?;
    let mut requirements = store.requirements;

    // Apply filters if provided
    if let Some(status_str) = status {
        let status_filter = parse_status(status_str)?;
        requirements.retain(|r| r.status == status_filter);
    }

    if let Some(priority_str) = priority {
        let priority_filter = parse_priority(priority_str)?;
        requirements.retain(|r| r.priority == priority_filter);
    }

    if let Some(type_str) = req_type {
        let type_filter = parse_type(type_str)?;
        requirements.retain(|r| r.req_type == type_filter);
    }

    if let Some(feature_str) = feature {
        requirements.retain(|r| r.feature == *feature_str);
    }

    if let Some(tags_str) = tags {
        let tag_filters: Vec<String> = tags_str.split(',').map(|s| s.trim().to_string()).collect();
        requirements.retain(|r| tag_filters.iter().any(|f| tag_filter_matches(f, &r.tags)));
    }

    // Display the requirements
    if requirements.is_empty() {
        println!("{}", "No requirements found.".yellow());
        return Ok(());
    }

    println!(
        "{:<10} | {:<36} | {:<30} | {:<10} | {:<10} | {:<15}",
        "SPEC-ID", "UUID", "Title", "Status", "Priority", "Feature"
    );
    println!("{}", "-".repeat(120));

    for req in requirements {
        let status_str = match req.status {
            RequirementStatus::Draft => "Draft".yellow(),
            RequirementStatus::Approved => "Approved".blue(),
            RequirementStatus::Planned => "Planned".cyan(),
            RequirementStatus::InProgress => "In Progress".magenta(),
            RequirementStatus::Done => "Done".bright_green().bold(),
            RequirementStatus::Completed => "Completed".green(),
            RequirementStatus::Rejected => "Rejected".red(),
            RequirementStatus::NeedsAttention => "Needs Attention".magenta().bold(),
        };

        let priority_str = match req.priority {
            RequirementPriority::High => "High".red(),
            RequirementPriority::Medium => "Medium".yellow(),
            RequirementPriority::Low => "Low".green(),
        };

        let spec_id_display = req.spec_id.as_deref().unwrap_or("-");

        println!(
            "{:<10} | {:<36} | {:<30} | {:<10} | {:<10} | {:<15}",
            spec_id_display,
            req.id.to_string(),
            req.title,
            status_str,
            priority_str,
            req.feature
        );
    }

    Ok(())
}

/// Read the `[external_refs]` provider → base-URL map from `.aida/config.toml`.
///
/// Each line under the section is `provider = "https://..."` (e.g.
/// `linear = "https://linear.app/acme/issue/"`). The project root is the
/// parent of the orphan store path; fall back to `find_project_root()` and
/// finally CWD. Missing file or section yields an empty map (callers then use
/// the built-in defaults — see `aida_core::external_refs::render_ref_url`).
/// Mirrors the line-by-line `read_config_workflow_hints` pattern.
/// trace:STORY-476 | ai:claude
fn read_external_ref_base_urls(
    store_path: &std::path::Path,
) -> std::collections::HashMap<String, String> {
    let project_root = store_path
        .parent()
        .map(|p| p.to_path_buf())
        .or_else(|| find_project_root().ok())
        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
    let config_path = project_root.join(".aida").join("config.toml");
    let mut map = std::collections::HashMap::new();
    let content = match std::fs::read_to_string(&config_path) {
        Ok(c) => c,
        Err(_) => return map,
    };
    let mut in_section = false;
    for raw in content.lines() {
        let line = raw.trim();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if let Some(stripped) = line.strip_prefix('[') {
            in_section = stripped.trim_end_matches(']').trim() == "external_refs";
            continue;
        }
        if in_section {
            if let Some((key, val)) = line.split_once('=') {
                let provider = key.trim().to_ascii_lowercase();
                // Strip a trailing inline `# comment`, then surrounding quotes.
                let v = val
                    .split('#')
                    .next()
                    .unwrap_or("")
                    .trim()
                    .trim_matches('"')
                    .trim_matches('\'')
                    .to_string();
                if !provider.is_empty() && !v.is_empty() {
                    map.insert(provider, v);
                }
            }
        }
    }
    map
}

/// The status to DISPLAY for a requirement. For an EPIC this is the read-only
/// rollup of its children (`derive_epic_status`), so the full-store display
/// surfaces (`aida show`, `aida why`, `aida status`) agree with the cache-backed
/// `aida list`, whose `status` column already holds the derived value. For every
/// non-epic, and for an epic whose only children are Rejected (the derivation
/// declines to auto-reject), this is the stored status.
// trace:BUG-626 | ai:claude
fn effective_display_status(
    store: &aida_core::RequirementsStore,
    req: &aida_core::models::Requirement,
) -> RequirementStatus {
    if req.req_type == RequirementType::Epic {
        if let Some(derived) = aida_core::rollup::derive_epic_status(store, req.id) {
            return derived;
        }
    }
    req.status.clone()
}

fn show_requirement(storage: &Storage, id_str: &str) -> Result<()> {
    // Load requirements first (needed for SPEC-ID lookup)
    let store = storage.load()?;

    // Parse UUID or SPEC-ID
    let id = parse_requirement_id(id_str, &store)?;

    // Find the specified requirement
    let req = store
        .get_requirement_by_id(&id)
        .context("Requirement not found")?;

    // Display the requirement details
    println!("{}: {}", "ID".blue(), req.id);
    if let Some(spec_id) = &req.spec_id {
        println!("{}: {}", "SPEC-ID".blue(), spec_id);
    }
    println!("{}: {}", "Title".blue(), req.title);
    println!("{}: {}", "Description".blue(), req.description);

    // BUG-626: an epic's displayed status is the read-only rollup of its
    // children, not the stored field. trace:BUG-626 | ai:claude
    let display_status = effective_display_status(&store, req);
    let status_str = match display_status {
        RequirementStatus::Draft => "Draft".yellow(),
        RequirementStatus::Approved => "Approved".blue(),
        RequirementStatus::Planned => "Planned".cyan(),
        RequirementStatus::InProgress => "In Progress".magenta(),
        RequirementStatus::Done => "Done".bright_green().bold(),
        RequirementStatus::Completed => "Completed".green(),
        RequirementStatus::Rejected => "Rejected".red(),
        RequirementStatus::NeedsAttention => "Needs Attention".magenta().bold(),
    };
    println!("{}: {}", "Status".blue(), status_str);

    let priority_str = match req.priority {
        RequirementPriority::High => "High".red(),
        RequirementPriority::Medium => "Medium".yellow(),
        RequirementPriority::Low => "Low".green(),
    };
    println!("{}: {}", "Priority".blue(), priority_str);

    let type_str = match req.req_type {
        RequirementType::Functional => "Functional",
        RequirementType::NonFunctional => "Non-Functional",
        RequirementType::System => "System",
        RequirementType::User => "User",
        RequirementType::ChangeRequest => "Change Request",
        RequirementType::Bug => "Bug",
        RequirementType::Epic => "Epic",
        RequirementType::Story => "Story",
        RequirementType::Task => "Task",
        RequirementType::Spike => "Spike",
        RequirementType::Sprint => "Sprint",
        RequirementType::Folder => "Folder",
        RequirementType::Meta => "Meta",
        RequirementType::Principle => "Principle",
        RequirementType::Vision => "Vision",
        RequirementType::Constraint => "Constraint",
        RequirementType::Decision => "Decision",
        RequirementType::Term => "Term",
        RequirementType::Doc => "Doc",
    };
    println!("{}: {}", "Type".blue(), type_str);

    println!("{}: {}", "Owner".blue(), req.owner);
    // STORY-639: render assignee only when set. trace:STORY-639 | ai:claude
    if let Some(assignee) = req.assignee.as_deref() {
        println!("{}: {}", "Assignee".blue(), assignee);
    }
    println!("{}: {}", "Feature".blue(), req.feature);
    println!("{}: {}", "Created".blue(), req.created_at);
    println!("{}: {}", "Modified".blue(), req.modified_at);

    if !req.tags.is_empty() {
        let tags_str = req.tags.iter().cloned().collect::<Vec<_>>().join(", ");
        println!("{}: {}", "Tags".blue(), tags_str);
    }

    if !req.dependencies.is_empty() {
        let deps_str = req
            .dependencies
            .iter()
            .map(|uuid| uuid.to_string())
            .collect::<Vec<_>>()
            .join(", ");
        println!("{}: {}", "Dependencies".blue(), deps_str);
    }

    // STORY-542: user-facing interface changes captured at close — the
    // deterministic source the operator digest reads. trace:STORY-542
    if let Some(ic) = req.interface_changes.as_ref() {
        if !ic.is_empty() {
            println!("\n{}:", "Interface changes".green());
            let surfaces: [(&str, &Vec<String>); 4] = [
                ("CLI", &ic.cli),
                ("MCP", &ic.mcp),
                ("TUI", &ic.tui),
                ("Other", &ic.other),
            ];
            for (label, lines) in surfaces {
                for line in lines {
                    println!("  {} {}", format!("[{label}]").cyan(), line);
                }
            }
        }
    }

    if !req.relationships.is_empty() {
        println!("\n{}:", "Relationships".green());
        for relationship in &req.relationships {
            let target = store.get_requirement_by_id(&relationship.target_id);
            if let Some(target_req) = target {
                let target_spec = target_req.spec_id.as_deref().unwrap_or("N/A");

                // TASK-102: shared phrase mapping (STORY-333 added typed
                // blocked-by/blocks prose; now via `relationship_phrase`).
                let description = relationship_phrase(&relationship.rel_type);

                println!(
                    "  {} {} - {}",
                    description.cyan(),
                    target_spec.yellow(),
                    target_req.title
                );
            } else {
                println!(
                    "  {} {} {}",
                    relationship.rel_type.to_string().cyan(),
                    relationship.target_id.to_string().yellow(),
                    "(not found)".red()
                );
            }
        }
    }

    if !req.comments.is_empty() {
        println!("\n{}:", "Comments".green());
        for comment in &req.comments {
            print_comment(comment, 0);
        }
    }

    if !req.history.is_empty() {
        println!("\n{}:", "History".green());
        for entry in &req.history {
            println!(
                "\n{}:",
                entry
                    .timestamp
                    .with_timezone(&chrono::Local)
                    .format("%Y-%m-%d %H:%M:%S")
                    .to_string()
                    .yellow()
            );
            println!("  {} {}", "By:".dimmed(), entry.author.cyan());
            for change in &entry.changes {
                println!(
                    "  {} {} → {}",
                    change.field_name.magenta(),
                    change.old_value.red(),
                    change.new_value.green()
                );
            }
        }
    }

    Ok(())
}

/// STORY-582: render the durable processing-record audit trail for `aida
/// show`. One block per record: timestamp + agent header, the linkage
/// (PR/commit/brief), the summary, and the decisions / punted / verdict
/// tails when present. trace:STORY-582 | ai:claude
fn print_processing_records(records: &[aida_core::ProcessingRecord]) {
    println!("\n{}:", "Processing record".green().bold());
    for rec in records {
        println!(
            "\n{}  {}",
            rec.timestamp
                .with_timezone(&chrono::Local)
                .format("%Y-%m-%d %H:%M:%S")
                .to_string()
                .yellow(),
            format!("by {}", rec.agent).cyan(),
        );
        // Linkage line — PR / commit / brief, whichever are present.
        let mut linkage: Vec<String> = Vec::new();
        if let Some(pr) = rec.pr {
            linkage.push(format!("PR #{pr}"));
        }
        if let Some(sha) = rec.commit_sha.as_deref() {
            linkage.push(format!("commit {}", &sha[..sha.len().min(8)]));
        }
        if let Some(brief) = rec.brief_ref.as_deref() {
            linkage.push(format!("brief {brief}"));
        }
        if let Some(v) = rec.review_verdict.as_deref() {
            linkage.push(format!("verdict {v}"));
        }
        if !linkage.is_empty() {
            println!(
                "  {} {}",
                crate::glyph(crate::glyphs::Glyph::SubArrow).dimmed(),
                linkage.join(" · ").dimmed()
            );
        }
        println!("  {}", rec.summary);
        for d in &rec.decisions {
            println!("  {} {}", "decision:".magenta(), d);
        }
        for p in &rec.punted {
            println!("  {} {}", "punted:".yellow(), p);
        }
    }
}

/// STORY-582: `aida record list|prune` — inspect or trim the durable
/// processing-record audit trail. List is read-only (backend); prune writes
/// through `Storage::update_atomically`, propose-by-default. trace:STORY-582
fn handle_record_command(
    cmd: &crate::cli::RecordCommand,
    backend: &aida_core::CachedGitBackend,
    store_path: &std::path::Path,
) -> Result<()> {
    use crate::cli::RecordCommand;
    match cmd {
        RecordCommand::List { spec } => {
            let store = backend.load()?;
            let mut shown = 0usize;
            for req in &store.requirements {
                if req.processing_record.is_empty() {
                    continue;
                }
                if let Some(want) = spec {
                    let hit = [req.agreed_id.as_deref(), req.spec_id.as_deref()]
                        .into_iter()
                        .flatten()
                        .any(|s| s.eq_ignore_ascii_case(want));
                    if !hit {
                        continue;
                    }
                }
                println!("{} — {}", req.display_id().cyan().bold(), req.title);
                print_processing_records(&req.processing_record);
                println!();
                shown += 1;
            }
            if shown == 0 {
                match spec {
                    Some(s) => println!("No processing records on {s}."),
                    None => println!("No processing records recorded yet."),
                }
            }
            Ok(())
        }
        RecordCommand::Prune {
            spec,
            older_than,
            apply,
        } => {
            let cutoff =
                older_than.map(|days| chrono::Utc::now() - chrono::Duration::days(days as i64));
            // Pure decision over the loaded store: how many records each
            // matched spec would lose. Reused for the dry-run report and the
            // atomic write so the two never drift.
            let store = backend.load()?;
            let mut plan: Vec<(String, usize, usize)> = Vec::new(); // (id, remove, keep)
            for req in &store.requirements {
                if req.processing_record.is_empty() {
                    continue;
                }
                if let Some(want) = spec {
                    let hit = [req.agreed_id.as_deref(), req.spec_id.as_deref()]
                        .into_iter()
                        .flatten()
                        .any(|s| s.eq_ignore_ascii_case(want));
                    if !hit {
                        continue;
                    }
                }
                let remove = req
                    .processing_record
                    .iter()
                    .filter(|r| cutoff.map(|c| r.timestamp < c).unwrap_or(true))
                    .count();
                if remove > 0 {
                    plan.push((
                        req.display_id(),
                        remove,
                        req.processing_record.len() - remove,
                    ));
                }
            }

            if plan.is_empty() {
                println!("Nothing to prune.");
                return Ok(());
            }

            let total: usize = plan.iter().map(|(_, r, _)| r).sum();
            let window = older_than
                .map(|d| format!("older than {d}d"))
                .unwrap_or_else(|| "all".to_string());
            println!(
                "{} {} processing record(s) across {} spec(s) ({}):",
                if *apply { "Pruning" } else { "Would prune" },
                total,
                plan.len(),
                window
            );
            for (id, remove, keep) in &plan {
                println!("  {id}: −{remove} (keeps {keep})");
            }

            if !*apply {
                println!("\n{}", "Dry run — pass --apply to write.".dimmed());
                return Ok(());
            }

            let storage = Storage::new(store_path);
            let spec_filter = spec.clone();
            storage.update_atomically(|s| {
                for req in &mut s.requirements {
                    if req.processing_record.is_empty() {
                        continue;
                    }
                    if let Some(want) = spec_filter.as_deref() {
                        let hit = [req.agreed_id.as_deref(), req.spec_id.as_deref()]
                            .into_iter()
                            .flatten()
                            .any(|s| s.eq_ignore_ascii_case(want));
                        if !hit {
                            continue;
                        }
                    }
                    let before = req.processing_record.len();
                    req.processing_record
                        .retain(|r| cutoff.map(|c| r.timestamp >= c).unwrap_or(false));
                    if req.processing_record.len() != before {
                        req.modified_at = chrono::Utc::now();
                    }
                }
            })?;
            println!(
                "{} pruned {} record(s).",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                total
            );
            Ok(())
        }
    }
}

// trace:REQ-0232 | ai:claude:high
/// Apply additive (`--add-tag`) and subtractive (`--remove-tag`) tag deltas
/// without disturbing tags the caller didn't name. Empty / whitespace-only
/// entries are ignored. Adding a present tag or removing an absent one is
/// a graceful no-op. Returns whether the set actually changed.
// trace:TASK-351 | ai:claude
pub(crate) fn apply_tag_deltas(
    tags: &mut HashSet<String>,
    add: &[String],
    remove: &[String],
) -> bool {
    let mut changed = false;
    for raw in add {
        let trimmed = raw.trim();
        if !trimmed.is_empty() && tags.insert(trimmed.to_string()) {
            changed = true;
        }
    }
    for raw in remove {
        let trimmed = raw.trim();
        if !trimmed.is_empty() && tags.remove(trimmed) {
            changed = true;
        }
    }
    changed
}

/// Build the loud-on-clobber warning shown when `aida edit --tags` REPLACES the
/// whole tag set. `--tags` is a full replace (other scripts depend on that), so
/// we don't change its semantics — we surface the old→new diff so the caller
/// sees that provenance/routing tags were dropped, and point at the incremental
/// `--add-tag` / `--remove-tag` forms. Returns `None` when the set is unchanged
/// (no warning needed). The returned string is sorted for deterministic output.
/// trace:BUG-545 | ai:claude
pub(crate) fn tags_replace_warning(
    old_tags: &HashSet<String>,
    new_tags: &HashSet<String>,
) -> Option<String> {
    if old_tags == new_tags {
        return None;
    }
    let fmt_set = |s: &HashSet<String>| -> String {
        if s.is_empty() {
            "(none)".to_string()
        } else {
            let mut v: Vec<&String> = s.iter().collect();
            v.sort();
            v.iter().map(|t| t.as_str()).collect::<Vec<_>>().join(",")
        }
    };
    Some(format!(
        "--tags REPLACES all tags (was: {} → now: {}). \
         Use --add-tag/--remove-tag to modify incrementally.",
        fmt_set(old_tags),
        fmt_set(new_tags)
    ))
}

/// Handler for `aida graph <SPEC>` — query the cross-spec relationship graph
/// (blocked-by / blocks chains, epic rollup, reverse impact) on top of the
/// cycle-safe `graph_walk` primitive (TASK-594). Read-only; the flagship
/// "outsmart the flat-markdown spec tools" demo. trace:STORY-489 | ai:claude
#[allow(clippy::too_many_arguments)]
fn handle_graph_command(
    store: &aida_core::RequirementsStore,
    id_str: &str,
    blocked_by: bool,
    blocks: bool,
    tree: bool,
    impact: bool,
    follow: &[String],
    depth: Option<usize>,
    json: bool,
) -> Result<()> {
    use aida_core::graph_walk::{status_rollup, walk_union, Direction};

    let mode_count = [blocked_by, blocks, tree, impact]
        .iter()
        .filter(|b| **b)
        .count()
        + usize::from(!follow.is_empty());
    if mode_count > 1 {
        anyhow::bail!(
            "choose at most one graph mode: --blocked-by, --blocks, --tree, --impact, or --follow"
        );
    }

    let id = parse_requirement_id(id_str, store)?;
    let root = store
        .get_requirement_by_id(&id)
        .context("Requirement not found")?;
    let root_label = root.display_id();
    let root_title = root.title.clone();

    // Resolve mode → (walk specs, label). Default: tree. Each spec is a
    // (rel_types, direction) leg; impact spans two legs so a unidirectionally-
    // stored Blocks edge is still caught (BUG-411).
    type WalkSpecs = Vec<(Vec<RelationshipType>, Direction)>;
    let (specs, mode): (WalkSpecs, &str) = if blocked_by {
        (
            vec![(vec![RelationshipType::BlockedBy], Direction::Outgoing)],
            "blocked-by",
        )
    } else if blocks {
        (
            vec![(vec![RelationshipType::Blocks], Direction::Outgoing)],
            "blocks",
        )
    } else if impact {
        // Blocked by the root = X.BlockedBy→root (incoming BlockedBy) OR
        // root.Blocks→X (outgoing Blocks); a one-directional edge needs both.
        (
            vec![
                (vec![RelationshipType::BlockedBy], Direction::Incoming),
                (vec![RelationshipType::Blocks], Direction::Outgoing),
            ],
            "impact",
        )
    } else if !follow.is_empty() {
        // FR-282: traverse arbitrary named relationship types (custom or
        // built-in), outgoing. from_str maps an unknown name to Custom(name)
        // (BUG-251), so `--follow begets` walks Custom("begets") edges — the
        // query a flat per-feature spec store can't do over custom edges.
        (
            follow
                .iter()
                .map(|t| (vec![RelationshipType::from_str(t)], Direction::Outgoing))
                .collect(),
            "follow",
        )
    } else {
        // BUG-448: the spec hierarchy edge can live on EITHER endpoint, and the
        // rel_type names the TARGET's role (the convention export.rs reads): a
        // parent carries `Child → child`, while a child carries `Parent →
        // parent` (what `aida add --parent` / import write — export.rs
        // set_relationship). Unioning OUTGOING `Child` + `Parent` therefore
        // traverses the hierarchy whichever side recorded the edge, and from any
        // starting node — down via `Child`, up via `Parent` (so a query on a
        // child reaches its epic and back down to its siblings). The
        // visited/seen sets dedup the overlap. trace:BUG-448 | ai:claude
        (
            vec![(
                vec![RelationshipType::Child, RelationshipType::Parent],
                Direction::Outgoing,
            )],
            "tree",
        )
    };
    let is_tree = mode == "tree";

    let result = walk_union(store, id, &specs, depth);

    if json {
        let nodes: Vec<_> = result
            .nodes
            .iter()
            .map(|nid| {
                let r = store.get_requirement_by_id(nid);
                serde_json::json!({
                    "id": r.map(|x| x.display_id()).unwrap_or_else(|| nid.to_string()),
                    "title": r.map(|x| x.title.clone()),
                    "status": r.map(|x| format!("{:?}", x.status)),
                    "resolved": r.is_some(),
                })
            })
            .collect();
        let rollup = status_rollup(store, &result.nodes);
        let out = serde_json::json!({
            "root": root_label,
            "mode": mode,
            "count": result.nodes.len(),
            "nodes": nodes,
            "rollup": {
                "total": rollup.total,
                "completed": rollup.completed,
                "done": rollup.done,
                "in_progress": rollup.in_progress,
                "remaining": rollup.remaining,
                "shelved": rollup.shelved,
                "rejected": rollup.rejected,
            },
        });
        println!("{}", serde_json::to_string_pretty(&out)?);
        return Ok(());
    }

    println!(
        "{} {} {} — {}",
        "Graph".bold(),
        format!("({mode})").dimmed(),
        root_label.cyan().bold(),
        root_title
    );
    if result.nodes.is_empty() {
        println!("  {}", "(no related specs in this direction)".dimmed());
        return Ok(());
    }
    if is_tree {
        // Indented hierarchy so parents, children, and siblings are distinct
        // (BUG-534). tree_layout includes the queried node, rooted at the epic;
        // an arrow marks "you are here" when the query is not the structural root.
        for (nid, depth) in aida_core::graph_walk::tree_layout(id, &result.nodes, &result.edges) {
            let queried = nid == id;
            let lead = if queried {
                match depth {
                    0 => format!("{} ", crate::glyph(crate::glyphs::Glyph::Arrow)).to_string(),
                    d => format!(
                        "{}{} ",
                        "  ".repeat(d - 1),
                        crate::glyph(crate::glyphs::Glyph::Arrow)
                    ),
                }
            } else {
                "  ".repeat(depth)
            };
            match store.get_requirement_by_id(&nid) {
                Some(r) => {
                    let label = if queried {
                        r.display_id().cyan().bold()
                    } else {
                        r.display_id().yellow()
                    };
                    let here = if queried {
                        format!("  {}", "(queried)".dimmed())
                    } else {
                        String::new()
                    };
                    println!("{}{}  {}{}", lead, label, r.title, here);
                }
                None => println!(
                    "{}{}  {}",
                    lead,
                    nid.to_string().yellow(),
                    "(unresolved)".red()
                ),
            }
        }
    } else {
        for nid in &result.nodes {
            match store.get_requirement_by_id(nid) {
                Some(r) => println!("  {}  {}", r.display_id().yellow(), r.title),
                None => println!("  {}  {}", nid.to_string().yellow(), "(unresolved)".red()),
            }
        }
    }
    if is_tree {
        let r = status_rollup(store, &result.nodes);
        let shelved = if r.shelved > 0 {
            format!(" · {} shelved", r.shelved)
        } else {
            String::new()
        };
        let rejected = if r.rejected > 0 {
            format!(" · {} rejected", r.rejected)
        } else {
            String::new()
        };
        println!(
            "\n{} {} total · {} completed · {} in progress · {} remaining{}{}",
            "Rollup:".bold(),
            r.total,
            r.completed,
            r.in_progress,
            r.remaining,
            shelved,
            rejected
        );
    }
    Ok(())
}

/// STORY-439: stamp `complexity:<level>` / `estimated-assistance:<level>`
/// tags on `spec` so the new dimension composes with existing tag tooling
/// (`aida queue list --tag-prefix complexity:`, batch routing). Mirrors
/// `load_store_for_lookup` for backend resolution. Best-effort — a missing
/// store / missing spec / save failure logs and returns; the pickup itself
/// is unaffected. trace:STORY-439 | ai:claude
fn apply_calibration_tags(
    storage: &Storage,
    spec: &str,
    complexity: Option<complexity_calibration::ComplexityLevel>,
    assist_est: Option<complexity_calibration::AssistanceLevel>,
) {
    if complexity.is_none() && assist_est.is_none() {
        return;
    }
    // Git-canonical path — direct backend write, exactly like Command::Edit.
    if let Some(store_path) = detect_distributed_store() {
        if let Ok(backend) = aida_core::GitBackend::new(&store_path) {
            use aida_core::DatabaseBackend;
            let Ok(Some(mut req)) = backend.get_requirement_by_spec_id(spec) else {
                return;
            };
            let mut changed = false;
            if let Some(c) = complexity {
                changed |= complexity_calibration::apply_complexity_tag(&mut req.tags, c);
            }
            if let Some(a) = assist_est {
                changed |= complexity_calibration::apply_assistance_tag(&mut req.tags, a);
            }
            if changed {
                req.modified_at = chrono::Utc::now();
                if let Err(e) = backend.update_requirement(&req) {
                    eprintln!(
                        "  {} could not stamp calibration tags on {spec}: {e}",
                        crate::glyph(crate::glyphs::Glyph::Warning).yellow()
                    );
                }
            }
            return;
        }
    }
    // Legacy fallback — load the whole store, mutate, save. Heavier but
    // only fires on projects that haven't migrated.
    let Ok(mut store) = storage.load() else {
        return;
    };
    let Some(req) = store
        .requirements
        .iter_mut()
        .find(|r| r.spec_id.as_deref() == Some(spec) || r.agreed_id.as_deref() == Some(spec))
    else {
        return;
    };
    let mut changed = false;
    if let Some(c) = complexity {
        changed |= complexity_calibration::apply_complexity_tag(&mut req.tags, c);
    }
    if let Some(a) = assist_est {
        changed |= complexity_calibration::apply_assistance_tag(&mut req.tags, a);
    }
    if changed {
        req.modified_at = chrono::Utc::now();
        if let Err(e) = storage.save(&store) {
            eprintln!(
                "  {} could not save calibration tags on {spec}: {e}",
                crate::glyph(crate::glyphs::Glyph::Warning).yellow()
            );
        }
    }
}

/// STORY-451: stamp `effort:<touchpoint>:<bucket>` while preserving the
/// other effort touchpoints. Best-effort sibling of [`apply_calibration_tags`].
/// trace:STORY-451 | ai:codex
fn apply_effort_tag(
    storage: &Storage,
    spec: &str,
    touchpoint: effort_calibration::EffortTouchpoint,
    effort: Option<effort_calibration::EffortBucket>,
) {
    let Some(effort) = effort else {
        return;
    };
    if let Some(store_path) = detect_distributed_store() {
        if let Ok(backend) = aida_core::GitBackend::new(&store_path) {
            use aida_core::DatabaseBackend;
            let Ok(Some(mut req)) = backend.get_requirement_by_spec_id(spec) else {
                return;
            };
            if effort_calibration::apply_effort_tag(&mut req.tags, touchpoint, effort) {
                req.modified_at = chrono::Utc::now();
                if let Err(e) = backend.update_requirement(&req) {
                    eprintln!(
                        "  {} could not stamp effort tag on {spec}: {e}",
                        crate::glyph(crate::glyphs::Glyph::Warning).yellow()
                    );
                }
            }
            return;
        }
    }
    let Ok(mut store) = storage.load() else {
        return;
    };
    let Some(req) = store
        .requirements
        .iter_mut()
        .find(|r| r.spec_id.as_deref() == Some(spec) || r.agreed_id.as_deref() == Some(spec))
    else {
        return;
    };
    if effort_calibration::apply_effort_tag(&mut req.tags, touchpoint, effort) {
        req.modified_at = chrono::Utc::now();
        if let Err(e) = storage.save(&store) {
            eprintln!(
                "  {} could not save effort tag on {spec}: {e}",
                crate::glyph(crate::glyphs::Glyph::Warning).yellow()
            );
        }
    }
}

#[cfg(test)]
mod apply_tag_deltas_tests {
    use super::apply_tag_deltas;
    use std::collections::HashSet;

    fn set(items: &[&str]) -> HashSet<String> {
        items.iter().map(|s| s.to_string()).collect()
    }

    fn vec(items: &[&str]) -> Vec<String> {
        items.iter().map(|s| s.to_string()).collect()
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn add_inserts_new_tag_and_preserves_others() {
        let mut tags = set(&["a", "b", "c"]);
        let changed = apply_tag_deltas(&mut tags, &vec(&["x"]), &[]);
        assert!(changed);
        assert_eq!(tags, set(&["a", "b", "c", "x"]));
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn remove_drops_named_tag_and_preserves_others() {
        let mut tags = set(&["a", "b", "c"]);
        let changed = apply_tag_deltas(&mut tags, &[], &vec(&["b"]));
        assert!(changed);
        assert_eq!(tags, set(&["a", "c"]));
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn add_and_remove_compose_in_one_call() {
        let mut tags = set(&["a", "b"]);
        let changed = apply_tag_deltas(&mut tags, &vec(&["x", "y"]), &vec(&["a"]));
        assert!(changed);
        assert_eq!(tags, set(&["b", "x", "y"]));
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn adding_present_tag_is_noop() {
        let mut tags = set(&["a", "b"]);
        let changed = apply_tag_deltas(&mut tags, &vec(&["a"]), &[]);
        assert!(!changed);
        assert_eq!(tags, set(&["a", "b"]));
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn removing_absent_tag_is_noop() {
        let mut tags = set(&["a", "b"]);
        let changed = apply_tag_deltas(&mut tags, &[], &vec(&["z"]));
        assert!(!changed);
        assert_eq!(tags, set(&["a", "b"]));
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn whitespace_entries_are_ignored() {
        let mut tags = set(&["a"]);
        let changed = apply_tag_deltas(&mut tags, &vec(&["", "  "]), &vec(&[" "]));
        assert!(!changed);
        assert_eq!(tags, set(&["a"]));
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn entries_are_trimmed() {
        let mut tags = set(&["a"]);
        let changed = apply_tag_deltas(&mut tags, &vec(&["  x  "]), &vec(&[" a "]));
        assert!(changed);
        assert_eq!(tags, set(&["x"]));
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn empty_inputs_make_no_change() {
        let mut tags = set(&["a", "b"]);
        let changed = apply_tag_deltas(&mut tags, &[], &[]);
        assert!(!changed);
        assert_eq!(tags, set(&["a", "b"]));
    }

    // trace:TASK-351 | ai:claude
    #[test]
    fn add_then_remove_same_tag_in_one_call_is_net_zero_if_present() {
        // remove runs after add, so add x + remove x with x absent yields {} change net
        let mut tags = set(&["a"]);
        let changed = apply_tag_deltas(&mut tags, &vec(&["x"]), &vec(&["x"]));
        assert!(changed); // x was inserted then removed — both ops registered changes
        assert_eq!(tags, set(&["a"]));
    }

    // BUG-545: `--add-tag` preserves the existing set (the regression the bug
    // describes: a single-tag edit must NOT clobber provenance/routing tags).
    // trace:BUG-545 | ai:claude
    #[test]
    fn add_tag_preserves_existing_provenance_tags() {
        let mut tags = set(&["from-friction", "papercut", "safety", "aida:edit"]);
        let changed = apply_tag_deltas(&mut tags, &vec(&["supervised"]), &[]);
        assert!(changed);
        // All five present — the original four survive the add.
        assert_eq!(
            tags,
            set(&[
                "from-friction",
                "papercut",
                "safety",
                "aida:edit",
                "supervised"
            ])
        );
    }

    // BUG-545: `--remove-tag` drops only the named tag, leaving the rest intact.
    // trace:BUG-545 | ai:claude
    #[test]
    fn remove_tag_drops_only_named_tag() {
        let mut tags = set(&["from-friction", "papercut", "safety", "supervised"]);
        let changed = apply_tag_deltas(&mut tags, &[], &vec(&["supervised"]));
        assert!(changed);
        assert_eq!(tags, set(&["from-friction", "papercut", "safety"]));
    }
}

#[cfg(test)]
mod tags_replace_warning_tests {
    use super::tags_replace_warning;
    use std::collections::HashSet;

    fn set(items: &[&str]) -> HashSet<String> {
        items.iter().map(|s| s.to_string()).collect()
    }

    // BUG-545: the loud-on-clobber warning fires when `--tags` shrinks a
    // multi-tag set down to one, and shows the old→new diff (sorted).
    // trace:BUG-545 | ai:claude
    #[test]
    fn warns_with_sorted_old_and_new_on_clobber() {
        let old = set(&["papercut", "from-friction", "safety", "aida:edit"]);
        let new = set(&["supervised"]);
        let msg = tags_replace_warning(&old, &new).expect("clobber should warn");
        assert!(
            msg.contains("was: aida:edit,from-friction,papercut,safety"),
            "old set should be listed sorted: {msg}"
        );
        assert!(
            msg.contains("now: supervised"),
            "new set should be listed: {msg}"
        );
        assert!(
            msg.contains("--add-tag/--remove-tag"),
            "warning should point at the incremental flags: {msg}"
        );
    }

    // BUG-545: no warning when the replace is a true no-op (same set).
    // trace:BUG-545 | ai:claude
    #[test]
    fn no_warning_when_set_unchanged() {
        let old = set(&["a", "b"]);
        let new = set(&["b", "a"]);
        assert!(tags_replace_warning(&old, &new).is_none());
    }

    // BUG-545: clearing all tags renders the new set as `(none)`.
    // trace:BUG-545 | ai:claude
    #[test]
    fn empty_new_set_renders_none() {
        let old = set(&["a"]);
        let new: HashSet<String> = HashSet::new();
        let msg = tags_replace_warning(&old, &new).expect("clearing should warn");
        assert!(
            msg.contains("now: (none)"),
            "empty new set is (none): {msg}"
        );
    }
}

/// Edit a requirement non-interactively using CLI flags
// why: command-dispatch fn whose params mirror distinct CLI flags; bundling into a struct adds indirection without clarifying the call sites.
#[allow(clippy::too_many_arguments)]
fn edit_requirement_cli(
    storage: &Storage,
    id_str: &str,
    title: &Option<String>,
    description: &Option<String>,
    status: &Option<String>,
    priority: &Option<String>,
    req_type: &Option<String>,
    owner: &Option<String>,
    feature: &Option<String>,
    tags: &Option<String>,
    // trace:TASK-351 | ai:claude
    add_tag: &[String],
    remove_tag: &[String],
) -> Result<()> {
    // Load requirements
    let store_for_lookup = storage.load()?;
    let id = parse_requirement_id(id_str, &store_for_lookup)?;

    let mut store = storage.load()?;
    let req = store
        .get_requirement_by_id_mut(&id)
        .context("Requirement not found")?;

    let mut changes: Vec<FieldChange> = Vec::new();
    let spec_id = req.spec_id.clone().unwrap_or_else(|| req.id.to_string());

    // Update title
    if let Some(new_title) = title {
        if !new_title.is_empty() && new_title != &req.title {
            changes.push(Requirement::field_change(
                "title",
                req.title.clone(),
                new_title.clone(),
            ));
            req.title = new_title.clone();
        }
    }

    // Update description
    if let Some(new_desc) = description {
        if new_desc != &req.description {
            changes.push(Requirement::field_change(
                "description",
                req.description.clone(),
                new_desc.clone(),
            ));
            req.description = new_desc.clone();
        }
    }

    // Update status
    let mut left_needs_attention = false;
    if let Some(status_str) = status {
        let new_status = match status_str.to_lowercase().as_str() {
            "draft" => RequirementStatus::Draft,
            "approved" => RequirementStatus::Approved,
            "planned" => RequirementStatus::Planned,
            "in_progress" | "in-progress" | "inprogress" => RequirementStatus::InProgress,
            "done" => RequirementStatus::Done,
            "completed" => RequirementStatus::Completed,
            "rejected" => RequirementStatus::Rejected,
            "needs_attention" | "needs-attention" | "needsattention" => {
                RequirementStatus::NeedsAttention
            }
            _ => anyhow::bail!("Invalid status '{}'. Use: draft, approved, planned, in_progress, done, completed, rejected, needs-attention", status_str),
        };
        // STORY-332: enforce the NeedsAttention transition rules here too.
        if let Some(msg) = forbidden_attention_transition(&req.status, &new_status) {
            anyhow::bail!(msg);
        }
        if new_status != req.status {
            // TASK-358: a triage that takes a spec out of NeedsAttention is
            // the trigger for cleaning up any orchestrator-escalated worktree
            // for it. Capture the transition direction before the field
            // changes — the actual cleanup fires after the store save so a
            // failed save doesn't leave a half-cleaned state.
            // trace:TASK-358 | ai:claude
            left_needs_attention = matches!(req.status, RequirementStatus::NeedsAttention)
                && !matches!(new_status, RequirementStatus::NeedsAttention);
            changes.push(Requirement::field_change(
                "status",
                format!("{:?}", req.status),
                format!("{:?}", new_status),
            ));
            req.status = new_status;
        }
    }

    // Update priority
    if let Some(priority_str) = priority {
        let new_priority = match priority_str.to_lowercase().as_str() {
            "high" => RequirementPriority::High,
            "medium" | "med" => RequirementPriority::Medium,
            "low" => RequirementPriority::Low,
            _ => anyhow::bail!(
                "Invalid priority '{}'. Use: high, medium, low",
                priority_str
            ),
        };
        if new_priority != req.priority {
            changes.push(Requirement::field_change(
                "priority",
                format!("{:?}", req.priority),
                format!("{:?}", new_priority),
            ));
            req.priority = new_priority;
        }
    }

    // Update type
    if let Some(type_str) = req_type {
        let new_type = match type_str.to_lowercase().as_str() {
            "functional" | "func" => RequirementType::Functional,
            "non-functional" | "nonfunctional" | "nfr" => RequirementType::NonFunctional,
            "system" | "sys" => RequirementType::System,
            "user" => RequirementType::User,
            "change-request" | "change" | "cr" => RequirementType::ChangeRequest,
            "bug" => RequirementType::Bug,
            "epic" => RequirementType::Epic,
            "story" => RequirementType::Story,
            "task" => RequirementType::Task,
            "spike" => RequirementType::Spike,
            "sprint" => RequirementType::Sprint,
            "folder" => RequirementType::Folder,
            "meta" => RequirementType::Meta,
            // ADR / knowledge-graph family (FR-1-074). trace:TASK-716 | ai:claude
            "principle" | "prin" => RequirementType::Principle,
            "vision" | "vis" => RequirementType::Vision,
            "constraint" | "con" => RequirementType::Constraint,
            "decision" | "adr" => RequirementType::Decision,
            "term" | "glossary" => RequirementType::Term,
            // trace:STORY-104 | ai:claude
            "doc" | "documentation" => RequirementType::Doc,
            _ => anyhow::bail!("Invalid type '{}'. Use: functional, non-functional, system, user, change-request, bug, epic, story, task, spike, sprint, folder, meta, principle, vision, constraint, decision, term, doc", type_str),
        };
        if new_type != req.req_type {
            changes.push(Requirement::field_change(
                "type",
                format!("{:?}", req.req_type),
                format!("{:?}", new_type),
            ));
            req.req_type = new_type;
        }
    }

    // Update owner
    if let Some(new_owner) = owner {
        if new_owner != &req.owner {
            changes.push(Requirement::field_change(
                "owner",
                req.owner.clone(),
                new_owner.clone(),
            ));
            req.owner = new_owner.clone();
        }
    }

    // Update feature
    if let Some(new_feature) = feature {
        if new_feature != &req.feature {
            changes.push(Requirement::field_change(
                "feature",
                req.feature.clone(),
                new_feature.clone(),
            ));
            req.feature = new_feature.clone();
        }
    }

    // Update tags
    if let Some(tags_str) = tags {
        let new_tags: HashSet<String> = tags_str
            .split(',')
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect();
        let old_tags: String = req.tags.iter().cloned().collect::<Vec<_>>().join(", ");
        let new_tags_str: String = new_tags.iter().cloned().collect::<Vec<_>>().join(", ");
        if new_tags != req.tags {
            changes.push(Requirement::field_change("tags", old_tags, new_tags_str));
            req.tags = new_tags;
        }
    }

    // TASK-351: partial tag edits — additive / subtractive variants that
    // don't clobber the rest. `--tags` and `--add-tag`/`--remove-tag` are
    // mutually exclusive at the clap layer, so at most one of the two
    // blocks fires.
    // trace:TASK-351 | ai:claude
    if !add_tag.is_empty() || !remove_tag.is_empty() {
        let old_tags: String = req.tags.iter().cloned().collect::<Vec<_>>().join(", ");
        if apply_tag_deltas(&mut req.tags, add_tag, remove_tag) {
            let new_tags_str: String = req.tags.iter().cloned().collect::<Vec<_>>().join(", ");
            changes.push(Requirement::field_change("tags", old_tags, new_tags_str));
        }
    }

    if changes.is_empty() {
        println!("{} No changes made to {}", "!".yellow(), spec_id);
        return Ok(());
    }

    // Record changes with CLI as author
    req.record_change("CLI".to_string(), changes.clone());

    // Save changes
    storage.save(&store)?;
    println!(
        "{} Updated {} ({} field(s) changed)",
        crate::glyph(crate::glyphs::Glyph::Check).green(),
        spec_id,
        changes.len()
    );

    // TASK-358: triage out of NeedsAttention — clean up any orchestrator-
    // escalated worktree for this spec. The lease's `escalated_to_human`
    // marker (stamped by the `--escalate-blocks` path) is the safety gate:
    // an interactive user session on the same spec, or an
    // `--escalate-defaults` advisor-resume, has the marker absent and is
    // left alone. trace:TASK-358 | ai:claude
    if left_needs_attention {
        if let Ok(project_root) = find_project_root() {
            cleanup_escalated_leases_for_spec(&project_root, &spec_id);
        }
    }

    Ok(())
}

fn edit_requirement_interactive(storage: &Storage, id_str: &str) -> Result<()> {
    // Load requirements first (needed for SPEC-ID lookup)
    let store_for_lookup = storage.load()?;

    // Parse UUID or SPEC-ID
    let id = parse_requirement_id(id_str, &store_for_lookup)?;

    // Load again as mutable
    let mut store = storage.load()?;

    // Find the specified requirement
    let req = store
        .get_requirement_by_id_mut(&id)
        .context("Requirement not found")?;

    // Track changes
    let mut changes: Vec<FieldChange> = Vec::new();
    let _old_req = req.clone();

    println!("Editing requirement: {}", req.title);
    println!("Leave field empty to keep current value");

    // Update title
    let title_prompt = format!("Title [{}]:", req.title);
    if let Ok(new_title) = inquire::Text::new(&title_prompt).prompt() {
        if !new_title.is_empty() && new_title != req.title {
            changes.push(Requirement::field_change(
                "title",
                req.title.clone(),
                new_title.clone(),
            ));
            req.title = new_title;
        }
    }

    // Update description
    println!("Current description:");
    println!("{}", req.description);

    let description_prompt = "New description (leave empty to keep current):";
    if let Ok(new_description) = inquire::Editor::new(description_prompt)
        .with_predefined_text(&req.description)
        .prompt()
    {
        if new_description != req.description {
            changes.push(Requirement::field_change(
                "description",
                req.description.clone(),
                new_description.clone(),
            ));
            req.description = new_description;
        }
    }

    // Update status
    let status_options = vec![
        RequirementStatus::Draft,
        RequirementStatus::Approved,
        RequirementStatus::Planned,
        RequirementStatus::InProgress,
        RequirementStatus::Done,
        RequirementStatus::Completed,
        RequirementStatus::Rejected,
    ];
    if let Ok(new_status) = inquire::Select::new("Status:", status_options).prompt() {
        if new_status != req.status {
            // STORY-332: the picker does not offer NeedsAttention (it is
            // reached only via `aida punt`), but a NeedsAttention spec can
            // still be edited here — enforce the transition rules so it
            // only resolves to Approved / In Progress / Rejected.
            if let Some(msg) = forbidden_attention_transition(&req.status, &new_status) {
                anyhow::bail!(msg);
            }
            changes.push(Requirement::field_change(
                "status",
                format!("{:?}", req.status),
                format!("{:?}", new_status),
            ));
            req.status = new_status;
        }
    }

    // Update priority
    let priority_options = vec![
        RequirementPriority::High,
        RequirementPriority::Medium,
        RequirementPriority::Low,
    ];
    if let Ok(new_priority) = inquire::Select::new("Priority:", priority_options).prompt() {
        if new_priority != req.priority {
            changes.push(Requirement::field_change(
                "priority",
                format!("{:?}", req.priority),
                format!("{:?}", new_priority),
            ));
            req.priority = new_priority;
        }
    }

    // Update owner
    let owner_prompt = format!("Owner [{}]:", req.owner);
    if let Ok(new_owner) = inquire::Text::new(&owner_prompt).prompt() {
        if !new_owner.is_empty() && new_owner != req.owner {
            changes.push(Requirement::field_change(
                "owner",
                req.owner.clone(),
                new_owner.clone(),
            ));
            req.owner = new_owner;
        }
    }

    // Update feature
    let feature_prompt = format!("Feature [{}]:", req.feature);
    if let Ok(new_feature) = inquire::Text::new(&feature_prompt).prompt() {
        if !new_feature.is_empty() && new_feature != req.feature {
            changes.push(Requirement::field_change(
                "feature",
                req.feature.clone(),
                new_feature.clone(),
            ));
            req.feature = new_feature;
        }
    }

    // Get author for history
    let author = inquire::Text::new("Your name (for history):")
        .prompt()
        .unwrap_or_else(|_| String::from("Unknown"));

    // Record changes
    req.record_change(author, changes);

    // Save changes
    storage.save(&store)?;
    println!("{}", "Requirement updated successfully!".green());

    Ok(())
}

fn delete_requirement(storage: &Storage, id_str: &str, skip_confirm: bool) -> Result<()> {
    // Load requirements first (needed for SPEC-ID lookup)
    let store_for_lookup = storage.load()?;

    // Parse UUID or SPEC-ID
    let id = parse_requirement_id(id_str, &store_for_lookup)?;

    // Load again as mutable
    let mut store = storage.load()?;

    // Find the requirement to delete
    let req = store
        .get_requirement_by_id(&id)
        .context("Requirement not found")?;

    // Display requirement info
    println!("{}", "Requirement to delete:".yellow());
    println!("  ID: {}", req.id);
    if let Some(spec_id) = &req.spec_id {
        println!("  SPEC-ID: {}", spec_id);
    }
    println!("  Title: {}", req.title);
    println!("  Description: {}", req.description);

    // Confirm deletion unless --yes flag is used
    if !skip_confirm {
        let confirm = inquire::Confirm::new("Are you sure you want to delete this requirement?")
            .with_default(false)
            .prompt()?;

        if !confirm {
            println!("{}", "Deletion cancelled.".yellow());
            return Ok(());
        }
    }

    // Remove the requirement
    store.requirements.retain(|r| r.id != id);

    // Save changes
    storage.save(&store)?;
    println!("{}", "Requirement deleted successfully!".green());

    Ok(())
}

/// True when a requirement's status means "this work is done — no new
/// children should be filed under it without explicit override". Used by
/// the BUG-64 guard on `aida add --parent` and `aida rel add --type
/// child` to refuse parenting under closed work, and to keep `aida show
/// --tree` / `aida list --parent` views from accumulating mixed-status
/// trees. trace:BUG-64 | ai:claude
pub(crate) fn is_terminal_status(status: &RequirementStatus) -> bool {
    // TASK-741: "terminal" is single-sourced in the lifecycle model so the
    // archive invariant, the BUG-64 parent guard, and the diagram all read the
    // same definition. trace:TASK-741 | ai:claude
    aida_core::lifecycle::State::from_status(status).is_terminal()
}

/// BUG-249: validate that a `queue move` target is actually movable —
/// distinguishing "not in the queue" from "in the queue but terminal".
/// Pure function over `entries`; the handler builds the args from its
/// already-resolved `req`/`entries`/`force` state.
///
/// Returns:
///   - `Err` "is not in the queue" when the target isn't present at all.
///   - `Err` "has terminal status (…) — pass --force …" when present but
///     the spec is Completed/Rejected and `--force` wasn't given.
///   - `Ok(())` otherwise.
///
/// Note: `queue_list(&user_id, /* include_completed */ true)` is the
/// entries we want — terminal entries do linger in the queue file (they
/// just aren't shown in the default `queue list` view), so the
/// in-queue-but-terminal state is real and distinct from the missing-
/// entry state.
/// The epic + its TRANSITIVE descendant UUIDs (children + grandchildren + …),
/// for `aida queue list --epic <ID>`.
///
/// Reuses the same hierarchy closure `aida graph <ID> --tree` walks
/// (`walk_union` over OUTGOING `Child` + `Parent` edges): the spec-hierarchy
/// edge can live on EITHER endpoint (a parent carries `Child → child`; a child
/// carries `Parent → parent`), so unioning both outgoing rel types traverses
/// the tree whichever side recorded the edge. `walk_union` excludes the root,
/// so we re-insert the epic's own UUID — an item queued directly against the
/// epic counts as "under" it.
// trace:TASK-923 | ai:claude (closure rationale: see BUG-448)
fn epic_descendant_uuid_set(
    store: &RequirementsStore,
    epic_id: uuid::Uuid,
) -> std::collections::HashSet<uuid::Uuid> {
    use aida_core::graph_walk::{walk_union, Direction};
    let specs = vec![(
        vec![RelationshipType::Child, RelationshipType::Parent],
        Direction::Outgoing,
    )];
    let result = walk_union(store, epic_id, &specs, None);
    let mut set: std::collections::HashSet<uuid::Uuid> = result.nodes.into_iter().collect();
    set.insert(epic_id);
    set
}

/// Pure filter — keep only the queue entries whose `requirement_id` is in
/// `descendants` (an epic's transitive descendant UUID set from
/// [`epic_descendant_uuid_set`]). Order-preserving; composes cleanly with the
/// role / scope / tag filters that run before it (they all reduce the same
/// `&QueueEntry` slice). An empty `descendants` yields an empty result.
// trace:TASK-923 | ai:claude
fn filter_entries_by_descendant_set<'a>(
    entries: &[&'a aida_core::QueueEntry],
    descendants: &std::collections::HashSet<uuid::Uuid>,
) -> Vec<&'a aida_core::QueueEntry> {
    entries
        .iter()
        .copied()
        .filter(|e| descendants.contains(&e.requirement_id))
        .collect()
}

// Unit coverage for the `aida queue list --epic/--parent` closure and pure
// filter. The closure (`epic_descendant_uuid_set`) must be transitive (epic +
// child + grandchild) and include the epic itself; the pure filter
// (`filter_entries_by_descendant_set`) must keep only in-set entries, compose
// with a prior role filter (it reduces the same already-filtered slice), and
// map an empty descendant set to an empty result.
// trace:TASK-923 | ai:claude
#[cfg(test)]
mod epic_queue_filter_tests {
    use super::{epic_descendant_uuid_set, filter_entries_by_descendant_set};
    use aida_core::models::{Relationship, RelationshipType, RequirementType};
    use aida_core::{QueueEntry, Requirement, RequirementsStore};
    use std::collections::HashSet;
    use uuid::Uuid;

    fn mk_req(spec_id: &str, t: RequirementType) -> Requirement {
        let mut r = Requirement::new(spec_id.to_string(), format!("{spec_id} body"));
        r.spec_id = Some(spec_id.to_string());
        r.req_type = t;
        r
    }

    fn mk_entry(req: Uuid, role: Option<&str>) -> QueueEntry {
        QueueEntry {
            user_id: "alice".to_string(),
            requirement_id: req,
            position: 1000,
            added_by: "alice".to_string(),
            note: None,
            added_at: chrono::Utc::now(),
            for_role: role.map(str::to_string),
            for_scope: None,
            for_session: None,
            added_by_machine: None,
        }
    }

    // Build epic → story (child) → task (grandchild), plus an unrelated task.
    // The hierarchy edge is recorded on BOTH endpoints (Parent on the child,
    // Child on the parent), matching how the store carries it, so the OUTGOING
    // Child+Parent union walk reaches every descendant.
    fn store_epic_tree() -> (RequirementsStore, Uuid, Uuid, Uuid, Uuid) {
        let mut epic = mk_req("EPIC-54", RequirementType::Epic);
        let mut story = mk_req("STORY-100", RequirementType::Story);
        let mut grandchild = mk_req("TASK-200", RequirementType::Task);
        let other = mk_req("TASK-999", RequirementType::Task);

        // epic --Child--> story ; story --Parent--> epic
        epic.relationships.push(Relationship {
            rel_type: RelationshipType::Child,
            target_id: story.id,
            created_at: None,
            created_by: None,
        });
        story.relationships.push(Relationship {
            rel_type: RelationshipType::Parent,
            target_id: epic.id,
            created_at: None,
            created_by: None,
        });
        // story --Child--> grandchild ; grandchild --Parent--> story
        story.relationships.push(Relationship {
            rel_type: RelationshipType::Child,
            target_id: grandchild.id,
            created_at: None,
            created_by: None,
        });
        grandchild.relationships.push(Relationship {
            rel_type: RelationshipType::Parent,
            target_id: story.id,
            created_at: None,
            created_by: None,
        });

        let (eid, sid, gid, oid) = (epic.id, story.id, grandchild.id, other.id);
        let mut store = RequirementsStore::new();
        store.requirements = vec![epic, story, grandchild, other];
        (store, eid, sid, gid, oid)
    }

    #[test]
    fn closure_is_transitive_and_includes_epic_itself() {
        let (store, epic, story, grandchild, other) = store_epic_tree();
        let set = epic_descendant_uuid_set(&store, epic);
        assert!(set.contains(&epic), "epic itself must be in the closure");
        assert!(set.contains(&story), "direct child must be in the closure");
        assert!(
            set.contains(&grandchild),
            "grandchild must be in the transitive closure"
        );
        assert!(
            !set.contains(&other),
            "unrelated spec must be excluded from the closure"
        );
    }

    #[test]
    fn filter_keeps_direct_and_grandchild_excludes_unrelated() {
        let (store, epic, story, grandchild, other) = store_epic_tree();
        let set = epic_descendant_uuid_set(&store, epic);

        let e_epic = mk_entry(epic, None);
        let e_story = mk_entry(story, None);
        let e_grand = mk_entry(grandchild, None);
        let e_other = mk_entry(other, None);
        let entries: Vec<&QueueEntry> = vec![&e_epic, &e_story, &e_grand, &e_other];

        let kept = filter_entries_by_descendant_set(&entries, &set);
        let kept_ids: HashSet<Uuid> = kept.iter().map(|e| e.requirement_id).collect();
        assert_eq!(
            kept.len(),
            3,
            "epic + child + grandchild kept, other dropped"
        );
        assert!(kept_ids.contains(&epic));
        assert!(kept_ids.contains(&story));
        assert!(kept_ids.contains(&grandchild));
        assert!(!kept_ids.contains(&other));
    }

    #[test]
    fn filter_composes_with_a_prior_role_filter() {
        let (store, epic, story, grandchild, _other) = store_epic_tree();
        let set = epic_descendant_uuid_set(&store, epic);

        // story routed to implementer (under epic), grandchild routed to
        // reviewer (under epic). A role pre-filter to "implementer" runs first,
        // exactly as the handler does, then the descendant filter ANDs over it.
        let e_story = mk_entry(story, Some("implementer"));
        let e_grand = mk_entry(grandchild, Some("reviewer"));
        let all: Vec<&QueueEntry> = vec![&e_story, &e_grand];

        let role_filtered: Vec<&QueueEntry> = all
            .iter()
            .copied()
            .filter(|e| e.for_role.as_deref() == Some("implementer"))
            .collect();
        let kept = filter_entries_by_descendant_set(&role_filtered, &set);
        assert_eq!(kept.len(), 1, "only the implementer item under the epic");
        assert_eq!(kept[0].requirement_id, story);
    }

    #[test]
    fn empty_descendant_set_yields_empty_result() {
        let some = Uuid::new_v4();
        let e = mk_entry(some, None);
        let entries: Vec<&QueueEntry> = vec![&e];
        let empty: HashSet<Uuid> = HashSet::new();
        let kept = filter_entries_by_descendant_set(&entries, &empty);
        assert!(kept.is_empty(), "empty descendant set → empty result");
    }
}

// trace:BUG-249 | ai:claude
fn classify_queue_move_target(
    target_id: uuid::Uuid,
    target_display: &str,
    target_status: &RequirementStatus,
    entries: &[aida_core::QueueEntry],
    force: bool,
) -> Result<()> {
    if !entries.iter().any(|e| e.requirement_id == target_id) {
        anyhow::bail!(
            "{} is not in the queue (run `aida queue add {}` first)",
            target_display,
            target_display
        );
    }
    if is_terminal_status(target_status) && !force {
        anyhow::bail!(
            "{} has terminal status ({:?}) — pass --force to move it anyway, or supersede with a new spec",
            target_display,
            target_status,
        );
    }
    Ok(())
}

/// Parse requirement ID - accepts either UUID or SPEC-ID. Used by the legacy
/// SQLite path; the git-canonical dispatch resolves IDs directly via
/// `get_requirement_by_spec_id` and uses `not_found::requirement_not_found`
/// at the call site (with the actual store path).
///
/// trace:FR-1-011 | ai:claude
fn parse_requirement_id(id_str: &str, store: &RequirementsStore) -> Result<Uuid> {
    // Try parsing as UUID first
    if let Ok(uuid) = Uuid::parse_str(id_str) {
        return Ok(uuid);
    }

    // Try as SPEC-ID
    if let Some(req) = store.get_requirement_by_spec_id(id_str) {
        return Ok(req.id);
    }

    // BUG-601: a loaded, non-empty store proves the store IS attached, so the
    // failure is a simply-nonexistent spec — emit the "check the spec ID" hint
    // rather than the misleading "no aida store found / cd into project root"
    // guidance that the None-path variant prints. The store-path isn't threaded
    // through this legacy helper, but store-emptiness is the signal we need:
    // non-empty ⇒ store present (spec-missing), empty ⇒ likely no store / wrong
    // directory (the original common failure mode). trace:BUG-601 | ai:claude
    if store.requirements.is_empty() {
        Err(not_found::requirement_not_found(id_str, None))
    } else {
        Err(not_found::requirement_not_found_in_loaded_store(id_str))
    }
}

fn parse_status(status_str: &str) -> Result<RequirementStatus> {
    match status_str.to_lowercase().as_str() {
        "draft" => Ok(RequirementStatus::Draft),
        "approved" => Ok(RequirementStatus::Approved),
        "planned" => Ok(RequirementStatus::Planned),
        "in_progress" | "in-progress" | "inprogress" => Ok(RequirementStatus::InProgress),
        "done" => Ok(RequirementStatus::Done),
        "completed" => Ok(RequirementStatus::Completed),
        "rejected" => Ok(RequirementStatus::Rejected),
        "needs_attention" | "needs-attention" | "needsattention" => {
            Ok(RequirementStatus::NeedsAttention)
        }
        _ => anyhow::bail!("Invalid status: {}", status_str),
    }
}

pub(crate) fn parse_priority(priority_str: &str) -> Result<RequirementPriority> {
    match priority_str.to_lowercase().as_str() {
        "high" => Ok(RequirementPriority::High),
        "medium" => Ok(RequirementPriority::Medium),
        "low" => Ok(RequirementPriority::Low),
        _ => anyhow::bail!("Invalid priority: {}", priority_str),
    }
}

fn parse_type(type_str: &str) -> Result<RequirementType> {
    match type_str.to_lowercase().as_str() {
        "functional" => Ok(RequirementType::Functional),
        "non-functional" | "nonfunctional" => Ok(RequirementType::NonFunctional),
        "system" => Ok(RequirementType::System),
        "user" => Ok(RequirementType::User),
        "change-request" | "changerequest" | "cr" => Ok(RequirementType::ChangeRequest),
        "bug" => Ok(RequirementType::Bug),
        "epic" => Ok(RequirementType::Epic),
        "story" => Ok(RequirementType::Story),
        "task" => Ok(RequirementType::Task),
        "spike" => Ok(RequirementType::Spike),
        "sprint" => Ok(RequirementType::Sprint),
        "folder" => Ok(RequirementType::Folder),
        "meta" => Ok(RequirementType::Meta),
        // Docs-layer types (FR-1-074). trace:FR-1-074 | ai:claude
        "principle" | "prin" => Ok(RequirementType::Principle),
        "vision" | "vis" => Ok(RequirementType::Vision),
        "constraint" | "con" => Ok(RequirementType::Constraint),
        "decision" | "adr" => Ok(RequirementType::Decision),
        "term" | "glossary" => Ok(RequirementType::Term),
        // trace:STORY-104 | ai:claude
        "doc" | "documentation" => Ok(RequirementType::Doc),
        _ => anyhow::bail!("Invalid requirement type: {}", type_str),
    }
}

/// Handle feature management subcommands
fn handle_feature_command(cmd: &FeatureCommand, storage: &Storage) -> Result<()> {
    // Load existing requirements
    let mut store = storage.load()?;

    match cmd {
        FeatureCommand::Add {
            name,
            prefix,
            interactive,
        } => {
            let should_be_interactive = *interactive || name.is_none() || prefix.is_none();

            if should_be_interactive {
                // Use interactive prompting
                let feature_name = crate::prompts::prompt_new_feature(&mut store)?;
                println!(
                    "{} Feature '{}' created successfully.",
                    crate::glyph(crate::glyphs::Glyph::Check).green(),
                    feature_name
                );
            } else {
                // Use command line arguments
                let name = name
                    .clone()
                    .ok_or_else(|| anyhow::anyhow!("Feature name is required"))?;
                let prefix = prefix
                    .clone()
                    .ok_or_else(|| anyhow::anyhow!("Feature prefix is required"))?;

                // Add feature with prefix to the new system
                let feature = store.add_feature(&name, &prefix)?;
                println!(
                    "{} Feature '{}' created with prefix '{}'.",
                    crate::glyph(crate::glyphs::Glyph::Check).green(),
                    feature.name,
                    feature.prefix
                );
            }

            // Save the updated store
            storage.save(&store)?;
        }
        FeatureCommand::List => {
            // Show both legacy features and new feature definitions
            println!("{}", "Defined Features:".blue().bold());
            println!("{:<10} | {:<10} | {:<30}", "Number", "Prefix", "Name");
            println!("{}", "-".repeat(55));

            if store.features.is_empty() {
                println!("{}", "(No features defined yet)".dimmed());
            } else {
                for feature in &store.features {
                    println!(
                        "{:<10} | {:<10} | {:<30}",
                        feature.number, feature.prefix, feature.name
                    );
                }
            }

            // Also show legacy feature names from requirements
            let legacy_features = store.get_feature_names();
            if !legacy_features.is_empty() {
                println!("\n{}", "Legacy Features (from requirements):".yellow());
                for feature in legacy_features {
                    println!("  - {}", feature);
                }
            }
        }
        FeatureCommand::Show { name } => {
            // Try to find in new feature definitions first
            if let Some(feature) = store
                .get_feature_by_name(name)
                .or_else(|| store.get_feature_by_prefix(name))
            {
                println!("{}: {}", "Feature".blue(), feature.name);
                println!("{}: {}", "Prefix".blue(), feature.prefix);
                println!("{}: {}", "Number".blue(), feature.number);
                if !feature.description.is_empty() {
                    println!("{}: {}", "Description".blue(), feature.description);
                }
            } else {
                // Fall back to legacy feature search
                let features = store.get_feature_names();
                let mut found = false;

                for feature in features {
                    if feature.contains(name) {
                        println!("{}: {}", "Feature".blue(), feature);

                        // Find requirements with this feature
                        println!("\n{}", "Requirements:".blue());
                        let requirements: Vec<&Requirement> = store
                            .requirements
                            .iter()
                            .filter(|r| r.feature == feature)
                            .collect();

                        if requirements.is_empty() {
                            println!("No requirements found with this feature.");
                        } else {
                            println!(
                                "{:<12} | {:<30} | {:<10} | {:<10}",
                                "ID", "Title", "Status", "Priority"
                            );
                            println!("{}", "-".repeat(70));

                            for req in requirements {
                                let spec_id = req.spec_id.as_deref().unwrap_or("-");
                                let status_str = format!("{:?}", req.status);
                                let priority_str = format!("{:?}", req.priority);

                                println!(
                                    "{:<12} | {:<30} | {:<10} | {:<10}",
                                    spec_id,
                                    &req.title[..req.title.len().min(30)],
                                    status_str,
                                    priority_str
                                );
                            }
                        }

                        found = true;
                        break;
                    }
                }

                if !found {
                    println!("{} Feature '{}' not found.", "!".yellow(), name);
                }
            }
        }
        FeatureCommand::Edit {
            name,
            new_name,
            new_prefix,
            interactive,
        } => {
            // Try to find in new feature definitions first
            if let Some(idx) = store.features.iter().position(|f| {
                f.name.to_lowercase() == name.to_lowercase() || f.prefix == name.to_uppercase()
            }) {
                let old_name = store.features[idx].name.clone();
                let old_prefix = store.features[idx].prefix.clone();

                if *interactive || (new_name.is_none() && new_prefix.is_none()) {
                    // Interactive mode
                    let updated_name = inquire::Text::new("New name:")
                        .with_default(&old_name)
                        .prompt()?;
                    let updated_prefix = inquire::Text::new("New prefix:")
                        .with_default(&old_prefix)
                        .prompt()?;

                    store.features[idx].name = updated_name;
                    store.features[idx].prefix = updated_prefix.to_uppercase();
                } else {
                    if let Some(n) = new_name {
                        store.features[idx].name = n.clone();
                    }
                    if let Some(p) = new_prefix {
                        store.features[idx].prefix = p.to_uppercase();
                    }
                }

                storage.save(&store)?;
                println!(
                    "{} Feature updated successfully.",
                    crate::glyph(crate::glyphs::Glyph::Check).green()
                );
            } else {
                // Fall back to legacy feature handling
                let features = store.get_feature_names();
                let mut found = false;

                for feature in features {
                    if feature.contains(name) {
                        let new_feature_name = if *interactive || new_name.is_none() {
                            crate::prompts::prompt_edit_feature(&feature)?
                        } else {
                            let new_name = new_name.clone().unwrap();
                            if let Some((prefix, _)) = feature.split_once('-') {
                                if prefix.parse::<u32>().is_ok() {
                                    format!("{}-{}", prefix, new_name)
                                } else {
                                    new_name
                                }
                            } else {
                                new_name
                            }
                        };

                        store.update_feature_name(&feature, &new_feature_name);
                        storage.save(&store)?;
                        println!(
                            "{} Feature '{}' renamed to '{}'.",
                            crate::glyph(crate::glyphs::Glyph::Check).green(),
                            feature,
                            new_feature_name
                        );
                        found = true;
                        break;
                    }
                }

                if !found {
                    println!("{} Feature '{}' not found.", "!".yellow(), name);
                }
            }
        }
    }

    Ok(())
}

/// Handle ID configuration commands
fn handle_config_command(cmd: &ConfigCommand, storage: &Storage) -> Result<()> {
    let mut store = storage.load()?;

    match cmd {
        ConfigCommand::Show { section } => {
            if let Some(section) = section {
                match section.as_str() {
                    "store.sync" => {
                        let project_root = store_sync_config_project_root(storage);
                        let cfg = read_store_sync_config(&project_root)?;
                        println!("{}", "Store Sync Configuration:".blue().bold());
                        println!("{}: {}", "auto_push".cyan(), cfg.auto_push.as_str());
                        println!(
                            "{}: {}",
                            "periodic_threshold".cyan(),
                            cfg.periodic_threshold
                                .map(|n| n.to_string())
                                .unwrap_or_else(|| "<unset>".to_string())
                        );
                        println!(
                            "{}: {}",
                            "periodic_interval".cyan(),
                            cfg.periodic_interval.as_deref().unwrap_or("<unset>")
                        );
                        println!("{}: {}", "source".cyan(), cfg.source);
                        if cfg.auto_push == StoreAutoPushMode::Periodic {
                            warn_if_periodic_auto_push(&project_root);
                        }
                        return Ok(());
                    }
                    other => {
                        anyhow::bail!("unknown config section `{}` (supported: store.sync)", other)
                    }
                }
            }
            println!("{}", "ID Configuration:".blue().bold());
            println!();

            let format_str = match store.id_config.format {
                IdFormat::SingleLevel => "Single-level (PREFIX-NNN)",
                IdFormat::TwoLevel => "Two-level (FEATURE-TYPE-NNN)",
            };
            println!("{}: {}", "Format".cyan(), format_str);

            let numbering_str = match store.id_config.numbering {
                NumberingStrategy::Global => "Global (one counter for all)",
                NumberingStrategy::PerPrefix => "Per-prefix (separate counter per prefix)",
                NumberingStrategy::PerFeatureType => "Per feature+type combination",
            };
            println!("{}: {}", "Numbering".cyan(), numbering_str);

            println!("{}: {}", "Digits".cyan(), store.id_config.digits);
            println!(
                "{}: {}",
                "Next global number".cyan(),
                store.next_spec_number
            );

            if !store.prefix_counters.is_empty() {
                println!("\n{}", "Prefix Counters:".blue());
                for (prefix, counter) in &store.prefix_counters {
                    println!("  {}: {}", prefix, counter);
                }
            }

            // BUG-533: ID config alone hides the whole effective-policy
            // surface (agent bypass posture, mailbox, advisor, archive,
            // telemetry, intake, presence). Render every known section with
            // its effective value + source so `config show` is the runtime
            // complement to docs/environment-variables.md.
            // trace:BUG-533
            let project_root = store_sync_config_project_root(storage);
            render_effective_policy(&project_root);
        }
        ConfigCommand::Format { format } => {
            store.id_config.format = match format.to_lowercase().as_str() {
                "single" | "single-level" | "1" => IdFormat::SingleLevel,
                "two" | "two-level" | "2" => IdFormat::TwoLevel,
                _ => anyhow::bail!("Invalid format. Use 'single' or 'two'."),
            };
            storage.save(&store)?;
            println!(
                "{} ID format set to {:?}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                store.id_config.format
            );
        }
        ConfigCommand::Numbering { strategy } => {
            store.id_config.numbering = match strategy.to_lowercase().as_str() {
                "global" => NumberingStrategy::Global,
                "per-prefix" | "prefix" => NumberingStrategy::PerPrefix,
                "per-feature-type" | "feature-type" => NumberingStrategy::PerFeatureType,
                _ => anyhow::bail!(
                    "Invalid strategy. Use 'global', 'per-prefix', or 'per-feature-type'."
                ),
            };
            storage.save(&store)?;
            println!(
                "{} Numbering strategy set to {:?}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                store.id_config.numbering
            );
        }
        ConfigCommand::Digits { digits } => {
            if *digits < 1 || *digits > 6 {
                anyhow::bail!("Digits must be between 1 and 6");
            }
            store.id_config.digits = *digits;
            storage.save(&store)?;
            println!(
                "{} ID digits set to {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                digits
            );
        }
        ConfigCommand::Migrate { yes } => {
            if !*yes {
                println!(
                    "{}",
                    "This will regenerate all requirement IDs based on current configuration."
                        .yellow()
                );
                println!("Current requirements: {}", store.requirements.len());
                let confirm = inquire::Confirm::new("Are you sure you want to migrate?")
                    .with_default(false)
                    .prompt()?;
                if !confirm {
                    println!("Migration cancelled.");
                    return Ok(());
                }
            }

            store.migrate_to_new_id_format();
            storage.save(&store)?;
            println!(
                "{} Successfully migrated {} requirements to new ID format.",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                store.requirements.len()
            );
        }
        ConfigCommand::User {
            node_id,
            email,
            toml: emit_toml,
        } => {
            // trace:STORY-44 | ai:claude
            handle_config_user(node_id.as_deref(), email.as_deref(), *emit_toml)?;
        }
        ConfigCommand::Hints { enabled } => {
            // trace:STORY-106 | ai:claude
            handle_config_hints(enabled.as_deref(), storage)?;
        }
        // STORY-633: glyph commands are intercepted before storage init in
        // both dispatch paths, so they never reach this generic handler.
        // trace:STORY-633 | ai:claude
        ConfigCommand::Glyph(_) => {
            unreachable!("`aida config glyph` is dispatched before handle_config_command")
        }
        // STORY-661: `aida config menu` is intercepted before storage init in
        // the early-dispatch block, so it never reaches this generic handler.
        // trace:STORY-661 | ai:claude
        ConfigCommand::Menu => {
            unreachable!("`aida config menu` is dispatched before handle_config_command")
        }
    }

    Ok(())
}

/// Where an effective config value came from. Rendered beside each value by
/// `aida config show` so the operator can tell a deliberate override from an
/// inherited default at a glance. trace:BUG-533 | ai:claude
enum PolicySource {
    /// No file or env set this — the built-in default is in force.
    Default,
    /// Set in the project's `.aida/config.toml`.
    ProjectConfig,
    /// Set in the global `~/.aida/agents.toml` (agent permission posture).
    GlobalAgents,
    /// Set in the global `~/.aida/config.toml` (user-wide default). STORY-620.
    GlobalConfig,
    /// Overridden by an environment variable (named).
    Env(&'static str),
}

impl PolicySource {
    fn label(&self) -> String {
        match self {
            PolicySource::Default => "default".dimmed().to_string(),
            PolicySource::ProjectConfig => ".aida/config.toml".dimmed().to_string(),
            PolicySource::GlobalAgents => "~/.aida/agents.toml".dimmed().to_string(),
            PolicySource::GlobalConfig => "~/.aida/config.toml".dimmed().to_string(),
            PolicySource::Env(name) => format!("{name} (env)").yellow().to_string(),
        }
    }

    /// Color-free scope label for the `aida config menu` TUI, which does its
    /// own styling. trace:STORY-661 | ai:claude
    fn plain_label(&self) -> String {
        match self {
            PolicySource::Default => "default".to_string(),
            PolicySource::ProjectConfig => ".aida/config.toml".to_string(),
            PolicySource::GlobalAgents => "~/.aida/agents.toml".to_string(),
            PolicySource::GlobalConfig => "~/.aida/config.toml".to_string(),
            PolicySource::Env(name) => format!("{name} (env)"),
        }
    }
}

/// One rendered policy row: a knob's effective value and where it resolved
/// from. trace:BUG-533 | ai:claude
struct PolicyRow {
    key: &'static str,
    value: String,
    source: PolicySource,
}

impl PolicyRow {
    fn print(&self) {
        println!(
            "  {}: {}  {}",
            self.key.cyan(),
            self.value,
            self.source.label()
        );
    }
}

/// One config section in the central policy registry: a `[section]` header and
/// the resolved knob rows under it.
///
/// TASK-793 (anti-drift, slice 2 of BUG-533): the registry — built by
/// [`policy_registry`] — is the single source of truth for which config knobs
/// `aida config show` renders. `render_effective_policy` iterates this list
/// rather than open-coding each section, so adding a knob is one registry entry
/// and it surfaces in `config show` automatically. The
/// [`KNOWN_CONFIG_SECTIONS`] const plus the `policy_registry_covers_*` tests are
/// the bouncer: a section read elsewhere in the codebase but absent from the
/// registry fails CI. trace:TASK-793 | ai:claude
struct PolicySection {
    /// The bare `[section]` name (no brackets) — the registry key matched
    /// against [`KNOWN_CONFIG_SECTIONS`] by the completeness test.
    section: &'static str,
    /// Bold header line shown above the rows (may add an inline gloss after the
    /// `[section]` token, e.g. "— agent permission posture").
    header: String,
    /// Resolved knob rows under this section.
    rows: Vec<PolicyRow>,
}

impl PolicySection {
    fn print(&self) {
        println!();
        println!("{}", self.header.bold());
        for row in &self.rows {
            row.print();
        }
    }
}

/// How a config knob may be edited from `aida config menu`, declared once per
/// knob in [`CONFIG_KNOBS`] (STORY-671 — the single source the editor, the
/// menu's `EditKind`, and the doc default all derive from). The value-type
/// carries the parse target the editor needs; [`EditSafety::ReadOnly`] knobs
/// (`id_format.*`, `deployment.*`, `agents.bypass`, `contained.*`, …) declare
/// *why* they are not live-editable so the menu can explain it.
///
/// This collapses the former hand-maintained `config_knob_meta` /
/// `config_knob_edit_kind` tables into the registry: an editable knob's type +
/// allowed set + range live with its doc + default in one declaration.
/// trace:STORY-671 | ai:claude
#[derive(Clone, Copy)]
enum EditSafety {
    /// A boolean knob — the menu toggles it. Carries the built-in default.
    Bool { default: bool },
    /// An enum knob over a fixed allowed set — the menu cycles it. The first
    /// value is the built-in default.
    Enum { allowed: &'static [&'static str] },
    /// An integer knob over an inclusive `[min, max]` range — the menu prompts.
    Integer { min: i64, max: i64 },
    /// Not live-editable from the menu. `reason` is the short why shown on Enter
    /// (env-shadowed knobs are detected at resolve time and override this).
    ReadOnly { reason: &'static str },
}

/// One config knob, declared once. This is the **single source of truth**
/// STORY-671 consolidates to: `aida config show`'s rows, `aida config menu`'s
/// `EditKind`, the menu's per-knob default + explanation, `aida config edit`'s
/// validation, AND the anti-drift test all derive from this table. Adding a
/// knob is one entry here (plus its resolution branch in [`policy_registry`],
/// which renders the live value) — no separate `config_knob_doc` /
/// `config_knob_meta` / `KNOWN_CONFIG_SECTIONS` edits to forget.
/// trace:STORY-671 | ai:claude
struct KnobSpec {
    /// The bare `[section]` name (no brackets).
    section: &'static str,
    /// The knob's bare key, or `"*"` for a section-wildcard entry whose doc +
    /// edit-safety apply to every key the resolver emits under that section
    /// (used where the key set is data-driven, e.g. `[seats]`, the `[team]`
    /// permission map). A concrete `(section, key)` entry always wins over the
    /// section wildcard.
    key: &'static str,
    /// One-line explanation (the framing `docs/environment-variables.md` uses).
    doc: &'static str,
    /// The built-in default shown in the menu (what you get with no config + no
    /// env override). String form so it renders uniformly across types.
    default: &'static str,
    /// Value-type + edit-safety: the one declaration the menu's `EditKind`, the
    /// editor's validation, and the read-only reason all derive from.
    edit: EditSafety,
}

/// The central config-knob registry — STORY-671's single source of truth. Each
