// ── Sandbox store (SPIKE-48) ─────────────────────────────────────────────
//
// A throwaway, discardable git-canonical store for drain-testing and scenario
// play. It is an ORDINARY store directory targeted via the `AIDA_STORE` env
// override (resolved in `aida_store_override`), so every `aida` command run in a
// shell that exports it operates on the sandbox instead of the project's real
// `aida-store` orphan branch. Lowest-machinery by design: a temp dir + a git
// repo + the same `GitBackend` init the real store uses — no daemon, no orphan
// branch, no remote. This is the dev-playground slice of SPIKE-48; the
// first-user/tutorial layer is deferred. trace:SPIKE-48 | ai:claude

/// Default sandbox store location: a stable per-user dir under the system temp
/// directory, so repeated `aida sandbox create` / `path` point at the same
/// playground without the user tracking a path. Per-user so two accounts on one
/// box don't collide. trace:SPIKE-48 | ai:claude
fn default_sandbox_path() -> std::path::PathBuf {
    let user = std::env::var("USER")
        .or_else(|_| std::env::var("USERNAME"))
        .unwrap_or_else(|_| "default".to_string());
    std::env::temp_dir().join(format!("aida-sandbox-{user}"))
}

fn sandbox_path_or_default(path: Option<&std::path::Path>) -> std::path::PathBuf {
    path.map(|p| p.to_path_buf())
        .unwrap_or_else(default_sandbox_path)
}

fn handle_sandbox_command(cmd: &cli::SandboxCommand) -> Result<()> {
    match cmd {
        cli::SandboxCommand::Create { path, seed, force } => {
            sandbox_create(sandbox_path_or_default(path.as_deref()), *seed, *force)
        }
        cli::SandboxCommand::Reset { path, seed } => {
            sandbox_reset(sandbox_path_or_default(path.as_deref()), *seed)
        }
        cli::SandboxCommand::Destroy { path } => {
            sandbox_destroy(sandbox_path_or_default(path.as_deref()))
        }
        cli::SandboxCommand::Path { path, export } => {
            sandbox_path(sandbox_path_or_default(path.as_deref()), *export)
        }
    }
}

/// Print the shell line that retargets `aida` at the sandbox. Shown by
/// `create` / `reset` / `path --export` so the user can copy-paste-activate.
fn sandbox_export_line(store: &std::path::Path) -> String {
    format!("export AIDA_STORE={}", store.display())
}

/// Is `dir` already a usable sandbox store (a git repo holding `objects/`)?
fn sandbox_is_populated(dir: &std::path::Path) -> bool {
    aida_core::git_ops::is_git_repo(dir) && dir.join("objects").is_dir()
}

/// Create (or no-op on) the sandbox store at `store`. Initializes a git repo +
/// `GitBackend` (which lays down `objects/` and `metadata.yaml`), optionally
/// seeds curated scenario specs, and prints the activation export line.
/// trace:SPIKE-48 | ai:claude
fn sandbox_create(store: std::path::PathBuf, seed: bool, force: bool) -> Result<()> {
    use aida_core::git_ops;

    if sandbox_is_populated(&store) && !force {
        println!(
            "{} sandbox store already exists at {}",
            "Note:".dimmed(),
            store.display().to_string().white().bold()
        );
        println!("  Use it:        {}", sandbox_export_line(&store).cyan());
        println!("  Re-seed:       {}", "aida sandbox reset --seed".cyan());
        println!("  Recreate:      {}", "aida sandbox create --force".cyan());
        return Ok(());
    }

    if force && store.exists() {
        std::fs::remove_dir_all(&store)
            .with_context(|| format!("failed to remove existing sandbox at {}", store.display()))?;
    }

    std::fs::create_dir_all(&store)
        .with_context(|| format!("failed to create sandbox dir {}", store.display()))?;

    if !git_ops::is_git_repo(&store) {
        git_ops::init(&store)?;
    }
    // A throwaway store still needs an identity for commits to succeed.
    let git_name =
        git_ops::git_config_get("user.name").unwrap_or_else(|_| "AIDA Sandbox".to_string());
    let git_email =
        git_ops::git_config_get("user.email").unwrap_or_else(|_| "sandbox@localhost".to_string());
    git_ops::configure_user(&store, &git_name, &git_email)?;

    // Initialize the backend (creates objects/ + metadata.yaml) and seed META
    // prompts so the playground behaves like a real project.
    let backend = aida_core::GitBackend::new(&store)?;
    let mut rs = aida_core::models::RequirementsStore::new();
    rs.name = "AIDA Sandbox".to_string();
    rs.title = "AIDA Sandbox".to_string();
    aida_core::meta::seed_meta_requirements(&mut rs)?;
    backend.save(&rs)?;

    std::fs::write(store.join("objects/.gitkeep"), "")?;
    git_ops::add_all(&store, "objects")?;
    if store.join("metadata.yaml").exists() {
        git_ops::add(&store, &["metadata.yaml"])?;
    }
    let _ = git_ops::commit(&store, "chore: initialize AIDA sandbox store");

    println!(
        "{} sandbox store at {}",
        "Created".green(),
        store.display().to_string().white().bold()
    );

    if seed {
        sandbox_seed(&store)?;
    }

    println!();
    println!("Activate it in this shell:");
    println!("  {}", sandbox_export_line(&store).cyan());
    println!(
        "Then `aida list` / `aida queue work` operate on the sandbox. {} when done.",
        "aida sandbox destroy".cyan()
    );
    Ok(())
}

/// Wipe the sandbox's contents and re-create it empty (or `--seed`-ed). The
/// directory path is reused so an exported `AIDA_STORE` stays valid.
/// trace:SPIKE-48 | ai:claude
fn sandbox_reset(store: std::path::PathBuf, seed: bool) -> Result<()> {
    if store.exists() {
        std::fs::remove_dir_all(&store)
            .with_context(|| format!("failed to reset sandbox at {}", store.display()))?;
    }
    sandbox_create(store, seed, true)
}

/// Delete the sandbox store directory entirely. Idempotent.
/// trace:SPIKE-48 | ai:claude
fn sandbox_destroy(store: std::path::PathBuf) -> Result<()> {
    if store.exists() {
        std::fs::remove_dir_all(&store)
            .with_context(|| format!("failed to destroy sandbox at {}", store.display()))?;
        println!(
            "{} sandbox store at {}",
            "Removed".green(),
            store.display().to_string().white().bold()
        );
        println!("  Unset the override: {}", "unset AIDA_STORE".cyan());
    } else {
        println!(
            "{} no sandbox store at {}",
            "Note:".dimmed(),
            store.display()
        );
    }
    Ok(())
}

/// Print the sandbox path (and existence), or the `export AIDA_STORE=...` line
/// with `--export`. trace:SPIKE-48 | ai:claude
fn sandbox_path(store: std::path::PathBuf, export: bool) -> Result<()> {
    if export {
        println!("{}", sandbox_export_line(&store));
        return Ok(());
    }
    let state = if sandbox_is_populated(&store) {
        "exists".green()
    } else {
        "not created".dimmed()
    };
    println!("{} ({})", store.display(), state);
    Ok(())
}

/// Seed a small, deterministic set of curated scenario specs into the sandbox:
/// a short lifecycle walk plus a blocked-by chain (so `aida graph --blocked-by`
/// and a drain have something to chew on). Deterministic + offline by design —
/// AI-generated scenarios are a deferred nicety. trace:SPIKE-48 | ai:claude
fn sandbox_seed(store: &std::path::Path) -> Result<()> {
    use aida_core::models::{RelationshipType, Requirement, RequirementStatus, RequirementType};

    let backend = aida_core::GitBackend::new(store)?;

    // Build the scenario specs in memory first so we can wire a blocked-by edge
    // by UUID (each Requirement gets its id at construction).
    let mut lifecycle = Requirement::new(
        "Sandbox: a lifecycle walk".to_string(),
        "Approved task to walk Draft -> Approved -> Planned -> In Progress -> Done. \
         Edit its status with `aida edit <id> --status ...` to feel the state machine."
            .to_string(),
    );
    lifecycle.req_type = RequirementType::Task;
    lifecycle.status = RequirementStatus::Approved;
    lifecycle.tags.insert("sandbox".to_string());

    let mut blocker = Requirement::new(
        "Sandbox: the blocker".to_string(),
        "This task blocks the dependent below. Try `aida graph <dependent-id> --blocked-by`."
            .to_string(),
    );
    blocker.req_type = RequirementType::Task;
    blocker.status = RequirementStatus::Approved;
    blocker.tags.insert("sandbox".to_string());

    let mut dependent = Requirement::new(
        "Sandbox: the dependent".to_string(),
        "Blocked by 'the blocker' — it won't be pickable until the blocker is Done.".to_string(),
    );
    dependent.req_type = RequirementType::Task;
    dependent.status = RequirementStatus::Approved;
    dependent.tags.insert("sandbox".to_string());
    dependent
        .relationships
        .push(aida_core::models::Relationship {
            rel_type: RelationshipType::BlockedBy,
            target_id: blocker.id,
            created_at: Some(chrono::Utc::now()),
            created_by: Some("sandbox".to_string()),
        });
    // Inverse edge on the blocker so the graph reads cleanly both ways.
    blocker.relationships.push(aida_core::models::Relationship {
        rel_type: RelationshipType::Blocks,
        target_id: dependent.id,
        created_at: Some(chrono::Utc::now()),
        created_by: Some("sandbox".to_string()),
    });

    let mut writer = backend.bulk_writer()?;
    writer.add(lifecycle)?;
    writer.add(blocker)?;
    writer.add(dependent)?;
    let count = writer.finish("chore: seed sandbox scenario specs")?;

    println!("  {} {} scenario specs", "Seeded".green(), count);
    Ok(())
}

/// Print the alignment between this commit's paired store SHA (from the
/// `Aida-Store:` trailer) and the current orphan store HEAD. Reports
/// "aligned" when they match, "drift" with commit count otherwise.
/// trace:EPIC-21 | ai:claude
fn store_status() -> Result<()> {
    let project_root = find_project_root()?;
    let store_path = project_root.join(".aida-store");

    // Current code HEAD.
    let code_head = std::process::Command::new("git")
        .arg("-C")
        .arg(&project_root)
        .args(["rev-parse", "HEAD"])
        .output()
        .ok()
        .and_then(|o| {
            if o.status.success() {
                Some(String::from_utf8_lossy(&o.stdout).trim().to_string())
            } else {
                None
            }
        });
    let code_head = match code_head {
        Some(s) if !s.is_empty() => s,
        _ => anyhow::bail!("not in a git repo or no commits yet"),
    };

    // Paired store SHA — read the Aida-Store trailer from HEAD's message.
    let head_msg = std::process::Command::new("git")
        .arg("-C")
        .arg(&project_root)
        .args(["log", "-1", "--format=%B"])
        .output()?;
    let head_msg = String::from_utf8_lossy(&head_msg.stdout).to_string();
    let trailers = std::process::Command::new("git")
        .arg("-C")
        .arg(&project_root)
        .args(["interpret-trailers", "--parse"])
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn()?;
    {
        use std::io::Write;
        if let Some(mut stdin) = trailers.stdin.as_ref() {
            let _ = stdin.write_all(head_msg.as_bytes());
        }
    }
    let trailer_output = trailers.wait_with_output()?;
    let trailer_text = String::from_utf8_lossy(&trailer_output.stdout).to_string();
    let paired_store_sha: Option<String> = trailer_text
        .lines()
        .find_map(|l| l.strip_prefix("Aida-Store:").map(|s| s.trim().to_string()));

    // Current orphan-store HEAD.
    let store_head: Option<String> = if store_path.exists() {
        std::process::Command::new("git")
            .arg("-C")
            .arg(&store_path)
            .args(["rev-parse", "HEAD"])
            .output()
            .ok()
            .and_then(|o| {
                if o.status.success() {
                    Some(String::from_utf8_lossy(&o.stdout).trim().to_string())
                } else {
                    None
                }
            })
    } else {
        None
    };

    println!("{}", "Code ↔ store pairing".bold());
    println!("  code HEAD:        {}", short_sha(&code_head).cyan());
    match &paired_store_sha {
        Some(p) => println!("  paired store SHA: {}", short_sha(p).cyan()),
        None => {
            println!(
                "  paired store SHA: {} {}",
                "(none)".dimmed(),
                "— commit was made before the prepare-commit-msg hook was installed".dimmed()
            );
        }
    }
    match &store_head {
        Some(s) => println!("  current store:    {}", short_sha(s).cyan()),
        None => println!(
            "  current store:    {} (no .aida-store/)",
            "(missing)".yellow()
        ),
    }
    println!();

    match (paired_store_sha.as_deref(), store_head.as_deref()) {
        (Some(p), Some(c)) if p == c => {
            println!(
                "{} aligned — code commit was paired with the current store HEAD.",
                crate::glyph(crate::glyphs::Glyph::Check).green()
            );
        }
        (Some(p), Some(c)) => {
            // Compute the commit counts: how many commits is store HEAD
            // ahead of / behind the paired SHA.
            let drift = std::process::Command::new("git")
                .arg("-C")
                .arg(&store_path)
                .args([
                    "rev-list",
                    "--left-right",
                    "--count",
                    &format!("{}...{}", p, c),
                ])
                .output()
                .ok();
            let (behind, ahead) = match drift {
                Some(o) if o.status.success() => {
                    let s = String::from_utf8_lossy(&o.stdout).trim().to_string();
                    let parts: Vec<&str> = s.split_whitespace().collect();
                    let b: i32 = parts.first().and_then(|x| x.parse().ok()).unwrap_or(0);
                    let a: i32 = parts.get(1).and_then(|x| x.parse().ok()).unwrap_or(0);
                    (b, a)
                }
                _ => (-1, -1),
            };
            // The store legitimately advances ahead of the pin on every
            // normal spec write — that is the healthy state, not drift. Only
            // a genuine divergence (paired SHA not an ancestor of the current
            // store HEAD) is worth flagging. trace:BUG-584
            let is_ancestor = store_sha_is_ancestor(&store_path, p, c);
            if behind <= 0 && is_ancestor {
                // Fast-forward: store simply moved forward N commits.
                if ahead > 0 {
                    println!(
                        "{} store ahead — {} normal spec-write commit(s) since this code commit was paired (healthy: the store moves forward as you file specs).",
                        crate::glyph(crate::glyphs::Glyph::Check).green(),
                        ahead
                    );
                } else {
                    // Ancestor with zero ahead-count shouldn't happen (that's
                    // the aligned arm), but stay quiet-and-clean if it does.
                    println!(
                        "{} store ahead — code commit was paired with an ancestor of the current store HEAD (healthy).",
                        crate::glyph(crate::glyphs::Glyph::Check).green(),
                    );
                }
            } else if behind < 0 {
                println!(
                    "{} drift — store diverged since this commit was made (could not count commits, paired SHA may not exist locally).",
                    "·".yellow()
                );
                println!(
                    "  v2 will offer: {}",
                    "aida store checkout HEAD   # rewind .aida-store/ to the paired SHA".dimmed()
                );
            } else {
                println!(
                    "{} drift — store diverged from the paired SHA (possible store-side history rewrite).",
                    "·".yellow()
                );
                println!(
                    "  {} commit(s) on the paired SHA are not on the current store HEAD; {} commit(s) on the current store HEAD are not on the paired SHA.",
                    behind, ahead
                );
                println!(
                    "  v2 will offer: {}",
                    "aida store checkout HEAD   # rewind .aida-store/ to the paired SHA".dimmed()
                );
            }
        }
        (None, _) => {
            println!(
                "{} no Aida-Store trailer on this commit — install the hook with: {}",
                "·".dimmed(),
                "aida store install-hook".cyan()
            );
        }
        (Some(_), None) => {
            println!(
                "{} commit has a paired SHA but no .aida-store/ in the worktree to compare against.",
                "·".yellow()
            );
        }
    }
    Ok(())
}

fn short_sha(sha: &str) -> String {
    if sha.len() >= 7 {
        sha[..7].to_string()
    } else {
        sha.to_string()
    }
}

/// Verdict for the code↔store SHA pairing. trace:BUG-584 | ai:claude
#[derive(Debug, PartialEq, Eq, Clone, Copy)]
enum StoreDriftVerdict {
    /// Nothing to compare — no trailer, or no `.aida-store/`.
    NoVerdict,
    /// Paired SHA == current store HEAD.
    Aligned,
    /// Current store HEAD is a fast-forward descendant of the paired SHA —
    /// the store simply moved forward via normal spec writes (`aida add` /
    /// `aida done`). This is the **normal, healthy** state, NOT drift: the
    /// store SHOULD be ahead of a code commit's pin once you file specs.
    StoreAhead,
    /// The paired SHA is NOT an ancestor of the current store HEAD — a
    /// genuine divergence: a store-side history rewrite, or a paired SHA that
    /// no longer exists locally. This is the only state worth warning about.
    Diverged,
}

/// Pure drift verdict: given the code commit's paired store SHA (from the
/// `Aida-Store:` trailer), the current orphan-store HEAD, and whether the
/// paired SHA is an ancestor of the current store HEAD, decide the pairing
/// state.
///
/// The pin's purpose (STORY-49) is to detect when the store has genuinely
/// *diverged* from what a code commit was paired against (a rewind/rewrite).
/// But the orphan store legitimately advances ahead of the pin on every
/// normal `aida add` / `aida done` write, so a bare `paired != current`
/// comparison fires on day one after ordinary use (BUG-584). We only treat a
/// difference as drift when the paired SHA is **not** an ancestor of the
/// current store HEAD — i.e. the store has truly diverged, not merely moved
/// forward.
///
/// `paired_is_ancestor_of_current` is the caller-supplied ancestry fact
/// (`git merge-base --is-ancestor <paired> <current>`); kept as a parameter
/// so this stays a pure, unit-testable function.
/// trace:STORY-49 trace:BUG-584 | ai:claude
fn store_drift_verdict(
    paired_store_sha: Option<&str>,
    current_store_head: Option<&str>,
    paired_is_ancestor_of_current: bool,
) -> StoreDriftVerdict {
    match (paired_store_sha, current_store_head) {
        (Some(p), Some(c)) if p.trim() == c.trim() => StoreDriftVerdict::Aligned,
        (Some(_), Some(_)) if paired_is_ancestor_of_current => StoreDriftVerdict::StoreAhead,
        (Some(_), Some(_)) => StoreDriftVerdict::Diverged,
        _ => StoreDriftVerdict::NoVerdict,
    }
}

/// True when `ancestor` is an ancestor of (or equal to) `descendant` in the
/// orphan store's git history — i.e. the store fast-forwarded from `ancestor`
/// to `descendant`. Resolved via `git merge-base --is-ancestor` inside the
/// `.aida-store/` worktree. Returns `false` on any git error or when either
/// SHA is missing locally (which is itself a divergence signal, so the
/// caller correctly reports drift). trace:BUG-584 | ai:claude
fn store_sha_is_ancestor(store_path: &std::path::Path, ancestor: &str, descendant: &str) -> bool {
    if !store_path.exists() {
        return false;
    }
    std::process::Command::new("git")
        .arg("-C")
        .arg(store_path)
        .args(["merge-base", "--is-ancestor", ancestor, descendant])
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

/// Read the `Aida-Store:` trailer SHA from the code HEAD commit message at
/// `project_root`, if present. Returns `None` on any git error, no trailer,
/// or no commits. trace:STORY-49 | ai:claude
fn paired_store_sha_for_head(project_root: &std::path::Path) -> Option<String> {
    let head_msg = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["log", "-1", "--format=%B"])
        .output()
        .ok()?;
    if !head_msg.status.success() {
        return None;
    }
    let head_msg = String::from_utf8_lossy(&head_msg.stdout).to_string();
    let trailers = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["interpret-trailers", "--parse"])
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn()
        .ok()?;
    {
        use std::io::Write;
        if let Some(mut stdin) = trailers.stdin.as_ref() {
            let _ = stdin.write_all(head_msg.as_bytes());
        }
    }
    let trailer_output = trailers.wait_with_output().ok()?;
    let trailer_text = String::from_utf8_lossy(&trailer_output.stdout).to_string();
    trailer_text
        .lines()
        .find_map(|l| l.strip_prefix("Aida-Store:").map(|s| s.trim().to_string()))
        .filter(|s| !s.is_empty())
}

/// Current orphan-store HEAD SHA from `<project_root>/.aida-store`, if the
/// worktree exists and git can resolve it. trace:STORY-49 | ai:claude
fn current_store_head_sha(project_root: &std::path::Path) -> Option<String> {
    let store_path = project_root.join(".aida-store");
    if !store_path.exists() {
        return None;
    }
    std::process::Command::new("git")
        .arg("-C")
        .arg(&store_path)
        .args(["rev-parse", "HEAD"])
        .output()
        .ok()
        .and_then(|o| {
            if o.status.success() {
                Some(String::from_utf8_lossy(&o.stdout).trim().to_string())
            } else {
                None
            }
        })
        .filter(|s| !s.is_empty())
}

/// STORY-49: one-line store/code SHA-drift warning for `aida status`.
///
/// Warn-only, and only on **genuine** divergence. The code HEAD's paired
/// store SHA (`Aida-Store:` trailer) is a pin recorded at commit time; the
/// orphan store legitimately moves ahead of it on every normal `aida add` /
/// `aida done`, so a bare "paired != current" comparison nagged on day one
/// after ordinary use (BUG-584). We surface the yellow line only when the
/// store has truly diverged (paired SHA is not an ancestor of the current
/// store HEAD — a rewind/rewrite, or a paired SHA missing locally). Silent
/// when aligned, when the store is simply ahead (the normal, healthy state),
/// when there is no trailer (hook not installed / pre-hook commit), or when
/// there is no `.aida-store/`. trace:STORY-49 trace:BUG-584
fn print_status_store_drift_section(project_root: &std::path::Path) {
    let paired = paired_store_sha_for_head(project_root);
    let current = current_store_head_sha(project_root);
    let store_path = project_root.join(".aida-store");
    let is_ancestor = match (paired.as_deref(), current.as_deref()) {
        (Some(p), Some(c)) => store_sha_is_ancestor(&store_path, p, c),
        _ => false,
    };
    if let StoreDriftVerdict::Diverged =
        store_drift_verdict(paired.as_deref(), current.as_deref(), is_ancestor)
    {
        println!(
            "  {} code HEAD pinned store {} but the current store {} diverged from it — run {} for detail",
            "Store drift:".bold().yellow(),
            short_sha(paired.as_deref().unwrap_or("")).dimmed(),
            short_sha(current.as_deref().unwrap_or("")).dimmed(),
            "aida store status".cyan()
        );
        println!();
    }
}

#[cfg(test)]
mod story_49_store_drift_tests {
    use super::{store_drift_verdict, StoreDriftVerdict};

    #[test]
    fn aligned_when_paired_equals_current() {
        // Ancestry is irrelevant when the two SHAs are equal.
        assert_eq!(
            store_drift_verdict(Some("abc123"), Some("abc123"), false),
            StoreDriftVerdict::Aligned
        );
    }

    #[test]
    fn whitespace_around_shas_is_ignored() {
        assert_eq!(
            store_drift_verdict(Some("  abc123\n"), Some("abc123"), false),
            StoreDriftVerdict::Aligned
        );
    }

    // BUG-584: the store legitimately advances ahead of the pin on every
    // normal `aida add` / `aida done`. When the paired SHA is an ancestor of
    // the current store HEAD, that is the healthy "store ahead" state — NOT
    // drift. This is the false-positive the day-one dogfood hit.
    #[test]
    fn store_ahead_is_not_drift() {
        assert_eq!(
            store_drift_verdict(Some("abc123"), Some("def456"), /* is_ancestor */ true),
            StoreDriftVerdict::StoreAhead
        );
    }

    // BUG-584: genuine divergence — paired SHA is NOT an ancestor of the
    // current store HEAD (history rewrite / rewind, or paired SHA missing
    // locally). This must still be reported as drift.
    #[test]
    fn genuine_divergence_is_drift() {
        assert_eq!(
            store_drift_verdict(Some("abc123"), Some("def456"), /* is_ancestor */ false),
            StoreDriftVerdict::Diverged
        );
    }

    #[test]
    fn no_verdict_without_a_paired_sha() {
        // No `Aida-Store:` trailer on the commit — nothing to compare.
        assert_eq!(
            store_drift_verdict(None, Some("abc123"), false),
            StoreDriftVerdict::NoVerdict
        );
    }

    #[test]
    fn no_verdict_without_a_current_store_head() {
        // No `.aida-store/` worktree — nothing to compare.
        assert_eq!(
            store_drift_verdict(Some("abc123"), None, false),
            StoreDriftVerdict::NoVerdict
        );
    }

    #[test]
    fn no_verdict_when_both_absent() {
        assert_eq!(
            store_drift_verdict(None, None, false),
            StoreDriftVerdict::NoVerdict
        );
    }
}

/// Install the prepare-commit-msg hook from EMBEDDED_TEMPLATES into
/// `.git/hooks/prepare-commit-msg`. Idempotent. trace:EPIC-21 | ai:claude
fn store_install_hook(force: bool) -> Result<()> {
    let project_root = find_project_root()?;
    let hooks_dir = project_root.join(".git").join("hooks");
    if !hooks_dir.exists() {
        anyhow::bail!(
            "{} doesn't exist — is this a git repo?",
            hooks_dir.display()
        );
    }
    let target = hooks_dir.join("prepare-commit-msg");
    if target.exists() && !force {
        anyhow::bail!(
            "{} already exists — pass --force to overwrite, or inspect with `cat {}`",
            target.display(),
            target.display()
        );
    }

    let body = aida_core::templates::EMBEDDED_TEMPLATES
        .get("hooks/aida-store-pair.sh")
        .copied()
        .ok_or_else(|| anyhow::anyhow!("aida-store-pair.sh missing from embedded templates"))?;

    std::fs::write(&target, body)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mut perms = std::fs::metadata(&target)?.permissions();
        perms.set_mode(0o755);
        std::fs::set_permissions(&target, perms)?;
    }

    println!(
        "{} installed prepare-commit-msg hook at {}",
        crate::glyph(crate::glyphs::Glyph::Check).green().bold(),
        target.display().to_string().cyan()
    );
    println!();
    println!("Every future code commit will get an `Aida-Store: <sha>` trailer pinning the");
    println!(
        "orphan-store HEAD at commit time. Inspect alignment with: {}",
        "aida store status".cyan()
    );
    Ok(())
}

// ----------------------------------------------------------------------------
// EPIC-19 — `aida doctor`: maintenance + migration commands.
// ----------------------------------------------------------------------------

fn handle_doctor_command(
    heal: bool,
    yes: bool,
    category: Option<&str>,
    json: bool,
    force: bool,
    all: bool,
    since: Option<&str>,
    cmd: Option<&cli::DoctorCommand>,
) -> Result<()> {
    let Some(cmd) = cmd else {
        return doctor_multi_agent(DoctorRunOptions {
            heal,
            yes,
            category: category.map(str::to_string),
            json,
            force,
            all,
            since: since.map(str::to_string),
        });
    };
    match cmd {
        cli::DoctorCommand::Check {
            category,
            all: sub_all,
            json,
        } => doctor_multi_agent(DoctorRunOptions {
            heal: false,
            yes,
            category: Some(category.clone()),
            json: *json,
            force,
            all: all || *sub_all,
            since: since.map(str::to_string),
        }),
        cli::DoctorCommand::Heal {
            category,
            yes,
            force,
            all: sub_all,
            json,
        } => doctor_multi_agent(DoctorRunOptions {
            heal: true,
            yes: *yes,
            category: Some(category.clone()),
            json: *json,
            force: *force,
            all: all || *sub_all,
            since: since.map(str::to_string),
        }),
        cli::DoctorCommand::MigrateCounterScope {
            to,
            dry_run,
            yes,
            size,
        } => doctor_migrate_counter_scope(to, *dry_run, *yes, *size),
        cli::DoctorCommand::RepairStaleBlocks { dry_run, yes } => {
            doctor_repair_stale_blocks(*dry_run, *yes)
        }
        cli::DoctorCommand::ScrubCollisions => doctor_scrub_collisions(),
        cli::DoctorCommand::VerifyRelationships { repair, yes } => {
            doctor_verify_relationships(*repair, *yes)
        }
        cli::DoctorCommand::ValidateTraceComments {
            strip_dangling,
            dry_run,
            yes,
        } => doctor_validate_trace_comments(*strip_dangling, *dry_run, *yes),
        cli::DoctorCommand::Fsck => doctor_fsck(),
        cli::DoctorCommand::ConventionCheck { quiet } => doctor_convention_check(*quiet),
    }
}

// ----------------------------------------------------------------------------
// STORY-462 — `aida doctor`: multi-agent state drift diagnostics + healing.
// ----------------------------------------------------------------------------

#[derive(Debug, Clone)]
struct DoctorRunOptions {
    heal: bool,
    yes: bool,
    category: Option<String>,
    json: bool,
    force: bool,
    all: bool,
    /// TASK-673: cutoff for the completed-without-commit integrity check —
    /// specs completed before this ref/date are exempt (legacy history).
    since: Option<String>,
}

#[derive(Debug, Clone, serde::Serialize)]
struct DoctorFinding {
    category: String,
    id: String,
    summary: String,
    action: String,
    safe_heal: bool,
}

#[derive(Debug, Clone, Default, serde::Serialize)]
struct DoctorHealResult {
    category: String,
    id: String,
    action: String,
    status: String,
    detail: Option<String>,
}

#[derive(Debug, Clone, Default, serde::Serialize)]
struct DoctorReport {
    total: usize,
    findings: Vec<DoctorFinding>,
    #[serde(skip_serializing_if = "is_zero_usize")]
    hidden_completed_without_commit: usize,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    healed: Vec<DoctorHealResult>,
    /// TASK-865: read-only bubblewrap OS-sandbox availability status line.
    #[serde(skip_serializing_if = "Option::is_none")]
    bwrap: Option<String>,
}

impl DoctorReport {
    fn from_findings(findings: Vec<DoctorFinding>) -> Self {
        Self {
            total: findings.len(),
            findings,
            hidden_completed_without_commit: 0,
            healed: Vec::new(),
            bwrap: Some(bwrap_status_line()),
        }
    }
}

fn is_zero_usize(n: &usize) -> bool {
    *n == 0
}

fn doctor_multi_agent(opts: DoctorRunOptions) -> Result<()> {
    let project_root = main_worktree_root_from(&find_project_root()?);
    let store_path = project_root.join(".aida-store");
    let store = Storage::new(&store_path)
        .load()
        .with_context(|| format!("loading AIDA store at {}", store_path.display()))?;
    let mut findings = collect_doctor_findings(&project_root, &store, opts.category.as_deref())?;
    let mut hidden_completed_without_commit = 0;

    // TASK-673: the completed-without-commit integrity check runs git scans
    // (a default-branch `git log` + `git grep`) so it is kept OUT of the hot
    // `collect_doctor_findings` path (which `aida status` calls on every
    // invocation) and appended here, where only `aida doctor` reaches it.
    // It honours the same `--category` filter as the built-in categories.
    // trace:TASK-673 | ai:claude
    if doctor_category_selected(opts.category.as_deref(), "completed-without-commit")? {
        let since = opts
            .since
            .clone()
            .or_else(|| std::env::var("AIDA_DOCTOR_COMPLETED_SINCE").ok())
            .or_else(default_completed_without_commit_recent_cutoff)
            .filter(|s| !s.trim().is_empty());
        let scan = scan_completed_without_commit_with_options(
            &project_root,
            &store,
            since.as_deref(),
            opts.all,
        );
        hidden_completed_without_commit = scan.hidden_older;
        findings.extend(scan.findings);
        findings.sort_by(|a, b| a.category.cmp(&b.category).then(a.id.cmp(&b.id)));
    }

    // TASK-717: stale-remote-branch scan. Like completed-without-commit it runs
    // git ancestry probes + a `gh pr list`, so it is kept OUT of the hot
    // `collect_doctor_findings` path and appended here where only `aida doctor`
    // reaches it. Honours the same `--category` filter. trace:TASK-717
    if doctor_category_selected(opts.category.as_deref(), "stale-remote-branches")? {
        findings.extend(scan_stale_remote_branches(&project_root, &store));
        findings.sort_by(|a, b| a.category.cmp(&b.category).then(a.id.cmp(&b.id)));
    }

    // TASK-878: merged Agent-tool worktree GC. Runs git ancestry probes + a forge
    // merged-PR lookup, so it is kept OUT of the hot `collect_doctor_findings`
    // path and appended here where only `aida doctor` reaches it. Honours the
    // same `--category` filter. trace:TASK-878 | ai:claude
    if doctor_category_selected(opts.category.as_deref(), "merged-agent-worktrees")? {
        findings.extend(scan_merged_agent_worktrees(&project_root));
        findings.sort_by(|a, b| a.category.cmp(&b.category).then(a.id.cmp(&b.id)));
    }

    let mut report = DoctorReport::from_findings(findings);
    report.hidden_completed_without_commit = hidden_completed_without_commit;

    if opts.heal {
        report.healed = heal_doctor_findings(&project_root, &report.findings, &opts)?;
    }

    if opts.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        render_doctor_report(&report, opts.heal)?;
        // STORY-707: `aida doctor` is the check-everything home. The heavy
        // orientation diagnostics that used to ride bare `aida status` — PR/CI
        // (a `gh` network call), live-session/lease liveness, worktree probes,
        // the full fleet roster, and cross-clone coordination — now surface
        // HERE, not on the fast default `aida status`. Gated to the full,
        // unfiltered text run (no `--category` narrow filter) so a targeted
        // `aida doctor check --category X` stays focused. trace:STORY-707
        if opts.category.is_none() {
            print_doctor_status_diagnostics(&project_root, &store);
        }
    }

    // BUG-471: heal now continues past a single finding's failure (no more
    // first-error abort), so the failure signal moves to the exit code — bail
    // non-zero after the report so scripts/automation still notice.
    // trace:BUG-471 | ai:claude
    let failed = report
        .healed
        .iter()
        .filter(|r| r.status == "failed")
        .count();
    if failed > 0 {
        anyhow::bail!("{failed} finding(s) failed to heal — see the report above");
    }
    Ok(())
}

/// TASK-752: detect tracked legacy centralized-backend artifacts —
/// `requirements.yaml`, dated `requirements_*.yaml` snapshots, and a stray
/// `scaffold-report.html` — when the project DECLARES git-canonical/distributed
/// storage but the git tree still TRACKS those files. This is storage-model
/// drift: config says git-canonical (the live store is the orphan `aida-store`
/// branch), but the tree carries the centralized model's files (PR-651 swept
/// ~2.3MB of exactly this by hand on the AIDA repo itself).
///
/// GUARD: gated strictly on git-canonical mode — `.aida/config.toml` declares
/// `mode = "distributed"` AND the orphan `aida-store` branch exists. On a legacy
/// `--centralized` project that legitimately USES `requirements.yaml` as its
/// active store, neither condition holds, so we return nothing and never nuke an
/// active backend. Returns the repo-relative tracked paths to flag (empty when
/// clean or when the project is not git-canonical).
// trace:TASK-752 | ai:claude
fn detect_legacy_store_cruft(project_root: &std::path::Path) -> Vec<String> {
    // Gate 1: config declares distributed/git-canonical mode.
    if distributed_mode_declared_from(project_root).is_none() {
        return Vec::new();
    }
    // Gate 2: the orphan `aida-store` branch (the actual writer of record)
    // exists — confirms the live store really is git-canonical, not a
    // half-migrated config.
    if !branch_exists_anywhere(project_root, "aida-store") {
        return Vec::new();
    }

    // `git ls-files` lists only TRACKED paths — an untracked-but-gitignored
    // `requirements.yaml` (the post-heal state) is correctly NOT flagged.
    let Ok(output) = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["ls-files", "-z"])
        .output()
    else {
        return Vec::new();
    };
    if !output.status.success() {
        return Vec::new();
    }
    let mut hits: Vec<String> = String::from_utf8_lossy(&output.stdout)
        .split('\0')
        .filter(|p| !p.is_empty())
        .filter(|p| is_legacy_store_cruft_path(p))
        .map(|p| p.to_string())
        .collect();
    hits.sort();
    hits.dedup();
    hits
}

/// Whether a repo-relative path is a legacy centralized-backend artifact:
/// a top-level `requirements*.yaml` (the legacy store + dated snapshots like
/// `requirements_20251206_205840.yaml`) or a top-level `scaffold-report.html`.
/// Top-level only — never matches nested paths (e.g. a `requirements.yaml`
/// fixture deep in a test tree).
// trace:TASK-752 | ai:claude
fn is_legacy_store_cruft_path(path: &str) -> bool {
    // Top-level only: no path separator.
    if path.contains('/') {
        return false;
    }
    path == "scaffold-report.html" || (path.starts_with("requirements") && path.ends_with(".yaml"))
}

/// BUG-563: detect per-clone RUNTIME files wrongly TRACKED on the orphan
/// `aida-store` branch — `.aida/node.toml` (the strictly-per-clone "I am node N"
/// pointer), `.aida/dispenser.toml` (per-node id counter), `.aida/*.lock`, and
/// `.aida/cache.db*` (the rebuildable read projection). If the orphan branch was
/// created (or had these committed) BEFORE the store-branch gitignore landed,
/// each clone's auto-sync commits rewrite `node.toml` with that clone's own node
/// id, so every cross-clone store-leg rebase conflicts on it forever — stranding
/// the rebase and breaking `aida push` with TOML parse errors from conflict
/// markers.
///
/// GUARD: gated strictly on git-canonical mode — `.aida/config.toml` declares
/// `mode = "distributed"` AND the orphan `aida-store` worktree is attached at
/// `.aida-store/`. The scan runs `git ls-files` IN THE STORE WORKTREE (not the
/// main repo), so it inspects the orphan branch's tree, never the project tree.
/// Returns the store-worktree-relative tracked paths to flag (empty when clean
/// or when the project is not git-canonical / the store worktree is absent).
// trace:BUG-563 | ai:claude
fn detect_store_tracked_runtime(project_root: &std::path::Path) -> Vec<String> {
    // Gate 1: config declares distributed/git-canonical mode.
    if distributed_mode_declared_from(project_root).is_none() {
        return Vec::new();
    }
    // Gate 2: the orphan `aida-store` worktree is actually attached — we scan
    // its tree, so it must be present on disk.
    let store_worktree = project_root.join(".aida-store");
    if !store_worktree.join("objects").is_dir() {
        return Vec::new();
    }

    // `git ls-files` in the STORE worktree lists only paths TRACKED on the
    // orphan branch — an untracked-but-gitignored `node.toml` (the post-heal
    // state) is correctly NOT flagged.
    let Ok(output) = std::process::Command::new("git")
        .arg("-C")
        .arg(&store_worktree)
        .args(["ls-files", "-z"])
        .output()
    else {
        return Vec::new();
    };
    if !output.status.success() {
        return Vec::new();
    }
    let mut hits: Vec<String> = String::from_utf8_lossy(&output.stdout)
        .split('\0')
        .filter(|p| !p.is_empty())
        .filter(|p| is_store_tracked_runtime_path(p))
        .map(|p| p.to_string())
        .collect();
    hits.sort();
    hits.dedup();
    hits
}

/// Whether a store-worktree-relative path is a per-clone runtime file that must
/// never be tracked on the orphan `aida-store` branch: `.aida/node.toml`,
/// `.aida/dispenser.toml`, any `.aida/*.lock`, or any `.aida/cache.db*`
/// (`cache.db`, `cache.db-journal`, `cache.db-wal`, `cache.db-shm`). Scoped to
/// the top-level `.aida/` dir only — never matches nested paths or shared,
/// legitimately-tracked store files (`config.toml`, `metadata.yaml`, the
/// `objects/`/`registry/` trees, requirement yaml).
// trace:BUG-563 | ai:claude
fn is_store_tracked_runtime_path(path: &str) -> bool {
    // Only files directly under a top-level `.aida/` dir.
    let Some(name) = path.strip_prefix(".aida/") else {
        return false;
    };
    // No further nesting — `.aida/<name>` only, not `.aida/sub/<name>`.
    if name.contains('/') {
        return false;
    }
    name == "node.toml"
        || name == "dispenser.toml"
        || name.ends_with(".lock")
        || name == "cache.db"
        || name.starts_with("cache.db-")
}

fn collect_doctor_findings(
    project_root: &std::path::Path,
    store: &aida_core::models::RequirementsStore,
    category_filter: Option<&str>,
) -> Result<Vec<DoctorFinding>> {
    let filter = category_filter.map(normalize_doctor_category).transpose()?;
    let mut out = Vec::new();
    let cleanup = collect_cleanup_report(project_root, store);
    let leases = list_leases(project_root);
    let live_sessions = process_probe::probe_live_claude_sessions();
    let now = chrono::Utc::now();

    let mut push = |finding: DoctorFinding| {
        if filter
            .as_deref()
            .is_none_or(|want| want == finding.category)
        {
            out.push(finding);
        }
    };

    // TASK-696: an ANCESTOR CLAUDE.md / CLAUDE.local.md / AGENTS.md whose
    // @-imports resolve OUTSIDE this project bleeds into every child project —
    // it pollutes the child's context AND trips Claude Code's "Allow external
    // CLAUDE.md file imports?" prompt on launch. The classic cause is an
    // accidental `aida init` in a parent-of-projects (TASK-686 now prevents new
    // ones; this detects existing ones). Read-only finding — removing a stray
    // ancestor file is a follow-up heal. trace:TASK-696 | ai:claude
    for ancestor in project_root.ancestors().skip(1) {
        for fname in external_import_bleed::ANCESTOR_INSTRUCTION_FILES {
            let file = ancestor.join(fname);
            let Ok(content) = std::fs::read_to_string(&file) else {
                continue;
            };
            let escaping: Vec<String> = external_import_bleed::parse_at_imports(&content)
                .into_iter()
                .filter(|imp| {
                    external_import_bleed::import_escapes_project(ancestor, imp, project_root)
                })
                .collect();
            if !escaping.is_empty() {
                push(DoctorFinding {
                    category: "external-import-bleed".to_string(),
                    id: file.display().to_string(),
                    summary: format!(
                        "ancestor {} has {} @-import(s) resolving outside this project ({}) — it bleeds into every child + trips Claude Code's external-import prompt",
                        file.display(),
                        escaping.len(),
                        escaping.join(", ")
                    ),
                    action: format!(
                        "review {} — if it's a stray scaffold (e.g. an accidental `aida init` in a parent-of-projects), remove the stray ancestor instruction file",
                        file.display()
                    ),
                    safe_heal: false,
                });
            }
        }
    }

    let cache_path =
        aida_core::CachedGitBackend::default_cache_path(&project_root.join(".aida-store"));
    let lock_info_path = aida_core::cache_lock_info_path(&cache_path);
    if let Some(lock_info) = aida_core::read_cache_lock_info(&cache_path)? {
        let stale_secs = std::env::var("AIDA_CACHE_LOCK_STALE_SECS")
            .ok()
            .and_then(|v| v.parse::<i64>().ok())
            .unwrap_or(300);
        let age_secs = lock_info
            .started_at_utc()
            .map(|started| now.signed_duration_since(started).num_seconds())
            .unwrap_or(0);
        if age_secs >= stale_secs && !process_probe::pid_is_alive(lock_info.pid) {
            push(DoctorFinding {
                category: "stale-locks".to_string(),
                id: lock_info_path.display().to_string(),
                summary: format!(
                    "cache lock-info from dead pid {} ({}) is {} old",
                    lock_info.pid,
                    if lock_info.command.trim().is_empty() {
                        "unknown command"
                    } else {
                        lock_info.command.as_str()
                    },
                    humanize_duration_secs(age_secs.max(0) as u64)
                ),
                action: format!("remove stale lock-info file {}", lock_info_path.display()),
                safe_heal: true,
            });
        }
    }

    // STORY-496: reap dead-PID agent-registry entries. A record under
    // `.aida/agents/` whose creator process is gone is confirmed multi-agent
    // drift — the `aida status` "Active agents" headline counts these corpses,
    // and no existing command cleans them up. Reap ONLY entries whose pid is
    // not alive (conservative: a reused/returned pid is left alone, handled by
    // the re-check at heal time). trace:STORY-496 | ai:claude
    {
        let agent_ctx = agent_registry::AgentClassifyContext::new(now, 30, Vec::new());
        for view in agent_registry::list_agent_views(project_root, &agent_ctx) {
            if !process_probe::pid_is_alive(view.pid) {
                push(DoctorFinding {
                    category: "dead-agents".to_string(),
                    id: format!("{}#{}", view.agent_type, view.pid),
                    summary: format!(
                        "agent `{}` (pid {}) is dead — its registry entry under \
                         .aida/agents/ was never reaped",
                        view.agent_type, view.pid
                    ),
                    action: format!(
                        "remove dead-agent registry entry for {}#{}",
                        view.agent_type, view.pid
                    ),
                    safe_heal: true,
                });
            }
        }
    }

    for lease in &leases {
        let worktree_exists = lease.worktree_path.exists();
        // BUG-511: review-verb leases classify by creator PID, not worktree.
        let state = lease_state_for(lease, &live_sessions, now);
        let pid_dead = lease
            .creator_pid
            .is_some_and(|pid| !process_probe::pid_is_alive(pid));
        let branch_merged = matches!(
            detect_merged_pr_for_branch_via_forge(project_root, &lease.branch),
            PrLookup::Found(_)
        );
        if matches!(state, LeaseState::Stale) || pid_dead || branch_merged {
            push(DoctorFinding {
                category: "stale-leases".to_string(),
                id: lease.id.clone(),
                summary: format!(
                    "{} owns {} on branch `{}` ({})",
                    lease.id,
                    lease.scope,
                    lease.branch,
                    if !worktree_exists {
                        "worktree missing".to_string()
                    } else if pid_dead {
                        "creator pid dead".to_string()
                    } else if branch_merged {
                        "branch merged".to_string()
                    } else {
                        state.label().to_string()
                    }
                ),
                action: format!("save patch if dirty, then end lease {}", lease.id),
                safe_heal: true,
            });
        }

        if matches!(
            store
                .get_requirement_by_spec_id(&lease.scope)
                .map(|req| &req.status),
            Some(RequirementStatus::Approved)
        ) {
            push(DoctorFinding {
                category: "spec-status-drift".to_string(),
                id: lease.scope.clone(),
                summary: format!(
                    "{} is Approved but lease {} is active",
                    lease.scope, lease.id
                ),
                action: "bump spec to In Progress".to_string(),
                safe_heal: true,
            });
        }
        if matches!(
            store
                .get_requirement_by_spec_id(&lease.scope)
                .map(|req| &req.status),
            Some(RequirementStatus::Done)
        ) {
            push(DoctorFinding {
                category: "spec-status-drift".to_string(),
                id: lease.id.clone(),
                summary: format!(
                    "{} is Done but lease {} is still active",
                    lease.scope, lease.id
                ),
                action: format!("confirm and end lease {}", lease.id),
                safe_heal: true,
            });
        }
    }

    for item in &cleanup.sticky_in_progress {
        push(DoctorFinding {
            category: "spec-status-drift".to_string(),
            id: item.spec_id.clone(),
            summary: format!(
                "{} is In Progress but no active lease holds it",
                item.spec_id
            ),
            action: "revert spec to Approved (no active lease found)".to_string(),
            safe_heal: true,
        });
    }

    for item in &cleanup.uncommitted_wip {
        let Some(scope) = item.scope.as_ref() else {
            continue;
        };
        let behind = branch_behind_main(project_root, &item.branch)
            .map(|(n, _)| n)
            .unwrap_or(0);
        if behind >= 100 {
            push(DoctorFinding {
                category: "abandoned-leases".to_string(),
                id: scope.clone(),
                summary: format!(
                    "{} has {} modified file(s) on `{}` {} commits behind main",
                    scope, item.modified_files, item.branch, behind
                ),
                action: "save salvage patch, end lease, remove worktree, re-brief from salvage"
                    .to_string(),
                safe_heal: true,
            });
        }
    }

    for item in &cleanup.branches_ahead_no_pr {
        push(DoctorFinding {
            category: "orphan-branches".to_string(),
            id: item.branch.clone(),
            summary: format!(
                "`{}` is {} commit(s) ahead of main with no open PR",
                item.branch, item.commits_ahead
            ),
            action: "operator decision: open PR, keep, or delete with --yes --force".to_string(),
            safe_heal: false,
        });
    }

    for item in &cleanup.stale_reviewer_leases {
        push(DoctorFinding {
            category: "stale-reviewer-leases".to_string(),
            id: item.lease_id.clone(),
            summary: format!(
                "reviewer lease {} points at merged PR-{}",
                item.lease_id, item.pr_number
            ),
            action: format!("end lease {}", item.lease_id),
            safe_heal: true,
        });
    }

    let lease_worktrees: std::collections::HashSet<std::path::PathBuf> = leases
        .iter()
        .map(|lease| {
            lease
                .worktree_path
                .canonicalize()
                .unwrap_or_else(|_| lease.worktree_path.clone())
        })
        .collect();
    let project_canon = project_root
        .canonicalize()
        .unwrap_or_else(|_| project_root.to_path_buf());
    for wt in list_worktrees(project_root) {
        let wt_canon = wt.path.canonicalize().unwrap_or_else(|_| wt.path.clone());
        if wt_canon == project_canon || wt.branch.as_deref() == Some("aida-store") {
            continue;
        }
        if !lease_worktrees.contains(&wt_canon) {
            push(DoctorFinding {
                category: "orphan-worktrees".to_string(),
                id: wt.path.display().to_string(),
                summary: format!("worktree {} has no active lease", wt.path.display()),
                action: "save patch if dirty, then git worktree remove".to_string(),
                safe_heal: true,
            });
        }
    }

    // TASK-570: surface orphan queue entries — rows whose backing spec
    // was deleted ("??? (deleted)" ghosts from auto-queued reviewer items).
    // `aida queue prune --orphaned` (TASK-537) is the direct cleanup verb;
    // the doctor mirrors its detection so `--heal` can route through this
    // category as part of the default "fix what's drifted" sweep.
    // trace:TASK-570 | ai:claude
    let queue_user_id = current_user_id(None);
    let queue_storage = Storage::new(project_root.join(".aida-store"));
    if let Ok(queue_entries) =
        queue_storage.queue_list(&queue_user_id, /* include_completed */ false)
    {
        let existing_ids: std::collections::HashSet<uuid::Uuid> =
            store.requirements.iter().map(|r| r.id).collect();
        for entry in &queue_entries {
            if existing_ids.contains(&entry.requirement_id) {
                continue;
            }
            let role = entry
                .for_role
                .as_deref()
                .map(|r| format!(" [for:{r}]"))
                .unwrap_or_default();
            let note = entry
                .note
                .as_deref()
                .map(|n| format!(" — {n}"))
                .unwrap_or_default();
            push(DoctorFinding {
                category: "orphan-queue-entries".to_string(),
                id: entry.requirement_id.to_string(),
                summary: format!(
                    "queue position {}{} points at deleted spec{}",
                    entry.position, role, note
                ),
                action: "remove orphan queue entry (aida queue prune --orphaned)".to_string(),
                safe_heal: true,
            });
        }
    }

    let pending_briefs = collect_agent_briefs(project_root, None, false)?;
    let lease_scopes: std::collections::HashSet<String> =
        leases.iter().map(|lease| lease.scope.clone()).collect();
    for brief in pending_briefs {
        if lease_scopes.contains(&brief.spec_id) {
            push(DoctorFinding {
                category: "brief-lease-drift".to_string(),
                id: brief.path.display().to_string(),
                summary: format!(
                    "pending brief for {} exists while a lease is active",
                    brief.spec_id
                ),
                action: format!(
                    "ack brief or end/re-brief: aida brief ack {}",
                    brief.path.display()
                ),
                safe_heal: false,
            });
        }
        if matches!(
            store
                .get_requirement_by_spec_id(&brief.spec_id)
                .map(|req| &req.status),
            Some(RequirementStatus::Completed | RequirementStatus::Rejected)
        ) {
            push(DoctorFinding {
                category: "brief-spec-drift".to_string(),
                id: brief.path.display().to_string(),
                summary: format!("pending brief targets terminal spec {}", brief.spec_id),
                action: format!("ack OBE brief {}", brief.path.display()),
                safe_heal: true,
            });
            push(DoctorFinding {
                category: "OBE-briefs".to_string(),
                id: brief.path.display().to_string(),
                summary: format!("brief for {} is obsolete", brief.spec_id),
                action: format!("ack OBE brief {}", brief.path.display()),
                safe_heal: true,
            });
        }
    }

    // TASK-752: tracked legacy centralized-backend artifacts on a git-canonical
    // project (requirements*.yaml / scaffold-report.html still in the tree while
    // the live store is the orphan aida-store branch). Cheap `git ls-files`
    // scan; the detector self-gates on distributed mode + orphan branch, so it
    // is a no-op on a legacy --centralized project that legitimately uses
    // requirements.yaml as its active store. trace:TASK-752 | ai:claude
    for path in detect_legacy_store_cruft(project_root) {
        push(DoctorFinding {
            category: "legacy-store-cruft".to_string(),
            id: path.clone(),
            summary: format!(
                "tracked legacy-store artifact `{}` on a git-canonical project",
                path
            ),
            action: "git rm the file + gitignore it (live store is the orphan aida-store branch)"
                .to_string(),
            safe_heal: true,
        });
    }

    // BUG-563: per-clone RUNTIME files (`.aida/node.toml`, `.aida/dispenser.toml`,
    // `.aida/*.lock`, `.aida/cache.db*`) wrongly TRACKED on the orphan aida-store
    // branch. Each clone's auto-sync rewrites node.toml with its own node id, so
    // every cross-clone store-leg rebase conflicts on it forever. Cheap
    // `git ls-files` scan IN THE `.aida-store` WORKTREE; the detector self-gates
    // on distributed mode + an attached store worktree. trace:BUG-563 | ai:claude
    for path in detect_store_tracked_runtime(project_root) {
        push(DoctorFinding {
            category: "store-tracked-runtime".to_string(),
            id: path.clone(),
            summary: format!(
                "per-clone runtime file `{}` is tracked on the orphan aida-store branch (every cross-clone rebase conflicts on it forever)",
                path
            ),
            action: "git rm --cached the file in the store worktree + gitignore it (per-clone runtime state must stay untracked)"
                .to_string(),
            safe_heal: true,
        });
    }

    out.sort_by(|a, b| a.category.cmp(&b.category).then(a.id.cmp(&b.id)));
    Ok(out)
}

fn normalize_doctor_category(raw: &str) -> Result<String> {
    let s = raw.trim().to_ascii_lowercase().replace('_', "-");
    let normalized = match s.as_str() {
        "stale-lease" | "stale-leases" | "leases" => "stale-leases",
        "abandoned-lease" | "abandoned-leases" | "abandoned" => "abandoned-leases",
        "brief-lease" | "brief-lease-drift" => "brief-lease-drift",
        "brief-spec" | "brief-spec-drift" => "brief-spec-drift",
        "spec-status" | "spec-status-drift" => "spec-status-drift",
        "orphan-worktree" | "orphan-worktrees" | "worktrees" => "orphan-worktrees",
        "orphan-branch" | "orphan-branches" | "branches" => "orphan-branches",
        // TASK-717: stale REMOTE branches (origin/*) verify-and-prune.
        // trace:TASK-717
        "stale-remote-branch"
        | "stale-remote-branches"
        | "remote-branch"
        | "remote-branches"
        | "remote-branch-prune" => "stale-remote-branches",
        // TASK-878: merged Agent-tool isolation worktrees
        // (.claude/worktrees/agent-* on worktree-agent-* branches) that
        // accumulate. trace:TASK-878 | ai:claude
        "merged-agent-worktree"
        | "merged-agent-worktrees"
        | "agent-worktree"
        | "agent-worktrees"
        | "worktree-gc"
        | "agent-worktree-gc" => "merged-agent-worktrees",
        "stale-reviewer" | "stale-reviewer-lease" | "stale-reviewer-leases" => {
            "stale-reviewer-leases"
        }
        "stale-lock" | "stale-locks" | "locks" => "stale-locks",
        "obe-brief" | "obe-briefs" | "obsolete-briefs" => "OBE-briefs",
        // TASK-570: orphan queue entries — "??? (deleted)" ghosts in
        // `aida queue list`. trace:TASK-570 | ai:claude
        "orphan-queue" | "orphan-queue-entry" | "orphan-queue-entries" | "queue-orphans" => {
            "orphan-queue-entries"
        }
        // STORY-496: dead-PID agent-registry entries (corpses under
        // `.aida/agents/`). trace:STORY-496 | ai:claude
        "dead-agent" | "dead-agents" | "stale-agent" | "stale-agents" | "agents" => "dead-agents",
        // TASK-673: Completed specs git can't corroborate. trace:TASK-673 | ai:claude
        "completed-without-commit"
        | "completed-without-commits"
        | "completed-no-commit"
        | "uncorroborated-completed"
        | "integrity" => "completed-without-commit",
        // TASK-696: ancestor CLAUDE.md/AGENTS.md @-imports resolving outside the
        // project (external-import bleed). trace:TASK-696 | ai:claude
        "external-import-bleed"
        | "external-imports"
        | "ancestor-claude"
        | "ancestor-bleed"
        | "bleed" => "external-import-bleed",
        // TASK-752: tracked legacy centralized-backend artifacts
        // (requirements*.yaml / scaffold-report.html) on a git-canonical
        // project. trace:TASK-752 | ai:claude
        "legacy-store-cruft" | "legacy-store" | "store-cruft" | "legacy-cruft"
        | "requirements-yaml" => "legacy-store-cruft",
        // BUG-563: per-clone runtime files (node.toml / dispenser.toml /
        // *.lock / cache.db*) wrongly tracked on the orphan aida-store branch.
        // trace:BUG-563 | ai:claude
        "store-tracked-runtime"
        | "store-runtime"
        | "tracked-runtime"
        | "store-node-toml"
        | "store-runtime-cruft" => "store-tracked-runtime",
        other => anyhow::bail!(
            "unknown doctor category `{}` (valid: stale-leases, abandoned-leases, \
             brief-lease-drift, brief-spec-drift, spec-status-drift, orphan-worktrees, \
             orphan-branches, stale-remote-branches, merged-agent-worktrees, \
             orphan-queue-entries, stale-reviewer-leases, stale-locks, dead-agents, \
             OBE-briefs, completed-without-commit, legacy-store-cruft, \
             store-tracked-runtime)",
            other
        ),
    };
    Ok(normalized.to_string())
}

/// Whether `category` (a normalized doctor category) is in scope given the
/// user's `--category` filter. `None` filter selects everything. Errors only
/// if the filter itself is an unknown category. trace:TASK-673 | ai:claude
fn doctor_category_selected(filter: Option<&str>, category: &str) -> Result<bool> {
    match filter {
        None => Ok(true),
        Some(raw) => Ok(normalize_doctor_category(raw)? == category),
    }
}

const COMPLETED_WITHOUT_COMMIT_RECENT_DAYS: i64 = 60;

fn default_completed_without_commit_recent_cutoff() -> Option<String> {
    let cutoff = chrono::Utc::now() - chrono::Duration::days(COMPLETED_WITHOUT_COMMIT_RECENT_DAYS);
    Some(cutoff.format("%Y-%m-%d").to_string())
}

fn completed_without_commit_expects_code(req_type: &RequirementType) -> bool {
    // trace:TASK-755 | ai:codex
    matches!(
        req_type,
        RequirementType::Functional
            | RequirementType::NonFunctional
            | RequirementType::System
            | RequirementType::User
            | RequirementType::ChangeRequest
            | RequirementType::Bug
            | RequirementType::Story
            | RequirementType::Task
    )
}

#[derive(Debug, Clone, Default)]
struct CompletedWithoutCommitScan {
    findings: Vec<DoctorFinding>,
    hidden_older: usize,
}

/// TASK-673: spec-graph ⟂ git tripwire. Returns a `completed-without-commit`
/// finding for every spec in `Completed` status that NO commit on the default
/// CODE branch references (by `(SPEC-ID)` subject/trailer) and that NO tracked
/// file at that branch carries a `// trace:SPEC-ID`. A Completed spec with zero
/// corroboration means the requirement graph is asserting work git has never
/// seen — the defense-in-depth companion to the BUG-449 MCP gate.
///
/// CRITICAL: scans the default CODE branch only (resolved via
/// `resolve_default_branch_ref`), never the orphan `aida-store` branch — whose
/// `update SPEC-NNN` bookkeeping commits mention the bare id and would mask
/// every violation. Plan commits are skipped (their trailer names planned, not
/// delivered, specs). `Done` specs are deliberately excluded: that is the
/// queue's "awaiting commit" transient, surfaced separately, so this check
/// targets only the harder Completed-without-corroboration case. Read-only.
///
/// `since` (a git ref/tag or ISO date) exempts specs last modified before that
/// point, quieting noise on legacy history predating trace conventions. The
/// reference scan itself always walks the FULL default-branch history so an old
/// corroborating commit is never missed. trace:TASK-673 | ai:claude
fn scan_completed_without_commit(
    project_root: &std::path::Path,
    store: &aida_core::models::RequirementsStore,
    since: Option<&str>,
) -> Vec<DoctorFinding> {
    scan_completed_without_commit_with_options(project_root, store, since, false).findings
}

/// Build the corroboration set: every spec-id any commit message references.
/// Scans the FULL message (subject + body) of each commit — a squash-merge
/// concatenates each child commit's `(SPEC-ID)` trailer into the BODY, so a
/// subject-only scan false-flags every squash-merged spec (BUG-606). Unions the
/// subject-trailer extractor (`(SPEC-ID)` / leading `SPEC-ID:`) with the
/// body-trailer extractor (skips code-like lines per BUG-412). Plan commits are
/// skipped — they name PLANNED, not shipped, specs (BUG-426). Pure + testable.
/// trace:BUG-606 | ai:claude
/// Full-history corroboration set for the default branch: every spec-id any
/// commit message references (subject + body, squash-body-aware). The
/// completed-without-commit and claimed-done-divergence detectors both rely on
/// this being COMPLETE — an incomplete set false-flags shipped specs.
/// trace:BUG-606 | ai:claude
fn referenced_spec_ids_on_default_branch(
    project_root: &std::path::Path,
) -> std::collections::HashSet<String> {
    let Some(default) = detect_default_branch_ref(project_root) else {
        return std::collections::HashSet::new();
    };
    let out = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["log", "-z", "--pretty=format:%B", &default])
        .output();
    match out {
        Ok(o) if o.status.success() => {
            let text = String::from_utf8_lossy(&o.stdout);
            referenced_spec_ids_from_messages(text.split('\0'))
        }
        _ => std::collections::HashSet::new(),
    }
}

fn referenced_spec_ids_from_messages<'a>(
    messages: impl IntoIterator<Item = &'a str>,
) -> std::collections::HashSet<String> {
    // Liberal token match: a spec-id can appear ANYWHERE in the message — a
    // clean `(TASK-1)` trailer, a squash body `… (BUG-110) (#144)`, a
    // punctuated `(BUG-109).`, or mid-prose `(ADR-3 / TASK-647), so …`. For a
    // CORROBORATION check ("is there ANY git evidence this spec exists"),
    // matching the id token anywhere is correct and conservative — a benign
    // over-match just means we don't false-flag, which the check explicitly
    // prefers over a missed reference. Anchored to UPPERCASE 2+-letter prefixes
    // so lowercase prose ("step-1") doesn't pollute; coincidental tokens like
    // `UTF-8` are harmless (no spec collides). trace:BUG-606 | ai:claude
    let re =
        regex::Regex::new(r"\b[A-Z]{2,}-[0-9]+(?:-[0-9]+)?\b").expect("valid spec-id token regex");
    // A bare `update SPEC-ID` subject is the `aida edit` orphan-store
    // bookkeeping commit — it exists for EVERY edited spec, so counting it as
    // corroboration would mask every violation (STORY-462). trace:BUG-606
    let bookkeeping_re = regex::Regex::new(r"(?i)^update\s+[A-Za-z]+-[0-9]+(?:-[0-9]+)?$")
        .expect("valid bookkeeping-subject regex");
    let mut referenced = std::collections::HashSet::new();
    for message in messages {
        let subject = message
            .lines()
            .find(|l| !l.trim().is_empty())
            .unwrap_or("")
            .trim();
        // Plan commits name PLANNED, not shipped, specs (BUG-426); bare
        // `update SPEC-ID` is store bookkeeping (STORY-462) — neither
        // corroborates a completion.
        if subject.is_empty() || is_plan_commit_subject(subject) || bookkeeping_re.is_match(subject)
        {
            continue;
        }
        for m in re.find_iter(message) {
            referenced.insert(m.as_str().to_ascii_uppercase());
        }
    }
    referenced
}

fn scan_completed_without_commit_with_options(
    project_root: &std::path::Path,
    store: &aida_core::models::RequirementsStore,
    since: Option<&str>,
    include_older: bool,
) -> CompletedWithoutCommitScan {
    use std::process::Command as PCmd;

    let completed: Vec<&aida_core::models::Requirement> = store
        .requirements
        .iter()
        .filter(|r| matches!(r.status, RequirementStatus::Completed))
        .filter(|r| completed_without_commit_expects_code(&r.req_type))
        .filter(|r| r.spec_id.is_some() || r.agreed_id.is_some())
        .collect();
    if completed.is_empty() {
        return CompletedWithoutCommitScan::default();
    }

    // No resolvable default branch (e.g. a store with no code repo) → we cannot
    // corroborate, so stay silent rather than flag every Completed spec.
    let Some(default_ref) = resolve_default_branch_ref(project_root) else {
        return CompletedWithoutCommitScan::default();
    };

    let git = |args: &[&str]| -> Option<String> {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).into_owned())
    };

    // ---- Reference set: spec ids named by commits on the default branch. ----
    // Full history (no --max-count) so an old corroborating commit is never
    // missed — the `since` cutoff bounds *flagging*, not the reference scan.
    // BUG-606: scan the FULL message (%B), not just the subject (%s). A
    // squash-merge keeps only the PR title as its subject and concatenates each
    // child commit's `(SPEC-ID)` trailer into the BODY, so a subject-only scan
    // false-flagged every squash-merged Completed spec (observed: ~1464 false
    // positives — specs with 10+ body-referencing commits reported as
    // "no commit referencing it"). `-z` NUL-delimits commits so multi-line
    // bodies parse unambiguously. trace:BUG-606 | ai:claude
    let mut referenced: std::collections::HashSet<String> =
        match git(&["log", "-z", "--pretty=format:%B", &default_ref]) {
            Some(log) => referenced_spec_ids_from_messages(log.split('\0')),
            None => std::collections::HashSet::new(),
        };

    // ---- Reference set, second source: `// trace:SPEC-ID` in tracked files. ----
    // `git grep <ref>` scans only tracked blobs at the default branch tree —
    // exactly "a tracked file carries the trace". Unioning trace hits keeps the
    // reference set as complete as possible so the check stays conservative
    // (false positives erode trust faster than the rare miss).
    if let Some(grep) = git(&[
        "grep",
        "-hoI",
        "-E",
        r"trace:[A-Za-z]+-[0-9]+(-[0-9]+)?",
        &default_ref,
    ]) {
        for line in grep.lines() {
            if let Some(id) = parse_trace_id_token(line) {
                referenced.insert(id);
            }
        }
    }

    // ---- Optional legacy-exemption cutoff. ----
    let cutoff = since.and_then(|s| resolve_completed_since_cutoff(project_root, s));

    let mut findings = Vec::new();
    let mut hidden_older = 0;
    for req in completed {
        let spec_id = req.spec_id.as_deref().or(req.agreed_id.as_deref());
        let Some(spec_id) = spec_id else { continue };
        let referenced_by_id = referenced.contains(&spec_id.to_ascii_uppercase())
            || req
                .agreed_id
                .as_deref()
                .map(|a| referenced.contains(&a.to_ascii_uppercase()))
                .unwrap_or(false)
            || req
                .spec_id
                .as_deref()
                .map(|s| referenced.contains(&s.to_ascii_uppercase()))
                .unwrap_or(false);
        if referenced_by_id {
            continue;
        }
        if let Some(cut) = cutoff {
            if !include_older && req.modified_at < cut {
                hidden_older += 1;
                continue;
            }
        }
        findings.push(DoctorFinding {
            category: "completed-without-commit".to_string(),
            id: spec_id.to_string(),
            summary: format!(
                "Completed spec {spec_id} has no commit referencing it on {default_ref} \
                 (and no tracked trace comment) — git cannot corroborate the completion"
            ),
            action: format!(
                "land a commit carrying `({spec_id})` then `aida pull`, or re-open for triage \
                 (`aida doctor --heal --category completed-without-commit --yes --force`)"
            ),
            // Re-opening a Completed spec is a real status mutation, never a
            // "safe" auto-fix — gated behind --yes --force like branch deletion.
            safe_heal: false,
        });
    }
    findings.sort_by(|a, b| a.id.cmp(&b.id));
    CompletedWithoutCommitScan {
        findings,
        hidden_older,
    }
}

// ============================================================================
// TASK-717 — `aida doctor`: verify-and-prune stale REMOTE branches.
//
// `aida doctor --heal --category orphan-branches` only deletes LOCAL orphan
// branches; stale `origin/*` branches accumulate and must be pruned by hand.
// This adds a `stale-remote-branches` category that surfaces remote branches
// and verify-and-prunes them with a squash-aware safety model:
//
//   safe-to-delete iff ANY of:
//     - the branch's spec is Completed/Rejected, OR
//     - the branch HEAD is an ancestor of origin/main (already merged), OR
//     - origin/main carries a commit referencing the spec `(SPEC-ID)`
//   AND none of the EXCLUDE conditions apply:
//     - the branch is a protected ref (main/master/aida-store), OR
//     - the branch has an open PR
//   AND the branch has NO genuinely-unique unmerged commits (those are KEPT
//   and flagged for the operator, never deleted).
//
// Dry-run by default (read-only list + per-branch verdict/reason); the heal
// is gated behind --yes --force (destructive remote deletion). trace:TASK-717
// ============================================================================

/// The classification verdict for one remote branch. trace:TASK-717
#[derive(Debug, Clone, PartialEq, Eq)]
enum RemoteBranchVerdict {
    /// Protected or open-PR — excluded from any consideration.
    Excluded(String),
    /// Verified merged/terminal AND no unique unmerged commits → safe to prune.
    SafeToDelete(String),
    /// Has genuinely-unique unmerged commits → keep, flag for the operator.
    Keep(String),
}

/// Inputs to the pure remote-branch classifier — every git/gh probe result the
/// safety model needs, gathered once per branch by the scanner. Keeping the
/// classification pure makes the squash-aware safety model unit-testable
/// without git or gh. trace:TASK-717
#[derive(Debug, Clone)]
struct RemoteBranchFacts {
    /// True when the branch is a protected ref (main/master/aida-store).
    protected: bool,
    /// True when an open PR currently has this branch as its head.
    has_open_pr: bool,
    /// True when the branch HEAD is an ancestor of origin/main (fully merged —
    /// covers fast-forward / non-squash merges).
    ancestor_of_main: bool,
    /// True when origin/main carries a commit whose subject/trailer references
    /// the branch's spec id (covers squash merges, where the branch tip keeps a
    /// different SHA but the work shipped).
    spec_referenced_on_main: bool,
    /// The branch's spec status, when the branch name maps to a known spec and
    /// that spec is Completed or Rejected (terminal). None otherwise.
    spec_terminal: bool,
    /// Count of commits on the branch not reachable from origin/main. Zero means
    /// nothing unique is at risk; non-zero with no other "merged" signal means
    /// the branch carries unique unmerged work that must be KEPT.
    unique_unmerged_commits: u32,
}

/// Pure squash-aware classification of one remote branch. No git/gh — every
/// input is pre-gathered in `RemoteBranchFacts`. This is the safety model:
/// excludes protected + open-PR branches first; declares safe-to-delete only on
/// a positive "merged/terminal" signal AND zero unique unmerged commits;
/// otherwise keeps the branch and flags it. trace:TASK-717
fn classify_stale_remote_branch(facts: &RemoteBranchFacts) -> RemoteBranchVerdict {
    // EXCLUDE first — protected and open-PR branches are never candidates.
    if facts.protected {
        return RemoteBranchVerdict::Excluded("protected ref".to_string());
    }
    if facts.has_open_pr {
        return RemoteBranchVerdict::Excluded("has an open PR".to_string());
    }

    // A positive "this work has shipped / is terminal" signal — any one suffices.
    let merged_reason = if facts.ancestor_of_main {
        Some("HEAD is an ancestor of origin/main (merged)")
    } else if facts.spec_referenced_on_main {
        Some("origin/main carries a commit referencing its spec (squash-merged)")
    } else if facts.spec_terminal {
        Some("its spec is Completed/Rejected")
    } else {
        None
    };

    let Some(merged_reason) = merged_reason else {
        // No merged/terminal signal at all → never delete; flag for the operator.
        return RemoteBranchVerdict::Keep(
            "no merge/terminal signal — operator decision".to_string(),
        );
    };

    // Even with a merged signal, a branch carrying genuinely-unique unmerged
    // commits (e.g. an unmerged migration-guide on a squash-merged branch) must
    // be KEPT — deleting it would lose work. Ancestor-of-main implies zero unique
    // commits, so this only bites the squash/terminal paths.
    if facts.unique_unmerged_commits > 0 && !facts.ancestor_of_main {
        return RemoteBranchVerdict::Keep(format!(
            "{merged_reason}, but {} unique unmerged commit(s) — keep, operator decision",
            facts.unique_unmerged_commits
        ));
    }

    RemoteBranchVerdict::SafeToDelete(merged_reason.to_string())
}

/// Derive the candidate spec id from a work-branch name (`task-281-foo` →
/// `TASK-281`). Returns None when the branch doesn't follow the work-branch
/// convention. trace:TASK-717
fn spec_id_from_work_branch(branch: &str) -> Option<String> {
    if !is_work_spec_branch_name(branch) {
        return None;
    }
    // `<type>-<digits>[-suffix...]` → keep `<type>-<digits>`.
    let mut parts = branch.splitn(3, '-');
    let kind = parts.next()?;
    let num = parts.next()?;
    if kind.is_empty() || num.is_empty() || !num.chars().next()?.is_ascii_digit() {
        return None;
    }
    // The number segment can carry a trailing `.suffix` (e.g. `epic-20.batch7`);
    // trim at the first non-digit so we land on the bare spec id.
    let digits: String = num.chars().take_while(|c| c.is_ascii_digit()).collect();
    if digits.is_empty() {
        return None;
    }
    Some(format!("{}-{}", kind.to_ascii_uppercase(), digits))
}

/// TASK-717: scan stale `origin/*` branches and classify each under the
/// squash-aware safety model. Read-only — performs git ancestry/rev-list probes
/// and one `gh pr list` for the open-PR set, never mutates anything. Returns a
/// `stale-remote-branches` finding for every branch that is either SafeToDelete
/// (verdict carries the merge reason; `safe_heal=false` so deletion stays gated
/// behind --yes --force) or Keep (flagged for the operator, never auto-healed).
/// Excluded branches produce no finding. trace:TASK-717
fn scan_stale_remote_branches(
    project_root: &std::path::Path,
    store: &aida_core::models::RequirementsStore,
) -> Vec<DoctorFinding> {
    use std::process::Command as PCmd;

    let git = |args: &[&str]| -> Option<String> {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
            .map(|o| String::from_utf8_lossy(&o.stdout).into_owned())
    };

    // No resolvable default branch → we cannot corroborate merges, so stay
    // silent rather than risk flagging every remote branch.
    let Some(default_ref) = resolve_default_branch_ref(project_root) else {
        return Vec::new();
    };

    // Spec ids referenced by commits on origin/main (squash-merge signal).
    let mut referenced_on_main: std::collections::HashSet<String> =
        std::collections::HashSet::new();
    if let Some(log) = git(&["log", "--pretty=format:%s", &default_ref]) {
        for subject in log.lines() {
            let subject = subject.trim();
            if subject.is_empty() || is_plan_commit_subject(subject) {
                continue;
            }
            for id in extract_spec_ids_from_commit(subject) {
                referenced_on_main.insert(id.to_ascii_uppercase());
            }
        }
    }

    let open_pr_branches = collect_open_prs(project_root).by_branch;
    const PROTECTED: &[&str] = &["main", "master", "aida-store", "HEAD"];

    let mut findings = Vec::new();
    for rc in collect_remote_branch_commits(project_root) {
        let branch = rc.branch;
        let protected = PROTECTED.iter().any(|p| p.eq_ignore_ascii_case(&branch));
        let has_open_pr = open_pr_branches.contains_key(&branch);

        // Ancestor-of-main check: empty `origin/main..origin/branch` rev-list.
        let ancestor_of_main = git(&[
            "rev-list",
            "--count",
            &format!("{default_ref}..origin/{branch}"),
        ])
        .and_then(|s| s.trim().parse::<u32>().ok())
        .map(|n| n == 0)
        .unwrap_or(false);

        // unique_unmerged_commits == ancestor-count above; reuse it.
        let unique_unmerged_commits = git(&[
            "rev-list",
            "--count",
            &format!("{default_ref}..origin/{branch}"),
        ])
        .and_then(|s| s.trim().parse::<u32>().ok())
        .unwrap_or(0);

        let spec_id = spec_id_from_work_branch(&branch);
        let spec_referenced_on_main = spec_id
            .as_deref()
            .map(|id| referenced_on_main.contains(&id.to_ascii_uppercase()))
            .unwrap_or(false);
        let spec_terminal = spec_id
            .as_deref()
            .and_then(|id| store.get_requirement_by_spec_id(id))
            .map(|req| {
                matches!(
                    req.status,
                    RequirementStatus::Completed | RequirementStatus::Rejected
                )
            })
            .unwrap_or(false);

        let facts = RemoteBranchFacts {
            protected,
            has_open_pr,
            ancestor_of_main,
            spec_referenced_on_main,
            spec_terminal,
            unique_unmerged_commits,
        };

        match classify_stale_remote_branch(&facts) {
            RemoteBranchVerdict::Excluded(_) => {
                // Protected / open-PR — never surfaced as a finding.
            }
            RemoteBranchVerdict::SafeToDelete(reason) => {
                findings.push(DoctorFinding {
                    category: "stale-remote-branches".to_string(),
                    id: branch.clone(),
                    summary: format!("remote branch `origin/{branch}` is stale ({reason})"),
                    action: format!(
                        "delete remote branch (`aida doctor --heal --category \
                         stale-remote-branches --yes --force`, or `git push origin \
                         --delete {branch}`)"
                    ),
                    // Remote deletion is destructive — gate behind --yes --force.
                    safe_heal: false,
                });
            }
            RemoteBranchVerdict::Keep(reason) => {
                findings.push(DoctorFinding {
                    category: "stale-remote-branches".to_string(),
                    id: branch.clone(),
                    summary: format!("remote branch `origin/{branch}` flagged: {reason}"),
                    action: "operator decision: review and keep, open a PR, or delete by hand"
                        .to_string(),
                    // Never auto-deleted — flag-only.
                    safe_heal: false,
                });
            }
        }
    }
    findings.sort_by(|a, b| a.id.cmp(&b.id));
    findings
}

/// TASK-717: delete one stale remote branch via `git push origin --delete`.
/// Only reachable when the finding's action surfaced it as SafeToDelete and the
/// caller passed --yes --force (see `heal_doctor_finding`). A Keep-flagged
/// branch never routes here — its action string is operator-only. trace:TASK-717
fn heal_doctor_stale_remote_branch(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    // Keep-flagged findings carry an operator-only action and must never be
    // auto-deleted, even under --yes --force.
    if !finding.action.contains("--category stale-remote-branches") {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some("flagged for operator decision — not auto-deleted".to_string()),
        });
    }
    let status = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["push", "origin", "--delete", &finding.id])
        .status()
        .with_context(|| format!("deleting remote branch origin/{}", finding.id))?;
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "deleted stale remote branch".to_string(),
        status: if status.success() { "healed" } else { "failed" }.to_string(),
        detail: None,
    })
}

// ============================================================================
// TASK-878: auto-GC merged Agent-tool worktrees.
//
// The Agent tool (and `aida agent new --isolation worktree`) leaves an isolated
// worktree under `.claude/worktrees/agent-<id>` on a `worktree-agent-<id>`
// branch. `git worktree prune` only removes worktrees whose DIRECTORY is gone —
// these keep their dir + branch, so they accumulate (98 piled up in one fan-out
// session, BUG-582) and the stale local branches make `aida human`'s
// reviews-awaiting view false-positive on already-merged work.
//
// This adds a `merged-agent-worktrees` doctor category that surfaces those
// worktrees and verify-and-removes them under a squash-aware safety model:
//
//   removable iff a positive "this work has shipped" signal AND no risk:
//     - the branch HEAD is an ancestor of origin/main (ff / non-squash merge), OR
//     - the branch's PR is MERGED on the forge (covers squash merges, where the
//       branch tip keeps a different SHA but the work shipped)
//   AND none of the KEEP conditions apply:
//     - the worktree has uncommitted changes (clean != no work — never delete), OR
//     - the branch carries genuinely-unique unmerged commits not in main
//   When NO merged signal exists at all, the worktree is KEPT and flagged for the
//   operator (never auto-removed).
//
// Read-only by default (list + per-worktree verdict). The heal is DESTRUCTIVE
// (removes a worktree + deletes its branch) so `safe_heal=false`: it routes
// through the STORY-666 destructive-heal gate — refused in an unattended /
// autonomous context, performed only under explicit interactive --yes --force
// sign-off. trace:TASK-878
// ============================================================================

/// Is this worktree one of the AIDA/Agent-tool managed isolation worktrees that
/// accumulate? Matched on EITHER the conventional path segment
/// (`.claude/worktrees/agent-<id>`) OR the conventional branch name
/// (`worktree-agent-<id>`) — both are stamped by the same launcher, and matching
/// either keeps detached or oddly-pathed cases in scope. Pure → unit-testable.
/// trace:TASK-878 | ai:claude
fn is_agent_managed_worktree(path: &std::path::Path, branch: Option<&str>) -> bool {
    let path_str = path.to_string_lossy().replace('\\', "/");
    let path_match = path_str.contains("/.claude/worktrees/agent-")
        || path_str.contains(".claude/worktrees/agent-");
    let branch_match = branch
        .map(|b| b.starts_with("worktree-agent-"))
        .unwrap_or(false);
    path_match || branch_match
}

/// The classification verdict for one agent-managed worktree. trace:TASK-878
#[derive(Debug, Clone, PartialEq, Eq)]
enum AgentWorktreeVerdict {
    /// Verified merged AND clean AND no unique unmerged commits → safe to GC.
    Removable(String),
    /// Dirty, carrying unmerged work, or no merge signal → keep, flag operator.
    Keep(String),
}

/// Inputs to the pure agent-worktree classifier — every git/forge probe result
/// the safety model needs, gathered once per worktree by the scanner. Keeping
/// the classification pure makes the squash-aware safety model unit-testable
/// without git or a forge. trace:TASK-878
#[derive(Debug, Clone)]
struct AgentWorktreeFacts {
    /// True when the worktree has uncommitted changes (tracked or staged dirt,
    /// or untracked files). A dirty worktree is NEVER removed — clean != no work,
    /// and dirty is unambiguously "has work".
    dirty: bool,
    /// True when the branch HEAD is an ancestor of origin/main (fully merged —
    /// covers fast-forward / non-squash merges; implies zero unique commits).
    ancestor_of_main: bool,
    /// True when the forge reports a MERGED PR for this branch (covers squash
    /// merges, where the branch tip keeps a different SHA but the work shipped).
    pr_merged: bool,
    /// Count of commits on the branch not reachable from origin/main. Zero means
    /// nothing unique is at risk; non-zero with no ancestor signal means the
    /// branch carries unique unmerged work that must be KEPT.
    unique_unmerged_commits: u32,
}

/// Pure squash-aware classification of one agent-managed worktree. No git/forge
/// — every input is pre-gathered in `AgentWorktreeFacts`. This is the safety
/// model: a dirty worktree is always kept; removal needs a positive merged
/// signal AND zero unique unmerged commits; otherwise the worktree is kept and
/// flagged. trace:TASK-878 | ai:claude
fn classify_agent_worktree(facts: &AgentWorktreeFacts) -> AgentWorktreeVerdict {
    // KEEP first — uncommitted work is unambiguously "has work". Clean != no
    // work, but dirty is definitely work; never delete it.
    if facts.dirty {
        return AgentWorktreeVerdict::Keep(
            "uncommitted changes present — never auto-removed".to_string(),
        );
    }

    // A positive "this work has shipped" signal — either suffices.
    let merged_reason = if facts.ancestor_of_main {
        Some("branch is an ancestor of origin/main (merged)")
    } else if facts.pr_merged {
        Some("its PR is merged (squash-merged)")
    } else {
        None
    };

    let Some(merged_reason) = merged_reason else {
        // No merged signal at all → never remove; flag for the operator.
        return AgentWorktreeVerdict::Keep("no merge signal — operator decision".to_string());
    };

    // Even with a merged signal, a branch carrying genuinely-unique unmerged
    // commits (e.g. extra commits added after the PR squash-merged) must be KEPT
    // — removing it would lose work. Ancestor-of-main implies zero unique
    // commits, so this only bites the squash-merge path.
    if facts.unique_unmerged_commits > 0 && !facts.ancestor_of_main {
        return AgentWorktreeVerdict::Keep(format!(
            "{merged_reason}, but {} unique unmerged commit(s) — keep, operator decision",
            facts.unique_unmerged_commits
        ));
    }

    AgentWorktreeVerdict::Removable(merged_reason.to_string())
}

// ============================================================================
// BUG-614: conservative worktree GC.
//
// `git worktree prune` (lossless, run on session-end) removes only the
// administrative entries whose directories are already gone — never a live
// worktree. The explicit operator GC (`aida session gc`) is the destructive
// half: it removes a `.claude/worktrees/agent-*` worktree ONLY when ALL of
//   - its branch is merged into the default branch OR gone, AND
//   - the worktree is CLEAN (no uncommitted/untracked changes), AND
//   - it is NOT locked (no `locked` line in `git worktree list --porcelain`),
//     AND
//   - no live process / active session-lease references it.
// hold. Anything else is PRESERVED and reported. Removal uses
// `git worktree remove` (NOT `--force`) so git's own safety checks add a second
// guard; if git refuses we SKIP (never `-f`) and report. trace:BUG-614
// ============================================================================

/// BUG-614: lossless prune of dead worktree bookkeeping. `git worktree prune`
/// only removes administrative entries for worktrees whose directories no
/// longer exist — it never deletes a live worktree, so this is always safe.
/// Best-effort and quiet: a spawn/exec failure is swallowed (the caller treats
/// it as a non-event). trace:BUG-614 | ai:claude
fn lossless_prune_worktrees(project_root: &std::path::Path) {
    let _ = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["worktree", "prune"])
        .output();
}

/// BUG-614: the GC eligibility verdict for one agent-managed worktree.
#[derive(Debug, Clone, PartialEq, Eq)]
enum WorktreeGcVerdict {
    /// All four safety predicates hold → safe for the operator GC to remove.
    Eligible,
    /// At least one predicate fails → PRESERVE and report the reason.
    Preserve(String),
}

/// BUG-614: pure inputs to the conservative GC predicate — every probe result
/// the safety model needs, gathered once per worktree by the scanner. Keeping
/// the predicate pure (no git/lease/process probes) makes the four safety
/// gates exhaustively unit-testable. trace:BUG-614 | ai:claude
#[derive(Debug, Clone)]
struct WorktreeGcFacts {
    /// True when this worktree is one of the `.claude/worktrees/agent-*` /
    /// `worktree-agent-*` isolation worktrees (the only ones the GC touches).
    is_agent_managed: bool,
    /// True when the branch is merged into the default branch OR is gone
    /// (detached / branch deleted). A worktree whose branch carries unmerged
    /// work is never GC'd.
    merged_or_gone: bool,
    /// True when the worktree has uncommitted/untracked changes. Dirty is
    /// unambiguously "has work" — never removed.
    dirty: bool,
    /// True when `git worktree list --porcelain` reports a `locked` line for
    /// this worktree. A locked worktree is operator-protected — never removed.
    locked: bool,
    /// True when a live process or an active session-lease references this
    /// worktree (a session is in flight there). Never removed.
    has_active_lease: bool,
}

/// BUG-614: the conservative GC predicate. Removal requires ALL of:
/// agent-managed AND merged-or-gone AND clean AND unlocked AND no active lease.
/// Any failing gate PRESERVES the worktree with a human-readable reason. The
/// order is deliberate: cheapest / most-protective signals first so the reason
/// names the strongest objection. Default-to-preserve: an unrecognized state
/// is kept, never removed. trace:BUG-614 | ai:claude
fn classify_worktree_gc(facts: &WorktreeGcFacts) -> WorktreeGcVerdict {
    if !facts.is_agent_managed {
        return WorktreeGcVerdict::Preserve("not an agent-managed worktree".to_string());
    }
    // Dirty first — uncommitted work is the costliest thing to lose.
    if facts.dirty {
        return WorktreeGcVerdict::Preserve(
            "uncommitted changes present — never auto-removed".to_string(),
        );
    }
    if facts.locked {
        return WorktreeGcVerdict::Preserve("worktree is locked — operator-protected".to_string());
    }
    if facts.has_active_lease {
        return WorktreeGcVerdict::Preserve(
            "an active session/process references it — in flight".to_string(),
        );
    }
    if !facts.merged_or_gone {
        return WorktreeGcVerdict::Preserve(
            "branch is not merged into the default branch — unmerged work".to_string(),
        );
    }
    WorktreeGcVerdict::Eligible
}

/// BUG-614: the set of worktree paths (canonicalized) that a live process or an
/// active session-lease references. Two sources, unioned:
///   1. session leases whose `worktree_path` resolves to a live state
///      ([`lease_state_for`] == Live) — a session is genuinely in flight there;
///   2. live `claude` processes whose cwd sits inside a worktree (covers
///      Agent-tool worktrees that carry no AIDA lease).
/// A path appearing in either set is "active" and must never be GC'd.
/// trace:BUG-614 | ai:claude
fn active_worktree_paths(project_root: &std::path::Path) -> HashSet<std::path::PathBuf> {
    let canon = |p: &std::path::Path| p.canonicalize().unwrap_or_else(|_| p.to_path_buf());
    let mut out: HashSet<std::path::PathBuf> = HashSet::new();
    let now = chrono::Utc::now();
    let live = process_probe::probe_live_claude_sessions();
    // (1) live session leases.
    for lease in list_leases(project_root) {
        if lease.worktree_path.as_os_str().is_empty() {
            continue;
        }
        if matches!(lease_state_for(&lease, &live, now), LeaseState::Live) {
            out.insert(canon(&lease.worktree_path));
        }
    }
    // (2) live claude processes whose cwd is a (non-stale) real directory.
    for s in &live {
        if s.stale_cwd {
            continue;
        }
        out.insert(canon(&s.cwd));
    }
    out
}

/// BUG-614: does any active worktree path equal `wt` or sit beneath it? A live
/// process one level down still pins the worktree. trace:BUG-614 | ai:claude
fn worktree_is_active(wt: &std::path::Path, active: &HashSet<std::path::PathBuf>) -> bool {
    let wt_canon = wt.canonicalize().unwrap_or_else(|_| wt.to_path_buf());
    active
        .iter()
        .any(|a| *a == wt_canon || a.starts_with(&wt_canon))
}

/// BUG-614: is this worktree locked? Parses `git worktree list --porcelain` and
/// reports whether the record for `wt` carries a bare `locked` line (git emits
/// `locked` with an optional reason after it). Read-only; false on any git
/// failure so a probe error never makes us treat a worktree as removable.
/// trace:BUG-614 | ai:claude
fn worktree_is_locked(project_root: &std::path::Path, wt: &std::path::Path) -> bool {
    let out = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["worktree", "list", "--porcelain"])
        .output();
    let Ok(out) = out else { return false };
    if !out.status.success() {
        return false;
    }
    let wt_canon = wt.canonicalize().unwrap_or_else(|_| wt.to_path_buf());
    let text = String::from_utf8_lossy(&out.stdout);
    let mut cur_match = false;
    for line in text.lines() {
        if let Some(p) = line.strip_prefix("worktree ") {
            let rec = std::path::PathBuf::from(p);
            let rec_canon = rec.canonicalize().unwrap_or(rec);
            cur_match = rec_canon == wt_canon;
        } else if cur_match && (line == "locked" || line.starts_with("locked ")) {
            return true;
        }
    }
    false
}

/// BUG-614: `aida session gc` — the explicit operator GC of stale agent
/// worktrees. Scans every `.claude/worktrees/agent-*` worktree, gathers the
/// four safety facts, and (unless `--dry-run`) runs `git worktree remove` (NOT
/// `--force`) on the ones the pure predicate calls Eligible. Anything preserved
/// is reported with its reason; a worktree git itself refuses to remove is
/// SKIPPED (never force-removed) and reported. Always runs the lossless prune
/// first. Never invoked on the hot `aida status` read path — only on this
/// explicit operator command. trace:BUG-614 | ai:claude
fn session_gc(dry_run: bool, yes: bool) -> Result<()> {
    let project_root = find_project_root()?;

    // Lossless first — clears dead bookkeeping cheaply regardless of the GC.
    lossless_prune_worktrees(&project_root);

    let default_ref = resolve_default_branch_ref(&project_root);
    let project_canon = project_root
        .canonicalize()
        .unwrap_or_else(|_| project_root.to_path_buf());
    let active = active_worktree_paths(&project_root);

    let git_count = |args: &[&str]| -> Option<u32> {
        std::process::Command::new("git")
            .arg("-C")
            .arg(&project_root)
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
            .and_then(|o| {
                String::from_utf8_lossy(&o.stdout)
                    .trim()
                    .parse::<u32>()
                    .ok()
            })
    };

    let mut eligible: Vec<(std::path::PathBuf, Option<String>)> = Vec::new();
    let mut preserved: Vec<(std::path::PathBuf, String)> = Vec::new();

    for wt in list_worktrees(&project_root) {
        let wt_canon = wt.path.canonicalize().unwrap_or_else(|_| wt.path.clone());
        // Never touch the main worktree or the store worktree.
        if wt_canon == project_canon || wt.branch.as_deref() == Some("aida-store") {
            continue;
        }
        let is_agent_managed = is_agent_managed_worktree(&wt.path, wt.branch.as_deref());
        if !is_agent_managed {
            continue;
        }

        // merged_or_gone: a detached/branchless agent worktree counts as "gone"
        // (no branch ⇒ nothing unmerged to lose); a branch is merged when it has
        // zero commits beyond the default ref. Without a resolvable default ref
        // we cannot prove merged-ness — treat as NOT merged (preserve).
        let merged_or_gone = match (wt.branch.as_deref(), default_ref.as_deref()) {
            (None, _) => true,
            (Some(branch), Some(default_ref)) => {
                git_count(&["rev-list", "--count", &format!("{default_ref}..{branch}")])
                    .map(|n| n == 0)
                    .unwrap_or(false)
            }
            (Some(_), None) => false,
        };

        let facts = WorktreeGcFacts {
            is_agent_managed,
            merged_or_gone,
            dirty: !worktree_dirty_entries(&wt.path).is_empty(),
            locked: worktree_is_locked(&project_root, &wt.path),
            has_active_lease: worktree_is_active(&wt.path, &active),
        };

        match classify_worktree_gc(&facts) {
            WorktreeGcVerdict::Eligible => eligible.push((wt.path.clone(), wt.branch.clone())),
            WorktreeGcVerdict::Preserve(reason) => preserved.push((wt.path.clone(), reason)),
        }
    }

    if eligible.is_empty() && preserved.is_empty() {
        println!("No agent-managed worktrees found — nothing to GC.");
        return Ok(());
    }

    if !preserved.is_empty() {
        println!(
            "Preserved {} worktree(s) (kept by design):",
            preserved.len()
        );
        for (path, reason) in &preserved {
            println!("  {} {} — {}", "keep".yellow(), path.display(), reason);
        }
    }

    if eligible.is_empty() {
        println!("No worktree is GC-eligible (merged + clean + unlocked + no active lease).");
        return Ok(());
    }

    println!(
        "{} agent worktree(s) are GC-eligible (merged + clean + unlocked + no active lease):",
        eligible.len()
    );
    for (path, branch) in &eligible {
        match branch {
            Some(b) => println!("  {} {} (branch `{}`)", "remove".cyan(), path.display(), b),
            None => println!("  {} {} (detached)", "remove".cyan(), path.display()),
        }
    }

    if dry_run {
        println!("\n--dry-run: no worktrees removed. Re-run without --dry-run to GC them.");
        return Ok(());
    }

    if !yes {
        use std::io::Write;
        eprint!(
            "\nRemove the {} eligible worktree(s)? [y/N] ",
            eligible.len()
        );
        std::io::stderr().flush()?;
        let mut ans = String::new();
        std::io::stdin().read_line(&mut ans)?;
        if !matches!(ans.trim().to_ascii_lowercase().as_str(), "y" | "yes") {
            println!("Aborted — nothing removed.");
            return Ok(());
        }
    }

    let mut removed = 0usize;
    let mut skipped = 0usize;
    for (path, _branch) in &eligible {
        // `git worktree remove` (NOT --force): git re-checks the worktree is
        // clean and unlocked and refuses otherwise — a second guard on top of
        // our predicate. On refusal we SKIP (never force) and report.
        // trace:BUG-614 | ai:claude
        let res = std::process::Command::new("git")
            .arg("-C")
            .arg(&project_root)
            .args(["worktree", "remove"])
            .arg(path)
            .output();
        match res {
            Ok(o) if o.status.success() => {
                removed += 1;
                println!(
                    "  {} removed {}",
                    crate::glyph(crate::glyphs::Glyph::Check).green(),
                    path.display()
                );
            }
            Ok(o) => {
                skipped += 1;
                let err = String::from_utf8_lossy(&o.stderr);
                println!(
                    "  {} git refused to remove {} — kept (not forced): {}",
                    "skip".yellow(),
                    path.display(),
                    err.trim()
                );
            }
            Err(e) => {
                skipped += 1;
                println!(
                    "  {} could not spawn git for {} — kept: {}",
                    "skip".yellow(),
                    path.display(),
                    e
                );
            }
        }
    }

    // Lossless tidy of any bookkeeping the removals left behind.
    lossless_prune_worktrees(&project_root);

    println!(
        "\nGC complete: {} removed, {} skipped, {} preserved.",
        removed,
        skipped,
        preserved.len()
    );
    Ok(())
}

/// TASK-878: scan AIDA/Agent-tool managed worktrees and classify each under the
/// squash-aware safety model. Read-only — performs git ancestry/rev-list probes
/// and one forge merged-PR lookup per branch, never mutates anything. Returns a
/// `merged-agent-worktrees` finding for every agent worktree that is either
/// Removable (verified merged + clean + no unique commits; `safe_heal=false` so
/// removal stays gated behind --yes --force + the STORY-666 sign-off) or Keep
/// (flagged for the operator, never auto-removed). The project's own worktree
/// and the `aida-store` worktree are skipped. trace:TASK-878
fn scan_merged_agent_worktrees(project_root: &std::path::Path) -> Vec<DoctorFinding> {
    use std::process::Command as PCmd;

    let git = |args: &[&str]| -> Option<u32> {
        PCmd::new("git")
            .arg("-C")
            .arg(project_root)
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
            .and_then(|o| {
                String::from_utf8_lossy(&o.stdout)
                    .trim()
                    .parse::<u32>()
                    .ok()
            })
    };

    // Without a resolvable default branch we cannot corroborate merges; stay
    // silent rather than risk flagging live worktrees.
    let Some(default_ref) = resolve_default_branch_ref(project_root) else {
        return Vec::new();
    };

    let project_canon = project_root
        .canonicalize()
        .unwrap_or_else(|_| project_root.to_path_buf());

    let mut findings = Vec::new();
    for wt in list_worktrees(project_root) {
        let wt_canon = wt.path.canonicalize().unwrap_or_else(|_| wt.path.clone());
        // Never touch the main worktree or the store worktree.
        if wt_canon == project_canon || wt.branch.as_deref() == Some("aida-store") {
            continue;
        }
        if !is_agent_managed_worktree(&wt.path, wt.branch.as_deref()) {
            continue;
        }
        let Some(branch) = wt.branch.as_deref() else {
            // A detached agent worktree carries no branch to verify against
            // origin/main — keep it; the operator can inspect by hand.
            findings.push(DoctorFinding {
                category: "merged-agent-worktrees".to_string(),
                id: wt.path.display().to_string(),
                summary: format!(
                    "agent worktree {} is detached (no branch) — flagged",
                    wt.path.display()
                ),
                action: "operator decision: inspect, then `git worktree remove` by hand"
                    .to_string(),
                safe_heal: false,
            });
            continue;
        };

        let dirty = !worktree_dirty_entries(&wt.path).is_empty();
        let ancestor_of_main = git(&["rev-list", "--count", &format!("{default_ref}..{branch}")])
            .map(|n| n == 0)
            .unwrap_or(false);
        let unique_unmerged_commits =
            git(&["rev-list", "--count", &format!("{default_ref}..{branch}")]).unwrap_or(0);
        // Only consult the forge when the cheap ancestry probe was inconclusive
        // (covers the squash-merge case) and the worktree is clean — a dirty
        // worktree is kept regardless, so skip the network call.
        let pr_merged = if !ancestor_of_main && !dirty {
            matches!(
                detect_merged_pr_for_branch_via_forge(project_root, branch),
                PrLookup::Found(_)
            )
        } else {
            false
        };

        let facts = AgentWorktreeFacts {
            dirty,
            ancestor_of_main,
            pr_merged,
            unique_unmerged_commits,
        };

        match classify_agent_worktree(&facts) {
            AgentWorktreeVerdict::Removable(reason) => {
                findings.push(DoctorFinding {
                    category: "merged-agent-worktrees".to_string(),
                    id: wt.path.display().to_string(),
                    summary: format!(
                        "agent worktree {} on `{branch}` is mergeable-and-gone ({reason})",
                        wt.path.display()
                    ),
                    action: format!(
                        "remove worktree + delete branch `{branch}` (`aida doctor --heal \
                         --category merged-agent-worktrees --yes --force`)"
                    ),
                    // DESTRUCTIVE (worktree removal + branch deletion) → gated
                    // behind --yes --force AND the STORY-666 autonomous-context
                    // refusal in `heal_doctor_findings`.
                    safe_heal: false,
                });
            }
            AgentWorktreeVerdict::Keep(reason) => {
                findings.push(DoctorFinding {
                    category: "merged-agent-worktrees".to_string(),
                    id: wt.path.display().to_string(),
                    summary: format!(
                        "agent worktree {} on `{branch}` flagged: {reason}",
                        wt.path.display()
                    ),
                    action: "operator decision: review and keep, or remove by hand".to_string(),
                    // Never auto-removed — flag-only.
                    safe_heal: false,
                });
            }
        }
    }
    findings.sort_by(|a, b| a.id.cmp(&b.id));
    findings
}

/// TASK-878: remove one merged agent worktree + delete its branch. Only
/// reachable when the finding surfaced it as Removable AND the caller passed
/// --yes --force under an interactive (non-autonomous) context — the STORY-666
/// destructive-heal gate in `heal_doctor_findings` fails closed otherwise. A
/// Keep-flagged worktree never routes here (its action string is operator-only).
/// Re-verifies the worktree is still clean right before removing (a salvage
/// patch is written if anything appeared since the scan) and only deletes the
/// branch after the worktree is gone. trace:TASK-878 | ai:claude
fn heal_doctor_merged_agent_worktree(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    // Keep-flagged findings carry an operator-only action and must never be
    // auto-removed, even under --yes --force.
    if !finding.action.contains("--category merged-agent-worktrees") {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some("flagged for operator decision — not auto-removed".to_string()),
        });
    }
    let worktree = std::path::PathBuf::from(&finding.id);
    if !worktree.exists() {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some(format!("{} already gone", worktree.display())),
        });
    }

    // Resolve the worktree's branch so we can delete it after removal.
    let branch = list_worktrees(project_root)
        .into_iter()
        .find(|wt| {
            wt.path.canonicalize().unwrap_or_else(|_| wt.path.clone())
                == worktree.canonicalize().unwrap_or_else(|_| worktree.clone())
        })
        .and_then(|wt| wt.branch);

    // Re-check: never delete uncommitted work that appeared between scan and
    // heal. Salvage anything dirty, then refuse to remove. trace:TASK-878
    if !worktree_dirty_entries(&worktree).is_empty() {
        let salvage =
            salvage_worktree_patch(project_root, "merged-agent-worktree", None, &worktree)?;
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some(format!(
                "worktree became dirty since scan — NOT removed{}",
                salvage
                    .map(|p| format!(" (salvage patch: {})", p.display()))
                    .unwrap_or_default()
            )),
        });
    }

    // STORY-714: shared teardown — pre_destroy cargo-clean hook (TASK-0396)
    // fires before removal, and a pooled tree is deregistered from the registry.
    let removed = aida_core::worktree_pool_destroy::teardown_worktree_path(
        project_root,
        &worktree,
        &worktree_pool_global_hooks("pre_destroy"),
    );
    if removed.is_err() {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "failed".to_string(),
            detail: Some(format!("git worktree remove {} failed", worktree.display())),
        });
    }

    // Delete the now-unused local branch (the stale-branch source of the
    // `aida human` false-positives). `-D` because a squash-merged branch isn't
    // recognized as merged by `-d`, and the scan already verified it shipped.
    let mut detail = None;
    if let Some(branch) = branch {
        let deleted = std::process::Command::new("git")
            .arg("-C")
            .arg(project_root)
            .args(["branch", "-D", &branch])
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        detail = Some(if deleted {
            format!("removed worktree + deleted branch `{branch}`")
        } else {
            format!("removed worktree (branch `{branch}` delete failed or already gone)")
        });
    }

    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "removed merged agent worktree".to_string(),
        status: "healed".to_string(),
        detail,
    })
}

/// Parse the spec id out of a `git grep -o` hit on the trace regex. The line is
/// the matched text (`trace:SPEC-ID`), possibly carrying a `ref:file:` prefix
/// git adds when grepping a tree; we locate the last `trace:` and read the id
/// after it. Returns the id upper-cased, or None if the token is malformed.
/// trace:TASK-673 | ai:claude
fn parse_trace_id_token(line: &str) -> Option<String> {
    let idx = line.rfind("trace:")?;
    let rest = &line[idx + "trace:".len()..];
    let end = rest
        .find(|c: char| !(c.is_ascii_alphanumeric() || c == '-'))
        .unwrap_or(rest.len());
    let tok = &rest[..end];
    // Shape: <ALPHA>+ '-' <DIGITS> (optional '-<DIGITS>'). Guard against a bare
    // word or a leading digit so non-spec `trace:` strings don't pollute the set.
    let first_alpha = tok.chars().next().is_some_and(|c| c.is_ascii_alphabetic());
    if first_alpha && tok.contains('-') {
        Some(tok.to_ascii_uppercase())
    } else {
        None
    }
}

/// Resolve a `--since` value to a UTC cutoff: first try it as a git ref/tag and
/// take that commit's committer date; failing that, parse it as an RFC-3339
/// datetime or a bare `YYYY-MM-DD` date. None if it resolves to neither.
/// trace:TASK-673 | ai:claude
fn resolve_completed_since_cutoff(
    project_root: &std::path::Path,
    since: &str,
) -> Option<chrono::DateTime<chrono::Utc>> {
    use std::process::Command as PCmd;
    let out = PCmd::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["log", "-1", "--format=%cI", since])
        .output()
        .ok();
    if let Some(o) = out {
        if o.status.success() {
            let s = String::from_utf8_lossy(&o.stdout).trim().to_string();
            if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(&s) {
                return Some(dt.with_timezone(&chrono::Utc));
            }
        }
    }
    if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(since) {
        return Some(dt.with_timezone(&chrono::Utc));
    }
    if let Ok(d) = chrono::NaiveDate::parse_from_str(since, "%Y-%m-%d") {
        let naive = d.and_hms_opt(0, 0, 0)?;
        return Some(chrono::DateTime::<chrono::Utc>::from_naive_utc_and_offset(
            naive,
            chrono::Utc,
        ));
    }
    None
}

/// The heavy orientation diagnostics moved off bare `aida status`
/// and onto `aida doctor`. Prints the PR/CI status (a `gh` network call),
/// live-session/lease liveness + fleet roster, the Claude Code presence line,
/// the worktree pane, the open-PR roster, and cross-clone coordination claims —
/// the same section printers `aida status --full` uses. Constructs the cached
/// backend on demand (the doctor's own load goes through the legacy `Storage`
/// path) so `collect_user_context` has the cache-backed handle it needs. Each
/// section graceful-degrades on its own data; best-effort — a backend that can't
/// be opened simply prints nothing here rather than failing the doctor run.
// trace:STORY-707 | ai:claude
fn print_doctor_status_diagnostics(
    project_root: &std::path::Path,
    store: &aida_core::models::RequirementsStore,
) {
    let store_path = project_root.join(".aida-store");
    let Ok(dispenser) = load_dispenser(&store_path) else {
        return;
    };
    let Ok(inner) = aida_core::GitBackend::new(&store_path).map(|b| b.with_dispenser(dispenser))
    else {
        return;
    };
    let cache_path = aida_core::CachedGitBackend::default_cache_path(&store_path);
    let Ok(backend) = aida_core::CachedGitBackend::with_inner(inner, &cache_path) else {
        return;
    };

    println!();
    println!("{}", "─── Status diagnostics ───".bold());
    println!(
        "  {}",
        "(moved off `aida status` so the default snapshot stays instant — STORY-707)".dimmed()
    );
    println!();

    // The full user-context gather: PR/CI (gh), branch facts, queue snapshot,
    // and the live-session-probed agent roster. This is the ~16s the fast
    // `aida status` no longer pays — it lives here now.
    let user_ctx = collect_user_context(project_root, store, &backend, false);

    print_status_pr_section(&user_ctx, false);
    print_status_queue_section(&user_ctx, false);
    print_status_presence_line(project_root);
    print_status_agents_section(&user_ctx, true);
    print_status_claude_code_section(project_root);
    print_status_worktrees_section(project_root, true);
    print_status_open_prs_section(project_root, true);
    print_status_coordination_section(&store_path, chrono::Utc::now(), true);
}

fn render_doctor_report(report: &DoctorReport, healed: bool) -> Result<()> {
    println!("{}", "─── AIDA doctor ───".bold());
    if report.findings.is_empty() && report.hidden_completed_without_commit == 0 {
        println!(
            "  {} no multi-agent state drift detected",
            crate::glyph(crate::glyphs::Glyph::Check).green()
        );
    } else {
        let mut current = "";
        for finding in &report.findings {
            if current != finding.category {
                current = &finding.category;
                println!();
                println!(
                    "{} {}",
                    crate::glyph(crate::glyphs::Glyph::Bullet).cyan(),
                    current.bold()
                );
            }
            let safety = if finding.safe_heal { "safe" } else { "manual" };
            println!("  - {} [{}]", finding.summary, safety.dimmed());
            println!("    → {}", finding.action.dimmed());
        }
        if report.hidden_completed_without_commit > 0 {
            if current != "completed-without-commit" {
                println!();
                println!(
                    "{} {}",
                    crate::glyph(crate::glyphs::Glyph::Bullet).cyan(),
                    "completed-without-commit".bold()
                );
            }
            println!(
                "  ({} older completed-without-commit finding{} hidden — pass --all to list)",
                report.hidden_completed_without_commit,
                if report.hidden_completed_without_commit == 1 {
                    ""
                } else {
                    "s"
                }
            );
        }
        println!();
        println!(
            "  Total: {} visible finding{}",
            report.findings.len(),
            if report.findings.len() == 1 { "" } else { "s" }
        );
    }

    if healed {
        println!();
        println!("{}", "─── Heal results ───".bold());
        if report.healed.is_empty() {
            println!("  (no heal actions applied)");
        }
        for result in &report.healed {
            println!(
                "  - {} {}: {}",
                result.status.as_str().bold(),
                result.id,
                result.action
            );
            if let Some(detail) = &result.detail {
                println!("    {}", detail.dimmed());
            }
        }
    } else if !report.findings.is_empty() {
        println!("  Re-run with {} to apply safe fixes.", "--heal".cyan());
    }

    // TASK-865: report read-only environment facts the operator wants when
    // triaging launch confinement — currently the bubblewrap OS-sandbox status.
    // Availability only; this never enables `os_wrap`. trace:TASK-865 | ai:claude
    println!();
    println!("{}", "─── Environment ───".bold());
    render_doctor_bwrap_row();
    render_doctor_forge_row();
    Ok(())
}

/// Render the forge-CLI availability row in `aida doctor`'s environment section.
/// `aida pr auto-queue-review` (and the rest of the PR/CI lifecycle) fails hard
/// when the project's forge CLI (`gh` for GitHub, `glab` for GitLab) is not on
/// PATH, so surface it here — OK / missing-with-install-hint / none-needed
/// (pure-git) — rather than letting it stay silent until the first `pr` command.
/// Colourised to match the doctor-check output style. trace:TASK-860 | ai:claude
fn render_doctor_forge_row() {
    let project_root = match find_project_root() {
        Ok(root) => main_worktree_root_from(&root),
        // No project context (e.g. run outside a repo) — fall back to CWD so the
        // row still reports something useful rather than panicking.
        Err(_) => std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from(".")),
    };
    let (kind, msg) = crate::forge::forge_cli_status(&project_root);
    let glyph = if kind == crate::forge::ForgeKind::None {
        // Pure-git needs no forge CLI — informational, not a warning.
        crate::glyph(crate::glyphs::Glyph::Bullet).dimmed()
    } else if kind.cli_on_path() {
        crate::glyph(crate::glyphs::Glyph::Check).green()
    } else {
        crate::glyph(crate::glyphs::Glyph::Warning).yellow()
    };
    println!("  {} {}", glyph, msg);
}

/// One-line bubblewrap (`bwrap`) OS-sandbox availability status, shared by
/// `aida doctor` and `aida init`. Reports AVAILABILITY only — it does not
/// enable `os_wrap` (the `[contained] os_wrap` knob is a separate concern).
/// trace:TASK-865 | ai:claude
fn bwrap_status_line() -> String {
    match crate::session::bwrap_availability() {
        crate::session::BwrapAvailability::Ok => {
            "bwrap: OK (userns confinement available)".to_string()
        }
        crate::session::BwrapAvailability::NotInstalled => "bwrap: not installed".to_string(),
        crate::session::BwrapAvailability::UsernsBlocked { hint } => {
            format!("bwrap: installed but userns blocked — {hint}")
        }
    }
}

/// Render the bwrap availability row in `aida doctor`'s environment section,
/// colourised to match the doctor-check output style. When confinement is
/// blocked or bwrap is missing, print the EXACT copy-pasteable remediation
/// (not just a one-line prose hint) plus a pointer at the guided setup command;
/// when it's ready, confirm how to opt in. trace:TASK-865 | ai:claude
/// trace:STORY-665 | ai:claude
fn render_doctor_bwrap_row() {
    let avail = crate::session::bwrap_availability();
    let glyph = match avail {
        crate::session::BwrapAvailability::Ok => crate::glyph(crate::glyphs::Glyph::Check).green(),
        crate::session::BwrapAvailability::NotInstalled => {
            crate::glyph(crate::glyphs::Glyph::Bullet).dimmed()
        }
        crate::session::BwrapAvailability::UsernsBlocked { .. } => {
            crate::glyph(crate::glyphs::Glyph::Warning).yellow()
        }
    };
    println!("  {} {}", glyph, bwrap_status_line());
    match avail {
        crate::session::BwrapAvailability::Ok => {
            // Ready — confirm + point at how to opt in (it's off by default).
            println!(
                "    {}",
                "OS sandbox is ready. Opt in per-host with `export AIDA_OS_WRAP=1` (recommended — \
                 no shared-config change), or repo-wide with [contained] os_wrap = true in .aida/config.toml."
                    .dimmed()
            );
        }
        crate::session::BwrapAvailability::NotInstalled => {
            // Exact install command, then the guided-setup pointer.
            println!("    {}", "Install bubblewrap, then enable:".dimmed());
            println!("      {}", crate::session::BWRAP_INSTALL_DEBIAN.cyan());
            println!(
                "    {}",
                "Then run `aida doctor --fix-sandbox` for the full setup steps.".dimmed()
            );
        }
        crate::session::BwrapAvailability::UsernsBlocked { .. } => {
            // The kernel blocks unprivileged userns — print the EXACT runtime +
            // persist sysctl commands, clearly marked as sudo. trace:STORY-665
            println!(
                "    {}",
                "Kernel blocks unprivileged user namespaces. Fix (run these yourself):".dimmed()
            );
            println!(
                "      {}  {}",
                crate::session::BWRAP_USERNS_SYSCTL_RUNTIME.cyan(),
                "# this boot".dimmed()
            );
            println!(
                "      {}  {}",
                crate::session::BWRAP_USERNS_SYSCTL_PERSIST.cyan(),
                "# persist".dimmed()
            );
            println!(
                "    {}",
                "Then run `aida doctor --fix-sandbox` for the full setup + verify steps.".dimmed()
            );
        }
    }
}

/// `aida doctor --fix-sandbox` — guided, copy-pasteable bring-up of the OS
/// sandbox (bubblewrap write-confinement) on the current host. A PRINTER, not a
/// silent sudo-runner: it detects the current state, prints the exact ordered
/// sequence (install / persist-sysctl / opt-in / verify) with sudo steps marked
/// "run this yourself", and runs the NON-sudo availability re-probe as a smoke
/// check. Honest + safe — it never escalates privileges on the user's behalf.
/// trace:STORY-665 | ai:claude
fn doctor_fix_sandbox() -> Result<()> {
    use crate::session::{
        bwrap_availability, BwrapAvailability, BWRAP_INSTALL_DEBIAN, BWRAP_USERNS_SYSCTL_PERSIST,
        BWRAP_USERNS_SYSCTL_RUNTIME,
    };

    println!(
        "{}",
        "Guided OS-sandbox setup (bubblewrap write-confinement)"
            .bold()
            .cyan()
    );
    println!(
        "{}",
        "AIDA can run the agent it launches under an OS-level write-confinement \n\
         sandbox (bwrap). It is opt-in and off by default. This walks you through \n\
         bringing it up on THIS host. sudo steps are yours to run."
            .dimmed()
    );
    println!();

    let avail = bwrap_availability();

    // Step 1 — detected state.
    println!("{}", "1. Detected state".bold());
    match &avail {
        BwrapAvailability::Ok => println!(
            "   {} bwrap is installed and the unprivileged-userns self-test passes.",
            crate::glyph(crate::glyphs::Glyph::Check).green()
        ),
        BwrapAvailability::NotInstalled => println!(
            "   {} bwrap is not installed on this host.",
            crate::glyph(crate::glyphs::Glyph::Warning).yellow()
        ),
        BwrapAvailability::UsernsBlocked { .. } => println!(
            "   {} bwrap is installed, but the kernel is blocking the unprivileged \n      user namespace it needs (Ubuntu 23.10+/24.04 AppArmor default).",
            crate::glyph(crate::glyphs::Glyph::Warning).yellow()
        ),
    }
    println!();

    let mut step = 2;

    // Step 2 — install (only if missing).
    if avail == BwrapAvailability::NotInstalled {
        println!("{}", format!("{step}. Install bubblewrap").bold());
        println!("   {}", "Run this yourself (sudo):".dimmed());
        println!("      {}", BWRAP_INSTALL_DEBIAN.cyan());
        println!(
            "   {}",
            "(non-Debian: use your package manager's `bubblewrap` package)".dimmed()
        );
        println!();
        step += 1;
    }

    // Step (conditional) — lift + persist the userns sysctl.
    if matches!(avail, BwrapAvailability::UsernsBlocked { .. })
        || avail == BwrapAvailability::NotInstalled
    {
        println!(
            "{}",
            format!("{step}. Permit unprivileged user namespaces").bold()
        );
        println!(
            "   {}",
            "Run these yourself (sudo). First applies it now, second persists across reboots:"
                .dimmed()
        );
        println!(
            "      {}  {}",
            BWRAP_USERNS_SYSCTL_RUNTIME.cyan(),
            "# this boot".dimmed()
        );
        println!(
            "      {}  {}",
            BWRAP_USERNS_SYSCTL_PERSIST.cyan(),
            "# persist".dimmed()
        );
        println!();
        step += 1;
    }

    // Step — opt in (the knob is off by default regardless of host state).
    println!("{}", format!("{step}. Enable the sandbox (opt-in)").bold());
    println!(
        "   {}",
        "Set the knob in .aida/config.toml (off by default):".dimmed()
    );
    println!("      {}", "[contained]".cyan());
    println!("      {}", "os_wrap = true".cyan());
    println!(
        "   {}",
        "Recommended: enable per-host with `export AIDA_OS_WRAP=1` (no shared-config change). The config knob above enables it repo-wide.".dimmed()
    );
    println!();
    step += 1;

    // Step — verify.
    println!("{}", format!("{step}. Verify").bold());
    println!(
        "   {}",
        "Re-run this command (or `aida doctor`) — step 1 should report a passing self-test:"
            .dimmed()
    );
    println!("      {}", "aida doctor --fix-sandbox".cyan());
    println!(
        "   {}",
        "Once enabled, `aida config show` renders the resolved [contained] posture.".dimmed()
    );
    println!();

    // Non-sudo smoke: re-probe availability and report the live verdict so the
    // operator sees whether the host is already there without touching sudo.
    println!("{}", "Live smoke check (non-sudo re-probe)".bold());
    match bwrap_availability() {
        BwrapAvailability::Ok => println!(
            "   {} Confinement self-test PASSES — this host is ready; just set os_wrap = true.",
            crate::glyph(crate::glyphs::Glyph::Check).green()
        ),
        BwrapAvailability::NotInstalled => println!(
            "   {} bwrap still not on PATH — run the install step above.",
            crate::glyph(crate::glyphs::Glyph::Warning).yellow()
        ),
        BwrapAvailability::UsernsBlocked { .. } => println!(
            "   {} Self-test still failing — run the sudo sysctl step above, then re-check.",
            crate::glyph(crate::glyphs::Glyph::Warning).yellow()
        ),
    }
    println!();
    println!(
        "   {}",
        "Full reference: docs/agents/claude-bubblewrap-sandbox.md".dimmed()
    );

    Ok(())
}

/// STORY-666: is THIS process an autonomous / unattended context for the
/// purposes of the destructive-heal gate? Pure so it is unit-testable without
/// touching the real terminal or environment — `doctor_running_autonomously`
/// (below) feeds it the live signals.
///
/// **Autonomous = no interactive TTY OR a corroborated live orchestrator run.**
///
/// Deliberately NOT keyed on `--yes` alone: a human at a keyboard typing
/// `aida doctor --heal --force --yes` IS the explicit sign-off, and that
/// interactive path must stay exactly as it is today (STORY-666 req #3). The
/// `--yes` flag only ever *reaches* a destructive heal together with `--force`,
/// and at a TTY that combination is a deliberate human decision; what we must
/// fail-closed against is the genuinely unattended case — piped/CI stdin (no
/// TTY) or an `--auto-complete` drain (orchestrator token live). trace:STORY-666
fn doctor_context_is_autonomous(stdin_is_tty: bool, orchestrated: bool) -> bool {
    !stdin_is_tty || orchestrated
}

/// STORY-666: live-signal wrapper for [`doctor_context_is_autonomous`] — reads
/// the real TTY state + the corroborated orchestrator verdict for `project_root`.
// trace:STORY-666 | ai:claude
fn doctor_running_autonomously(project_root: &std::path::Path) -> bool {
    let orchestrated = orchestrator::detect(project_root).is_orchestrated();
    doctor_context_is_autonomous(std::io::stdin().is_terminal(), orchestrated)
}

/// STORY-666: the heal disposition for one finding-category, decided by its
/// safe/destructive classification, the requested flags, and whether we are in
/// an autonomous context. Pure → unit-testable. The single place the
/// fail-closed invariant lives. trace:STORY-666 | ai:claude
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum HealDisposition {
    /// Apply the category's heals (safe always; destructive only with explicit
    /// interactive sign-off).
    Proceed,
    /// A destructive category was requested via `--force --yes` but we are in a
    /// non-interactive/autonomous context — refuse and report (fail-closed).
    GateAutonomous,
    /// A destructive category WITHOUT the `--force --yes` opt-in — the
    /// pre-existing "needs a manual decision" skip (unchanged).
    SkipNeedsForce,
}

fn doctor_heal_disposition(
    safe: bool,
    force: bool,
    yes: bool,
    autonomous: bool,
) -> HealDisposition {
    if safe {
        // Safe, reversible heals proceed in every context — the safe
        // classification IS the bouncer. Never over-gate routine fixes.
        return HealDisposition::Proceed;
    }
    // Destructive from here down.
    if !(force && yes) {
        return HealDisposition::SkipNeedsForce;
    }
    if autonomous {
        // Fail-closed: a destructive heal must not execute silently with no one
        // to make the check-before-delete judgment.
        return HealDisposition::GateAutonomous;
    }
    // Destructive + --force --yes + interactive TTY = explicit human sign-off.
    HealDisposition::Proceed
}

fn heal_doctor_findings(
    project_root: &std::path::Path,
    findings: &[DoctorFinding],
    opts: &DoctorRunOptions,
) -> Result<Vec<DoctorHealResult>> {
    // STORY-666: detect the autonomous/unattended context ONCE for the whole
    // run — the destructive-heal gate keys off it. trace:STORY-666 | ai:claude
    let autonomous = doctor_running_autonomously(project_root);
    let mut out = Vec::new();
    let mut by_category: std::collections::BTreeMap<String, Vec<&DoctorFinding>> =
        std::collections::BTreeMap::new();
    for finding in findings {
        by_category
            .entry(finding.category.clone())
            .or_default()
            .push(finding);
    }
    for (category, items) in by_category {
        let safe = items.iter().all(|item| item.safe_heal);
        match doctor_heal_disposition(safe, opts.force, opts.yes, autonomous) {
            HealDisposition::Proceed => {}
            HealDisposition::SkipNeedsForce => {
                out.push(DoctorHealResult {
                    category: category.clone(),
                    id: category.clone(),
                    action: "skipped category requiring manual decision".to_string(),
                    status: "skipped".to_string(),
                    detail: Some(
                        "pass --yes --force only when you want destructive branch cleanup".into(),
                    ),
                });
                continue;
            }
            HealDisposition::GateAutonomous => {
                // STORY-666: fail-closed. A destructive heal was requested
                // (--force --yes) but we are unattended (no TTY / live drain).
                // Refuse it, name exactly what was skipped, and print the precise
                // interactive command to run it under human sign-off. The
                // `skipped` status keeps the audit trail legible and the heal
                // never executes. trace:STORY-666 | ai:claude
                out.push(DoctorHealResult {
                    category: category.clone(),
                    id: category.clone(),
                    action: format!(
                        "gated — destructive heal of {} finding(s) withheld (unattended context)",
                        items.len()
                    ),
                    status: "skipped".to_string(),
                    detail: Some(format!(
                        "destructive fixes require sign-off and were NOT applied in this \
                         unattended context. Re-run it at an interactive terminal: \
                         `aida doctor --heal --force --yes --category {category}`"
                    )),
                });
                continue;
            }
        }
        if !opts.yes && !confirm_doctor_category(&category, items.len())? {
            out.push(DoctorHealResult {
                category: category.clone(),
                id: category.clone(),
                action: "operator declined".to_string(),
                status: "skipped".to_string(),
                detail: None,
            });
            continue;
        }
        for finding in items {
            // BUG-471: a single finding's heal failure must not abort the whole
            // run (the resilient-drain discipline). Record it as a `failed`
            // result and continue; the caller surfaces failures + exits non-zero.
            // trace:BUG-471 | ai:claude
            match heal_doctor_finding(project_root, finding, opts) {
                Ok(result) => out.push(result),
                Err(e) => out.push(DoctorHealResult {
                    category: category.clone(),
                    id: finding.id.clone(),
                    action: finding.action.clone(),
                    status: "failed".to_string(),
                    detail: Some(e.to_string()),
                }),
            }
        }
    }
    Ok(out)
}

fn confirm_doctor_category(category: &str, count: usize) -> Result<bool> {
    use std::io::Write;
    // BUG-407: never block on a prompt nobody can answer. In a non-interactive
    // shell (no TTY — a background task, CI, or piped stdin) `stdin.read_line`
    // blocks forever on an open-but-empty socket (the observed `aida doctor
    // --heal` hang: 7.5min, 0 progress, WCHAN unix_stream_read_generic).
    // Decline fast with guidance instead; `--heal --yes` skips this prompt
    // entirely (the caller only calls us when !opts.yes). trace:BUG-407
    if !std::io::stdin().is_terminal() {
        eprintln!(
            "  {} non-interactive shell — skipping '{}' ({} finding(s)). Re-run \
             `aida doctor --heal --yes` (add --force for destructive categories) \
             to apply without prompting.",
            "Note:".yellow().bold(),
            category,
            count
        );
        return Ok(false);
    }
    print!("Heal {} finding(s) in {}? [y/N] ", count, category);
    std::io::stdout().flush()?;
    let mut ans = String::new();
    std::io::stdin().read_line(&mut ans)?;
    Ok(matches!(
        ans.trim().to_ascii_lowercase().as_str(),
        "y" | "yes"
    ))
}

fn heal_doctor_finding(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
    opts: &DoctorRunOptions,
) -> Result<DoctorHealResult> {
    match finding.category.as_str() {
        "stale-leases" | "abandoned-leases" | "stale-reviewer-leases" => {
            heal_doctor_lease(project_root, finding)
        }
        "brief-spec-drift" | "OBE-briefs" => heal_doctor_brief(finding),
        "spec-status-drift" if finding.action.starts_with("confirm and end lease") => {
            heal_doctor_lease(project_root, finding)
        }
        "spec-status-drift" => heal_doctor_spec_status(project_root, finding),
        "orphan-worktrees" => heal_doctor_orphan_worktree(project_root, finding),
        // TASK-752: git-rm the tracked legacy-store artifact + gitignore it —
        // exactly PR-651's resolution. safe_heal (the detector self-gates on
        // git-canonical mode, so this never touches an active centralized
        // backend). trace:TASK-752 | ai:claude
        "legacy-store-cruft" => heal_doctor_legacy_store_cruft(project_root, finding),
        // BUG-563: git-rm --cached the per-clone runtime file in the STORE
        // worktree + gitignore it + commit on the store worktree. safe_heal (the
        // detector self-gates on git-canonical mode + an attached store
        // worktree). trace:BUG-563 | ai:claude
        "store-tracked-runtime" => heal_doctor_store_tracked_runtime(project_root, finding),
        "orphan-queue-entries" => heal_doctor_orphan_queue_entry(project_root, finding),
        "stale-locks" => heal_doctor_stale_lock(finding),
        "dead-agents" => heal_doctor_dead_agent(project_root, finding),
        "orphan-branches" if opts.force && opts.yes => {
            heal_doctor_orphan_branch(project_root, finding)
        }
        // TASK-717: prune a verified-stale REMOTE branch. DESTRUCTIVE (deletes
        // origin/*) so force+yes gated like local orphan-branch deletion.
        // trace:TASK-717
        "stale-remote-branches" if opts.force && opts.yes => {
            heal_doctor_stale_remote_branch(project_root, finding)
        }
        // TASK-878: GC a merged Agent-tool worktree + its branch. DESTRUCTIVE
        // (worktree removal + branch deletion) so force+yes gated like the
        // stale-remote-branch deletion above, AND routed through the STORY-666
        // autonomous-context refusal in heal_doctor_findings (safe_heal=false).
        // trace:TASK-878
        "merged-agent-worktrees" if opts.force && opts.yes => {
            heal_doctor_merged_agent_worktree(project_root, finding)
        }
        // TASK-673: re-open an uncorroborated Completed spec to Done so it
        // surfaces in the queue's "awaiting commit" lane for triage rather than
        // silently asserting work git never saw. Force-gated (see heal_doctor_findings).
        "completed-without-commit" if opts.force && opts.yes => {
            heal_doctor_completed_without_commit(project_root, finding)
        }
        // TASK-699: remove a stray ancestor instruction file whose @-imports
        // escape the project. DESTRUCTIVE — it deletes a file OUTSIDE the repo —
        // so it's force+yes gated (see heal_doctor_findings's safe-heal gate).
        // trace:TASK-699
        "external-import-bleed" if opts.force && opts.yes => {
            heal_doctor_external_import_bleed(project_root, finding)
        }
        _ => Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some("diagnostic-only category; follow the printed action".to_string()),
        }),
    }
}

/// STORY-496: reap a dead-PID agent-registry entry. The finding id is
/// `{agent_type}#{pid}`. Re-checks the pid is still dead before removing — a
/// pid can be reused by an unrelated process between scan and heal, and we
/// must never reap a live agent. trace:STORY-496 | ai:claude
fn heal_doctor_dead_agent(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let (agent_type, pid_str) = finding.id.split_once('#').ok_or_else(|| {
        anyhow::anyhow!(
            "malformed dead-agent id `{}` (expected type#pid)",
            finding.id
        )
    })?;
    let pid: u32 = pid_str
        .parse()
        .with_context(|| format!("bad pid in dead-agent id `{}`", finding.id))?;
    if process_probe::pid_is_alive(pid) {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some(format!("pid {pid} is now alive — not reaping")),
        });
    }
    let removed = agent_registry::remove_agent(project_root, agent_type, pid)?;
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: finding.action.clone(),
        status: if removed { "healed" } else { "skipped" }.to_string(),
        detail: if removed {
            None
        } else {
            Some("registry entry already gone".to_string())
        },
    })
}

/// TASK-699: opt-in heal for the `external-import-bleed` category — remove a
/// stray ancestor CLAUDE.md / CLAUDE.local.md / AGENTS.md whose @-imports escape
/// the project (the classic accidental-`aida init`-in-a-parent-of-projects
/// scaffold). DESTRUCTIVE: it deletes a file OUTSIDE the repo, so the caller
/// gates it behind --heal --force --yes. Guardrails honored here:
///   - removes ONLY the stray instruction file (the finding id), never the
///     ancestor's docs/ or anything else;
///   - re-reads the file and re-verifies at least one @-import STILL escapes the
///     project right before deleting (mirrors heal_doctor_dead_agent's re-check
///     so a file edited/fixed between scan and heal is left alone);
///   - prints exactly what will be deleted before removing it.
// trace:TASK-699 | ai:claude
fn heal_doctor_external_import_bleed(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let file = std::path::PathBuf::from(&finding.id);
    // Re-check: the file may have been removed or edited since the scan.
    let Ok(content) = std::fs::read_to_string(&file) else {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some(format!("{} already gone", file.display())),
        });
    };
    let file_dir = file.parent().unwrap_or_else(|| std::path::Path::new("/"));
    if !external_import_bleed::file_still_escapes(file_dir, &content, project_root) {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some(format!(
                "{} no longer has @-imports escaping the project — not removing",
                file.display()
            )),
        });
    }
    // Print EXACTLY what will be deleted before acting (guardrail #4).
    println!(
        "  {} removing stray ancestor instruction file: {}",
        "→".red().bold(),
        file.display()
    );
    std::fs::remove_file(&file).with_context(|| format!("failed to remove {}", file.display()))?;
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: format!("removed stray ancestor instruction file {}", file.display()),
        status: "healed".to_string(),
        detail: None,
    })
}

fn heal_doctor_lease(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    // BUG-471: a lease already ended (e.g. removed earlier in this same heal
    // run, or by a concurrent session) is a no-op, not an error — mirror the
    // dead-agent "already gone" handling so heal stays idempotent.
    // trace:BUG-471 | ai:claude
    let Some(lease) = list_leases(project_root)
        .into_iter()
        .find(|lease| lease.id == finding.id)
    else {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "skipped".to_string(),
            detail: Some("lease already ended".to_string()),
        });
    };
    let salvage = salvage_worktree_patch(
        project_root,
        &lease.scope,
        lease.role.as_deref(),
        &lease.worktree_path,
    )?;
    let removed = force_cleanup_lease(project_root, &lease);
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "ended lease with salvage-first cleanup".to_string(),
        status: if removed { "healed" } else { "partial" }.to_string(),
        detail: salvage.map(|p| format!("salvage patch: {}", p.display())),
    })
}

fn heal_doctor_brief(finding: &DoctorFinding) -> Result<DoctorHealResult> {
    let path = std::path::Path::new(&finding.id);
    if !path.exists() {
        let acked = path.with_file_name(format!(
            "{}.acked",
            path.file_name()
                .and_then(|n| n.to_str())
                .unwrap_or_default()
        ));
        if acked.exists() {
            return Ok(DoctorHealResult {
                category: finding.category.clone(),
                id: finding.id.clone(),
                action: "brief already acked".to_string(),
                status: "skipped".to_string(),
                detail: Some(acked.display().to_string()),
            });
        }
    }
    ack_agent_brief(path)?;
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "acked obsolete brief".to_string(),
        status: "healed".to_string(),
        detail: None,
    })
}

fn heal_doctor_spec_status(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let storage = Storage::new(project_root.join(".aida-store"));
    let mut store = storage.load()?;
    let mut action = None;
    for req in &mut store.requirements {
        if req.spec_id.as_deref() != Some(finding.id.as_str()) {
            continue;
        }
        if matches!(req.status, RequirementStatus::Approved)
            && finding.action.starts_with("bump spec to In Progress")
        {
            req.status = RequirementStatus::InProgress;
            req.modified_at = chrono::Utc::now();
            action = Some("bumped Approved spec to In Progress".to_string());
        } else if matches!(req.status, RequirementStatus::InProgress)
            && finding.action.contains("no active lease")
        {
            req.status = RequirementStatus::Approved;
            req.modified_at = chrono::Utc::now();
            action = Some(format!(
                "reverted {} from In Progress to Approved (no active lease found)",
                finding.id
            ));
        }
    }
    if action.is_some() {
        storage.save(&store)?;
    }
    let changed = action.is_some();
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: action.unwrap_or_else(|| "no automatic status change applied".to_string()),
        status: if changed { "healed" } else { "skipped" }.to_string(),
        detail: None,
    })
}

/// TASK-673: re-open a Completed-without-corroboration spec to Done. Done is the
/// "finished on a branch, awaiting merge" state, so the spec lands in the
/// queue's "awaiting commit" lane where the missing corroboration is visible and
/// actionable — far better than a Completed row git can't back up. Re-checks the
/// status is still Completed (a concurrent `aida pull` may have legitimately
/// corroborated it since the scan). The finding id matches either spec_id or
/// agreed_id. trace:TASK-673 | ai:claude
fn heal_doctor_completed_without_commit(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let storage = Storage::new(project_root.join(".aida-store"));
    let mut store = storage.load()?;
    let mut action = None;
    for req in &mut store.requirements {
        let matches_id = req.spec_id.as_deref() == Some(finding.id.as_str())
            || req.agreed_id.as_deref() == Some(finding.id.as_str());
        if !matches_id {
            continue;
        }
        if matches!(req.status, RequirementStatus::Completed) {
            req.status = RequirementStatus::Done;
            req.modified_at = chrono::Utc::now();
            action = Some(format!(
                "re-opened {} from Completed to Done (no corroborating commit) for triage",
                finding.id
            ));
        }
        break;
    }
    if action.is_some() {
        storage.save(&store)?;
    }
    let changed = action.is_some();
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: action
            .unwrap_or_else(|| "spec is no longer Completed — nothing to re-open".to_string()),
        status: if changed { "healed" } else { "skipped" }.to_string(),
        detail: None,
    })
}

fn heal_doctor_orphan_worktree(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let worktree = std::path::PathBuf::from(&finding.id);
    let salvage = salvage_worktree_patch(project_root, "orphan-worktree", None, &worktree)?;
    // STORY-714: route through the shared teardown so the pre_destroy
    // cargo-clean hook fires (TASK-0396) and a pooled tree is deregistered.
    let healed = aida_core::worktree_pool_destroy::teardown_worktree_path(
        project_root,
        &worktree,
        &worktree_pool_global_hooks("pre_destroy"),
    )
    .is_ok();
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "removed orphan worktree".to_string(),
        status: if healed { "healed" } else { "failed" }.to_string(),
        detail: salvage.map(|p| format!("salvage patch: {}", p.display())),
    })
}

/// TASK-752: heal a tracked legacy-store-cruft finding — exactly PR-651's
/// resolution: `git rm` the file from the tree, then append the gitignore block
/// (`requirements*.yaml`, `scaffold-report.html`) so the artifacts can't return.
/// Idempotent: a path already untracked (e.g. a prior heal removed it) reports
/// `skipped`; the gitignore block is appended only once. trace:TASK-752 | ai:claude
fn heal_doctor_legacy_store_cruft(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let path = &finding.id;

    // Re-confirm the file is still tracked before removing — between scan and
    // heal another heal (or a manual `git rm`) may have already dropped it.
    let still_tracked = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["ls-files", "--error-unmatch", path])
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false);

    if !still_tracked {
        // Still make sure the gitignore guard is in place (idempotent).
        let gi = ensure_legacy_store_cruft_gitignore(project_root)?;
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: "already untracked".to_string(),
            status: "skipped".to_string(),
            detail: gi.then(|| "appended gitignore guard".to_string()),
        });
    }

    let status = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["rm", "--quiet", "--"])
        .arg(path)
        .status()
        .with_context(|| format!("git rm {path}"))?;
    if !status.success() {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "failed".to_string(),
            detail: Some(format!("git rm {path} failed")),
        });
    }

    let appended = ensure_legacy_store_cruft_gitignore(project_root)?;
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "git rm + gitignore (live store is the orphan aida-store branch)".to_string(),
        status: "healed".to_string(),
        detail: appended.then(|| "appended gitignore guard".to_string()),
    })
}

/// TASK-752: append PR-651's exact gitignore guard so the swept legacy-store
/// artifacts can't return. Idempotent — no-op if the patterns are already
/// present. Returns whether it wrote anything. trace:TASK-752 | ai:claude
fn ensure_legacy_store_cruft_gitignore(project_root: &std::path::Path) -> Result<bool> {
    use std::io::Write;
    let gitignore_path = project_root.join(".gitignore");
    let existing = std::fs::read_to_string(&gitignore_path).unwrap_or_default();
    // Already guarded? `requirements*.yaml` is the load-bearing pattern.
    if existing.lines().any(|l| l.trim() == "requirements*.yaml") {
        return Ok(false);
    }
    let block = "\n# Legacy pre-git-canonical store snapshots (live store is the orphan aida-store branch)\n\
         requirements*.yaml\n\
         scaffold-report.html\n";
    let mut f = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&gitignore_path)
        .with_context(|| format!("opening {}", gitignore_path.display()))?;
    f.write_all(block.as_bytes())
        .with_context(|| format!("appending to {}", gitignore_path.display()))?;
    Ok(true)
}

/// BUG-563: heal a per-clone runtime file wrongly tracked on the orphan
/// `aida-store` branch — `git rm --cached` it IN THE STORE WORKTREE (untrack but
/// keep the working copy, since the live clone still needs its own node.toml /
/// dispenser.toml / cache), ensure the store-worktree gitignore guards the
/// per-clone runtime set, then COMMIT the untrack on the store worktree so the
/// orphan branch stops carrying it. Idempotent: a path already untracked (e.g. a
/// prior heal removed it) reports `skipped`; the gitignore block is appended only
/// once; a no-op commit is skipped. trace:BUG-563 | ai:claude
fn heal_doctor_store_tracked_runtime(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let store_worktree = project_root.join(".aida-store");
    let path = &finding.id;

    // Re-confirm the file is still tracked on the orphan branch before removing —
    // between scan and heal another heal (or a manual `git rm`) may have already
    // dropped it.
    let still_tracked = std::process::Command::new("git")
        .arg("-C")
        .arg(&store_worktree)
        .args(["ls-files", "--error-unmatch", path])
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false);

    if !still_tracked {
        // Still make sure the gitignore guard is in place (idempotent).
        let gi = ensure_store_tracked_runtime_gitignore(&store_worktree)?;
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: "already untracked".to_string(),
            status: "skipped".to_string(),
            detail: gi.then(|| "appended gitignore guard".to_string()),
        });
    }

    // Untrack but KEEP the working copy — this clone still needs its own
    // per-clone runtime file; only the orphan branch must stop carrying it.
    let status = std::process::Command::new("git")
        .arg("-C")
        .arg(&store_worktree)
        .args(["rm", "--cached", "--quiet", "--"])
        .arg(path)
        .status()
        .with_context(|| format!("git rm --cached {path} in store worktree"))?;
    if !status.success() {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "failed".to_string(),
            detail: Some(format!("git rm --cached {path} failed")),
        });
    }

    let appended = ensure_store_tracked_runtime_gitignore(&store_worktree)?;

    // Stage the gitignore (if we touched it) and commit the untrack on the
    // store worktree so the orphan branch stops carrying the per-clone file.
    if appended {
        let _ = std::process::Command::new("git")
            .arg("-C")
            .arg(&store_worktree)
            .args(["add", ".gitignore"])
            .status();
    }
    let commit = std::process::Command::new("git")
        .arg("-C")
        .arg(&store_worktree)
        .args([
            "commit",
            "--quiet",
            "-m",
            "chore(store): stop tracking per-clone runtime file (BUG-563)",
        ])
        .status()
        .with_context(|| "committing untrack on store worktree".to_string())?;
    if !commit.success() {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: finding.action.clone(),
            status: "failed".to_string(),
            detail: Some("commit on store worktree failed".to_string()),
        });
    }

    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "git rm --cached + gitignore + commit on store worktree (per-clone runtime stays untracked)"
            .to_string(),
        status: "healed".to_string(),
        detail: appended.then(|| "appended gitignore guard".to_string()),
    })
}

/// BUG-563: append the per-clone-runtime gitignore guard to the STORE worktree's
/// `.gitignore` so the untracked files can't return on the orphan branch.
/// Idempotent — no-op if the load-bearing patterns are already present. Returns
/// whether it wrote anything. trace:BUG-563 | ai:claude
fn ensure_store_tracked_runtime_gitignore(store_worktree: &std::path::Path) -> Result<bool> {
    use std::io::Write;
    let gitignore_path = store_worktree.join(".gitignore");
    let existing = std::fs::read_to_string(&gitignore_path).unwrap_or_default();
    // Already guarded? `.aida/node.toml` is the load-bearing pattern (the one
    // that conflicts on every cross-clone rebase).
    if existing.lines().any(|l| l.trim() == ".aida/node.toml") {
        return Ok(false);
    }
    let block =
        "\n# Per-clone runtime state — must never be tracked on the orphan aida-store branch\n\
         .aida/node.toml\n\
         .aida/dispenser.toml\n\
         .aida/*.lock\n\
         .aida/cache.db\n\
         .aida/cache.db-journal\n\
         .aida/cache.db-shm\n\
         .aida/cache.db-wal\n";
    let mut f = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&gitignore_path)
        .with_context(|| format!("opening {}", gitignore_path.display()))?;
    f.write_all(block.as_bytes())
        .with_context(|| format!("appending to {}", gitignore_path.display()))?;
    Ok(true)
}

// TASK-570: heal an orphan queue entry by routing through the same
// `storage.queue_remove` primitive that `aida queue prune --orphaned`
// (TASK-537) uses. Idempotent — a re-run after the entry is already gone
// reports `skipped`. trace:TASK-570 | ai:claude
fn heal_doctor_orphan_queue_entry(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let user_id = current_user_id(None);
    let storage = Storage::new(project_root.join(".aida-store"));
    let entry_uuid: uuid::Uuid = finding
        .id
        .parse()
        .with_context(|| format!("parsing queue entry id {}", finding.id))?;
    let entries = storage.queue_list(&user_id, /* include_completed */ false)?;
    if !entries.iter().any(|e| e.requirement_id == entry_uuid) {
        return Ok(DoctorHealResult {
            category: finding.category.clone(),
            id: finding.id.clone(),
            action: "orphan queue entry already removed".to_string(),
            status: "skipped".to_string(),
            detail: None,
        });
    }
    storage.queue_remove(&user_id, &entry_uuid)?;
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "removed orphan queue entry".to_string(),
        status: "healed".to_string(),
        detail: None,
    })
}

fn heal_doctor_stale_lock(finding: &DoctorFinding) -> Result<DoctorHealResult> {
    let path = std::path::Path::new(&finding.id);
    let removed = if path.exists() {
        std::fs::remove_file(path)
            .with_context(|| format!("removing stale lock-info file {}", path.display()))?;
        true
    } else {
        false
    };
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "removed stale cache lock-info file".to_string(),
        status: if removed { "healed" } else { "skipped" }.to_string(),
        detail: if removed {
            None
        } else {
            Some("lock-info file was already gone".to_string())
        },
    })
}

fn heal_doctor_orphan_branch(
    project_root: &std::path::Path,
    finding: &DoctorFinding,
) -> Result<DoctorHealResult> {
    let status = std::process::Command::new("git")
        .arg("-C")
        .arg(project_root)
        .args(["branch", "-D", &finding.id])
        .status()
        .with_context(|| format!("deleting branch {}", finding.id))?;
    Ok(DoctorHealResult {
        category: finding.category.clone(),
        id: finding.id.clone(),
        action: "deleted orphan branch".to_string(),
        status: if status.success() { "healed" } else { "failed" }.to_string(),
        detail: None,
    })
}

fn salvage_worktree_patch(
    project_root: &std::path::Path,
    spec_id: &str,
    agent: Option<&str>,
    worktree: &std::path::Path,
) -> Result<Option<std::path::PathBuf>> {
    if !worktree.exists() || worktree_dirty_entries(worktree).is_empty() {
        return Ok(None);
    }
    let stamp = chrono::Utc::now().format("%Y-%m-%dT%H%M%SZ");
    let agent = agent.unwrap_or("unknown");
    let filename = format!(
        "{}-{}-attempt-{}.patch",
        sanitize_salvage_component(spec_id),
        sanitize_salvage_component(agent),
        stamp
    );
    let dir = project_root.join(".aida").join("salvage");
    std::fs::create_dir_all(&dir)?;
    let path = dir.join(filename);
    let mut body = String::new();
    body.push_str(&format!(
        "# AIDA salvage patch\n# worktree: {}\n\n",
        worktree.display()
    ));
    body.push_str(&git_output_lossy(worktree, &["diff", "--binary", "HEAD"]));
    body.push_str(&git_output_lossy(
        worktree,
        &["diff", "--binary", "--cached"],
    ));
    let untracked = git_output_lossy(worktree, &["ls-files", "--others", "--exclude-standard"]);
    if !untracked.trim().is_empty() {
        body.push_str("\n# Untracked files present at salvage time:\n");
        for line in untracked.lines() {
            body.push_str("#   ");
            body.push_str(line);
            body.push('\n');
        }
    }
    if body.trim().is_empty() {
        return Ok(None);
    }
    std::fs::write(&path, body)?;
    Ok(Some(path))
}

fn git_output_lossy(worktree: &std::path::Path, args: &[&str]) -> String {
    let out = std::process::Command::new("git")
        .arg("-C")
        .arg(worktree)
        .args(args)
        .output();
    match out {
        Ok(out) => String::from_utf8_lossy(&out.stdout).to_string(),
        Err(_) => String::new(),
    }
}

fn humanize_duration_secs(secs: u64) -> String {
    if secs < 60 {
        format!("{secs}s")
    } else if secs < 3600 {
        format!("{}m {}s", secs / 60, secs % 60)
    } else {
        format!("{}h {}m", secs / 3600, (secs % 3600) / 60)
    }
}

fn sanitize_salvage_component(s: &str) -> String {
    let mut out: String = s
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
                c
            } else {
                '-'
            }
        })
        .collect();
    while out.contains("--") {
        out = out.replace("--", "-");
    }
    out.trim_matches('-').to_string()
}

#[cfg(test)]
