        assert!(!load_agents_bypass(&project).unwrap());

        // User base on, no project file → on.
        std::fs::write(home.join(".aida/agents.toml"), "[agents]\nbypass = true\n").unwrap();
        assert!(load_agents_bypass(&project).unwrap());

        // Project explicitly off → overrides user base on.
