    /// TASK-94: the trace-graph scanner walks source files, captures the
    /// full node-aware spec id, finds the symbol on or just below the
    /// trace line, and skips build/vendor trees.
    #[test]
    fn plan_helpers_scan_trace_graph() {
        let dir = tempfile::tempdir().unwrap();
        let src = dir.path().join("sub");
        std::fs::create_dir_all(&src).unwrap();
        std::fs::write(
            src.join("a.rs"),
            "// trace:STORY-86 | ai:claude\nfn auto_bump() {}\n\n// trace:FR-1-042\nstruct Thing;\n",
        )
        .unwrap();
        std::fs::write(src.join("b.rs"), "pub fn inline() {} // trace:TASK-50\n").unwrap();
        // A file under target/ must be skipped.
        let skip = dir.path().join("target");
        std::fs::create_dir_all(&skip).unwrap();
        std::fs::write(skip.join("c.rs"), "// trace:STORY-86\nfn ignored() {}\n").unwrap();

        let wanted: HashSet<String> = ["STORY-86", "FR-1-042", "TASK-50"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let hits = scan_trace_graph(dir.path(), &wanted);

        // STORY-86 → auto_bump in a.rs only (the target/ copy is skipped).
        let s86 = hits.get("STORY-86").expect("STORY-86 hit");
        assert_eq!(s86.len(), 1);
        assert_eq!(s86[0].symbol.as_deref(), Some("auto_bump"));
        // Node-aware id captured in full — never bucketed under `FR-1`.
        assert!(!hits.contains_key("FR-1"));
        assert_eq!(
            hits.get("FR-1-042").expect("FR-1-042 hit")[0]
                .symbol
                .as_deref(),
            Some("Thing")
        );
        // An inline trailing trace comment resolves the symbol on its line.
        assert_eq!(
            hits.get("TASK-50").expect("TASK-50 hit")[0]
                .symbol
                .as_deref(),
            Some("inline")
        );
    }

    /// TASK-0418: the pre-plan scan's stale-assumption detector flags code
    /// paths the spec names that no longer resolve — a missing file and a
    /// missing symbol — while leaving present file+symbol refs alone and
    /// ignoring `path:line` refs (a numeric suffix is a drift-prone line ref,
    /// not a stale-FILE signal).
    #[test]
    fn preplan_scan_flags_stale_assumptions() {
        let dir = tempfile::tempdir().unwrap();
        let sub = dir.path().join("aida-cli/src");
        std::fs::create_dir_all(&sub).unwrap();
        std::fs::write(sub.join("real.rs"), "pub fn still_here() {}\n").unwrap();

        let desc = "Touches `aida-cli/src/real.rs:still_here` and \
                    `aida-cli/src/real.rs:gone_now`. Also see \
                    `aida-cli/src/deleted.rs`. Line ref aida-cli/src/real.rs:42 \
                    should NOT be flagged.";
        let stale = scan_stale_assumptions(dir.path(), desc);
        let refs: Vec<&str> = stale.iter().map(|s| s.reference.as_str()).collect();

        // Missing file and missing symbol are flagged.
        assert!(refs.contains(&"aida-cli/src/deleted.rs"));
        assert!(refs.contains(&"aida-cli/src/real.rs:gone_now"));
        // The present file+symbol is NOT flagged.
        assert!(!refs.contains(&"aida-cli/src/real.rs:still_here"));
        // The `:42` line ref collapses to the bare (present) file and is
        // therefore not flagged as missing.
        assert!(!refs.iter().any(|r| r.contains(":42")));
    }

