        assert_eq!(parse_review_scope("pr-42"), Some((ReviewForge::GitHub, 42)));
        assert_eq!(parse_review_scope("MR-7"), Some((ReviewForge::GitLab, 7)));
        assert_eq!(
            parse_review_scope("mr-2024"),
            Some((ReviewForge::GitLab, 2024))
        );
