/// TASK-136 / BUG-420: drain-reliability tunables for the orchestrator's phase
/// loop. Resolved once per `RealPhaseDriver` from the `[drain]` section of
/// `.aida/config.toml`, then overridden by env vars (which the `queue work`
/// dispatch sets from the `--no-progress-minutes` / `--phase-ceiling-minutes`
/// flags so the values compose across single-spec / batch / nextN drains
/// without threading through every signature — the same env-var pattern
/// `AIDA_CALIBRATE` uses). A `0`-minute value disables that watchdog check.
/// trace:TASK-136 BUG-420 | ai:claude
#[derive(Debug, Clone, Copy)]
struct DrainTuning {
    /// TASK-136: how many times to retry the phase-1 GH PR-verify on a
    /// transient GH-API outage before declaring the run inconclusive. The
    /// backoff cadence is [`auto_complete::gh_verify_backoff_schedule`]
    /// (30s / 1m / 5m / then 15m). Default 3.
    gh_verify_retries: usize,
    /// BUG-420: no-progress window — a headless phase that makes no commit /
    /// file-change for this long is killed and shelved. Default 10m; `0`
    /// disables.
    no_progress: std::time::Duration,
    /// BUG-420: hard wall-clock ceiling per headless phase, a backstop in case
    /// progress-detection misses. Default 45m; `0` disables.
    ceiling: std::time::Duration,
}

impl DrainTuning {
    /// Resolve from `[drain]` config then env overrides. Env wins so the
    /// per-invocation flags (mapped to env at dispatch) override the project
    /// default. trace:TASK-136 BUG-420 | ai:claude
    fn resolve(project_root: &std::path::Path) -> Self {
        let cfg = read_drain_config(project_root);
        let env_usize = |k: &str| -> Option<usize> {
            std::env::var(k).ok().and_then(|s| s.trim().parse().ok())
        };
        let env_u64 =
            |k: &str| -> Option<u64> { std::env::var(k).ok().and_then(|s| s.trim().parse().ok()) };
        let gh_verify_retries = env_usize("AIDA_GH_VERIFY_RETRIES")
            .or(cfg.gh_verify_retries)
            .unwrap_or(3);
        let no_progress_min = env_u64("AIDA_NO_PROGRESS_MINUTES")
            .or(cfg.no_progress_minutes)
            .unwrap_or(10);
        let ceiling_min = env_u64("AIDA_PHASE_CEILING_MINUTES")
            .or(cfg.phase_ceiling_minutes)
            .unwrap_or(45);
        Self {
            gh_verify_retries,
            no_progress: std::time::Duration::from_secs(no_progress_min.saturating_mul(60)),
            ceiling: std::time::Duration::from_secs(ceiling_min.saturating_mul(60)),
        }
    }
}

/// BUG-420: a phase-scoped no-progress + wall-clock-ceiling watchdog for a
/// *headless* orchestrator phase. While the `claude -p` child runs, the
/// orchestrator's [`exit_signal::spawn_and_wait_watched`] poll loop calls
/// [`PhaseWatchdog::check`]; it (rate-limited) probes the phase worktree for
/// new commits / file changes and trips when both stall for `no_progress` or
/// when wall-clock exceeds `ceiling`. The pure verdict is
/// [`auto_complete::watchdog_verdict`]; this struct is just the I/O shell that
/// gathers the facts and remembers the last-progress timestamp.
///
/// The worktree is created by the phase child, so it is not known at spawn
/// time — `check` resolves it lazily from the session lease and, until it
/// appears, treats the phase as "making progress" (startup grace) so a slow
/// session launch never trips the watchdog. trace:BUG-420 | ai:claude
struct PhaseWatchdog {
    project_root: std::path::PathBuf,
    session_id: String,
    phase_start: std::time::Instant,
    last_progress: std::time::Instant,
    last_sig: Option<String>,
    last_poll: std::time::Instant,
    poll_every: std::time::Duration,
    no_progress: std::time::Duration,
    ceiling: std::time::Duration,
    worktree: Option<std::path::PathBuf>,
}

impl PhaseWatchdog {
    /// How often to actually shell out to git — far coarser than the
    /// `spawn_and_wait` poll cadence (which is ~100ms) so the watchdog never
    /// spins git. trace:BUG-420 | ai:claude
    const GIT_POLL: std::time::Duration = std::time::Duration::from_secs(30);

    fn new(
        project_root: std::path::PathBuf,
        session_id: String,
        no_progress: std::time::Duration,
        ceiling: std::time::Duration,
    ) -> Self {
        let now = std::time::Instant::now();
        Self {
            project_root,
            session_id,
            phase_start: now,
            last_progress: now,
            last_sig: None,
            last_poll: now,
            poll_every: Self::GIT_POLL,
            no_progress,
            ceiling,
            worktree: None,
        }
    }

    /// A progress signature for the worktree: HEAD sha + a hash of the
    /// porcelain status + the newest mtime among changed files. A degenerate
    /// echo/sleep spin moves none of these; a real session commits, stages, or
    /// re-edits a file (advancing its mtime). `None` when git can't be read.
    /// trace:BUG-420 | ai:claude
    fn progress_signature(worktree: &std::path::Path) -> Option<String> {
        let sha = git_capture(worktree, &["rev-parse", "HEAD"]).unwrap_or_default();
        let porcelain = git_capture(worktree, &["status", "--porcelain"]).unwrap_or_default();
        // Newest mtime among the changed paths — catches repeated edits to an
        // already-dirty file (porcelain text alone would not change).
        let mut newest: u128 = 0;
        for line in porcelain.lines() {
            // Porcelain lines are `XY <path>`; take everything after the status
            // columns. Rename lines (`R  old -> new`) end with the new path.
            let path = line
                .get(3..)
                .unwrap_or("")
                .rsplit(" -> ")
                .next()
                .unwrap_or("");
            let path = path.trim().trim_matches('"');
            if path.is_empty() {
                continue;
            }
            if let Ok(meta) = std::fs::metadata(worktree.join(path)) {
                if let Ok(m) = meta.modified() {
                    if let Ok(d) = m.duration_since(std::time::UNIX_EPOCH) {
                        newest = newest.max(d.as_nanos());
                    }
                }
            }
        }
        if sha.is_empty() && porcelain.is_empty() {
            return None;
        }
        Some(format!("{sha}|{}|{newest}", porcelain.len()))
    }

    /// Probe (rate-limited) and return `Some(reason)` if the watchdog should
    /// trip — the caller then reaps the child. trace:BUG-420 | ai:claude
    fn check(&mut self) -> Option<String> {
        // Both checks disabled → never trips.
        if self.no_progress.is_zero() && self.ceiling.is_zero() {
            return None;
        }
        let now = std::time::Instant::now();
        if now.duration_since(self.last_poll) < self.poll_every {
            return None;
        }
        self.last_poll = now;

        // Lazily resolve the worktree from the session lease. Until it appears
        // (the child is still starting up), keep resetting last_progress so a
        // slow launch can't trip the no-progress check.
        if self.worktree.is_none() {
            self.worktree =
                find_orchestrated_lease(&self.project_root, &self.session_id).map(|(_, _, wt)| wt);
            if self.worktree.is_none() {
                self.last_progress = now;
                // Ceiling still applies even before the worktree resolves.
                return auto_complete::watchdog_verdict(
                    now.duration_since(self.last_progress),
                    now.duration_since(self.phase_start),
                    self.no_progress,
                    self.ceiling,
                )
                .map(|t| self.trip_reason(t));
            }
        }
        let worktree = self.worktree.clone().unwrap();

        // BUG-453: progress = worktree change OR headless-log growth. The log
        // grows whenever the session emits events (reads, thoughts, edits), so a
        // productive-but-currently-reading implementer keeps resetting the timer
        // and is no longer false-killed; a genuinely hung/crashed session stops
        // emitting (log static) and the worktree stays static, so the no-progress
        // check still trips, and the wall-clock ceiling backstops a runaway.
        // trace:BUG-453 | ai:claude
        let wt_sig = Self::progress_signature(&worktree);
        let log_len = headless_log_len(&self.project_root, &self.session_id);
        let combined = match (wt_sig, log_len) {
            (Some(w), Some(l)) => Some(format!("{w}|log:{l}")),
            (Some(w), None) => Some(w),
            (None, Some(l)) => Some(format!("log:{l}")),
            (None, None) => None,
        };
        if let Some(sig) = combined {
            if self.last_sig.as_deref() != Some(sig.as_str()) {
                self.last_sig = Some(sig);
                self.last_progress = now;
            }
        }

        // TASK-298: a `--no-human` headless run that hit a permission gate (or
        // reported an `is_error` envelope) is silently stuck — `claude -p`
        // exits 0 even when it bailed (SPIKE-7), so neither the natural-exit
        // path nor the no-progress timer would catch it promptly. The log
        // keeps the offending event, so scan it and trip the watchdog
        // *immediately* with the specific reason rather than waiting out the
        // no-progress / ceiling window. trace:TASK-298 | ai:claude
        if let Some(reason) = read_headless_log_for_session(&self.project_root, &self.session_id)
            .as_deref()
            .and_then(headless_log_permission_stall)
        {
            return Some(reason);
        }

        auto_complete::watchdog_verdict(
            now.duration_since(self.last_progress),
            now.duration_since(self.phase_start),
            self.no_progress,
            self.ceiling,
        )
        .map(|t| self.trip_reason(t))
    }

    fn trip_reason(&self, trip: auto_complete::WatchdogTrip) -> String {
        match trip {
            auto_complete::WatchdogTrip::NoProgress => format!(
                "no commit or file-change for {}m — likely a degenerate session",
                self.no_progress.as_secs() / 60
            ),
            auto_complete::WatchdogTrip::Ceiling => format!(
                "phase exceeded the {}m wall-clock ceiling",
                self.ceiling.as_secs() / 60
            ),
        }
    }
}

/// Run `git -C <worktree> <args>` and capture trimmed stdout, or `None` on any
/// spawn / non-zero / decode error. trace:BUG-420 | ai:claude
fn git_capture(worktree: &std::path::Path, args: &[&str]) -> Option<String> {
    let out = std::process::Command::new("git")
        .arg("-C")
        .arg(worktree)
        .args(args)
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

/// The `[drain]` config values, all optional. trace:TASK-136 BUG-420 | ai:claude
#[derive(Debug, Default, Clone, Copy)]
struct DrainConfigToml {
    gh_verify_retries: Option<usize>,
    no_progress_minutes: Option<u64>,
    phase_ceiling_minutes: Option<u64>,
}

/// Hand-rolled `[drain]`-section scanner for `.aida/config.toml`, mirroring the
/// other section readers (e.g. `read_behavior_permission_mode`) so the crate
/// stays serde-free for one small optional section. Unknown keys are ignored.
/// trace:TASK-136 BUG-420 | ai:claude
fn read_drain_config(project_dir: &std::path::Path) -> DrainConfigToml {
    let mut out = DrainConfigToml::default();
    let config_path = project_dir.join(".aida").join("config.toml");
    let Ok(content) = std::fs::read_to_string(&config_path) else {
        return out;
    };
    let mut in_drain = false;
    for raw in content.lines() {
        let line = strip_toml_inline_comment(raw).trim();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if let Some(rest) = line.strip_prefix('[') {
            in_drain = rest.trim_start_matches('[').starts_with("drain");
            continue;
        }
        if !in_drain {
            continue;
        }
        if let Some((key, val)) = line.split_once('=') {
            let key = key.trim();
            let val = val.trim().trim_matches('"').trim();
            match key {
                "gh_verify_retries" => out.gh_verify_retries = val.parse().ok(),
                "no_progress_minutes" => out.no_progress_minutes = val.parse().ok(),
                "phase_ceiling_minutes" => out.phase_ceiling_minutes = val.parse().ok(),
                _ => {}
            }
        }
    }
    out
}

struct RealPhaseDriver {
    project_root: std::path::PathBuf,
    spec: String,
    permission_mode: Option<String>,
    json: bool,
    branch: Option<String>,
    implementer_lease: Option<String>,
    pr_number: Option<u32>,
    ci_run_id: Option<String>,
    /// Cached aida binary path, resolved once at construction. Re-resolving
    /// per-call broke in BUG-217 when the implementer's phase-1 `cargo build`
    /// replaced the running dev binary: `/proc/self/exe` then includes a
    /// " (deleted)" suffix, and `Command::new("<path> (deleted)").spawn()`
    /// fails with ENOENT. trace:BUG-217 | ai:claude
    aida_exe: std::path::PathBuf,
    /// STORY-263: headless mode. `Some` → the reviewer phase is launched
    /// headless (`claude -p`); the implementer phase stays interactive in
    /// this cut (STORY-276 wires it). `None` → fully interactive.
    no_human: Option<auto_complete::NoHumanMode>,
    /// TASK-329: poll cadence + SIGTERM→SIGKILL grace for the graceful-exit
    /// signal. Resolved once from `AIDA_EXIT_POLL_MS` / `AIDA_EXIT_GRACE_MS`.
    exit_cfg: exit_signal::ExitSignalConfig,
    /// BUG-233: the corroboration token for this orchestrator run. Passed to
    /// every phase child as `AIDA_AUTO_COMPLETE_TOKEN` so the child can verify
    /// — against the live marker file — that its `AIDA_AUTO_COMPLETE=1` comes
    /// from a real orchestrator rather than guessing.
    run_token: String,
    /// STORY-306: the Claude `--session-id` the phase-1 implementer was
    /// launched with. When phase 1 punts and the advisor tier resolves the
    /// fork, `resume_implementer` `--resume`s exactly this session so the
    /// implementer re-enters its own conversation with the working model it
    /// had built. `None` until `run_implementer` mints it.
    implementer_session: Option<String>,
    /// STORY-306: the worktree the phase-1 implementer ran in. Required by
    /// `resume_implementer`: `claude --resume` finds the persisted session
    /// only when its cwd matches the cwd the session was created with (Claude
    /// derives the project slug under `~/.claude/projects/<slug>/` from cwd),
    /// so the resume must `current_dir(<this worktree>)`. `None` until
    /// `run_implementer` locates the lease.
    implementer_worktree: Option<std::path::PathBuf>,
    /// BUG-311: thread the user's `aida queue work --auto-complete --steal`
    /// flag through to the phase-1 implementer subprocess. Without this the
    /// outer `--steal` is dropped on the floor — phase 1's `handle_queue_work`
    /// sees the dormant lease, bails with the canned "pass --steal" message,
    /// and the orchestrator reports a generic phase-1 failure even though
    /// the user *did* pass --steal. trace:BUG-311 | ai:claude
    steal: bool,
    /// TASK-559: thread the user's `aida queue work --auto-complete
    /// --force-claim` flag through to the phase-1 implementer subprocess.
    force_claim: bool,
    /// STORY-281: opt out of the reviewer pre-flight stale-base refusal.
    /// When false (default), phase 3 refuses to launch the reviewer if the
    /// PR's base is behind origin AND a file the PR touches has moved on
    /// the base since the PR forked. When true, the refusal becomes a
    /// warning so review-against-stale proceeds. Also propagated to the
    /// reviewer subprocess so its own pre-flight respects the opt-out.
    /// trace:STORY-281 | ai:claude
    allow_stale_base: bool,
    /// STORY-429: opt out of phase-3 auto-rebase recovery.
    no_auto_rebase: bool,
    /// STORY-429: embedded telemetry for phase-3 stale-base auto-rebase.
    auto_rebase_events: Vec<auto_complete_telemetry::AutoRebaseEvent>,
    /// STORY-442: opt-in lifecycle short-circuit tags for non-integrity
    /// phases. Phase 2 owns CI waiting; phases 3/6 are sequenced in
    /// `auto_complete.rs`.
    lifecycle_skip: auto_complete::LifecycleSkip,
    /// TASK-136 / BUG-420: GH-verify retry budget + watchdog thresholds,
    /// resolved once from `[drain]` config + env/flag overrides.
    drain_tuning: DrainTuning,
}

#[derive(Debug, PartialEq, Eq)]
enum Phase3StaleOverlapAction {
    Proceed,
    Refuse(String),
}

/// TASK-136: the outcome of one phase-1 PR-verify attempt. The verify can
/// settle definitively (a PR found, no PR, or a hard failure) or hit a
/// *transient* GH-API outage that leaves it unable to confirm a PR — only the
/// last case is retried (with the [`auto_complete::gh_verify_backoff_schedule`]
/// backoff). trace:TASK-136 | ai:claude
/// BUG-444: given that BOTH phase-1 PR lookups returned empty-but-successful,
/// decide whether that's a *definitive* no-PR (the branch was never pushed) or a
/// *retryable* eventual-consistency window (the branch is on origin, so a PR
/// likely exists but isn't indexed yet). Only an `Absent` branch is a definitive
/// NoPr; `Present` and `LsRemoteFailed` both retry. Pure so the keystone
/// decision is unit-tested without gh/git. trace:BUG-444 | ai:claude
fn empty_phase1_lookup_is_definitive_nopr(origin: &BranchOriginProbe) -> bool {
    matches!(origin, BranchOriginProbe::Absent)
}

enum Phase1PrResolve {
    /// An open PR was found (directly or recovered via the spec-id search).
    Found(OpenPrInfo),
    /// Definitively no open PR — falls through to the punt / NoPr path.
    NoPr,
    /// A definitive hard failure (gh missing / gh errored / branch not on
    /// origin) — return it as the phase failure, no retry.
    Fail(auto_complete::PhaseFailure),
    /// Transient: GH was unreachable but the branch may carry a PR — retry,
    /// then declare Inconclusive with this reason if the budget is exhausted.
    Retry(String),
}

/// STORY-492: a `--resume-drain` re-entry context for [`run_auto_complete`] —
/// the reconciled phase to re-enter at plus the branch + PR to seed into the
/// driver (the skipped earlier phases would have discovered these). `None`
/// passed to `run_auto_complete` means a normal phase-1 drain.
/// trace:STORY-492 | ai:claude
struct ResumeEntry {
    start_phase: auto_complete::Phase,
    branch: Option<String>,
    pr: Option<u32>,
}

impl RealPhaseDriver {
    // why: command-dispatch fn whose params mirror distinct CLI flags; bundling into a struct adds indirection without clarifying the call sites.
    #[allow(clippy::too_many_arguments)]
    fn new(
        project_root: std::path::PathBuf,
        spec: String,
        permission_mode: Option<String>,
        json: bool,
        no_human: Option<auto_complete::NoHumanMode>,
        run_token: String,
        steal: bool,
        force_claim: bool,
        allow_stale_base: bool,
        no_auto_rebase: bool,
        lifecycle_skip: auto_complete::LifecycleSkip,
    ) -> Self {
        let drain_tuning = DrainTuning::resolve(&project_root);
        Self {
            project_root,
            spec,
            permission_mode,
            json,
            branch: None,
            implementer_lease: None,
            pr_number: None,
            ci_run_id: None,
            aida_exe: resolve_aida_exe(),
            no_human,
            exit_cfg: exit_signal::ExitSignalConfig::from_env(),
            run_token,
            implementer_session: None,
            implementer_worktree: None,
            steal,
            force_claim,
            allow_stale_base,
            no_auto_rebase,
            auto_rebase_events: Vec::new(),
            lifecycle_skip,
            drain_tuning,
        }
    }

    fn sessions_dir(&self) -> std::path::PathBuf {
        self.project_root.join(".aida").join("sessions")
    }

    fn aida_exe(&self) -> std::path::PathBuf {
        self.aida_exe.clone()
    }

    fn record_auto_rebase(&mut self, pr_number: u64, outcome: impl Into<String>) {
        self.auto_rebase_events
            .push(auto_complete_telemetry::AutoRebaseEvent {
                phase: auto_complete::Phase::Reviewer.index() as u8,
                pr_number,
                outcome: outcome.into(),
            });
    }

    fn should_auto_rebase_stale_base(&self, attempted: bool) -> Result<(), &'static str> {
        if self.allow_stale_base {
            return Err("allow-stale-base");
        }
        if self.no_auto_rebase {
            return Err("disabled");
        }
        if self.no_human != Some(auto_complete::NoHumanMode::Both) {
            return Err("not-fully-headless");
        }
        if attempted {
            return Err("retry-limit");
        }
        Ok(())
    }

    fn attempt_phase3_auto_rebase(&mut self, pr_number: u64) -> bool {
        if !self.json {
            eprintln!(
                "  {} stale-base + overlap detected on PR-{pr_number}; attempting one clean auto-rebase…",
                "↻".cyan()
            );
        }
        let status = std::process::Command::new(self.aida_exe())
            .current_dir(&self.project_root)
            .args(build_phase3_auto_rebase_args(pr_number))
            .status();
        match status {
            Ok(s) if s.success() => {
                self.record_auto_rebase(pr_number, "clean");
                if !self.json {
                    eprintln!(
                        "  {} PR-{pr_number} auto-rebased cleanly; proceeding with phase 3",
                        crate::glyph(crate::glyphs::Glyph::Check).green().bold()
                    );
                }
                true
            }
            Ok(_) => {
                self.record_auto_rebase(pr_number, "conflict");
                false
            }
            Err(e) => {
                self.record_auto_rebase(pr_number, format!("failed:{e}"));
                false
            }
        }
    }

    fn resolve_phase3_stale_overlap(
        &mut self,
        pr_number: u32,
        auto_rebase_attempted: &mut bool,
        msg: String,
    ) -> Phase3StaleOverlapAction {
        match self.should_auto_rebase_stale_base(*auto_rebase_attempted) {
            Ok(()) => {
                *auto_rebase_attempted = true;
                if self.attempt_phase3_auto_rebase(pr_number as u64) {
                    return Phase3StaleOverlapAction::Proceed;
                }
                Phase3StaleOverlapAction::Refuse(msg)
            }
            Err("allow-stale-base") => {
                self.record_auto_rebase(pr_number as u64, "skipped:allow-stale-base");
                eprintln!(
                    "  {} stale-base + overlap detected; `--allow-stale-base` is set, \
                     proceeding with reviewer.\n{}",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                    msg.yellow()
                );
                Phase3StaleOverlapAction::Proceed
            }
            Err(reason) => {
                self.record_auto_rebase(pr_number as u64, format!("skipped:{reason}"));
                Phase3StaleOverlapAction::Refuse(msg)
            }
        }
    }

    fn auto_punt_text_question(
        &self,
        worktree_path: &std::path::Path,
        session_uuid: &str,
    ) -> Option<String> {
        if !self
            .no_human
            .map(|m| m.wants_headless_implementer())
            .unwrap_or(false)
        {
            return None;
        }
        let content = read_headless_log_for_session(&self.project_root, session_uuid)?;
        let punt = pending_text_question_from_headless_log(&content)?;
        let status = std::process::Command::new(self.aida_exe())
            .current_dir(worktree_path)
            .args(build_auto_punt_args(&self.spec, &punt.detail, &punt.lean))
            .env("AIDA_SESSION_ROLE", "implementer")
            .status()
            .ok()?;
        if !status.success() {
            return None;
        }
        Some(format!(
            "[design-fork] {} (lean: {})",
            punt.detail, punt.lean
        ))
    }

    /// Locate the session lease `aida queue work --session-id <uuid>` created
    /// for this orchestrator phase, pinned by the `claude_session_id` the
    /// orchestrator minted. Deterministic — unaffected by concurrent leases
    /// from parallel user sessions or nested `/aida-pickup`, and immune to
    /// the `.manifest.toml` companion file that the old lease-set diff
    /// miscounted as a second lease (the BUG-114 phase-1 failure). On a miss,
    /// the error suggests bare `--resume` (continues the most recent recorded
    /// claude session) and lists the candidate lease ids as diagnostic-only —
    /// they are lease ids, not `--resume` arguments (TASK-271).
    /// trace:BUG-114 trace:TASK-271 | ai:claude
    fn discover_orchestrated_lease(
        &self,
        claude_session_id: &str,
    ) -> Result<(String, String, std::path::PathBuf), auto_complete::PhaseFailure> {
        find_orchestrated_lease(&self.project_root, claude_session_id).ok_or_else(|| {
            let candidates = lease_ids_in(&self.sessions_dir());
            if candidates.is_empty() {
                auto_complete::PhaseFailure::new(
                    "no session lease appeared — `aida queue work` did not start a session",
                )
            } else {
                // TASK-271: suggest BARE `--resume` (continues the most recent
                // recorded claude session for the scope) — never paste a listed
                // id into `--resume`, because these are LEASE ids and `--resume`
                // resolves against claude SESSION ids, so a pasted lease id hits
                // a second clean error. The lease list is diagnostic-only.
                // trace:TASK-271 trace:BUG-114 | ai:claude
                auto_complete::PhaseFailure::new(format!(
                    "could not match the orchestrated session (claude id {}) to a \
                     session lease. Resume the most recent recorded session with \
                     `aida queue work {} --resume` (bare — no id needed). \
                     Active lease id(s), for diagnosis only (NOT `--resume` \
                     arguments — these are lease ids, not claude session ids): {}.",
                    &claude_session_id[..claude_session_id.len().min(8)],
                    self.spec,
                    candidates.join(", "),
                ))
            }
        })
    }

    /// Ground-truth check for the BUG-241 reconcile: find a *merged* PR that
    /// credits the dispatched spec. BUG-357 makes the spec-credit check
    /// mandatory: an unrelated merged PR on the same/misattributed branch is
    /// not evidence that this spec shipped. Prefers the PR number an earlier
    /// phase already discovered (checked directly with
    /// [`pr_is_merged_with_sink`]); otherwise looks one up by branch.
    /// `None` when no merged PR exists, the PR credits a different spec, or
    /// `gh` can't answer — all leave the original failure standing.
    /// trace:BUG-241, BUG-286, BUG-357 | ai:claude
    fn detect_merged_pr(&self) -> Option<u32> {
        // BUG-286: route the orchestrator's reconcile-time `gh pr view`
        // through the retry helper with stderr + drain-state sinks. A
        // transient blip in this read used to leave the failure standing
        // (returning `None` is "cannot confirm", which leaves reconcile_failure
        // at GenuineFailure). Retry first, surface the retry to both channels.
        // trace:BUG-286 | ai:claude
        let mut stderr_sink = network_retry::StderrSink;
        let mut state_sink = drain_state::DrainStateSink {
            project_root: &self.project_root,
            spec: self.spec.clone(),
            phase: Some(format!(
                "{} (reconcile)",
                auto_complete::Phase::Reviewer.index()
            )),
        };
        let mut sink = network_retry::DualSink {
            a: &mut stderr_sink,
            b: &mut state_sink,
        };
        if let Some(pr) = self.pr_number {
            // We already know the PR — `gh pr view` is the direct check.
            if pr_is_merged_with_sink(&self.project_root, pr, &mut sink) != Some(true) {
                return None;
            }
            return matches!(
                pr_credit_match_with_sink(&self.project_root, pr, &self.spec, None, &mut sink),
                PrCreditMatch::Dispatched
            )
            .then_some(pr);
        }
        // Phase 1 never resolved a PR — try a branch-keyed merged-PR lookup.
        // `detect_merged_pr_for_branch` already classifies network errors
        // into `PrLookup::GhUnreachable` and the orchestrator already absorbs
        // them as "cannot confirm" — so the branch leg stays as-is.
        match self
            .branch
            .as_deref()
            .map(|b| detect_merged_pr_for_branch_via_forge(&self.project_root, b))
        {
            Some(PrLookup::Found(pr)) => matches!(
                pr_credit_match_with_sink(
                    &self.project_root,
                    pr.number as u32,
                    &self.spec,
                    Some(&pr.title),
                    &mut sink,
                ),
                PrCreditMatch::Dispatched
            )
            .then_some(pr.number as u32),
            _ => None,
        }
    }

    /// STORY-301: stamp the drain-state file with the phase about to run, so
    /// `aida drain status` (and the `/aida-pickup` banner) show live progress.
    /// Best-effort — a missing file is a silent no-op, never blocks the phase.
    /// trace:STORY-301 | ai:claude
    fn mark_drain_phase(&self, phase: auto_complete::Phase) {
        drain_state::set_phase(&self.project_root, &self.spec, phase.index(), phase.slug());
    }

    /// STORY-347: spawn one headless advisor (cold-boot OR fork) against the
    /// already-written punt request and collect its [`punt::PuntResponse`] +
    /// JSONL log path. Factored out so the calibration loop can run two
    /// passes against the same request — one cold-boot driving the drain,
    /// one fork-from-live as shadow. Returns the response and absolute log
    /// path; an error is a phase-fatal (the spawn failed or the advisor
    /// wrote no usable response).
    ///
    /// `response_path` is the file the advisor will write to — distinct
    /// paths for the primary and shadow passes so they don't clobber. The
    /// caller is responsible for clearing any stale file beforehand.
    /// trace:STORY-347 | ai:claude
    fn spawn_advisor_session(
        &self,
        pass: AdvisorPass,
        advisor_cfg: &advisor::AdvisorConfig,
        response_path: &std::path::Path,
        request_path: &std::path::Path,
    ) -> Result<(punt::PuntResponse, std::path::PathBuf), auto_complete::PhaseFailure> {
        use auto_complete::{FailureKind, PhaseFailure};

        // TASK-894: resolve the vendor that hosts the advisor tier. Default is
        // Claude — selecting Codex (via `AIDA_HEADLESS_VENDOR=codex` or
        // `[orchestrator] headless_vendor = "codex"`) is the explicit opt-in,
        // mirroring STORY-683's drain-phase generalization. A non-Claude vendor
        // has no `--resume` / session model, so the fork-from-live JSONL
        // machinery (Claude-specific) must not run; force the pass to cold-boot
        // and host a fresh spawn per punt. trace:TASK-894 | ai:claude
        let vendor = session::resolve_headless_vendor(&self.project_root);
        let pass = match pass {
            AdvisorPass::Fork(_) if vendor != session::HeadlessVendor::Claude => {
                if !self.json {
                    eprintln!(
                        "  {} vendor `{}` has no resumable session — hosting a fresh advisor per punt (no fork).",
                        "◆".dimmed(),
                        vendor.as_str()
                    );
                }
                AdvisorPass::ColdBoot
            }
            other => other,
        };

        let (advisor_uuid, forked_from) = match &pass {
            AdvisorPass::Fork(plan) => match advisor::execute_fork(plan) {
                Ok(_) => (plan.fork_uuid.clone(), Some(plan.live.clone())),
                Err(e) => {
                    if !self.json {
                        eprintln!(
                            "  {} advisor fork failed ({e}); falling back to cold-boot.",
                            "◆".yellow()
                        );
                    }
                    (uuid::Uuid::now_v7().to_string(), None)
                }
            },
            AdvisorPass::ColdBoot => (uuid::Uuid::now_v7().to_string(), None),
        };
        let is_fork = forked_from.is_some();

        let log_path = self
            .project_root
            .join(".aida")
            .join("headless-logs")
            .join(format!(
                "advise-{}-{}.jsonl",
                self.spec,
                &advisor_uuid[..advisor_uuid.len().min(8)]
            ));
        if let Some(dir) = log_path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        let log = std::fs::File::create(&log_path).map_err(|e| {
            PhaseFailure::of(
                FailureKind::Spawn,
                format!("advisor tier: could not create the headless log: {e}"),
            )
        })?;
        if !self.json {
            if let Some(live) = forked_from.as_ref() {
                let mb = live.jsonl_size_bytes as f64 / (1024.0 * 1024.0);
                eprintln!(
                    "  {} forking live advisor session {} ({:.2} MB transcript, via {}) for the design-fork…",
                    "◆".cyan(),
                    &live.uuid[..live.uuid.len().min(8)],
                    mb,
                    live.discovery.label(),
                );
            } else {
                eprintln!(
                    "  {} spawning a headless advisor (cold-boot) for the design-fork…",
                    "◆".cyan()
                );
            }
        }
        let tee_label = if is_fork { "advisor-fork" } else { "advisor" };
        let tee_opts =
            crate::headless_tee::TeeOptions::from_env_and_flag(false).with_label(tee_label);
        let tee_handle = crate::headless_tee::start_tee(&log_path, &tee_opts);
        // STORY-626: the cold-boot branch is context-poor — seed it with the
        // live advisor context file (same prepend the assess cold-boot uses),
        // so unattended punt decisions match the live session. trace:STORY-626
        // TASK-894: build the per-vendor `(program, args)` — Claude resumes the
        // forked session or cold-boots; Codex always hosts a fresh `codex exec`
        // (no resume). `is_fork` is always false for a non-Claude vendor (the
        // pass was forced to cold-boot above), so the fork JSONL is never read.
        // trace:TASK-894 | ai:claude
        let seeded = crate::intake::seeded_advise_prompt(&self.project_root);
        let (program, advisor_args) =
            session::advisor_tier_program_and_args(vendor, is_fork, &seeded, &advisor_uuid);
        let status = std::process::Command::new(&program)
            .current_dir(&self.project_root)
            .args(advisor_args)
            .env("AIDA_HEADLESS", "1")
            .env(punt::REQUEST_FILE_ENV, request_path)
            .env(punt::RESPONSE_FILE_ENV, response_path)
            // TASK-586: the advisor tier runs as the advisor role.
            .env("AIDA_SESSION_ROLE", "advisor")
            .stdout(std::process::Stdio::from(log))
            .status()
            .map_err(|e| {
                PhaseFailure::of(
                    FailureKind::Spawn,
                    format!("advisor tier: could not launch the advisor session: {e}"),
                )
            })?;
        tee_handle.stop();

        // Clean up the fork JSONL if the config asks us to. Default is to
        // keep it for audit. Errors are non-fatal.
        if is_fork && !advisor_cfg.keep_fork_jsonls {
            if let AdvisorPass::Fork(plan) = &pass {
                let _ = std::fs::remove_file(&plan.fork_jsonl);
            }
        }
        if !status.success() {
            return Err(PhaseFailure::new(format!(
                "the headless advisor session exited {} — see {}",
                status
                    .code()
                    .map(|c| c.to_string())
                    .unwrap_or_else(|| "with a signal".to_string()),
                log_path.display(),
            )));
        }
        let response = punt::read_punt_response(response_path).ok_or_else(|| {
            PhaseFailure::of(
                FailureKind::Internal,
                format!(
                    "the headless advisor wrote no usable response — see {}",
                    log_path.display()
                ),
            )
        })?;
        Ok((response, log_path))
    }
}

/// STORY-347: which kind of advisor pass to spawn — a fresh cold-boot
/// `claude -p` (substrate only) or a fork-from-live `claude --resume` on a
/// copied JSONL. The orchestrator decides which up front; this enum is the
/// internal type that flows into `spawn_advisor_session`.
/// trace:STORY-347 | ai:claude
enum AdvisorPass {
    ColdBoot,
    Fork(advisor::ForkPlan),
}

/// STORY-347: resolve the effective calibration mode for the current
/// orchestrator run. The `AIDA_CALIBRATE=1`/`0` env var (set by the
/// `--calibrate`/`--no-calibrate` queue-work flags) overrides
/// `[advisor] calibration_mode` from `.aida/config.toml`.
/// trace:STORY-347 | ai:claude
fn effective_calibration_mode(cfg: &advisor::AdvisorConfig) -> advisor::CalibrationMode {
    match std::env::var("AIDA_CALIBRATE").ok().as_deref() {
        Some("1") | Some("true") | Some("on") | Some("yes") => advisor::CalibrationMode::On,
        Some("0") | Some("false") | Some("off") | Some("no") => advisor::CalibrationMode::Off,
        _ => cfg.calibration_mode,
    }
}

impl RealPhaseDriver {
    /// STORY-492: seed the branch + PR a `--resume-drain` re-entry skipped
    /// phases would have discovered, so the resumed phases (CI / reviewer /
    /// merge / pull) have the context they need. Called once before
    /// `orchestrate_with_resume` on a resume. trace:STORY-492 | ai:claude
    fn seed_resume_state(&mut self, branch: Option<String>, pr: Option<u32>) {
        if branch.is_some() {
            self.branch = branch;
        }
        if pr.is_some() {
            self.pr_number = pr;
        }
    }

    /// TASK-136: one phase-1 PR-verify attempt, factored out of
    /// [`Self::run_implementer`] so the transient GH-unreachable case can be
    /// retried with a backoff. Encapsulates the BUG-223 branch-then-spec
    /// fallback and the BUG-257 `git ls-remote` narrowing. Mutates `self.branch`
    /// when the spec-id search recovers a swapped branch. trace:TASK-136
    fn detect_phase1_pr(&mut self, branch: &str) -> Phase1PrResolve {
        // STORY-516: forge-routed branch lookup (view op). The inner spec-id
        // search (detect_open_pr_for_spec) is the LIST op — routed in a later
        // slice — so it stays PrLookup here. The BUG-444/BUG-257 narrowing
        // bodies are unchanged; only the outer variant names move to
        // ChangeLookup. trace:STORY-516 trace:BUG-444 trace:BUG-257 | ai:claude
        match change_lookup_for_branch(&self.project_root, branch) {
            crate::forge::ChangeLookup::Found(c) => Phase1PrResolve::Found(OpenPrInfo {
                number: c.id,
                title: c.title.unwrap_or_default(),
                url: c.url,
            }),
            crate::forge::ChangeLookup::NoChange => {
                match detect_open_pr_for_spec_via_forge(&self.project_root, &self.spec) {
                    PrLookup::Found(pr) => {
                        // Realign the branch so the CI / merge phases probe the
                        // PR's actual head, not the worktree HEAD the branch-keyed
                        // lookup just missed on. trace:BUG-223
                        if let Some(head) = pr_head_branch(&self.project_root, pr.number) {
                            self.branch = Some(head);
                        }
                        eprintln!(
                            "  {} no open PR on branch `{}` — recovered PR-{} via a `{}` \
                         search (the implementer branch was swapped by /aida-pr's \
                         merged-branch guard)",
                            "ⓘ".cyan(),
                            branch,
                            pr.number,
                            self.spec,
                        );
                        Phase1PrResolve::Found(pr)
                    }
                    // BUG-444: both the `--head` and `--search` lookups returned
                    // empty-BUT-SUCCESSFUL. These are eventually-consistent GitHub
                    // LIST queries (`--search` hits the search index, which lags PR
                    // creation by seconds), so an empty result right after
                    // `/aida-pr` ran `gh pr create` does NOT mean "no PR" — it
                    // usually means "not indexed yet". If the branch is on origin
                    // the session pushed, so a PR very likely exists: RETRY within
                    // the eventual-consistency window (reusing the TASK-136 backoff)
                    // instead of declaring a false NoPr. Only a branch that is
                    // genuinely absent from origin is an immediate NoPr (the session
                    // never pushed). This was the dominant drain-failure cause:
                    // ~98% of sessions ship a PR, yet a whole batch could false-fail
                    // by racing the index. trace:BUG-444 EPIC-33 | ai:claude
                    _ => {
                        let origin = probe_branch_on_origin(&self.project_root, branch);
                        if empty_phase1_lookup_is_definitive_nopr(&origin) {
                            Phase1PrResolve::NoPr
                        } else {
                            let reason = match origin {
                                BranchOriginProbe::Present => format!(
                                    "no open PR indexed yet for `{branch}` (and the \
                                 `{spec}` search), but the branch is on origin — \
                                 likely GitHub eventual-consistency lag after \
                                 `gh pr create`",
                                    spec = self.spec
                                ),
                                _ => format!(
                                    "no open PR found for `{branch}` and `git ls-remote` \
                                 could not confirm whether the branch is on origin — \
                                 retrying before concluding no PR exists"
                                ),
                            };
                            Phase1PrResolve::Retry(reason)
                        }
                    }
                }
            }
            crate::forge::ChangeLookup::CliMissing => {
                Phase1PrResolve::Fail(auto_complete::PhaseFailure::of(
                    auto_complete::FailureKind::MissingTool,
                    "`gh` is not on PATH — auto-complete needs it to track the PR",
                ))
            }
            crate::forge::ChangeLookup::CliFailed(why) => {
                Phase1PrResolve::Fail(auto_complete::PhaseFailure::new(format!(
                    "could not look up the PR for `{branch}`: {why}"
                )))
            }
            // BUG-257: the GH API was unreachable — *transient*, not "no PR".
            // Narrow with `git ls-remote` (git protocol, separate from the
            // HTTPS API): if the branch isn't on origin no PR can exist, so
            // that collapses to a genuine NoPR failure. Otherwise it is a
            // retryable inconclusive. trace:BUG-257 TASK-136 | ai:claude
            crate::forge::ChangeLookup::Unreachable(why) => {
                match probe_branch_on_origin(&self.project_root, branch) {
                    BranchOriginProbe::Absent => {
                        Phase1PrResolve::Fail(auto_complete::PhaseFailure::of(
                            auto_complete::FailureKind::NoPr,
                            format!(
                                "GH API unreachable ({why}), and `git ls-remote` confirms \
                             branch `{branch}` is not on origin — no PR can exist. \
                             Resume the session and push: `aida queue work {spec} --resume`",
                                spec = self.spec
                            ),
                        ))
                    }
                    BranchOriginProbe::Present => Phase1PrResolve::Retry(format!(
                        "GH API unreachable ({why}); branch `{branch}` is on origin \
                     so a PR may exist — cannot confirm without the API"
                    )),
                    BranchOriginProbe::LsRemoteFailed => Phase1PrResolve::Retry(format!(
                        "GH API unreachable ({why}); `git ls-remote` also failed — \
                     cannot determine whether a PR exists for `{branch}`"
                    )),
                }
            }
        }
    }
}

impl auto_complete::PhaseDriver for RealPhaseDriver {
    fn run_implementer(
        &mut self,
    ) -> Result<auto_complete::ImplementerOutcome, auto_complete::PhaseFailure> {
        self.mark_drain_phase(auto_complete::Phase::Implementer);
        let session_uuid = uuid::Uuid::now_v7().to_string();
        // STORY-306: remember the minted session id — if phase 1 punts and the
        // advisor tier resolves the fork, `resume_implementer` `--resume`s
        // exactly this session. trace:STORY-306 | ai:claude
        self.implementer_session = Some(session_uuid.clone());

        let headless_impl = self
            .no_human
            .map(|m| m.wants_headless_implementer())
            .unwrap_or(false);
        let args = build_implementer_phase_args(
            &self.spec,
            &session_uuid,
            self.steal,
            self.force_claim,
            headless_impl,
            self.permission_mode.as_deref(),
        );
        let mut cmd = std::process::Command::new(self.aida_exe());
        cmd.current_dir(&self.project_root)
            .args(&args)
            .env(orchestrator::AUTO_COMPLETE_ENV, "1")
            // BUG-233: the corroboration token, so the child can verify this
            // orchestrator run is live rather than guessing from the bare var.
            .env(orchestrator::TOKEN_ENV, &self.run_token);
        // TASK-306: tell the child's statusline this is phase 1 of 6 (and the
        // `--no-human` scope) so the interactive implementer session shows it
        // is an orchestrator phase the user is expected to act in.
        // trace:TASK-306 | ai:claude
        cmd.env(
            orchestrator::PHASE_ENV,
            auto_complete::Phase::Implementer.index().to_string(),
        );
        if let Some(mode) = self.no_human {
            cmd.env(orchestrator::NO_HUMAN_MODE_ENV, mode.slug());
        }

        // STORY-276: provision the punt-signal handshake. An implementer that
        // hits a design-fork runs `aida punt`, which drops a signal file at
        // this path (it reads `AIDA_PUNT_SIGNAL_FILE`). Clear any stale file
        // from a prior run, then point the subprocess at it. Set for every
        // mode — an interactive `--auto-complete` implementer can punt too,
        // and the orchestrator must park gracefully rather than report a
        // phantom NoPr failure. Mirrors the reviewer's verdict-file handshake.
        // trace:STORY-276 | ai:claude
        let punt_signal = punt::signal_path(&self.project_root, &self.spec);
        if let Some(parent) = punt_signal.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let _ = std::fs::remove_file(&punt_signal);
        cmd.env(punt::SIGNAL_FILE_ENV, &punt_signal);

        // BUG-250: provision the PR-hold handshake the same way. An implementer
        // that deliberately holds the PR (branch pushed, PR withheld for a
        // manual gate) runs `aida pr hold`, which drops a `HoldSignal` at this
        // path. The orchestrator reads it after the session exits and reports a
        // clean `Held` outcome rather than a phantom NoPr failure. Clear any
        // stale file from a prior run first. trace:BUG-250 | ai:claude
        let hold_signal = punt::hold_signal_path(&self.project_root, &self.spec);
        if let Some(parent) = hold_signal.parent() {
            let _ = std::fs::create_dir_all(parent);
        }
        let _ = std::fs::remove_file(&hold_signal);
        cmd.env(punt::HOLD_SIGNAL_FILE_ENV, &hold_signal);

        // TASK-329: spawn + poll for the graceful-exit sentinel rather than a
        // blocking `.status()`. In interactive `--zen` mode the skill
        // auto-resolves its end-of-drain prompt and goes idle, but the Claude
        // Code REPL has no EOF to synthesize from inside its own session
        // (BUG-230) — so the orchestrator reaps the child when the skill
        // touches `.aida/sessions/<session-id>.exit-requested`. A child that
        // exits on its own is still reaped immediately; the sentinel is
        // additive, not a replacement. Protocol: see the `exit_signal` module.
        // trace:TASK-329 | ai:claude
        let sentinel = exit_signal::sentinel_path(&self.sessions_dir(), &session_uuid);
        // BUG-420: arm the no-progress / ceiling watchdog for a *headless*
        // implementer only — an interactive REPL legitimately idles waiting for
        // the user, so it must never be killed for "no progress". The closure
        // owns its own coarse git-poll cadence; the spawn loop just consults it.
        // trace:BUG-420 | ai:claude
        let mut watchdog = headless_impl.then(|| {
            PhaseWatchdog::new(
                self.project_root.clone(),
                session_uuid.clone(),
                self.drain_tuning.no_progress,
                self.drain_tuning.ceiling,
            )
        });
        let mut wd_closure = watchdog.as_mut().map(|w| move || w.check());
        let wd_dyn: Option<&mut dyn FnMut() -> Option<String>> = wd_closure
            .as_mut()
            .map(|c| c as &mut dyn FnMut() -> Option<String>);
        // TASK-298: a headless implementer launches `claude -p`, which spawns
        // an agent test-worker pool; put it in its own process group so the reap
        // sweeps the whole group on every exit path. An interactive implementer
        // keeps the tree-walk-only path so its REPL stays interactive.
        // trace:TASK-298 | ai:claude
        let outcome = exit_signal::spawn_and_wait_watched(
            cmd,
            &sentinel,
            &self.exit_cfg,
            wd_dyn,
            headless_impl,
        )
        .map_err(|e| {
            auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::Spawn,
                format!("could not launch the implementer session: {e}"),
            )
        })?;
        // BUG-420: the watchdog killed a degenerate headless session — surface
        // it as a shelvable phase-1 failure so a batch drain parks the spec and
        // advances. trace:BUG-420 | ai:claude
        if let exit_signal::ExitOutcome::WatchdogTripped(reason) = &outcome {
            return Err(auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::Watchdog,
                format!("the implementer phase watchdog stopped the session — {reason}"),
            ));
        }
        if let exit_signal::ExitOutcome::Natural(status) = &outcome {
            if !status.success() {
                // BUG-266: before classifying this as a phase-1 failure,
                // inspect the headless `claude -p` JSONL log for telltale
                // signs that the Anthropic API took the session out
                // (529 / 5xx / `Overloaded` / `upstream connect error` /
                // `stream timeout`). A transient upstream outage is not the
                // implementer attempting and failing the work — it is
                // *Inconclusive*, on the same terms BUG-257 introduced for
                // the GH-API leg. The drain pauses cleanly; the operator
                // resumes with the printed `aida queue work <spec> --resume
                // <session-id>` hint, which re-attaches to this exact
                // session via Claude Code's persisted JSONL.
                // trace:BUG-266 | ai:claude
                if self
                    .no_human
                    .map(|m| m.wants_headless_implementer())
                    .unwrap_or(false)
                {
                    if let Some(reason_line) =
                        read_headless_log_for_session(&self.project_root, &session_uuid)
                            .as_deref()
                            .and_then(claude_log_indicates_api_outage)
                    {
                        // TASK-402 (friction #1 + #5): make this retry hint
                        // paste-ready. The headless implementer ran in a
                        // sibling worktree, so `claude --resume` (project-slug
                        // scoped by cwd) is invisible from the main repo — emit
                        // the `cd <worktree>` step alongside the *full* session
                        // UUID. trace:TASK-402 | ai:claude
                        let resume_base =
                            format!("aida queue work {} --resume {}", self.spec, session_uuid);
                        let resume_cmd = resume_command_with_cwd(
                            &resume_base,
                            self.implementer_worktree
                                .as_deref()
                                .map(|p| p.to_string_lossy())
                                .as_deref(),
                            std::env::current_dir()
                                .ok()
                                .map(|p| p.to_string_lossy().into_owned())
                                .as_deref(),
                        );
                        let hint =
                            format!("Anthropic API was unavailable; resume with: `{resume_cmd}`");
                        return Ok(auto_complete::ImplementerOutcome::Inconclusive {
                            reason: format!(
                                "Anthropic API outage during the headless implementer: {reason_line}"
                            ),
                            retry_hint: Some(hint),
                        });
                    }
                }
                return Err(auto_complete::PhaseFailure::new(format!(
                    "the implementer session exited {} — it was aborted or errored",
                    status
                        .code()
                        .map(|c| c.to_string())
                        .unwrap_or_else(|| "with a signal".to_string())
                )));
            }
        } else {
            eprintln!(
                "  {} implementer skill signalled completion — session reaped",
                "ⓘ".cyan()
            );
        }

        // Locate the session `queue work` created — pinned by the id we
        // minted into `--session-id`, not a lease-set diff (BUG-114).
        let (lease_id, recorded_branch, worktree_path) =
            self.discover_orchestrated_lease(&session_uuid)?;
        self.implementer_lease = Some(lease_id.clone());
        // STORY-306: remember the worktree — `resume_implementer` must run
        // `claude --resume` with this exact cwd so Claude's project-slug
        // derivation finds the persisted session.
        self.implementer_worktree = Some(worktree_path.clone());

        // STORY-276: did the implementer punt? `aida punt` dropped the signal
        // file and the spec is now parked in NeedsAttention — there is no PR
        // to chase. Hand the punt up so `orchestrate` routes it through the
        // STORY-306 advisor tier.
        //
        // STORY-306: do NOT end the session here. STORY-276 ran `aida session
        // end` on a punt (a punt was terminal then) — but now the advisor tier
        // may resolve the fork and resume *this exact session* (`claude -p
        // --resume`), which needs the lease + worktree intact. So the punted
        // session persists. An escalate-blocks punt that is never resumed
        // leaves the worktree to a later cleanup pass — a filed followup. The
        // branch is reconciled from the worktree HEAD now so a resume +
        // PR-lookup has it. trace:STORY-276, STORY-306 | ai:claude
        if let Some(signal) = punt::read_signal(&punt_signal) {
            let _ = std::fs::remove_file(&punt_signal);
            self.branch = Some(reconcile_orchestrated_branch(
                &self.project_root,
                &lease_id,
                &worktree_path,
                &recorded_branch,
            ));
            return Ok(auto_complete::ImplementerOutcome::Punted {
                reason: signal.summary(),
            });
        }

        // BUG-250: did the implementer deliberately HOLD the PR? `aida pr hold`
        // dropped the hold-signal file — the branch is pushed but the PR was
        // intentionally withheld for a manual gate. This must be checked BEFORE
        // the "no open PR → failure" path below, or a deliberate hold gets
        // mis-filed as a phase-1 failure with a wrong recovery hint (the exact
        // BUG-250 symptom). Reconcile the branch from the worktree HEAD so the
        // epilogue's `gh pr create` hint + a later resume target the pushed
        // branch. Unlike the punt signal, the hold marker is NOT removed here —
        // it persists so a resume can recognise the deliberate-hold state.
        // trace:BUG-250 | ai:claude
        if let Some(signal) = punt::read_hold_signal(&hold_signal) {
            let held_branch = reconcile_orchestrated_branch(
                &self.project_root,
                &lease_id,
                &worktree_path,
                &recorded_branch,
            );
            self.branch = Some(held_branch.clone());
            return Ok(auto_complete::ImplementerOutcome::Held {
                reason: signal.reason,
                branch: held_branch,
            });
        }

        // BUG-223: the branch recorded in the lease is a session-start
        // snapshot. If `/aida-pr` hit BUG-88's merged-branch-name guard
        // during the implementer phase it moved the commits to a fresh
        // branch, and the recorded branch is now stale. The worktree's
        // live HEAD is ground truth — reconcile from it (rewriting the
        // lease so `aida session end` agrees) before the PR lookup.
        // trace:BUG-223 | ai:claude
        let branch = reconcile_orchestrated_branch(
            &self.project_root,
            &lease_id,
            &worktree_path,
            &recorded_branch,
        );
        self.branch = Some(branch.clone());

        // The pipeline has nothing to review or merge without a PR — verify
        // the implementer opened one before exiting. The branch-keyed lookup
        // is primary; if it comes up empty — a swap the worktree-HEAD
        // reconciliation above could not catch (detached HEAD, worktree
        // already gone) — fall back to a spec-id search before declaring a
        // false negative. trace:BUG-223 | ai:claude
        //
        // TASK-136: a *transient* GH-API outage (the BUG-257 `Inconclusive`
        // case) is retried with a bounded backoff before the orchestrator
        // gives up — a momentary blip clears here rather than pausing /
        // shelving the whole drain. Only the unreachable case retries; a
        // definitive Found / NoPr / hard-failure breaks out immediately.
        // trace:TASK-136 | ai:claude
        let schedule =
            auto_complete::gh_verify_backoff_schedule(self.drain_tuning.gh_verify_retries);
        let mut attempt = 0usize;
        let pr = loop {
            match self.detect_phase1_pr(&branch) {
                Phase1PrResolve::Found(pr) => break Some(pr),
                Phase1PrResolve::NoPr => break None,
                Phase1PrResolve::Fail(f) => return Err(f),
                Phase1PrResolve::Retry(reason) => {
                    if attempt < schedule.len() {
                        let wait = schedule[attempt];
                        attempt += 1;
                        if !self.json {
                            eprintln!(
                                "  {} GH verify inconclusive (attempt {}/{}) — retrying in {}s: {}",
                                crate::glyph(crate::glyphs::Glyph::Hourglass).yellow(),
                                attempt,
                                schedule.len(),
                                wait.as_secs(),
                                reason,
                            );
                        }
                        std::thread::sleep(wait);
                        continue;
                    }
                    // Retry budget exhausted and still unreachable. The
                    // batch-vs-single shelve/pause decision is made upstream in
                    // `orchestrate_with_lifecycle_skip` from this Inconclusive.
                    return Ok(auto_complete::ImplementerOutcome::Inconclusive {
                        reason,
                        retry_hint: None,
                    });
                }
            }
        };

        match pr {
            Some(pr) => {
                self.pr_number = Some(pr.number as u32);
                Ok(auto_complete::ImplementerOutcome::PrOpened)
            }
            None => {
                // BUG-459: substrate-as-bouncer for the "implementer committed
                // its work but asked 'want me to push + open a PR?' instead of
                // acting" headless no-op. The skill already forbids this, but a
                // confident model still does it occasionally — so don't depend on
                // model compliance: if the branch has real commits ahead of main,
                // the work IS there and recoverable, so the ORCHESTRATOR opens the
                // PR itself (reusing the forge-routed pr_ship_create_pr) rather
                // than failing/punting. trace:BUG-459 | ai:claude
                let ahead = branch_commits_ahead_main(&self.project_root, &branch).unwrap_or(0);
                if ahead > 0 {
                    match pr_ship_create_pr(&self.project_root, &branch) {
                        Ok(pr) => {
                            if !self.json {
                                eprintln!(
                                    "  {} implementer left {} commit(s) with no PR — opened PR-{} \
                                     for it (BUG-459 recovery)",
                                    "ⓘ".cyan(),
                                    ahead,
                                    pr
                                );
                            }
                            self.pr_number = Some(pr as u32);
                            return Ok(auto_complete::ImplementerOutcome::PrOpened);
                        }
                        Err(e) => {
                            if !self.json {
                                eprintln!(
                                    "  {} could not auto-open a PR for the committed work \
                                     ({e:#}) — falling back to punt/fail",
                                    crate::glyph(crate::glyphs::Glyph::Warning).yellow()
                                );
                            }
                        }
                    }
                }
                if let Some(reason) = self.auto_punt_text_question(&worktree_path, &session_uuid) {
                    return Ok(auto_complete::ImplementerOutcome::Punted { reason });
                }
                Err(auto_complete::PhaseFailure::of(
                    auto_complete::FailureKind::NoPr,
                    "the implementer session exited cleanly but opened no PR — \
                     run `/aida-pr` inside the session before exiting",
                ))
            }
        }
    }

    fn finish_ci(&mut self) -> Result<(), auto_complete::PhaseFailure> {
        self.mark_drain_phase(auto_complete::Phase::Ci);
        let branch = self.branch.clone().ok_or_else(|| {
            auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::Internal,
                "internal: branch not resolved before the CI phase",
            )
        })?;

        // Probe, then block until CI is terminal unless the spec opted into
        // lifecycle:no-ci-wait / lifecycle:trivial. The non-waiting path still
        // records the PR number and still ends the implementer lease below;
        // it just lets CI finish in parallel with review/merge. trace:STORY-442
        let mut probe = ci_probe_via_forge(&branch); // STORY-516: forge-routed
        if matches!(probe, CiProbe::InProgress { .. }) && self.lifecycle_skip.no_ci_wait {
            eprintln!(
                "  {} CI still running on `{}` — skipping wait per lifecycle tag.",
                "↷".cyan(),
                branch
            );
        } else if matches!(probe, CiProbe::InProgress { .. }) {
            eprintln!(
                "  {} waiting for CI on `{}` to finish…",
                crate::glyph(crate::glyphs::Glyph::InFlight).yellow(),
                branch
            );
            probe = if self.json {
                wait_for_ci_terminal(&branch)
            } else {
                watch_ci_for_context_via_forge(&branch, self.no_human.is_some())
                // STORY-516
            };
        }

        match probe {
            CiProbe::Green { pr_number } => {
                self.pr_number = Some(pr_number);
            }
            CiProbe::Red {
                pr_number,
                failed_summary,
            } => {
                self.pr_number = Some(pr_number);
                self.ci_run_id = latest_run_id_for_branch(&branch);
                return Err(auto_complete::PhaseFailure::of(
                    auto_complete::FailureKind::CiRed,
                    format!("CI is red on PR-{pr_number}: {failed_summary}"),
                ));
            }
            CiProbe::PrNoChecks { pr_number } => {
                self.pr_number = Some(pr_number);
                eprintln!(
                    "  {} PR-{pr_number} has no CI checks — nothing to gate on.",
                    "ⓘ".cyan()
                );
            }
            CiProbe::InProgress { pr_number } => {
                self.pr_number = Some(pr_number);
                if !self.lifecycle_skip.no_ci_wait {
                    return Err(auto_complete::PhaseFailure::of(
                        auto_complete::FailureKind::CiTimeout,
                        format!("CI on PR-{pr_number} did not reach a terminal state in time"),
                    ));
                }
            }
            CiProbe::NoSignal(reason) => {
                // We confirmed a PR in phase 1, so this is an environment
                // issue (gh missing / lookup failed), not "no PR". Can't
                // gate on CI — proceed with a warning.
                eprintln!(
                    "  {} CI state unavailable ({reason}) — proceeding without a CI gate.",
                    "ⓘ".cyan()
                );
            }
        }

        // CI cleared — end the implementer session. This removes the
        // worktree and auto-queues the `Review PR-N` item for the reviewer.
        let lease = self.implementer_lease.clone().ok_or_else(|| {
            auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::Internal,
                "internal: implementer lease not recorded",
            )
        })?;
        let status = std::process::Command::new(self.aida_exe())
            .current_dir(&self.project_root)
            .args(["session", "end", &lease, "--yes", "--skip-ci"])
            .status()
            // A spawn failure here is local subprocess plumbing, not red CI —
            // tag it `Spawn` so the hint says so. trace:BUG-218 | ai:claude
            .map_err(|e| {
                auto_complete::PhaseFailure::of(
                    auto_complete::FailureKind::Spawn,
                    format!("could not run `aida session end`: {e}"),
                )
            })?;
        if !status.success() {
            return Err(auto_complete::PhaseFailure::new(
                "could not end the implementer session — it may have uncommitted \
                 changes; commit or discard them, then re-run",
            ));
        }
        Ok(())
    }

    fn run_reviewer(
        &mut self,
    ) -> Result<auto_complete::ReviewerOutcome, auto_complete::PhaseFailure> {
        self.mark_drain_phase(auto_complete::Phase::Reviewer);
        let pr = self.pr_number.ok_or_else(|| {
            auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::Internal,
                "internal: PR number not resolved before the review phase",
            )
        })?;

        // STORY-501: ensure the "Review PR-N" hand-off story exists before we
        // hand the PR to `aida queue work PR-N`. Normally phase 2 (finish_ci →
        // `aida session end`) mints it — but a `--resume-drain` that re-enters
        // here SKIPPED phase 2, so without this the review story is missing and
        // `queue work PR-N` falls back to PR→spec→`/aida-pickup`: an implementer
        // pickup that OWNS and re-implements the spec (the shared root of
        // BUG-436, BUG-438, and the duplicate-PR). With the story present,
        // `queue work PR-N` takes the review path (review_target=Some → role
        // reviewer, `/aida-review`, PR-scoped lease — no spec ownership).
        //
        // Idempotent: a normal drain finds the story already queued and no-ops
        // (silent). A transient `gh` failure to mint is non-fatal — the reviewer
        // proceeds and the BUG-436/BUG-438 guards backstop the fallback.
        // trace:STORY-501 | ai:claude
        if let Some(branch) = self.branch.clone() {
            let outcome = try_auto_queue_pr_review(
                &self.project_root,
                &branch,
                &uuid::Uuid::now_v7().to_string(),
                AutoQueueOrigin::SessionEnd,
            );
            match outcome.status {
                // Minted now (the resume case) or couldn't mint (gh down) —
                // surface it. AlreadyExists (normal drain) / by-design skips
                // stay silent so the normal path is unchanged.
                AutoQueueStatus::Filed | AutoQueueStatus::SkippedNeedsAttention => {
                    render_auto_queue_outcome(&outcome);
                }
                AutoQueueStatus::AlreadyExists | AutoQueueStatus::SkippedByDesign => {}
            }
        }

        // STORY-281: pre-flight stale-base check before launching the
        // headless reviewer. The 2026-05-17 self-test surfaced the
        // failure mode — PR queued for review with two PRs merged in
        // the interim, one touching the same file. Block if the PR's
        // base is behind origin AND a file the PR touches has moved on
        // base since fork. `--allow-stale-base` opts out.
        // A failure inside the check itself (gh missing, fetch failure)
        // logs a warning and proceeds — we never block a drain on
        // transient infrastructure issues, only on confirmed-stale
        // confirmed-overlap. trace:STORY-281 | ai:claude
        // trace:BUG-473 | ai:claude
        // Single-pass check (not a loop): BUG-364 deliberately changed the old
        // `continue` (re-check the base after rebasing) into trust-the-rebase-and-
        // proceed, so every arm settles the decision on the first evaluation. The
        // `auto_rebase_attempted` flag is retained because `resolve_phase3_stale_overlap`
        // / `should_auto_rebase_stale_base` take it by `&mut` to guard a second
        // rebase attempt; with no re-entry it is always `false` here.
        let mut auto_rebase_attempted = false;
        match preflight_stale_base_check(&self.project_root, pr as u64) {
            Ok(pr_rebase::StaleBaseOutcome::Current) => {}
            Ok(pr_rebase::StaleBaseOutcome::StaleNoOverlap { behind }) => {
                eprintln!(
                    "  {} {}",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                    pr_rebase::stale_base_warn_message(pr as u64, behind).yellow()
                );
            }
            Ok(pr_rebase::StaleBaseOutcome::StaleOverlap {
                behind,
                overlap_files,
                ..
            }) => {
                let msg = pr_rebase::stale_base_block_message(pr as u64, behind, &overlap_files);
                match self.resolve_phase3_stale_overlap(pr, &mut auto_rebase_attempted, msg) {
                    Phase3StaleOverlapAction::Proceed => {}
                    Phase3StaleOverlapAction::Refuse(msg) => {
                        return Err(auto_complete::PhaseFailure::new(msg));
                    }
                }
            }
            Err(e) => {
                eprintln!(
                    "  {} pre-flight stale-base check failed ({e}); proceeding with reviewer",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold()
                );
            }
        }

        // TASK-480: pre-flight intermediate-only check — sibling
        // substrate-as-bouncer gate to the stale-base loop above. Refuse
        // the reviewer (park NeedsAttention via PhaseFailure) when the
        // PR's diff is exclusively intermediate/generated paths, because
        // the fix is not reproducible. `--allow-intermediate-only`
        // (env `AIDA_ALLOW_INTERMEDIATE_ONLY`) opts out. Fails open on
        // infra error, same as stale-base. trace:TASK-480 | ai:claude
        {
            let allow = std::env::var("AIDA_ALLOW_INTERMEDIATE_ONLY")
                .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
                .unwrap_or(false);
            match preflight_intermediate_only_check(&self.project_root, pr as u64) {
                Ok(pr_rebase::IntermediateOnlyOutcome::Clean) => {}
                Ok(pr_rebase::IntermediateOnlyOutcome::SourcePlusIntermediate { intermediate }) => {
                    eprintln!(
                        "  {} {}",
                        crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                        pr_rebase::intermediate_only_warn_message(pr as u64, &intermediate)
                            .yellow()
                    );
                }
                Ok(pr_rebase::IntermediateOnlyOutcome::IntermediateOnly { intermediate }) => {
                    let msg = pr_rebase::intermediate_only_block_message(pr as u64, &intermediate);
                    if allow {
                        eprintln!(
                            "  {} intermediate-only diff detected; \
                             `--allow-intermediate-only` set, proceeding.\n{}",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold(),
                            msg.yellow()
                        );
                    } else {
                        return Err(auto_complete::PhaseFailure::new(msg));
                    }
                }
                Err(e) => {
                    eprintln!(
                        "  {} pre-flight intermediate-only check failed ({e}); \
                         proceeding with reviewer",
                        crate::glyph(crate::glyphs::Glyph::Warning).yellow().bold()
                    );
                }
            }
        }

        let mode = read_review_mode(&self.project_root);
        if mode == "delegated" {
            eprintln!(
                "  {} Review mode set to 'delegated' — triggering remote review on PR {}",
                "ⓘ".cyan(),
                pr
            );

            // The MissingTool guard also provides `gh` for the downstream
            // check-run polling (step 2), which is not part of the comment op.
            let gh = resolve_gh_binary().ok_or_else(|| {
                auto_complete::PhaseFailure::of(
                    auto_complete::FailureKind::MissingTool,
                    "`gh` is not on PATH — cannot trigger delegated review",
                )
            })?;

            // 1. Trigger review via PR comment (STORY-516: forge-routed `gh pr
            // comment`). trace:STORY-516 | ai:claude
            let review_change = crate::forge::ChangeRef {
                id: pr as u64,
                url: String::new(),
                branch: String::new(),
                base: String::new(),
                title: None,
            };
            if let Err(e) = crate::forge::forge_for(&self.project_root)
                .comment(&review_change, "@claude review once")
            {
                return Err(auto_complete::PhaseFailure::new(format!(
                    "failed to comment on PR {pr} to trigger delegated review: {e:#}"
                )));
            }

            // 2. Poll check-runs on the head SHA
            let sha = current_branch_head_sha(&self.project_root).ok_or_else(|| {
                auto_complete::PhaseFailure::of(
                    auto_complete::FailureKind::Internal,
                    "could not resolve head SHA of the current branch",
                )
            })?;

            eprintln!(
                "  {} Head SHA is {}; polling check-runs for severity tally...",
                "ⓘ".cyan(),
                sha
            );

            let start_poll = std::time::Instant::now();
            let timeout = std::time::Duration::from_secs(600); // 10 minutes timeout
            let interval = std::time::Duration::from_secs(10); // poll every 10 seconds
            let mut severity_data: Option<serde_json::Value> = None;

            while start_poll.elapsed() < timeout {
                let cmd_output = std::process::Command::new(&gh)
                    .current_dir(&self.project_root)
                    .args([
                        "api",
                        &format!("repos/:owner/:repo/commits/{}/check-runs", sha),
                    ])
                    .output();

                match cmd_output {
                    Ok(output) if output.status.success() => {
                        let body = String::from_utf8_lossy(&output.stdout);
                        if let Some(parsed) = extract_bughunter_severity(&body) {
                            severity_data = Some(parsed);
                            break;
                        }
                    }
                    Ok(output) => {
                        let err_msg = String::from_utf8_lossy(&output.stderr);
                        eprintln!(
                            "    {} Poll error: gh api returned non-zero status: {}",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                            err_msg.trim()
                        );
                    }
                    Err(e) => {
                        eprintln!(
                            "    {} Poll error: could not execute gh api: {}",
                            crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                            e
                        );
                    }
                }

                std::thread::sleep(interval);
            }

            // 3. Process outcomes / fail-safe
            if let Some(data) = severity_data {
                if let Some(obj) = data.as_object() {
                    let normal = obj.get("normal").and_then(|n| n.as_i64()).unwrap_or(0);

                    eprintln!(
                        "  {} Tally resolved: normal={}",
                        crate::glyph(crate::glyphs::Glyph::Check).green(),
                        normal
                    );

                    if normal > 0 {
                        eprintln!(
                            "  {} Major/critical issues detected; requesting changes",
                            crate::glyph(crate::glyphs::Glyph::Cross).red()
                        );
                        return Ok(auto_complete::ReviewerOutcome::Verdict(
                            auto_complete::Verdict::RequestChanges,
                        ));
                    } else {
                        eprintln!(
                            "  {} No major/critical issues detected; approving",
                            crate::glyph(crate::glyphs::Glyph::Check).green()
                        );
                        return Ok(auto_complete::ReviewerOutcome::Verdict(
                            auto_complete::Verdict::Approved,
                        ));
                    }
                } else {
                    eprintln!(
                        "  {} bughunter-severity data is malformed",
                        crate::glyph(crate::glyphs::Glyph::Warning).yellow()
                    );
                }
            } else {
                eprintln!(
                    "  {} bughunter-severity polling timed out or was missing",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow()
                );
            }

            // Fail-safe trigger: file a finding & park in NeedsAttention
            eprintln!(
                "  {} Triggering fail-safe: filing ReviewerVerdictUnavailable finding...",
                "ⓘ".cyan()
            );
            if let Err(e) = file_reviewer_verdict_unavailable_finding(&self.project_root, pr) {
                eprintln!(
                    "    {} could not file ReviewerVerdictUnavailable finding: {}",
                    crate::glyph(crate::glyphs::Glyph::Warning).yellow(),
                    e
                );
            }

            return Err(auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::NoVerdict,
                "delegated review failed: check-run or bughunter-severity was missing, malformed, or timed out",
            ));
        }

        // Verdict handshake: the `/aida-review` skill writes the verdict
        // JSON to AIDA_REVIEW_VERDICT_FILE and stops before merge.
        let verdict_dir = self.project_root.join(".aida").join("review-verdicts");
        std::fs::create_dir_all(&verdict_dir).map_err(|e| {
            auto_complete::PhaseFailure::new(format!(
                "could not create {}: {e}",
                verdict_dir.display()
            ))
        })?;
        let verdict_path = verdict_dir.join(format!("PR-{pr}.json"));
        let _ = std::fs::remove_file(&verdict_path); // clear any stale verdict

        // BUG-280: capture the wall-clock start of the reviewer subprocess so
        // a NoVerdict failure can scan the corresponding headless log for the
        // AskUserQuestion-in-headless symptom. trace:BUG-280 | ai:claude
        let reviewer_started_at = std::time::SystemTime::now();

        let session_uuid = uuid::Uuid::now_v7().to_string();
        let scope = format!("PR-{pr}");
        let mut cmd = std::process::Command::new(self.aida_exe());
        cmd.current_dir(&self.project_root)
            .args([
                "queue",
                "work",
                &scope,
                "--session-id",
                &session_uuid,
                "--no-pull",
            ])
            .env(orchestrator::AUTO_COMPLETE_ENV, "1")
            // BUG-233: corroboration token — same contract as the implementer
            // phase. The reviewer additionally keys off the verdict-file path.
            .env(orchestrator::TOKEN_ENV, &self.run_token)
            .env("AIDA_REVIEW_VERDICT_FILE", &verdict_path);
        // TASK-306: phase index + `--no-human` scope for the child statusline,
        // consistent with the implementer phase. The reviewer runs headless
        // under `--no-human` (so usually no statusline renders), but a plain
        // `--auto-complete` reviewer is interactive and shows `auto:3/6`.
        // trace:TASK-306 | ai:claude
        cmd.env(
            orchestrator::PHASE_ENV,
            auto_complete::Phase::Reviewer.index().to_string(),
        );
        if let Some(mode) = self.no_human {
            cmd.env(orchestrator::NO_HUMAN_MODE_ENV, mode.slug());
        }
        if let Some(pm) = &self.permission_mode {
            cmd.args(["--permission-mode", pm]);
        }
        // STORY-263: under `--no-human`, run the reviewer headless. Both
        // NoHumanMode variants (ReviewerOnly, Both) include the reviewer, so
        // a bare `--no-human` on the subprocess is all the orchestrator needs
        // to pass — `handle_queue_work` then launches `claude -p`. The
        // verdict-file handshake below is unchanged: headless or not, the
        // reviewer writes the verdict and the orchestrator reads it.
        // trace:STORY-263 | ai:claude
        if self.no_human.is_some() {
            cmd.arg("--no-human");
        }
        // STORY-281: propagate the stale-base opt-out so the child's own
        // pre-flight (in handle_queue_work) doesn't re-block on the same
        // signal the orchestrator-level check already cleared.
        // trace:STORY-281 | ai:claude
        if self.allow_stale_base {
            cmd.arg("--allow-stale-base");
        }

        // TASK-329: same graceful-exit handling as the implementer phase —
        // the reviewer skill touches the sentinel as its absolute last action,
        // after the verdict file is written. The interactive `--zen` reviewer
        // would otherwise sit at the REPL with no EOF to synthesize (BUG-230).
        // trace:TASK-329 | ai:claude
        let sentinel = exit_signal::sentinel_path(&self.sessions_dir(), &session_uuid);
        // BUG-420: arm the no-progress / ceiling watchdog for a *headless*
        // reviewer (both `--no-human` variants run the reviewer headless). An
        // interactive `--zen` reviewer is left unwatched — it may sit at the
        // REPL legitimately. trace:BUG-420 | ai:claude
        let mut watchdog = self.no_human.is_some().then(|| {
            PhaseWatchdog::new(
                self.project_root.clone(),
                session_uuid.clone(),
                self.drain_tuning.no_progress,
                self.drain_tuning.ceiling,
            )
        });
        let mut wd_closure = watchdog.as_mut().map(|w| move || w.check());
        let wd_dyn: Option<&mut dyn FnMut() -> Option<String>> = wd_closure
            .as_mut()
            .map(|c| c as &mut dyn FnMut() -> Option<String>);
        // TASK-298: both `--no-human` variants run the reviewer headless (it too
        // launches `claude -p` + an agent worker pool), so reap by process group
        // on every exit path. The interactive `--zen` reviewer stays on the
        // tree-walk path. trace:TASK-298 | ai:claude
        let outcome = exit_signal::spawn_and_wait_watched(
            cmd,
            &sentinel,
            &self.exit_cfg,
            wd_dyn,
            self.no_human.is_some(),
        )
        .map_err(|e| {
            auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::Spawn,
                format!("could not launch the reviewer session: {e}"),
            )
        })?;
        if let exit_signal::ExitOutcome::WatchdogTripped(reason) = &outcome {
            return Err(auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::Watchdog,
                format!("the reviewer phase watchdog stopped the session — {reason}"),
            ));
        }
        if let exit_signal::ExitOutcome::Natural(status) = &outcome {
            if !status.success() {
                return Err(auto_complete::PhaseFailure::new(format!(
                    "the reviewer session exited {}",
                    status
                        .code()
                        .map(|c| c.to_string())
                        .unwrap_or_else(|| "with a signal".to_string())
                )));
            }
        } else {
            eprintln!(
                "  {} reviewer skill signalled completion — session reaped",
                "ⓘ".cyan()
            );
        }

        let outcome = match read_verdict_file(&verdict_path) {
            Ok(o) => o,
            Err(failure) if self.no_human.is_some() => {
                // BUG-280: under a headless `--no-human` drain, a NoVerdict
                // failure is most often the AskUserQuestion-in-headless
                // symptom (reviewer skill called a confirmation prompt
                // forbidden by the harness, bailed before writing the
                // verdict file). Enrich the error message so the recovery
                // hint names the likely cause instead of the generic
                // "no verdict file." trace:BUG-280 | ai:claude
                return Err(enrich_no_verdict_with_headless_diagnostic(
                    failure,
                    &self.project_root,
                    reviewer_started_at,
                ));
            }
            Err(e) => return Err(e),
        };

        // STORY-439: tag-along read for reviewer-side calibration. Same
        // verdict file we just parsed; we re-read so the orchestrator's
        // PASS/FAIL decision stays untouched even if the calibration
        // capture changes. trace:STORY-439 | ai:claude
        capture_review_calibration_for_spec(&self.project_root, &verdict_path, &self.spec);

        // End the reviewer session (best-effort — the verdict is already in
        // hand, so a stuck reviewer worktree must not block the merge).
        if let Ok((reviewer_lease, _, _)) = self.discover_orchestrated_lease(&session_uuid) {
            let _ = std::process::Command::new(self.aida_exe())
                .current_dir(&self.project_root)
                .args(["session", "end", &reviewer_lease, "--yes", "--skip-ci"])
                .status();
        }

        Ok(outcome)
    }

    fn merge(&mut self) -> Result<(), auto_complete::PhaseFailure> {
        self.mark_drain_phase(auto_complete::Phase::Merge);
        let pr = self.pr_number.ok_or_else(|| {
            auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::Internal,
                "internal: PR number not resolved before the merge phase",
            )
        })?;
        // STORY-516/TASK-669: keep the `gh`-on-PATH guard as a MissingTool
        // (non-shelvable → stop-the-drain) pre-check. An env failure should halt
        // the batch, not shelve every member. The orchestrator is GitHub-only
        // today; a GitLab orchestrator would make this forge-aware.
        if resolve_gh_binary().is_none() {
            return Err(auto_complete::PhaseFailure::of(
                auto_complete::FailureKind::MissingTool,
                "`gh` is not on PATH — cannot merge the PR",
            ));
        }
        // BUG-286/TASK-669: route the phase-4 merge through Forge::merge_change,
        // passing a DualSink (stderr + drain-state) so transient-blip retry
        // events still correlate into `.aida/drain-state.json` for post-hoc
        // analysis. merge_change reuses the SPEC-410-pinned argv (`pr merge <pr>
        // --squash --delete-branch`, byte-identical) and the same network_retry
        // wrapper, and owns the gh subprocess — so the prior raw gh-stdout echo
        // is replaced by AIDA's own check line (consistent with `aida pr ship`). A
        // failed merge returns the unified Err → a shelvable `Failed`
        // PhaseFailure, matching the previous non-zero-exit behaviour.
        // trace:STORY-516 trace:TASK-669 trace:BUG-286 | ai:claude
        let mut stderr_sink = network_retry::StderrSink;
        let mut state_sink = drain_state::DrainStateSink {
            project_root: &self.project_root,
            spec: self.spec.clone(),
            phase: Some(format!(
                "{} ({})",
                auto_complete::Phase::Merge.index(),
                auto_complete::Phase::Merge.slug()
            )),
        };
        let mut sink = network_retry::DualSink {
            a: &mut stderr_sink,
            b: &mut state_sink,
        };
        let change_ref = crate::forge::ChangeRef {
            id: pr as u64,
            url: String::new(),
            branch: String::new(),
            base: String::new(),
            title: None,
        };
        let opts = crate::forge::MergeOptions {
            method: crate::forge::MergeMethod::Squash,
            squash_subject: None,
            delete_branch: true,
        };
        crate::forge::forge_for(&self.project_root)
            .merge_change(&change_ref, &opts, &mut sink)
            .map_err(|e| {
                auto_complete::PhaseFailure::new(format!("`gh pr merge {pr}` failed: {e:#}"))
            })?;
        println!(
            "  {} merged PR-{}",
            crate::glyph(crate::glyphs::Glyph::Check).green(),
            pr
        );
        // STORY-712: phase-4 merge success is an integration-milestone wake.
        // Best-effort, no control-flow change. trace:TASK-988 | ai:claude
        let (_, run_uuid) = drain_state::current_context(&self.project_root);
        events::emit(
            &self.project_root,
            &events::Event::new(
                Some(self.spec.clone()),
                run_uuid,
                events::EventKind::PrMerged { pr },
            ),
        );
        Ok(())
    }

    fn pull(&mut self) -> Result<(), auto_complete::PhaseFailure> {
        self.mark_drain_phase(auto_complete::Phase::Pull);
        let status = std::process::Command::new(self.aida_exe())
            .current_dir(&self.project_root)
            .arg("pull")
            .status()
            .map_err(|e| {
                auto_complete::PhaseFailure::of(
                    auto_complete::FailureKind::Spawn,
                    format!("could not run `aida pull`: {e}"),
                )
            })?;
        if !status.success() {
            // BUG-254: `aida pull` now exits non-zero when either leg
            // failed; the per-leg detail + recovery hint was printed by
            // the subprocess. Halting here keeps phase 6 from running
            // over a stale tree and masking the real cause.
            // trace:BUG-254 | ai:claude
            return Err(auto_complete::PhaseFailure::new(
                "`aida pull` failed — the code or store leg did not advance \
                 (see the subprocess output above for the recovery hint)",
            ));
        }
        Ok(())
    }

    fn build(&mut self) -> Result<(), auto_complete::PhaseFailure> {
        self.mark_drain_phase(auto_complete::Phase::Build);
        let status = std::process::Command::new("cargo")
            .current_dir(&self.project_root)
            .args(["build", "--release"])
            .status()
            .map_err(|e| {
                auto_complete::PhaseFailure::of(
                    auto_complete::FailureKind::Spawn,
                    format!("could not run `cargo build`: {e}"),
                )
            })?;
        if !status.success() {
            return Err(auto_complete::PhaseFailure::new(
                "`cargo build --release` failed",
            ));
        }
        Ok(())
    }

    fn hint_context(&self) -> auto_complete::HintContext {
        auto_complete::HintContext {
            spec: self.spec.clone(),
            branch: self.branch.clone(),
            pr_number: self.pr_number,
            implementer_session: self.implementer_lease.clone(),
            ci_run_id: self.ci_run_id.clone(),
            // STORY-508/TASK-651: resolve the active forge so recovery hints
            // name the right CLI when a phase fails.
            forge: crate::forge::resolve_forge_kind(&self.project_root),
        }
    }

    /// BUG-241: before the orchestrator declares a phase failed, check whether
    /// the spec shipped anyway. Two real cases this redeems:
    ///   - phase 1 produced no PR because the spec was already resolved by
    ///     supersession (instance B);
    ///   - phase 3 left no verdict file because the reviewer escalated and a
    ///     human merged the PR out-of-band (instance A).
    ///     trace:BUG-241 | ai:claude
    fn reconcile_failure(
        &mut self,
        phase: auto_complete::Phase,
        failure: &auto_complete::PhaseFailure,
    ) -> auto_complete::PhaseReconcile {
        use auto_complete::{FailureKind, Phase, PhaseReconcile};

        // Reconcile only the two phases that can succeed out-of-band. Phase 1
        // (implementer) can correctly produce no PR — the spec needed no code.
        // Phase 3 (reviewer) can end with no verdict file — a human merged
        // out-of-band. Phases 2/4/5/6 fail by a gate or command genuinely not
        // passing (red CI, a failed merge, a divergent pull, a broken build);
        // those are real regardless of whether the spec's code reached main,
        // so reconciling them would mask a true failure.
        if !matches!(phase, Phase::Implementer | Phase::Reviewer) {
            return PhaseReconcile::GenuineFailure;
        }
        // A spawn ENOENT, a missing tool, or a violated invariant is a local
        // / tooling fault — not an out-of-band success. Leave it standing
        // without spending a `gh` round-trip on it.
        if matches!(
            failure.kind,
            FailureKind::Spawn | FailureKind::MissingTool | FailureKind::Internal
        ) {
            return PhaseReconcile::GenuineFailure;
        }

        // Ground truth: a merged PR (instance A) and/or a Completed spec
        // (instance B). Either alone is proof the spec shipped.
        let merged_pr = self.detect_merged_pr();
        let completed = matches!(
            spec_status(&self.project_root, &self.spec),
            Some(RequirementStatus::Completed)
        );
        reconcile_verdict(merged_pr, completed, &self.spec)
    }

    /// BUG-245: read the PR's commit subjects to see which SPEC-ID they
    /// actually credit. Called by `orchestrate` after phase 1 confirms an
    /// open PR; on a dispatched≠credited mismatch the success epilogue
    /// credits the truth and the dispatched spec is left queued. Returns
    /// `None` when there is no PR yet, or `gh` cannot answer — "cannot
    /// determine" preserves the pre-BUG-245 behaviour (dispatched id is
    /// credited). trace:BUG-245 | ai:claude
    fn shipped_spec_id(&mut self) -> Option<String> {
        let pr = self.pr_number?;
        // BUG-286: same retry treatment as `detect_merged_pr` — a transient
        // blip during the dispatched≠credited check left the orchestrator
        // unable to detect a mismatch. The retry keeps the BUG-245 detection
        // robust against the BUG-286 blip class. trace:BUG-286 | ai:claude
        let mut stderr_sink = network_retry::StderrSink;
        let mut state_sink = drain_state::DrainStateSink {
            project_root: &self.project_root,
            spec: self.spec.clone(),
            phase: Some("1 (shipped-spec-check)".to_string()),
        };
        let mut sink = network_retry::DualSink {
            a: &mut stderr_sink,
            b: &mut state_sink,
        };
        pr_credited_spec_id_with_sink(&self.project_root, pr, &self.spec, &mut sink)
    }

    /// STORY-306 advisor tier — spawn a headless advisor to judge the design-
    /// fork phase 1 punted on. Assembles the rich payload, writes the request
    /// file, runs `/aida-advise` in the advisor role on the resolved headless
    /// vendor (Claude by default; Codex via `AIDA_HEADLESS_VENDOR`/config —
    /// TASK-894), reads the response, appends a punt-ledger record, and — on an
    /// escalate — tags the spec `needs-human` + leaves the advisor's reasoning
    /// as a comment.
    // trace:STORY-306 trace:TASK-894 | ai:claude
    fn run_advisor(
        &mut self,
    ) -> Result<auto_complete::AdvisorOutcome, auto_complete::PhaseFailure> {
        use auto_complete::{AdvisorOutcome, FailureKind, PhaseFailure};

        // Load the punted spec + its AttentionReason — `aida punt` recorded it.
        let store = load_store_for_lookup(&self.project_root).ok_or_else(|| {
            PhaseFailure::of(
                FailureKind::Internal,
                "advisor tier: could not load the requirements store",
            )
        })?;
        let target = store
            .get_requirement_by_spec_id(&self.spec)
            .ok_or_else(|| {
                PhaseFailure::of(
                    FailureKind::Internal,
                    format!("advisor tier: spec {} not found in the store", self.spec),
                )
            })?;
        let attention = target.attention_reason.clone().ok_or_else(|| {
            PhaseFailure::of(
                FailureKind::Internal,
                "advisor tier: the punted spec carries no AttentionReason",
            )
        })?;

        // Assemble the rich, ultraplan-grade payload and write the request.
        let request = assemble_punt_payload(&store, target, &self.project_root, &attention);
        let request_path = punt::punt_request_path(&self.project_root, &self.spec);
        let response_path = punt::punt_response_path(&self.project_root, &self.spec);
        let _ = std::fs::remove_file(&response_path); // clear any stale response
        punt::write_punt_request(&request_path, &request).map_err(|e| {
            PhaseFailure::of(
                FailureKind::Internal,
                format!("advisor tier: could not write the punt request: {e}"),
            )
        })?;

        // STORY-347: resolve effective calibration mode. Per-drain `--calibrate`
        // / `--no-calibrate` (via `AIDA_CALIBRATE`) overrides `[advisor]
        // calibration_mode` in `.aida/config.toml`. When ON, the cold-boot
        // verdict drives the drain *and* the orchestrator fires a fork-from-
        // live shadow verdict (when a live advisor is registered) to record
        // both into `.aida/punts/<punt-id>/calibration.yaml`. When OFF, the
        // drain is byte-identical to STORY-360's path — that path is left
        // unchanged below. trace:STORY-347 | ai:claude
        let advisor_cfg = advisor::AdvisorConfig::load(&self.project_root);
        let calibration_mode = effective_calibration_mode(&advisor_cfg);
        let punt_timestamp = chrono::Utc::now();
        let punt_id = calibration::build_punt_id(&self.spec, punt_timestamp);

        // Decide the primary path (the one whose verdict drives the drain).
        //   - Calibration OFF (today's STORY-360 behaviour): use `plan_fork` —
        //     fork if a live advisor exists and the config permits; cold-boot
        //     otherwise.
        //   - Calibration ON: force cold-boot for the primary path — the spec
        //     explicitly says "cold-boot drives the drain, the fork is shadow."
        //     trace:STORY-347 | ai:claude
        let (primary_response, primary_log) = if calibration_mode.is_on() {
            self.spawn_advisor_session(
                AdvisorPass::ColdBoot,
                &advisor_cfg,
                &response_path,
                &request_path,
            )?
        } else {
            let fork_plan = advisor::plan_fork(&self.project_root, &advisor_cfg);
            let pass = match fork_plan {
                Some(plan) => AdvisorPass::Fork(plan),
                None => AdvisorPass::ColdBoot,
            };
            self.spawn_advisor_session(pass, &advisor_cfg, &response_path, &request_path)?
        };

        // STORY-347: shadow fork in calibration mode. We've already spent the
        // cold-boot's cost; only run the fork when a live advisor exists so
        // the operator's `aida advisor register` is the explicit opt-in for
        // the second-fork cost. Failures here are non-fatal — the drain still
        // ships on the cold-boot verdict.
        let (shadow_response, shadow_log, fork_skip_reason) = if calibration_mode.is_on() {
            let live =
                advisor::discover_live_advisor_session(&advisor_cfg, Some(&self.project_root));
            match live {
                None => {
                    if !self.json {
                        eprintln!(
                            "  {} calibration: no live advisor registered, skipping fork.",
                            "◆".dimmed()
                        );
                    }
                    (None, None, Some("no-live-advisor".to_string()))
                }
                Some(_live) => {
                    // Re-plan now that we have a target so the size cap +
                    // mtime fallback rules in `plan_fork` apply.
                    match advisor::plan_fork(&self.project_root, &advisor_cfg) {
                        None => (None, None, Some("plan-skipped".to_string())),
                        Some(plan) => {
                            // Use a separate response file path so the shadow
                            // does not clobber the cold-boot's response we
                            // already consumed.
                            let shadow_response_path = self
                                .project_root
                                .join(".aida")
                                .join("punts")
                                .join(format!("{}.calibration-fork.response.json", self.spec));
                            let _ = std::fs::remove_file(&shadow_response_path);
                            match self.spawn_advisor_session(
                                AdvisorPass::Fork(plan),
                                &advisor_cfg,
                                &shadow_response_path,
                                &request_path,
                            ) {
                                Ok((resp, log)) => (Some(resp), Some(log), None),
                                Err(e) => {
                                    if !self.json {
                                        eprintln!(
                                            "  {} calibration: shadow fork failed ({}); recording cold-boot only.",
                                            "◆".dimmed(),
                                            e.reason
                                        );
                                    }
                                    (None, None, Some("fork-failed".to_string()))
                                }
                            }
                        }
                    }
                }
            }
        } else {
            (None, None, None)
        };

        // STORY-347: write the calibration ledger. Best-effort — a write
        // failure logs and continues; the drain still ships on the cold-boot.
        if calibration_mode.is_on() {
            let cold_log_rel = primary_log
                .strip_prefix(&self.project_root)
                .ok()
                .map(|p| p.to_string_lossy().to_string());
            let shadow_log_rel = shadow_log.as_ref().and_then(|p| {
                p.strip_prefix(&self.project_root)
                    .ok()
                    .map(|s| s.to_string_lossy().to_string())
            });
            let record = calibration::CalibrationRecord {
                punt_id: punt_id.clone(),
                spec: self.spec.clone(),
                timestamp: punt_timestamp,
                cold_boot: calibration::CalibrationVerdict::from_response(
                    &primary_response,
                    cold_log_rel,
                ),
                fork: shadow_response
                    .as_ref()
                    .map(|r| calibration::CalibrationVerdict::from_response(r, shadow_log_rel)),
                fork_skip_reason,
                drove_drain: "cold-boot".to_string(),
                annotation: None,
            };
            if let Err(e) = calibration::write_calibration(&self.project_root, &record) {
                if !self.json {
                    eprintln!(
                        "  {} calibration: failed to write ledger ({e}); continuing.",
                        "◆".yellow()
                    );
                }
            } else if !self.json {
                let summary = match record.agreement() {
                    Some(true) => "agreement",
                    Some(false) => "disagreement",
                    None => "cold-boot only",
                };
                eprintln!(
                    "  {} calibration: recorded {} at {}",
                    "◆".cyan(),
                    summary,
                    calibration::calibration_path(&self.project_root, &record.punt_id).display(),
                );
            }
        }

        let response = primary_response;
        let _ = primary_log; // referenced in calibration ledger above; not needed by post-processing

        // Append the advisor decision to the punt ledger (STORY-325 coupling —
        // v1's escalation rate must be measurable from day one).
        let resolution_path = match response.resolution {
            punt::PuntResolution::Resolved => "advisor-resolved",
            punt::PuntResolution::Escalated => "escalated-to-human",
        };
        let decision = match response.resolution {
            punt::PuntResolution::Resolved => Some("resolved".to_string()),
            punt::PuntResolution::Escalated => Some("escalated".to_string()),
        };
        let calibration_pair = if calibration_mode.is_on() {
            Some(punt_id)
        } else {
            None
        };
        let record = punt::PuntRecord {
            timestamp: chrono::Utc::now(),
            spec: self.spec.clone(),
            category: attention.category,
            detail: attention.detail.clone(),
            lean: attention.lean.clone(),
            raised_by: attention.raised_by.clone(),
            resolution_path: resolution_path.to_string(),
            classification: response.classification.clone(),
            escalation_reason: response.escalation_reason.clone(),
            answer: response.answer.clone(),
            answered_by: Some("advisor".to_string()),
            decision,
            principle_link: None,
            calibration_pair,
            paused_at: Some(attention.raised_at),
            resolved_at: Some(chrono::Utc::now()),
        };
        let _ = punt::append_to_ledger(&self.project_root, &record);

        match response.resolution {
            punt::PuntResolution::Resolved => {
                let answer = response.answer.clone().unwrap_or_default();
                if answer.trim().is_empty() {
                    return Err(PhaseFailure::of(
                        FailureKind::Internal,
                        "the advisor reported `resolved` but wrote no answer",
                    ));
                }
                // Leave the resolution on the spec so it is not invisible —
                // a resolved fork carries the advisor's answer + rationale
                // into the spec's comment trail.
                let _ = std::process::Command::new(self.aida_exe())
                    .current_dir(&self.project_root)
                    .args([
                        "comment",
                        "add",
                        &self.spec,
                        &format!(
                            "Advisor resolved the punted design-fork (STORY-306).\n\n\
                             Decision: {answer}\n\nReasoning: {}",
                            response.reasoning
                        ),
                    ])
                    .status();
                Ok(AdvisorOutcome::Resolved {
                    answer,
                    reasoning: response.reasoning.clone(),
                })
            }
            punt::PuntResolution::Escalated => {
                // Tag the spec `needs-human` (preserving existing tags) so
                // `aida findings` can tell an advisor-escalated fork from one
                // not yet triaged, and leave the advisor's reasoning — plus a
                // nudge toward the corpus-growth loop — as a comment.
                let mut tags: Vec<String> = target.tags.iter().cloned().collect();
                if !tags.iter().any(|t| t == "needs-human") {
                    tags.push("needs-human".to_string());
                }
                let _ = std::process::Command::new(self.aida_exe())
                    .current_dir(&self.project_root)
                    .args(["edit", &self.spec, "--tags", &tags.join(",")])
                    .status();
                let _ = std::process::Command::new(self.aida_exe())
                    .current_dir(&self.project_root)
                    .args([
                        "comment",
                        "add",
                        &self.spec,
                        &format!(
                            "Advisor escalated this design-fork to a human (STORY-306).\n\n\
                             Reasoning: {}\n\nWhen you resolve this, record the answer \
                             (a memory, an acceptance-criteria edit, or a discipline doc) \
                             so a future advisor can resolve the same kind of fork as a \
                             recorded principle.",
                            response.reasoning
                        ),
                    ])
                    .status();
                Ok(AdvisorOutcome::Escalated {
                    reason: response.reasoning.clone(),
                    category: response
                        .escalation_reason
                        .clone()
                        .unwrap_or_else(|| "unspecified".to_string()),
                })
            }
        }
    }

    /// STORY-306 advisor tier — resume the punted phase-1 implementer session
    /// with the advisor's judged `answer` (or, under `--escalate-defaults`, an
    /// authorization to ship the defensible default). `--resume`s the exact
    /// phase-1 Claude session so the implementer keeps the working model it
    /// built before punting; the worktree survived because STORY-306's punt
    /// path no longer ends the session. Classifies the outcome from ground
    /// truth — a re-punt leaves the spec in `NeedsAttention`, a ship opens a
    /// PR. trace:STORY-306 | ai:claude
    fn resume_implementer(
        &mut self,
        answer: &str,
    ) -> Result<auto_complete::ImplementerOutcome, auto_complete::PhaseFailure> {
        use auto_complete::{FailureKind, ImplementerOutcome, PhaseFailure};

        let session_id = self.implementer_session.clone().ok_or_else(|| {
            PhaseFailure::of(
                FailureKind::Internal,
                "advisor tier: no implementer session id to resume",
            )
        })?;
        let worktree = self.implementer_worktree.clone().ok_or_else(|| {
            PhaseFailure::of(
                FailureKind::Internal,
                "advisor tier: no implementer worktree recorded for the resume",
            )
        })?;

        let prompt = format!(
            "You punted spec {spec} on a design-fork. A headless advisor has now \
             judged it. Apply this decision and finish the spec — do NOT punt \
             again.\n\nADVISOR DECISION:\n{answer}\n\nTake the spec from Needs \
             Attention back to In Progress (`aida edit {spec} --status \
             in-progress`), implement the decision, and open the PR with \
             `/aida-pr` before exiting.",
            spec = self.spec,
        );

        let resume_uuid = uuid::Uuid::now_v7().to_string();
        let log_path = self
            .project_root
            .join(".aida")
            .join("headless-logs")
            .join(format!(
                "resume-{}-{}.jsonl",
                self.spec,
                &resume_uuid[..resume_uuid.len().min(8)]
            ));
        if !self.json {
            eprintln!(
                "  {} resuming the implementer session with the advisor's answer…",
                "◆".cyan()
            );
        }
        // TASK-307: tee the advisor-resume leg too. Label = "resume" so an
        // operator watching a drain can tell the resumed implementer apart
        // from the surrounding `[headless]` chatter. trace:TASK-307
        let tee_opts =
            crate::headless_tee::TeeOptions::from_env_and_flag(false).with_label("resume");
        let status = session::spawn_claude_headless_resume(
            &prompt,
            &session_id,
            &log_path,
            &worktree,
            &tee_opts,
            false,
        )
        .map_err(|e| {
            PhaseFailure::of(
                FailureKind::Spawn,
                format!("advisor tier: could not resume the implementer session: {e}"),
            )
        })?;
        if !status.success() {
            // BUG-266: same Anthropic-API outage classification on the
            // advisor-resume leg — `spawn_claude_headless_resume` is the
            // same headless `claude -p` substrate, so a 529/5xx mid-resume
            // is still Inconclusive (terminal here per the BUG-257 path: no
            // second advisor round, drain pauses for retry). The resume
            // hint points at the SAME session id so the operator's next
            // retry resumes where the API outage interrupted.
            // trace:BUG-266 | ai:claude
            if let Ok(content) = std::fs::read_to_string(&log_path) {
                if let Some(reason_line) = claude_log_indicates_api_outage(&content) {
                    let hint = format!(
                        "Anthropic API was unavailable; resume with: \
                         `aida queue work {spec} --resume {session_id}`",
                        spec = self.spec,
                    );
                    return Ok(ImplementerOutcome::Inconclusive {
                        reason: format!(
                            "Anthropic API outage during the advisor-resume implementer: {reason_line}"
                        ),
                        retry_hint: Some(hint),
                    });
                }
            }
            return Err(PhaseFailure::new(format!(
                "the resumed implementer session exited {} — see {}",
                status
                    .code()
                    .map(|c| c.to_string())
                    .unwrap_or_else(|| "with a signal".to_string()),
                log_path.display(),
            )));
        }

        // Classify from ground truth (the STORY-276 detect-punt logic): a
        // re-punt leaves the spec back in `NeedsAttention`.
        if matches!(
            spec_status(&self.project_root, &self.spec),
            Some(RequirementStatus::NeedsAttention)
        ) {
            let reason = load_store_for_lookup(&self.project_root)
                .and_then(|s| {
                    s.get_requirement_by_spec_id(&self.spec)
                        .and_then(|r| r.attention_reason.clone())
                })
                .map(|a| a.detail)
                .unwrap_or_else(|| "the resumed implementer punted again".to_string());
            return Ok(ImplementerOutcome::Punted { reason });
        }

        // A ship opens a PR — a spec-id lookup is branch-independent and
        // robust, with the recorded branch as a fallback.
        let pr =
            match detect_open_pr_for_spec_via_forge(&self.project_root, &self.spec) {
                PrLookup::Found(pr) => Some(pr),
                // STORY-516: inner branch lookup forge-routed (the outer spec search
                // is the list op, routed later). trace:STORY-516 | ai:claude
                PrLookup::NoOpenPr => self.branch.as_deref().and_then(|b| {
                    match change_lookup_for_branch(&self.project_root, b) {
                        crate::forge::ChangeLookup::Found(c) => Some(OpenPrInfo {
                            number: c.id,
                            title: c.title.unwrap_or_default(),
                            url: c.url,
                        }),
                        _ => None,
                    }
                }),
                PrLookup::GhMissing => {
                    return Err(PhaseFailure::of(
                        FailureKind::MissingTool,
                        "`gh` is not on PATH — auto-complete needs it to track the PR",
                    ));
                }
                PrLookup::GhFailed(why) => {
                    return Err(PhaseFailure::new(format!(
                        "could not look up the PR after the implementer resume: {why}"
                    )));
                }
                // BUG-257: a transient GH-API outage on the resumed-implementer PR
                // lookup is Inconclusive, not a failure. Drain pauses; the next
                // retry re-attempts the lookup once the API is reachable.
                // trace:BUG-257 | ai:claude
                PrLookup::GhUnreachable(why) => {
                    return Ok(ImplementerOutcome::Inconclusive {
                        reason: format!("GH API unreachable after the implementer resume: {why}"),
                        retry_hint: None,
                    });
                }
            };
        match pr {
            Some(pr) => {
                self.pr_number = Some(pr.number as u32);
                if let Some(head) = pr_head_branch(&self.project_root, pr.number) {
                    self.branch = Some(head);
                }
                Ok(ImplementerOutcome::PrOpened)
            }
            None => Err(PhaseFailure::of(
                FailureKind::NoPr,
                "the resumed implementer session exited but opened no PR — \
                 the advisor's answer did not produce shippable work",
            )),
        }
    }

    /// TASK-358: stamp the phase-1 implementer's lease as
    /// `escalated_to_human` once the orchestrator's `--escalate-blocks`
    /// path has decided this punt will not be resumed. The marker is read
    /// by `aida edit --status` (out of `NeedsAttention`) and
    /// `aida session prune --escalations` to know the lingering worktree
    /// is safe to remove. Best-effort: a stamp failure must not block the
    /// terminal `finish_escalated` — the cleanup just falls to the explicit
    /// prune verb instead. trace:TASK-358 | ai:claude
    fn mark_implementer_lease_escalated(&mut self) {
        let Some(lease_id) = self.implementer_lease.clone() else {
            return;
        };
        if let Err(e) = mark_lease_escalated_to_human(&self.project_root, &lease_id) {
            eprintln!(
                "  {} could not stamp lease {} as escalated: {e} — \
                 `aida session prune --escalations` can clean it up later",
                "Note:".dimmed(),
                lease_id,
            );
        }
    }

    // EPIC-28: park the spec in NeedsAttention with a structured FailureReason
    // so the batch drain can continue past this failure. trace:EPIC-28 | ai:claude
    fn shelve_on_failure(
        &mut self,
        spec: &str,
        phase: auto_complete::Phase,
        failure: &auto_complete::PhaseFailure,
        recovery_hint: &str,
    ) -> anyhow::Result<Option<aida_core::FailureReason>> {
        shelve_spec_on_failure(
            &self.project_root,
            spec,
            phase.slug(),
            phase.index() as u8,
            failure.kind.slug(),
            &failure.reason,
            recovery_hint,
        )
    }
}

/// TASK-84: pure resolver for `aida queue work` permission-mode.
/// Order (first non-None wins):
///   1. `flag`   — `--permission-mode` on the command line
///   2. `env`    — `AIDA_PERMISSION_MODE` env var
///   3. `config` — `.aida/config.toml [behavior] permission_mode`
///   4. `is_aida_worktree=true` default → `bypassPermissions` (worktree is
///      git-sandboxed; prompt flood ate autonomous runs — see TASK-84
///      description)
///   5. fallback → `acceptEdits` (safe default for non-AIDA cwd)
///      Returns the mode + a short origin string for the pre-flight summary.
///      Pure decision helper — kept separate so unit tests can pin the
///      resolution order without env/config side effects. trace:TASK-84 | ai:claude
///      STORY-495: resolve the effective `--permission-mode` for an interactive
///      `aida queue work` launch. `None` → honor Claude's native posture (no flag
///      injected — the faithful default). Precedence, highest first:
///   1. `--permission-mode` flag (explicit override)
///   2. `AIDA_PERMISSION_MODE` env (process-level opt-in)
///   3. `.aida/config.toml [behavior] permission_mode` (project policy)
///   4. `[agents] bypass` knob → `bypassPermissions` (uniform fleet opt-in)
///   5. otherwise → `None` (native)
///
/// Pre-STORY-495 this defaulted to `bypassPermissions` inside an AIDA worktree
/// and `acceptEdits` elsewhere; both auto-injections are gone — the uniform
/// knob is the single place that restores bypass posture. trace:STORY-495
fn resolve_queue_work_permission_mode(
    flag: Option<&str>,
    env: Option<&str>,
    config: Option<&str>,
    bypass_knob: bool,
    plan_only: bool,
) -> (Option<String>, &'static str) {
    if let Some(m) = flag.filter(|s| !s.is_empty()) {
        return (Some(m.to_string()), "--permission-mode flag");
    }
    // STORY-265: a plan-only session is read-only by default — it writes a
    // docs/plans/ file, not code. An explicit --permission-mode flag (above)
    // still wins; otherwise `plan` overrides env/config/bypass so the planning
    // session can't edit code even on a bypass-by-default project.
    if plan_only {
        return (Some("plan".to_string()), "--plan-only (read-only default)");
    }
    if let Some(m) = env.filter(|s| !s.is_empty()) {
        return (Some(m.to_string()), "AIDA_PERMISSION_MODE env");
    }
    if let Some(m) = config.filter(|s| !s.is_empty()) {
        return (Some(m.to_string()), ".aida/config.toml");
    }
    if bypass_knob {
        return (
            Some("bypassPermissions".to_string()),
            "[agents] bypass knob",
        );
    }
    (None, "native (faithful default)")
}

/// STORY-287: the three-mode autonomy ladder for `aida queue work`. Aligns
/// the human's role with the implementer's pause behavior:
///   - `Default`  — human is driving; every prompt pauses.
///   - `Zen`      — advisor on standby; mechanical `kind:confirmation`
///     prompts auto-resolve, `kind:design-fork` prompts pause.
///   - `NoHuman`  — nobody reachable; the headless drain (STORY-263).
///     trace:STORY-287 | ai:claude
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AutonomyMode {
    Default,
    Zen,
    NoHuman,
}

/// Resolve the effective autonomy mode from the `--zen` flag and the
/// presence of `--no-human`. Precedence is `--no-human` > `--zen` >
/// default — when both `--zen` and `--no-human` are set, `--no-human`
/// wins because it is the strictly stronger mode (it removes the human
/// entirely). Pure, so the precedence rule is unit-testable without
/// spawning a session. trace:STORY-287 | ai:claude
fn resolve_autonomy_mode(zen_flag: bool, no_human: bool) -> AutonomyMode {
    match (no_human, zen_flag) {
        (true, _) => AutonomyMode::NoHuman,
        (false, true) => AutonomyMode::Zen,
        (false, false) => AutonomyMode::Default,
    }
}

/// Resolved flag values after expanding the `aida queue work --drain` alias
/// (TASK-578). `--drain` is pure discoverability sugar: it sets the same
/// internal state that `--auto-complete --no-human=both --max <queue-size>`
/// already produced. Explicit flags always win, so `--drain
/// --no-human=reviewer-only` keeps `reviewer-only`,
/// `--drain --auto-complete=through-ci` keeps the early stop, and an explicit
/// `--max N` caps the drain instead of using the queue size.
/// trace:TASK-578 | ai:claude
#[derive(Debug, Clone, PartialEq, Eq)]
struct DrainResolution {
    auto_complete: Option<String>,
    no_human: Option<String>,
    max: Option<usize>,
}

/// Expand the `--drain` alias into the underlying auto-complete / no-human / max
/// state. When `drain` is false this is an identity map over the caller's flags.
/// When `drain` is true the unset fields take the drain defaults — full
/// auto-complete, fully-headless (`both`), and a `--max` of the drivable queue
/// size (falling back to 99 when the size is unknown / zero, per the spec). An
/// explicitly-supplied flag is never overwritten. `queue_size` is the number of
/// drivable queued items the caller has already resolved (0 ⇒ unknown). The
/// function is pure so the expansion can be unit-tested without a live queue.
/// trace:TASK-578 | ai:claude
fn resolve_drain_alias(
    drain: bool,
    auto_complete: Option<&str>,
    no_human: Option<&str>,
    max: Option<usize>,
    queue_size: usize,
) -> DrainResolution {
    if !drain {
        return DrainResolution {
            auto_complete: auto_complete.map(str::to_string),
            no_human: no_human.map(str::to_string),
            max,
        };
    }
    DrainResolution {
        auto_complete: Some(auto_complete.unwrap_or("full").to_string()),
        no_human: Some(no_human.unwrap_or("both").to_string()),
        // Explicit --max wins; otherwise bound the drain to the queue size, or
        // fall back to 99 when the size is unknown (the spec's "--max 99").
        max: Some(max.unwrap_or(if queue_size > 0 { queue_size } else { 99 })),
    }
}

/// TASK-84: quote-aware strip of an inline TOML comment.
/// Returns the slice of `s` before the first unquoted `#`. Tracks both
/// `"` and `'` so `key = "value with # inside"` round-trips correctly.
/// Spec-compliant TOML allows trailing `# comment` on key/value lines;
/// without this helper, a line like `permission_mode = "auto" # ...`
/// would parse to the literal string `auto" # ...` and get rejected by
/// `claude --permission-mode`. trace:TASK-84 | ai:claude
fn strip_toml_inline_comment(s: &str) -> &str {
    let mut in_dquote = false;
    let mut in_squote = false;
    for (i, c) in s.char_indices() {
        match c {
            '"' if !in_squote => in_dquote = !in_dquote,
            '\'' if !in_dquote => in_squote = !in_squote,
            '#' if !in_dquote && !in_squote => return &s[..i],
            _ => {}
        }
    }
    s
}

/// TASK-84: read `[behavior] permission_mode = "..."` from
/// `.aida/config.toml`. Returns `None` when the file is missing, the
/// section is absent, or the value is empty. We use a hand-rolled
/// section-aware scan (rather than pulling in serde for one optional
/// string) to stay consistent with `read_id_format_settings`.
/// trace:TASK-84 | ai:claude
fn read_behavior_permission_mode(project_dir: &std::path::Path) -> Option<String> {
    let config_path = project_dir.join(".aida").join("config.toml");
    let content = std::fs::read_to_string(&config_path).ok()?;
    let mut in_behavior = false;
    for raw in content.lines() {
        // Strip trailing inline comments before any other parsing so a
        // legitimate `permission_mode = "auto"  # default` doesn't end up
        // with the comment glued onto the value. trace:TASK-84 | ai:claude
        let line = strip_toml_inline_comment(raw).trim();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if let Some(rest) = line.strip_prefix('[') {
            in_behavior = rest.trim_end_matches(']').trim() == "behavior";
            continue;
        }
        if !in_behavior {
            continue;
        }
        if let Some(rest) = line.strip_prefix("permission_mode") {
            if let Some(val) = rest.split('=').nth(1) {
                let v = val.trim().trim_matches('"').trim_matches('\'').to_string();
                if v.is_empty() {
                    return None;
                }
                return Some(v);
            }
        }
    }
    None
}

/// TASK-81: search a lease list for any active lease whose scope matches
/// the requested scope (case-insensitive). Returns the freshest match by
/// `started_at` so the caller has a stable target for `session_end` even
/// if multiple stale leases somehow share a scope. Pure decision helper —
/// kept separate so the unit test in `queue_work_tests` doesn't need to
/// touch disk. trace:TASK-81 | ai:claude
fn find_scope_lease_conflict(leases: &[SessionLease], scope: &str) -> Option<SessionLease> {
    leases
        .iter()
        .filter(|l| l.scope.eq_ignore_ascii_case(scope))
        .max_by_key(|l| l.started_at)
        .cloned()
}

/// BUG-307: gather the three independent liveness signals for `lease` and
/// hand them to [`orchestrator::classify_for_auto_release`]. The classifier
/// is pure; this wrapper is where we touch the process table, lease-file
/// mtime, and `git status --porcelain`. Returns
/// [`orchestrator::AutoReleaseDecision::Live`] when the feature is disabled
/// so callers can branch uniformly. trace:BUG-307 | ai:claude
fn auto_release_decision_for_lease(
    project_root: &std::path::Path,
    lease: &SessionLease,
    config: &orchestrator::OrchestratorConfig,
) -> orchestrator::AutoReleaseDecision {
    // BUG-511: review-verb leases are advisory PID locks — no worktree, no
    // uncommitted work to lose — so liveness is the creator process, full
    // stop. Decided BEFORE the config gate and the mtime clock: a dead
    // review lease is always safe to release, a live one always refuses.
    if lease.review_verb {
        let pid_alive = lease
            .creator_pid
            .map(process_probe::pid_is_alive)
            .unwrap_or(false);
        return if pid_alive {
            orchestrator::AutoReleaseDecision::Live
        } else {
            let mtime_age_secs = std::fs::metadata(lease_path(project_root, &lease.id))
                .ok()
                .and_then(|m| m.modified().ok())
                .and_then(|t| t.elapsed().ok())
                .map(|d| d.as_secs() as i64)
                .unwrap_or(0);
            orchestrator::AutoReleaseDecision::SafelyDormant {
                process_dead: true,
                mtime_age_secs,
                worktree_missing: false,
            }
        };
    }

    if !config.auto_release_dormant_leases {
        return orchestrator::AutoReleaseDecision::Live;
    }

    // Signal 1: creator shell still alive? A lease without a recorded
    // `creator_pid` (pre-STORY-73) defaults to "dead" — those leases also
    // pre-date the orchestrator drain and are the canonical leaked-lease
    // case, so the auto-release path catches them.
    let pid_alive = lease
        .creator_pid
        .map(process_probe::pid_is_alive)
        .unwrap_or(false);

    // Signal 2: lease-file mtime age. We use the filesystem mtime rather
    // than `started_at` because future writers (mark_lease_escalated_to_human
    // etc.) bump the mtime — the file's freshness is the authoritative
    // "this lease was touched recently" signal.
    let lease_file = lease_path(project_root, &lease.id);
    let mtime_age_secs = std::fs::metadata(&lease_file)
        .ok()
        .and_then(|m| m.modified().ok())
        .and_then(|t| t.elapsed().ok())
        .map(|d| d.as_secs() as i64)
        // No mtime readable → treat as old (the lease was just listed from
        // disk, so this only fires under genuine fs weirdness; failing
        // "stale" lets the cleanup proceed).
        .unwrap_or(i64::MAX);

    // Signal 3: live `claude` running inside the worktree. Reuses the same
    // probe `aida session leases --all` uses for the ● live glyph so the
    // classifier agrees with what the operator sees in `session leases`.
    let live_claude_in_worktree = process_probe::probe_live_claude_sessions().iter().any(|s| {
        !s.stale_cwd && (s.cwd == lease.worktree_path || s.cwd.starts_with(&lease.worktree_path))
    });

    let worktree_exists = lease.worktree_path.exists();
    let worktree_dirty_count = if worktree_exists {
        worktree_dirty_entries(&lease.worktree_path).len()
    } else {
        0
    };

    orchestrator::classify_for_auto_release(
        pid_alive,
        mtime_age_secs,
        live_claude_in_worktree,
        worktree_exists,
        worktree_dirty_count,
        config.stale_lease_threshold_minutes,
    )
}

/// BUG-438: on `--resume-drain`, proactively release the crashed orchestrator's
/// lease(s) on `scope` whose creator process is dead — *independent of the
/// staleness clock*. The time-based auto-release ([`auto_release_decision_for_lease`])
/// keeps a dead-PID lease "Live" while its mtime is still fresh, so a **fast**
/// resume (within `stale_lease_threshold_minutes`) collides with the crashed
/// implementer's lease when the reviewer phase resolves PR→spec. We have already
/// passed the PID-liveness double-drive gate, so the original orchestrator is
/// dead — its child leases are too. We force `threshold = 0` so a dead-PID
/// *clean-worktree* lease releases regardless of mtime, while a **dirty**
/// worktree still classifies `DormantDirty` and is left untouched (no
/// uncommitted work is lost — the operator handles it). trace:BUG-438 | ai:claude
fn release_dead_leases_for_resume(project_root: &std::path::Path, scope: &str) {
    let mut cfg = orchestrator::OrchestratorConfig::load(project_root);
    // Resume is a deliberate recovery — release the crashed lease even if the
    // project disabled the dormant-lease auto-release, and ignore the mtime
    // clock (PID-death is the authoritative signal here).
    cfg.auto_release_dormant_leases = true;
    cfg.stale_lease_threshold_minutes = 0;
    let mut remaining = 16usize; // defense-in-depth bound, mirrors session_start
    while remaining > 0 {
        let leases = list_leases(project_root);
        let Some(conflict) = find_scope_lease_conflict(&leases, scope) else {
            break;
        };
        match auto_release_decision_for_lease(project_root, &conflict, &cfg) {
            orchestrator::AutoReleaseDecision::SafelyDormant { .. } => {
                eprintln!(
                    "  {} released the crashed drain's lease {} on `{}` (process dead)",
                    "ⓘ".cyan(),
                    (&conflict.id[..conflict.id.len().min(8)]).yellow(),
                    scope
                );
                let _ = force_cleanup_lease(project_root, &conflict);
                remaining -= 1;
            }
            // Live (process somehow still alive — won't happen post-gate) or
            // DormantDirty (uncommitted work) → leave it; the reviewer phase's
            // own conflict path / the operator handles those cases.
            _ => break,
        }
    }
}

/// BUG-307: format a seconds-old duration into the short human form used in
/// the auto-release log line (`"2h"`, `"45m"`, `"30s"`). Distinct from
/// [`humanize_relative`] — that one takes a chrono datetime and appends
/// " ago"; here the caller controls the surrounding text.
fn humanize_secs_short(secs: i64) -> String {
    if secs < 0 {
        return "0s".to_string();
    }
    let secs = secs as u64;
    if secs < 60 {
        return format!("{}s", secs);
    }
    let mins = secs / 60;
    if mins < 60 {
        return format!("{}m", mins);
    }
    let hours = mins / 60;
    if hours < 24 {
        return format!("{}h", hours);
    }
    let days = hours / 24;
    format!("{}d", days)
}

/// STORY-42: shell out to `aida db sync --pull`. We could refactor the
/// inline implementation in main(), but it's deeply tangled with the
/// dispatch and backend init — a child-process invocation is cheap
/// (sub-second when there's nothing to fetch) and lets queue work
/// reuse the canonical sync flow verbatim (conflict detection, cache
/// rebuild, the works). trace:STORY-42 | ai:claude
fn run_aida_db_sync_pull(store_path: &std::path::Path) -> Result<()> {
    eprintln!(
        "  {} pulling orphan-store via `aida db sync --pull` ...",
        "↻".cyan()
    );
    let mut cmd = std::process::Command::new(
        std::env::current_exe().unwrap_or_else(|_| std::path::PathBuf::from("aida")),
    );
    cmd.args(["db", "sync", "--pull"]);
    // Force the child to look at the same store as us — avoids ambiguity
    // when queue work runs from a sibling worktree.
    let _ = store_path; // signature future-proofing; current binary
                        // resolves the store via cwd's project root,
                        // which matches ours.
    let status = cmd
        .status()
        .with_context(|| "spawn `aida db sync --pull`")?;
    if !status.success() {
        anyhow::bail!("`aida db sync --pull` exited with {}", status);
    }
    Ok(())
}

/// STORY-42: write the session manifest from a queue-work plan so
/// /aida-pickup can walk the cluster top-down on launch. Items carry
/// the spec_id + status_at_plan that the resolver already computed,
/// so this function does not re-load the store.
/// trace:STORY-42 STORY-98 | ai:claude
fn write_queue_work_manifest(
    project_root: &std::path::Path,
    lease: &SessionLease,
    plan: &QueueWorkPlan,
    plan_context: Option<session_manifest::PlanContext>,
    claude_session_id: Option<String>,
    batch_name: Option<&str>,
) -> Result<()> {
    use crate::session_manifest::{ManifestItem, SessionManifest};

    let items: Vec<ManifestItem> = plan
        .entries
        .iter()
        .enumerate()
        .map(|(idx, e)| ManifestItem {
            spec_id: e.spec_id.clone(),
            position: (idx + 1) as u32,
            status_at_plan: e.status_at_plan.clone(),
            started_at: None,
            completed_at: None,
            note: None,
        })
        .collect();
    let manifest = SessionManifest {
        session_id: lease.id.clone(),
        planned_at: chrono::Utc::now(),
        plan_source: "queue work".to_string(),
        claude_session_id,
        // TASK-272: record the batch when set up via `aida queue work
        // --batch NAME` so /aida-pickup detects batch context.
        batch_name: batch_name.map(str::to_string),
        plan: plan_context,
        items,
    };
    let path = session_manifest::manifest_path(project_root, &lease.id);
    session_manifest::save(&path, &manifest)?;
    Ok(())
}

/// TASK-112: how `aida queue work` should launch claude — a cold launch
/// with a freshly-minted session id, or a resume of a recorded one.
/// trace:TASK-112 | ai:claude
#[derive(Debug)]
enum QueueWorkLaunch {
    /// Cold launch; the `String` is a freshly-minted UUID passed as
    /// `claude --session-id` so the new conversation is itself resumable.
    Fresh(String),
    /// Resume a recorded conversation by its claude session id.
    Resume(String),
}

impl QueueWorkLaunch {
    fn session_id(&self) -> &str {
        match self {
            QueueWorkLaunch::Fresh(id) | QueueWorkLaunch::Resume(id) => id,
        }
    }
}

/// TASK-402: does `s` look like an AIDA *lease* id rather than a Claude
/// *session* UUID? A lease id is a hyphenless hex run (e.g. `019e45cfc559`,
/// the short form printed by `session … started` check line); a Claude session UUID
/// always carries hyphens (`019e45cf-acea-73c1-9476-…`). The orchestrator's
/// phase-1 banner prominently shows the lease id, so pasting *that* into
/// `--resume <id>` is the #1 recovery papercut — it never prefix-matches a
/// recorded session. Detect the shape so we can point at the right id form
/// instead of the generic "no recorded session" miss. Pure + heuristic.
/// trace:TASK-402 | ai:claude
fn looks_like_lease_id(s: &str) -> bool {
    !s.is_empty()
        && !s.contains('-')
        && (8..=16).contains(&s.len())
        && s.chars().all(|c| c.is_ascii_hexdigit())
}

/// TASK-112: resolve a (possibly truncated) session id against the
/// recorded sessions for a scope. Returns the full id on a unique match;
/// a non-matching value of UUID-ish length is passed through verbatim
/// (the user pasted a full id we didn't index). trace:TASK-112 | ai:claude
fn resolve_resume_id(recorded: &[String], requested: &str) -> Result<String> {
    let matches: Vec<&String> = recorded
        .iter()
        .filter(|id| id.starts_with(requested))
        .collect();
    match matches.len() {
        1 => Ok(matches[0].clone()),
        0 if requested.len() >= 16 => Ok(requested.to_string()),
        // TASK-402 (friction #1): the pasted value has the shape of an AIDA
        // lease id, not a Claude session UUID. The banner that advertised
        // `session <lease> started` check line is the trap — `--resume` wants the
        // Claude session UUID. Name the mismatch and point at the right id.
        // trace:TASK-402 | ai:claude
        0 if looks_like_lease_id(requested) => anyhow::bail!(
            "`{}` looks like an AIDA lease id, but --resume needs the Claude \
             session UUID (e.g. 019e45cf-acea-73c1-…) — run \
             `aida queue work <scope> --list-sessions` to see the resumable \
             session ids (or pass bare `--resume` to take the most recent)",
            requested
        ),
        0 => anyhow::bail!(
            "no recorded claude session matches `{}` — run \
             `aida queue work <scope> --list-sessions` to see recorded ids",
            requested
        ),
        n => anyhow::bail!(
            "{} recorded sessions match `{}` — use a longer prefix",
            n,
            requested
        ),
    }
}

/// TASK-112: decide fresh-vs-resume for `aida queue work`. Called before
/// the worktree is created so a bad `--resume` fails clean.
///   * `--session-id <uuid>` → cold launch with that caller-minted id
///     (STORY-132 — the TUI tracks the conversation deterministically)
///   * `--fresh`           → cold launch, new minted id
///   * `--resume <id>`     → resume that id (prefix-matched)
///   * bare `--resume`     → resume the most recent recorded session
///   * neither, prior exists, interactive → prompt
///   * neither, otherwise  → cold launch
///     trace:TASK-112, STORY-132 | ai:claude
fn resolve_queue_work_launch(
    scope: &str,
    resume: Option<&str>,
    fresh: bool,
    session_id_override: Option<&str>,
) -> Result<QueueWorkLaunch> {
    use std::io::IsTerminal;

    let mint_fresh = || QueueWorkLaunch::Fresh(uuid::Uuid::now_v7().to_string());

    // STORY-132: a caller-minted session id is a fresh cold launch with
    // that exact UUID — validated up front so a malformed id fails clean
    // before any worktree side effects. Clap already makes it mutually
    // exclusive with `--resume`.
    if let Some(sid) = session_id_override {
        uuid::Uuid::parse_str(sid)
            .with_context(|| format!("--session-id `{}` is not a valid UUID", sid))?;
        return Ok(QueueWorkLaunch::Fresh(sid.to_string()));
    }

    if fresh {
        return Ok(mint_fresh());
    }

    let prior = session::list_scope_sessions(scope).unwrap_or_default();

    match resume {
        // Explicit `--resume <id>`.
        Some(id) if !id.is_empty() => {
            let recorded: Vec<String> = prior.iter().map(|m| m.id.clone()).collect();
            Ok(QueueWorkLaunch::Resume(resolve_resume_id(&recorded, id)?))
        }
        // Bare `--resume` — most recent recorded session for the scope.
        Some(_) => {
            let m = prior.first().ok_or_else(|| {
                anyhow::anyhow!(
                    "no recorded claude session for scope `{}` to resume — \
                     drop --resume (or pass --fresh) to cold-launch",
                    scope
                )
            })?;
            Ok(QueueWorkLaunch::Resume(m.id.clone()))
        }
        // Default: prompt when prior sessions exist and we're
        // interactive; cold-launch otherwise (non-interactive /
        // autonomous runs default to fresh — no blocking prompt).
        None => {
            if prior.is_empty() || !std::io::stdin().is_terminal() {
                return Ok(mint_fresh());
            }
            let fresh_label = "○  start a fresh session".to_string();
            let mut labels: Vec<String> = vec![fresh_label.clone()];
            for m in prior.iter().take(8) {
                labels.push(session::format_session_line(m));
            }
            let pick = inquire::Select::new(
                &format!(
                    "{} prior claude session(s) for {} — resume one?",
                    prior.len(),
                    scope
                ),
                labels.clone(),
            )
            .with_help_message("Use arrow keys to move, Enter to choose")
            .prompt()
            .context("session-resume picker cancelled")?;
            if pick == fresh_label {
                Ok(mint_fresh())
            } else {
                let idx = labels
                    .iter()
                    .position(|l| l == &pick)
                    .map(|p| p.saturating_sub(1))
                    .unwrap_or(0);
                Ok(QueueWorkLaunch::Resume(prior[idx].id.clone()))
            }
        }
    }
}

/// TASK-112: `aida queue work <scope> --list-sessions` — print recorded
/// claude conversations for the scope, newest first. trace:TASK-112
fn print_scope_sessions(scope: &str) -> Result<()> {
    let sessions = session::list_scope_sessions(scope)?;
    if sessions.is_empty() {
        println!(
            "{}",
            format!("(no recorded claude sessions for scope `{}`)", scope).dimmed()
        );
        println!(
            "  {}",
            "a session is recorded the first time `aida queue work` launches claude for this scope"
                .dimmed()
        );
        return Ok(());
    }
    println!(
        "{} claude session(s) for {} (most recent first):",
        sessions.len(),
        scope.cyan()
    );
    for m in &sessions {
        println!("  {}", session::format_session_line(m));
    }
    println!();
    // TASK-402 (friction #1 + #5): make the resume hint paste-ready. Show the
    // *full* Claude session UUID (the id `--resume` actually needs — not the
    // AIDA lease id the kickoff banner shows, and not the 8-char prefix in the
    // table above) and, when the session's recorded worktree differs from the
    // current cwd, prepend the `cd <worktree>` step so a headless session
    // launched in a sibling worktree is resumable in one paste.
    // trace:TASK-402 | ai:claude
    let most_recent = &sessions[0];
    let resume_cmd = paste_ready_resume_command(scope, most_recent);
    println!("  {}", "resume the most recent:".dimmed());
    println!("    {}", resume_cmd.cyan());
    println!();
    println!(
        "  {}",
        format!(
            "(or `aida queue work {} --resume <full-session-uuid>` for a specific one above)",
            scope
        )
        .dimmed()
    );
    Ok(())
}

/// TASK-402: assemble a single paste-ready resume command for a recorded
/// session. Uses the FULL session UUID (`--resume` rejects the AIDA lease id
/// and a truncated prefix can be ambiguous) and, when the session's recorded
/// worktree is known and is not the current cwd, prepends `cd <worktree> && `
/// so a headless session launched in a sibling worktree (Claude's `--resume`
/// is project-slug scoped — invisible from the main repo's cwd) resumes in one
/// paste. Pure given the cwd argument resolved by the caller.
/// trace:TASK-402 | ai:claude
fn paste_ready_resume_command(scope: &str, m: &session::SessionMeta) -> String {
    let base = format!("aida queue work {} --resume {}", scope, m.id);
    let current = std::env::current_dir()
        .ok()
        .map(|p| p.to_string_lossy().into_owned());
    resume_command_with_cwd(&base, m.last_cwd.as_deref(), current.as_deref())
}

/// TASK-402: pure helper — prepend a `cd <worktree> && ` step when the
/// session's recorded worktree is known and differs from the current cwd.
/// Keeps the cwd-resolution side effect out so it's unit-testable.
/// trace:TASK-402 | ai:claude
fn resume_command_with_cwd(base: &str, worktree: Option<&str>, current: Option<&str>) -> String {
    match worktree {
        Some(wt) if !wt.is_empty() && Some(wt) != current => {
            format!("cd {} && {}", wt, base)
        }
        _ => base.to_string(),
    }
}

#[cfg(test)]
mod queue_work_resume_tests {
    use super::*;

    #[test]
    fn resolve_resume_id_unique_prefix() {
        let recorded = vec!["abc123def456".to_string(), "xyz789ghi012".to_string()];
        assert_eq!(resolve_resume_id(&recorded, "abc").unwrap(), "abc123def456");
    }

    #[test]
    fn resolve_resume_id_ambiguous_prefix_errs() {
        let recorded = vec!["abc1".to_string(), "abc2".to_string()];
        assert!(resolve_resume_id(&recorded, "abc").is_err());
    }

    #[test]
    fn resolve_resume_id_passthrough_full_id() {
        // No recorded match, but a UUID-ish-length id → passed through.
        let recorded: Vec<String> = vec![];
        let full = "0123456789abcdef0123";
        assert_eq!(resolve_resume_id(&recorded, full).unwrap(), full);
    }

    #[test]
    fn resolve_resume_id_short_no_match_errs() {
        let recorded: Vec<String> = vec![];
        assert!(resolve_resume_id(&recorded, "abc").is_err());
    }

    // TASK-402 (friction #1): a pasted AIDA lease id is recognised by shape
    // and the error names the right id form instead of the generic miss.
    // trace:TASK-402 | ai:claude
    #[test]
    fn looks_like_lease_id_distinguishes_lease_from_uuid() {
        // AIDA lease ids: hyphenless hex, 8-16 chars.
        assert!(looks_like_lease_id("019e45cfc559"));
        assert!(looks_like_lease_id("019e45cf"));
        // Claude session UUIDs carry hyphens — not a lease id.
        assert!(!looks_like_lease_id("019e45cf-acea-73c1-9476-d044fe19d8e4"));
        // A bare short prefix the user typed is too short / not full hex run.
        assert!(!looks_like_lease_id("abc"));
        assert!(!looks_like_lease_id(""));
        // Non-hex characters disqualify it.
        assert!(!looks_like_lease_id("zzzzzzzz"));
    }

    #[test]
    fn resolve_resume_id_lease_shaped_miss_points_at_uuid() {
        // The user pasted the lease id from the kickoff banner. No recorded
        // session matches, but the message must call out the lease-vs-UUID
        // confusion, not the generic "no recorded session" miss.
        let recorded: Vec<String> = vec!["019e45cf-acea-73c1-9476-d044fe19d8e4".to_string()];
        let err = resolve_resume_id(&recorded, "019e45cfc559").unwrap_err();
        let msg = err.to_string().to_lowercase();
        assert!(msg.contains("lease id"), "msg: {msg}");
        assert!(msg.contains("uuid"), "msg: {msg}");
    }

    // TASK-402 (friction #5): the resume command is paste-ready — it prepends
    // the `cd <worktree>` step only when the recorded worktree differs from
    // the current cwd. trace:TASK-402 | ai:claude
    #[test]
    fn resume_command_prepends_cd_when_worktree_differs() {
        let base = "aida queue work TASK-358 --resume 019e45cf-acea-73c1";
        let cmd = resume_command_with_cwd(
            base,
            Some("/home/joe/ai/aida-task-358"),
            Some("/home/joe/ai/aida"),
        );
        assert_eq!(cmd, format!("cd /home/joe/ai/aida-task-358 && {base}"));
    }

    #[test]
    fn resume_command_omits_cd_when_worktree_matches_cwd() {
        let base = "aida queue work TASK-358 --resume 019e45cf-acea-73c1";
        let cmd =
            resume_command_with_cwd(base, Some("/home/joe/ai/aida"), Some("/home/joe/ai/aida"));
        assert_eq!(cmd, base);
    }

    #[test]
    fn resume_command_omits_cd_when_worktree_unknown() {
        let base = "aida queue work TASK-358 --resume 019e45cf-acea-73c1";
        let cmd = resume_command_with_cwd(base, None, Some("/home/joe/ai/aida"));
        assert_eq!(cmd, base);
        let cmd_empty = resume_command_with_cwd(base, Some(""), Some("/home/joe/ai/aida"));
        assert_eq!(cmd_empty, base);
    }

    #[test]
    fn queue_work_launch_session_id_accessor() {
        assert_eq!(QueueWorkLaunch::Fresh("f".into()).session_id(), "f");
        assert_eq!(QueueWorkLaunch::Resume("r".into()).session_id(), "r");
    }

    #[test]
    fn queue_work_session_id_override_threads_through() {
        // STORY-132: a caller-minted UUID becomes the Fresh launch id
        // verbatim, instead of the auto-generated `Uuid::now_v7()`.
        let uuid = "019e2cb7-a2cd-7782-a503-f0daf2b8df82";
        let launch = resolve_queue_work_launch("EPIC-26", None, false, Some(uuid)).unwrap();
        assert!(matches!(launch, QueueWorkLaunch::Fresh(_)));
        assert_eq!(launch.session_id(), uuid);
    }

    #[test]
    fn queue_work_rejects_non_uuid_session_id() {
        // STORY-132: a malformed `--session-id` fails clean, before any
        // worktree side effects, with a UUID-flavored message.
        let err =
            resolve_queue_work_launch("EPIC-26", None, false, Some("not-a-uuid")).unwrap_err();
        assert!(err.to_string().to_lowercase().contains("uuid"));
    }

    #[test]
    fn lease_ids_in_excludes_companion_files() {
        // BUG-114: `.manifest.toml` (always written when `--session-id` is
        // passed — which `--auto-complete` always does) and `.activity.toml`
        // are companions, not leases. Counting them was the phase-1
        // disambiguation failure.
        let dir = tempfile::tempdir().unwrap();
        let s = dir.path();
        let lease = "019e0000-0000-7000-8000-000000000001";
        std::fs::write(s.join(format!("{lease}.toml")), "id = \"x\"\n").unwrap();
        std::fs::write(s.join(format!("{lease}.activity.toml")), "").unwrap();
        std::fs::write(s.join(format!("{lease}.manifest.toml")), "").unwrap();
        std::fs::write(s.join("not-a-lease.txt"), "").unwrap();
        assert_eq!(lease_ids_in(s), vec![lease.to_string()]);
    }

    #[test]
    fn find_orchestrated_lease_pins_session_by_claude_id() {
        // BUG-114 regression: with several concurrent leases on disk — plus
        // the orchestrated session's own `.manifest.toml` companion — the
        // orchestrator must still resolve its session by the claude id it
        // minted, not by diffing the lease set.
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        let sessions = root.join(".aida").join("sessions");
        std::fs::create_dir_all(&sessions).unwrap();

        let mint = |lease_id: &str, branch: &str, claude_id: Option<&str>| {
            std::fs::write(
                sessions.join(format!("{lease_id}.toml")),
                format!(
                    "id = \"{lease_id}\"\nbranch = \"{branch}\"\nworktree_path = \"/tmp/{lease_id}\"\n"
                ),
            )
            .unwrap();
            let manifest = session_manifest::SessionManifest {
                session_id: lease_id.to_string(),
                planned_at: chrono::Utc::now(),
                plan_source: "queue work".to_string(),
                claude_session_id: claude_id.map(str::to_string),
                batch_name: None,
                plan: None,
                items: vec![],
            };
            session_manifest::save(&session_manifest::manifest_path(root, lease_id), &manifest)
                .unwrap();
        };

        // Two unrelated concurrent sessions + the orchestrated one.
        mint(
            "019e1111-aaaa",
            "feature-a",
            Some("aaaaaaaa-1111-7000-8000-000000000000"),
        );
        mint("019e2222-bbbb", "feature-b", None);
        let orchestrated = "019e3333-7000-8000-9000-000000000099";
        mint("019e9999-cccc", "task-259", Some(orchestrated));

        assert_eq!(
            find_orchestrated_lease(root, orchestrated),
            Some((
                "019e9999-cccc".to_string(),
                "task-259".to_string(),
                std::path::PathBuf::from("/tmp/019e9999-cccc"),
            )),
        );
        // An unknown claude id resolves to nothing — the caller turns that
        // into a candidate-naming failure message.
        assert!(find_orchestrated_lease(root, "no-such-id").is_none());
    }

    /// BUG-223: the pure swap-detection rule. A worktree HEAD that differs
    /// from the lease's session-start snapshot is a swap; an unchanged,
    /// detached, or undetectable HEAD leaves the recorded branch standing.
    #[test]
    fn swapped_branch_detects_a_genuine_swap() {
        // /aida-pr's BUG-88 guard moved the commits to a fresh branch.
        assert_eq!(
            swapped_branch(Ok("epic-23-10".to_string()), "epic-23-9"),
            Some("epic-23-10".to_string()),
        );
        // No swap — worktree HEAD still matches the lease snapshot.
        assert_eq!(
            swapped_branch(Ok("epic-23-9".to_string()), "epic-23-9"),
            None
        );
        // Detached HEAD — `rev-parse --abbrev-ref` yields the literal "HEAD".
        assert_eq!(swapped_branch(Ok("HEAD".to_string()), "epic-23-9"), None);
        // Empty / undetectable — trust the recorded branch.
        assert_eq!(swapped_branch(Ok(String::new()), "epic-23-9"), None);
        // git failed (worktree already gone) — trust the recorded branch.
        assert_eq!(
            swapped_branch(Err(anyhow::anyhow!("no worktree")), "epic-23-9"),
            None,
        );
    }

    /// BUG-223: `update_lease_branch` rewrites the `branch` field and only
    /// that field — every other lease field survives the round-trip.
    #[test]
    fn update_lease_branch_rewrites_only_the_branch() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        let sessions = leases_dir(root);
        std::fs::create_dir_all(&sessions).unwrap();
        let lease = SessionLease {
            id: "019eabcd-1234".to_string(),
            scope: "EPIC-23".to_string(),
            slug: "epic-23".to_string(),
            owner: "tester".into(),
            worktree_path: root.to_path_buf(),
            branch: "epic-23-9".to_string(),
            started_at: chrono::Utc::now(),
            hostname: "h".into(),
            role: Some("implementer".into()),
            creator_pid: Some(4242),
            cargo_target_dir: None,
            parent_project_root: None,
            pr_head_sha: None,
            pr_base_sha: None,
            pr_base_ref: None,
            zen_intent_token: None,
            escalated_to_human: None,
            parent_branch: None,
            parent_branch_sha: None,
            review_verb: false,
            claim_verb: false,
        };
        std::fs::write(
            sessions.join("019eabcd-1234.toml"),
            toml::to_string_pretty(&lease).unwrap(),
        )
        .unwrap();

        update_lease_branch(root, "019eabcd-1234", "epic-23-10").unwrap();

        let body = std::fs::read_to_string(sessions.join("019eabcd-1234.toml")).unwrap();
        let reloaded: SessionLease = toml::from_str(&body).unwrap();
        assert_eq!(reloaded.branch, "epic-23-10");
        // Every other field survives the rewrite untouched.
        assert_eq!(reloaded.scope, "EPIC-23");
        assert_eq!(reloaded.creator_pid, Some(4242));
        assert_eq!(reloaded.role.as_deref(), Some("implementer"));
    }

    /// BUG-223 regression: simulate `/aida-pr`'s BUG-88 guard swapping the
    /// implementer branch, and verify the orchestrator's reconciliation both
    /// returns the live branch and rewrites the stale lease.
    #[test]
    fn reconcile_orchestrated_branch_follows_a_pr_branch_swap() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();

        let git = |args: &[&str]| {
            let ok = std::process::Command::new("git")
                .current_dir(root)
                .args(args)
                .output()
                .unwrap()
                .status
                .success();
            assert!(ok, "git {args:?} failed");
        };
        // A git worktree on `epic-23-9` with one commit.
        git(&["init", "-q", "-b", "epic-23-9"]);
        git(&["config", "user.email", "t@t"]);
        git(&["config", "user.name", "t"]);
        git(&["config", "commit.gpgsign", "false"]);
        git(&["commit", "-q", "--allow-empty", "-m", "seed"]);

        // Lease recorded `epic-23-9` at session-start.
        let sessions = leases_dir(root);
        std::fs::create_dir_all(&sessions).unwrap();
        let lease = SessionLease {
            id: "019eaaaa-bbbb".to_string(),
            scope: "EPIC-23".into(),
            slug: "epic-23".into(),
            owner: "t".into(),
            worktree_path: root.to_path_buf(),
            branch: "epic-23-9".into(),
            started_at: chrono::Utc::now(),
            hostname: "h".into(),
            role: Some("implementer".into()),
            creator_pid: None,
            cargo_target_dir: None,
            parent_project_root: None,
            pr_head_sha: None,
            pr_base_sha: None,
            pr_base_ref: None,
            zen_intent_token: None,
            escalated_to_human: None,
            parent_branch: None,
            parent_branch_sha: None,
            review_verb: false,
            claim_verb: false,
        };
        std::fs::write(
            sessions.join("019eaaaa-bbbb.toml"),
            toml::to_string_pretty(&lease).unwrap(),
        )
        .unwrap();

        // No swap yet: reconcile is a no-op, returns the recorded branch.
        assert_eq!(
            reconcile_orchestrated_branch(root, "019eaaaa-bbbb", root, "epic-23-9"),
            "epic-23-9",
        );

        // `/aida-pr`'s BUG-88 guard moves the commits to a fresh branch.
        git(&["checkout", "-q", "-b", "epic-23-10"]);

        // Reconcile now follows the swap and rewrites the lease.
        assert_eq!(
            reconcile_orchestrated_branch(root, "019eaaaa-bbbb", root, "epic-23-9"),
            "epic-23-10",
        );
        let body = std::fs::read_to_string(sessions.join("019eaaaa-bbbb.toml")).unwrap();
        let reloaded: SessionLease = toml::from_str(&body).unwrap();
        assert_eq!(reloaded.branch, "epic-23-10");
    }
}

#[cfg(test)]
mod drain_reliability_wiring_tests {
    //! TASK-136 / BUG-420: the I/O-shell wiring around the pure decision cores
    //! (`gh_verify_backoff_schedule`, `watchdog_verdict`). The pure cores are
    //! tested in `auto_complete`; here we lock the config parsing, the watchdog
    //! trip-reason text, and the worktree progress signature.
    use super::*;

    #[test]
    fn read_drain_config_parses_drain_section() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(tmp.path().join(".aida")).unwrap();
        std::fs::write(
            tmp.path().join(".aida/config.toml"),
            "[node]\nid = \"x\"\n\n[drain]\ngh_verify_retries = 2  # transient blips\n\
             no_progress_minutes = 3\nphase_ceiling_minutes = 20\n",
        )
        .unwrap();
        let cfg = read_drain_config(tmp.path());
        assert_eq!(cfg.gh_verify_retries, Some(2));
        assert_eq!(cfg.no_progress_minutes, Some(3));
        assert_eq!(cfg.phase_ceiling_minutes, Some(20));
    }

    #[test]
    fn read_drain_config_absent_section_is_all_none() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(tmp.path().join(".aida")).unwrap();
        std::fs::write(tmp.path().join(".aida/config.toml"), "[node]\nid = \"x\"\n").unwrap();
        let cfg = read_drain_config(tmp.path());
        assert_eq!(cfg.gh_verify_retries, None);
        assert_eq!(cfg.no_progress_minutes, None);
        assert_eq!(cfg.phase_ceiling_minutes, None);
    }

    #[test]
    fn watchdog_trip_reason_names_the_threshold_minutes() {
        let wd = PhaseWatchdog::new(
            std::path::PathBuf::from("/tmp/nonexistent"),
            "sess".to_string(),
            std::time::Duration::from_secs(10 * 60),
            std::time::Duration::from_secs(45 * 60),
        );
        assert!(wd
            .trip_reason(auto_complete::WatchdogTrip::NoProgress)
            .contains("10m"));
        assert!(wd
            .trip_reason(auto_complete::WatchdogTrip::Ceiling)
            .contains("45m"));
    }

    #[test]
    fn resume_start_phase_clamp_bumps_ci_to_reviewer_only() {
        use auto_complete::Phase;
        // CI is the one unsafe re-entry (lease-coupled) → bumped to reviewer.
        assert_eq!(
            clamp_resume_start_phase(Phase::Ci),
            Phase::Reviewer,
            "a reconciled CI re-entry must clamp up to the reviewer",
        );
        // Every other phase is left exactly as reconciled.
        for p in [
            Phase::Implementer,
            Phase::Reviewer,
            Phase::Merge,
            Phase::Pull,
            Phase::Build,
        ] {
            assert_eq!(clamp_resume_start_phase(p), p);
        }
    }

    #[test]
    fn probe_resume_facts_is_conservative_when_nothing_exists() {
        // No git / gh / store → every postcondition is conservatively false, so
        // reconcile would re-run from the start rather than skip a real phase.
        let tmp = tempfile::tempdir().unwrap();
        let storage = Storage::new(tmp.path().join("requirements.db"));
        let (facts, branch, pr) = probe_resume_facts(tmp.path(), &storage, "TASK-1", None);
        assert!(!facts.branch_exists);
        assert!(!facts.pr_merged);
        assert!(!facts.spec_completed);
        assert!(!facts.ci_green);
        assert!(!facts.reviewed);
        assert!(!facts.build_ok);
        assert_eq!(branch, None);
        assert_eq!(pr, None);
    }

    #[test]
    fn progress_signature_changes_when_a_file_is_edited_then_committed() {
        // A real worktree: an edit and a commit each move the signature, so the
        // no-progress timer resets; an idle worktree keeps it stable.
        let tmp = tempfile::tempdir().unwrap();
        let wt = tmp.path();
        let git = |args: &[&str]| {
            assert!(std::process::Command::new("git")
                .arg("-C")
                .arg(wt)
                .args(args)
                .output()
                .unwrap()
                .status
                .success());
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "t@t.t"]);
        git(&["config", "user.name", "t"]);
        std::fs::write(wt.join("a.txt"), "one").unwrap();
        git(&["add", "."]);
        git(&["commit", "-q", "-m", "first"]);

        let sig1 = PhaseWatchdog::progress_signature(wt).expect("sig after first commit");
        // Idle: same signature.
        assert_eq!(
            sig1,
            PhaseWatchdog::progress_signature(wt).unwrap(),
            "an idle worktree must not register as progress",
        );
        // A new uncommitted edit changes the porcelain status → progress.
        std::fs::write(wt.join("b.txt"), "two").unwrap();
        let sig2 = PhaseWatchdog::progress_signature(wt).unwrap();
        assert_ne!(sig1, sig2, "an uncommitted edit is progress");
        // Committing it advances HEAD → progress again.
        git(&["add", "."]);
        git(&["commit", "-q", "-m", "second"]);
        let sig3 = PhaseWatchdog::progress_signature(wt).unwrap();
        assert_ne!(sig2, sig3, "a new commit is progress");
    }
}

// trace:ARCH-github-integration | ai:claude
/// Handle GitHub integration commands
// trace:ARCH-jira-integration | ai:claude
fn handle_jira_command(cmd: &JiraCommand, storage: &Storage) -> Result<()> {
    let rt = tokio::runtime::Runtime::new()?;

    match cmd {
        JiraCommand::Config {
            url,
            project,
            email,
            show,
            show_mapping,
        } => {
            let mut config = aida_core::JiraConfig::load()?;

            if *show {
                println!("{}", "Jira Configuration".bold());
                println!("{}", "─".repeat(40));
                println!(
                    "Instance:  {}",
                    if config.instance_url.is_empty() {
                        "(not set)"
                    } else {
                        &config.instance_url
                    }
                );
                println!(
                    "Project:   {}",
                    if config.project_key.is_empty() {
                        "(not set)"
                    } else {
                        &config.project_key
                    }
                );
                println!(
                    "Email:     {}",
                    if config.user_email.is_empty() {
                        "(not set)"
                    } else {
                        &config.user_email
                    }
                );
                println!(
                    "Token:     {}",
                    if config.effective_token().is_ok() {
                        "configured (AIDA_JIRA_TOKEN)"
                    } else {
                        "not configured"
                    }
                );
                println!("Enabled:   {}", config.enabled);
                return Ok(());
            }

            if *show_mapping {
                println!("{}", "Field Mapping Spec".bold());
                println!("{}", "─".repeat(50));
                println!("\n{}", "Type Mapping (AIDA → Jira):".bold());
                for (aida, jira) in &config.mapping.types {
                    println!("  {:<20} → {}", aida, jira);
                }
                println!("\n{}", "Status Mapping (AIDA → Jira):".bold());
                for (aida, jira) in &config.mapping.statuses {
                    println!("  {:<20} → {}", aida, jira);
                }
                println!("\n{}", "Priority Mapping (AIDA → Jira):".bold());
                for (aida, jira) in &config.mapping.priorities {
                    println!("  {:<20} → {}", aida, jira);
                }
                println!("\n{}", "Reverse Type Mapping (Jira → AIDA):".bold());
                for (jira, aida) in &config.mapping.reverse_types {
                    println!("  {:<20} → {}", jira, aida);
                }
                println!("\n{}", "Reverse Status Mapping (Jira → AIDA):".bold());
                for (jira, aida) in &config.mapping.reverse_statuses {
                    println!("  {:<20} → {}", jira, aida);
                }
                println!(
                    "\nEdit mapping at: {}",
                    aida_core::JiraConfig::config_path()?.display()
                );
                return Ok(());
            }

            if let Some(u) = url {
                config.instance_url = u.clone();
            }
            if let Some(p) = project {
                config.project_key = p.clone();
            }
            if let Some(e) = email {
                config.user_email = e.clone();
            }

            config.save()?;
            println!(
                "{} Jira configuration saved.",
                crate::glyph(crate::glyphs::Glyph::Check).green()
            );
        }
        JiraCommand::Test => {
            let config = aida_core::JiraConfig::load()?;
            let client = aida_core::JiraClient::new(config)?;
            let project = rt.block_on(client.test_connection())?;

            println!(
                "{} Connected to Jira",
                crate::glyph(crate::glyphs::Glyph::Check).green()
            );
            println!("  Project: {} ({})", project.name, project.key);
        }
        JiraCommand::List { jql, limit } => {
            let config = aida_core::JiraConfig::load()?;
            let client = aida_core::JiraClient::new(config.clone())?;

            let results = if let Some(query) = jql {
                rt.block_on(client.search(query, *limit))?
            } else {
                rt.block_on(client.list_issues(*limit))?
            };

            if results.issues.is_empty() {
                println!("No issues found.");
            } else {
                println!(
                    "{:<12} {:<10} {:<12} {:<10} Summary",
                    "Key", "Type", "Status", "Priority"
                );
                println!("{}", "─".repeat(75));
                for issue in &results.issues {
                    println!(
                        "{:<12} {:<10} {:<12} {:<10} {}",
                        issue.key,
                        truncate_str(issue.issue_type_name(), 9),
                        truncate_str(issue.status_name(), 11),
                        truncate_str(issue.priority_name(), 9),
                        truncate_str(issue.summary(), 40),
                    );
                }
                println!("\n{} issues", results.issues.len());
            }
        }
        JiraCommand::Show { key } => {
            let config = aida_core::JiraConfig::load()?;
            let client = aida_core::JiraClient::new(config)?;
            let issue = rt.block_on(client.get_issue(key))?;

            println!("{}: {}", "Key".bold(), issue.key);
            println!("{}: {}", "Summary".bold(), issue.summary());
            println!("{}: {}", "Type".bold(), issue.issue_type_name());
            println!("{}: {}", "Status".bold(), issue.status_name());
            println!("{}: {}", "Priority".bold(), issue.priority_name());
            if let Some(assignee) = issue.assignee_name() {
                println!("{}: {}", "Assignee".bold(), assignee);
            }
            if !issue.labels().is_empty() {
                println!("{}: {}", "Labels".bold(), issue.labels().join(", "));
            }
            let desc = issue.description_text();
            if !desc.is_empty() {
                println!("\n{}", desc);
            }
        }
        JiraCommand::Push { id } => {
            let config = aida_core::JiraConfig::load()?;
            let client = aida_core::JiraClient::new(config.clone())?;

            let store = storage.load()?;
            let req = store
                .requirements
                .iter()
                .find(|r| r.matches_id(id))
                .ok_or_else(|| not_found::requirement_not_found(id, Some(storage.path())))?;

            let display_id = req.display_id();
            let type_name = config.map_type(&format!("{:?}", req.req_type));
            let priority_name = config.map_priority(&req.effective_priority());

            let mut labels = Vec::new();
            labels.push(format!("aida:{}", display_id));
            for tag in &req.tags {
                labels.push(format!("aida:{}", tag));
            }

            let description_text = format!(
                "{}\n\n---\nAIDA: {} | UUID: {}",
                req.description, display_id, req.id
            );

            let request = aida_core::JiraCreateIssueRequest {
                fields: aida_core::JiraCreateIssueFields {
                    project: aida_core::JiraProjectRef {
                        key: config.project_key.clone(),
                    },
                    summary: format!("[{}] {}", display_id, req.title),
                    description: Some(aida_core::text_to_adf(&description_text)),
                    issuetype: aida_core::JiraIssueTypeRef { name: type_name },
                    priority: Some(aida_core::JiraPriorityRef {
                        name: priority_name,
                    }),
                    assignee: None,
                    labels,
                },
            };

            let created = rt.block_on(client.create_issue(&request))?;
            println!(
                "{} Created Jira issue {} for {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                created.key.white().bold(),
                display_id
            );
            println!("  URL: {}/browse/{}", config.instance_url, created.key);
        }
        JiraCommand::Sync { apply } => {
            let config = aida_core::JiraConfig::load()?;
            let client = aida_core::JiraClient::new(config.clone())?;

            let store = storage.load()?;

            // Find AIDA requirements linked to Jira issues
            // Link detection: title starts with [DEV-N] or [PROJ-N], or has jira: tags
            let linked: Vec<(&Requirement, String)> = store
                .requirements
                .iter()
                .filter_map(|r| {
                    // Check [KEY-N] prefix in title
                    if r.title.starts_with('[') {
                        if let Some(end) = r.title.find(']') {
                            let key = &r.title[1..end];
                            if key.contains('-')
                                && key
                                    .split('-')
                                    .next_back()
                                    .map(|n| n.parse::<u64>().is_ok())
                                    .unwrap_or(false)
                            {
                                return Some((r, key.to_string()));
                            }
                        }
                    }
                    // Check jira: tags
                    for tag in &r.tags {
                        if let Some(key) = tag.strip_prefix("jira:key:") {
                            return Some((r, key.to_string()));
                        }
                    }
                    None
                })
                .collect();

            // Also find Jira issues with aida: labels that aren't linked from AIDA side
            // (TODO: tighten JQL to filter on aida:label_prefix once verified)
            let jira_issues = rt
                .block_on(client.search(
                    &format!("project = {} ORDER BY updated DESC", config.project_key),
                    50,
                ))
                .unwrap_or_else(|_| aida_core::JiraSearchResults {
                    issues: Vec::new(),
                    next_page_token: None,
                    is_last: Some(true),
                    total: 0,
                });

            if linked.is_empty() && jira_issues.issues.is_empty() {
                println!("No linked items found.");
                println!("Link with: aida jira push FR-001 (or aida jira pull)");
                return Ok(());
            }

            println!("{}", "Jira Sync Status".bold());
            println!("{}", "─".repeat(70));

            let mut in_sync = 0;
            let mut drifted = 0;
            let mut errors = 0;

            for (req, jira_key) in &linked {
                match rt.block_on(client.get_issue(jira_key)) {
                    Ok(issue) => {
                        let mut diffs = Vec::new();

                        // Compare title (strip [KEY] prefix for comparison)
                        let aida_title = req
                            .title
                            .strip_prefix(&format!("[{}] ", jira_key))
                            .unwrap_or(&req.title);
                        if aida_title != issue.summary() {
                            diffs.push(format!(
                                "  title: AIDA='{}' Jira='{}'",
                                truncate_str(aida_title, 25),
                                truncate_str(issue.summary(), 25)
                            ));
                        }

                        // Compare status using mapping
                        let expected_jira_status = config.map_status(&req.effective_status());
                        let actual_jira_status = issue.status_name();
                        if expected_jira_status != actual_jira_status {
                            diffs.push(format!(
                                "  status: AIDA={} (→{}) Jira={}",
                                req.effective_status(),
                                expected_jira_status,
                                actual_jira_status
                            ));
                        }

                        // Compare priority
                        let expected_priority = config.map_priority(&req.effective_priority());
                        let actual_priority = issue.priority_name();
                        if expected_priority != actual_priority {
                            diffs.push(format!(
                                "  priority: AIDA={} (→{}) Jira={}",
                                req.effective_priority(),
                                expected_priority,
                                actual_priority
                            ));
                        }

                        let spec_id = req.display_id();
                        if diffs.is_empty() {
                            in_sync += 1;
                            println!(
                                "{} {:<12} ↔ {:<10} {} — in sync",
                                crate::glyph(crate::glyphs::Glyph::Check).green(),
                                spec_id,
                                jira_key,
                                truncate_str(aida_title, 35)
                            );
                        } else {
                            drifted += 1;
                            println!(
                                "{} {:<12} ↔ {:<10} {} — DRIFTED",
                                "△".yellow(),
                                spec_id,
                                jira_key,
                                truncate_str(aida_title, 35)
                            );
                            for d in &diffs {
                                println!("    {}", d);
                            }
                        }
                    }
                    Err(e) => {
                        errors += 1;
                        println!(
                            "{} {} ↔ {} — error: {}",
                            crate::glyph(crate::glyphs::Glyph::Cross).red(),
                            req.display_id(),
                            jira_key,
                            e
                        );
                    }
                }
            }

            println!();
            println!(
                "{} in sync, {} drifted, {} errors (of {} linked)",
                in_sync,
                drifted,
                errors,
                linked.len()
            );

            if drifted > 0 && !apply {
                println!("\nUse --apply to push AIDA state to Jira.");
            }

            if *apply && drifted > 0 {
                println!("\nApplying changes...");
                for (req, jira_key) in &linked {
                    let aida_title = req
                        .title
                        .strip_prefix(&format!("[{}] ", jira_key))
                        .unwrap_or(&req.title);

                    let fields = serde_json::json!({
                        "summary": aida_title,
                        "priority": { "name": config.map_priority(&req.effective_priority()) },
                    });

                    match rt.block_on(client.update_issue(jira_key, &fields)) {
                        Ok(_) => println!(
                            "  {} Updated {}",
                            crate::glyph(crate::glyphs::Glyph::Check).green(),
                            jira_key
                        ),
                        Err(e) => eprintln!(
                            "  {} Failed {}: {}",
                            crate::glyph(crate::glyphs::Glyph::Cross).red(),
                            jira_key,
                            e
                        ),
                    }
                }
            }
        }
        JiraCommand::Pull {
            jql,
            limit,
            dry_run,
        } => {
            let config = aida_core::JiraConfig::load()?;
            let client = aida_core::JiraClient::new(config.clone())?;

            let query = jql.clone().unwrap_or_else(|| {
                format!(
                    "project = {} AND status != Done ORDER BY updated DESC",
                    config.project_key
                )
            });
            let results = rt.block_on(client.search(&query, *limit))?;

            if results.issues.is_empty() {
                println!("No issues found.");
                return Ok(());
            }

            let store = storage.load()?;
            let existing_titles: std::collections::HashSet<String> =
                store.requirements.iter().map(|r| r.title.clone()).collect();

            let mut to_import = Vec::new();
            let mut skipped = 0;

            for issue in &results.issues {
                let jira_prefix = format!("[{}]", issue.key);
                if existing_titles.contains(&issue.fields.summary)
                    || store
                        .requirements
                        .iter()
                        .any(|r| r.title.starts_with(&jira_prefix))
                {
                    skipped += 1;
                } else {
                    to_import.push(issue);
                }
            }

            if to_import.is_empty() {
                println!(
                    "All {} issues already imported ({} skipped).",
                    results.issues.len(),
                    skipped
                );
                return Ok(());
            }

            println!(
                "Found {} issues to import ({} already exist):",
                to_import.len(),
                skipped
            );
            for issue in &to_import {
                let aida_type = config.reverse_map_type(issue.issue_type_name());
                println!(
                    "  {:<12} {:<10} {}",
                    issue.key,
                    aida_type,
                    truncate_str(issue.summary(), 50)
                );
            }

            if *dry_run {
                println!("\nDry run — no requirements created.");
                return Ok(());
            }

            // Bulk-writer path (FR-1-002): one commit per pull, no full-store
            // round-trip. trace:FR-1-002 | ai:claude
            let imported = bulk_import_via_writer(
                storage,
                "feat(jira)",
                to_import.iter().map(|issue| {
                    let aida_type_str = config.reverse_map_type(issue.issue_type_name());
                    let aida_status_str = config.reverse_map_status(issue.status_name());
                    let mut req = Requirement::new(
                        format!("[{}] {}", issue.key, issue.fields.summary),
                        issue.description_text(),
                    );
                    req.req_type =
                        parse_requirement_type(&aida_type_str).unwrap_or(RequirementType::Task);
                    req.set_status_from_str(&aida_status_str);
                    for label in issue.labels() {
                        req.tags.insert(format!("jira:{}", label));
                    }
                    req
                }),
            )?;

            println!(
                "\n{} Imported {} issues as requirements.",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                imported
            );
        }
    }
    Ok(())
}

fn handle_github_command(cmd: &GitHubCommand, storage: &Storage) -> Result<()> {
    let rt = tokio::runtime::Runtime::new()?;

    match cmd {
        GitHubCommand::Config {
            repo,
            token,
            api_url,
            show,
        } => {
            let mut config = aida_core::GitHubConfig::load()?;

            if *show {
                println!("{}", "GitHub Configuration".bold());
                println!("{}", "─".repeat(40));
                println!("API URL:  {}", config.api_url);
                println!(
                    "Repo:     {}",
                    if config.repo.is_empty() {
                        "(not set)"
                    } else {
                        &config.repo
                    }
                );
                println!(
                    "Token:    {}",
                    if config.effective_token().is_ok() {
                        "configured (AIDA_GITHUB_TOKEN)"
                    } else {
                        "not configured"
                    }
                );
                println!("Enabled:  {}", config.enabled);
                return Ok(());
            }

            if let Some(r) = repo {
                config.repo = r.clone();
            }
            if let Some(t) = token {
                std::env::set_var("AIDA_GITHUB_TOKEN", t);
                config.token = Some(t.clone());
                println!(
                    "{} Token set for this session. Set AIDA_GITHUB_TOKEN env var for persistence.",
                    "!".yellow()
                );
            }
            if let Some(u) = api_url {
                config.api_url = u.clone();
            }

            config.save()?;
            println!(
                "{} GitHub configuration saved.",
                crate::glyph(crate::glyphs::Glyph::Check).green()
            );
        }
        GitHubCommand::Test => {
            let config = aida_core::GitHubConfig::load()?;
            config.validate()?;

            let client = aida_core::GitHubClient::new(config)?;
            let repo = rt.block_on(client.test_connection())?;

            println!(
                "{} Connected to GitHub",
                crate::glyph(crate::glyphs::Glyph::Check).green()
            );
            println!("  Repository: {}", repo.full_name);
            println!("  URL:        {}", repo.html_url);
            println!("  Default:    {}", repo.default_branch);
            println!("  Private:    {}", repo.is_private);
        }
        GitHubCommand::List {
            state,
            labels,
            limit,
        } => {
            let config = aida_core::GitHubConfig::load()?;
            let client = aida_core::GitHubClient::new(config)?;

            let mut filter = aida_core::GitHubIssueFilter {
                state: Some(state.clone()),
                per_page: Some(*limit),
                ..Default::default()
            };
            if let Some(l) = labels {
                filter.labels = l.split(',').map(|s| s.trim().to_string()).collect();
            }

            let issues = rt.block_on(client.list_issues(Some(filter)))?;

            if issues.is_empty() {
                println!("No issues found.");
            } else {
                println!("{:<8} {:<10} {:<40} Labels", "#", "State", "Title");
                println!("{}", "─".repeat(75));
                for issue in &issues {
                    let labels_str: String = issue
                        .labels
                        .iter()
                        .map(|l| l.name.as_str())
                        .collect::<Vec<_>>()
                        .join(", ");
                    println!(
                        "{:<8} {:<10} {:<40} {}",
                        format!("#{}", issue.number),
                        issue.state,
                        truncate_str(&issue.title, 38),
                        labels_str,
                    );
                }
                println!("\n{} issues", issues.len());
            }
        }
        GitHubCommand::Show { number } => {
            let config = aida_core::GitHubConfig::load()?;
            let client = aida_core::GitHubClient::new(config)?;

            // Parse "GH-42" or "42"
            let num: u64 = number
                .trim_start_matches("GH-")
                .trim_start_matches("gh-")
                .trim_start_matches('#')
                .parse()
                .map_err(|_| anyhow::anyhow!("Invalid issue number: {}", number))?;

            let issue = rt.block_on(client.get_issue(num))?;

            println!("{}: #{}", "Number".bold(), issue.number);
            println!("{}: {}", "Title".bold(), issue.title);
            println!("{}: {}", "State".bold(), issue.state);
            println!("{}: {}", "Author".bold(), issue.user.login);
            if let Some(ref assignee) = issue.assignee {
                println!("{}: {}", "Assignee".bold(), assignee.login);
            }
            if !issue.labels.is_empty() {
                let labels: Vec<&str> = issue.labels.iter().map(|l| l.name.as_str()).collect();
                println!("{}: {}", "Labels".bold(), labels.join(", "));
            }
            println!("{}: {}", "URL".bold(), issue.html_url);
            println!("{}: {}", "Comments".bold(), issue.comments);
            if let Some(ref body) = issue.body {
                if !body.is_empty() {
                    println!("\n{}", body);
                }
            }
        }
        GitHubCommand::Push { id } => {
            let config = aida_core::GitHubConfig::load()?;
            let client = aida_core::GitHubClient::new(config.clone())?;

            let store = storage.load()?;
            let req = store
                .requirements
                .iter()
                .find(|r| r.matches_id(id))
                .ok_or_else(|| not_found::requirement_not_found(id, Some(storage.path())))?;

            // Build labels from type and priority
            let mut labels = Vec::new();
            let type_str = format!("{:?}", req.req_type);
            if let Some(label) = config.labels.types.get(&type_str) {
                labels.push(label.clone());
            }
            let priority_str = req.effective_priority();
            if let Some(label) = config.labels.priorities.get(&priority_str) {
                labels.push(label.clone());
            }
            let status_str = req.effective_status();
            if let Some(label) = config.labels.statuses.get(&status_str) {
                labels.push(label.clone());
            }

            // Build issue body with AIDA metadata
            let display_id = req.display_id();
            let body = format!(
                "{}\n\n---\n_AIDA: {} | UUID: {}_",
                req.description, display_id, req.id,
            );

            let request = aida_core::GitHubCreateIssueRequest {
                title: format!("[{}] {}", display_id, req.title),
                body: Some(body),
                labels,
                assignees: if req.owner.is_empty() {
                    Vec::new()
                } else {
                    vec![req.owner.clone()]
                },
                milestone: None,
            };

            let issue = rt.block_on(client.create_issue(&request))?;
            println!(
                "{} Created GitHub issue #{} for {}",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                issue.number,
                display_id
            );
            println!("  URL: {}", issue.html_url);
        }
        GitHubCommand::Sync { linked_only, apply } => {
            let config = aida_core::GitHubConfig::load()?;
            let client = aida_core::GitHubClient::new(config)?;

            let store = storage.load()?;

            // Find AIDA requirements linked to GitHub issues (by [GH-N] prefix or URL)
            let linked: Vec<(&Requirement, u64)> = store
                .requirements
                .iter()
                .filter_map(|r| {
                    // Check [GH-N] prefix
                    if r.title.starts_with("[GH-") {
                        if let Some(end) = r.title.find(']') {
                            if let Ok(n) = r.title[4..end].parse::<u64>() {
                                return Some((r, n));
                            }
                        }
                    }
                    // Check URLs
                    for url in &r.urls {
                        if url.url.contains("github.com") && url.url.contains("/issues/") {
                            if let Some(num_str) = url.url.rsplit('/').next() {
                                if let Ok(n) = num_str.parse::<u64>() {
                                    return Some((r, n));
                                }
                            }
                        }
                    }
                    None
                })
                .collect();

            if linked.is_empty() && *linked_only {
                println!("No linked GitHub issues found.");
                println!("Link with: aida github push FR-001 (or aida github pull)");
                return Ok(());
            }

            println!("{}", "GitHub Sync Status".bold());
            println!("{}", "─".repeat(65));

            let mut drift_count = 0;

            for (req, issue_number) in &linked {
                match rt.block_on(client.get_issue(*issue_number)) {
                    Ok(issue) => {
                        let mut diffs = Vec::new();

                        // Compare title (strip [GH-N] prefix for comparison)
                        let aida_title = req
                            .title
                            .strip_prefix(&format!("[GH-{}] ", issue_number))
                            .unwrap_or(&req.title);
                        if aida_title != issue.title {
                            diffs.push(format!(
                                "  title: AIDA='{}' GitHub='{}'",
                                truncate_str(aida_title, 30),
                                truncate_str(&issue.title, 30)
                            ));
                        }

                        // Compare state
                        let aida_closed = matches!(
                            req.status,
                            RequirementStatus::Completed | RequirementStatus::Rejected
                        );
                        let gh_closed = issue.state == "closed";
                        if aida_closed != gh_closed {
                            diffs.push(format!(
                                "  state: AIDA={} GitHub={}",
                                req.effective_status(),
                                issue.state
                            ));
                        }

                        if diffs.is_empty() {
                            println!(
                                "{} #{:<5} {} — in sync",
                                crate::glyph(crate::glyphs::Glyph::Check).green(),
                                issue_number,
                                truncate_str(aida_title, 45)
                            );
                        } else {
                            drift_count += 1;
                            println!(
                                "{} #{:<5} {} — DRIFTED",
                                "△".yellow(),
                                issue_number,
                                truncate_str(aida_title, 45)
                            );
                            for d in &diffs {
                                println!("    {}", d);
                            }
                        }
                    }
                    Err(e) => {
                        println!(
                            "{} #{:<5} — error: {}",
                            crate::glyph(crate::glyphs::Glyph::Cross).red(),
                            issue_number,
                            e
                        );
                    }
                }
            }

            println!();
            if drift_count == 0 {
                println!("All {} linked items in sync.", linked.len());
            } else {
                println!("{} of {} items have drifted.", drift_count, linked.len());
                if !apply {
                    println!("Use --apply to push AIDA state to GitHub.");
                }
            }

            if *apply && drift_count > 0 {
                println!();
                println!("Applying changes...");
                for (req, issue_number) in &linked {
                    let aida_title = req
                        .title
                        .strip_prefix(&format!("[GH-{}] ", issue_number))
                        .unwrap_or(&req.title);

                    let aida_closed = matches!(
                        req.status,
                        RequirementStatus::Completed | RequirementStatus::Rejected
                    );

                    let update = aida_core::GitHubUpdateIssueRequest {
                        title: Some(aida_title.to_string()),
                        body: Some(req.description.clone()),
                        state: Some(if aida_closed {
                            "closed".into()
                        } else {
                            "open".into()
                        }),
                        labels: None,
                        assignees: None,
                        milestone: None,
                    };

                    match rt.block_on(client.update_issue(*issue_number, &update)) {
                        Ok(_) => println!(
                            "  {} Updated #{}",
                            crate::glyph(crate::glyphs::Glyph::Check).green(),
                            issue_number
                        ),
                        Err(e) => eprintln!(
                            "  {} Failed #{}: {}",
                            crate::glyph(crate::glyphs::Glyph::Cross).red(),
                            issue_number,
                            e
                        ),
                    }
                }
            }
        }
        GitHubCommand::Pull {
            labels,
            open_only,
            limit,
            dry_run,
        } => {
            let config = aida_core::GitHubConfig::load()?;
            let client = aida_core::GitHubClient::new(config.clone())?;

            let mut filter = aida_core::GitHubIssueFilter {
                state: Some(if *open_only { "open" } else { "all" }.into()),
                per_page: Some(*limit),
                ..Default::default()
            };
            if let Some(l) = labels {
                filter.labels = l.split(',').map(|s| s.trim().to_string()).collect();
            }

            let issues = rt.block_on(client.list_issues(Some(filter)))?;

            if issues.is_empty() {
                println!("No issues found to import.");
                return Ok(());
            }

            // Check which issues are already imported (by matching title pattern)
            let store = storage.load()?;
            let existing_titles: std::collections::HashSet<String> =
                store.requirements.iter().map(|r| r.title.clone()).collect();

            let mut to_import: Vec<&aida_core::GitHubIssue> = Vec::new();
            let mut skipped = 0;

            for issue in &issues {
                // Skip if already imported (check for [GH-N] prefix or exact title match)
                let gh_prefix = format!("[GH-{}]", issue.number);
                let already_exists = existing_titles.contains(&issue.title)
                    || store
                        .requirements
                        .iter()
                        .any(|r| r.title.starts_with(&gh_prefix));

                if already_exists {
                    skipped += 1;
                } else {
                    to_import.push(issue);
                }
            }

            if to_import.is_empty() {
                println!(
                    "All {} issues already imported ({} skipped).",
                    issues.len(),
                    skipped
                );
                return Ok(());
            }

            println!(
                "Found {} issues to import ({} already exist):",
                to_import.len(),
                skipped
            );

            for issue in &to_import {
                // Determine type from labels
                let req_type = determine_type_from_labels(&issue.label_names(), &config.labels);
                let priority = determine_priority_from_labels(&issue.label_names(), &config.labels);

                println!(
                    "  #{:<6} {:<12} {:<8} {}",
                    issue.number,
                    format!("{:?}", req_type),
                    format!("{:?}", priority),
                    truncate_str(&issue.title, 50),
                );
            }

            if *dry_run {
                println!("\nDry run — no requirements created.");
                return Ok(());
            }

            // Import using the bulk-writer path (FR-1-002): one git commit
            // for the whole batch, no full-store load/iterate.
            // trace:FR-1-002 | ai:claude
            let imported = bulk_import_via_writer(
                storage,
                "feat(github)",
                to_import.iter().map(|issue| {
                    let req_type = determine_type_from_labels(&issue.label_names(), &config.labels);
                    let priority =
                        determine_priority_from_labels(&issue.label_names(), &config.labels);
                    let mut req = Requirement::new(
                        format!("[GH-{}] {}", issue.number, issue.title),
                        issue.body.clone().unwrap_or_default(),
                    );
                    req.req_type = req_type;
                    req.priority = priority;
                    if let Some(ref assignee) = issue.assignee {
                        req.owner = assignee.login.clone();
                    }
                    if issue.state == "closed" {
                        req.status = RequirementStatus::Completed;
                    }
                    for label in &issue.labels {
                        req.tags.insert(format!("gh:{}", label.name));
                    }
                    req.urls.push(aida_core::models::UrlLink {
                        id: Uuid::now_v7(),
                        url: issue.html_url.clone(),
                        title: format!("GitHub #{}", issue.number),
                        description: None,
                        open_mode: aida_core::models::UrlOpenMode::NewTab,
                        added_at: chrono::Utc::now(),
                        added_by: "github-import".to_string(),
                        last_verified: None,
                        last_verified_ok: None,
                    });
                    req
                }),
            )?;

            println!(
                "\n{} Imported {} issues as requirements.",
                crate::glyph(crate::glyphs::Glyph::Check).green(),
                imported
            );
        }
        GitHubCommand::Labels { create_missing } => {
            let config = aida_core::GitHubConfig::load()?;
            let client = aida_core::GitHubClient::new(config.clone())?;

            let existing = rt.block_on(client.list_labels())?;
            let existing_names: std::collections::HashSet<String> =
                existing.iter().map(|l| l.name.clone()).collect();

            println!("{}", "Repository Labels".bold());
            println!("{}", "─".repeat(40));
            for label in &existing {
                println!(
                    "  {} (#{}) {}",
                    label.name,
                    label.color,
                    label.description.as_deref().unwrap_or("")
                );
            }
            println!("\n{} labels", existing.len());

            if *create_missing {
                let all_labels: Vec<(&str, &str)> = config
                    .labels
                    .types
                    .values()
                    .map(|v| (v.as_str(), "0e8a16"))
                    .chain(
                        config
                            .labels
                            .priorities
                            .values()
                            .map(|v| (v.as_str(), "d93f0b")),
                    )
                    .chain(
                        config
                            .labels
                            .statuses
                            .values()
                            .map(|v| (v.as_str(), "1d76db")),
                    )
                    .collect();

                let mut created = 0;
                for (name, color) in all_labels {
                    if !existing_names.contains(name) {
                        match rt.block_on(client.create_label(name, color, Some("Created by AIDA")))
                        {
                            Ok(_) => {
                                println!(
                                    "  {} Created label: {}",
                                    crate::glyph(crate::glyphs::Glyph::Check).green(),
                                    name
                                );
                                created += 1;
                            }
                            Err(e) => {
                                eprintln!(
                                    "  {} Failed to create {}: {}",
                                    crate::glyph(crate::glyphs::Glyph::Cross).red(),
                                    name,
                                    e
                                );
                            }
                        }
                    }
                }
                if created == 0 {
                    println!("\nAll AIDA labels already exist.");
                } else {
                    println!("\n{} labels created.", created);
                }
            }
        }
    }

    Ok(())
}

/// Determine AIDA requirement type from GitHub labels.
fn determine_type_from_labels(
    labels: &[&str],
    label_config: &aida_core::GitHubLabelConfig,
) -> RequirementType {
    // Check each label against the type mappings (reverse lookup)
    for label in labels {
        for (type_name, mapped_label) in &label_config.types {
            if label.eq_ignore_ascii_case(mapped_label) {
                return match type_name.as_str() {
                    "Bug" => RequirementType::Bug,
                    "Story" => RequirementType::Story,
                    "Task" => RequirementType::Task,
                    "Epic" => RequirementType::Epic,
                    "Functional" => RequirementType::Functional,
                    "NonFunctional" => RequirementType::NonFunctional,
                    _ => RequirementType::Task,
                };
            }
        }
        // Also check common GitHub labels directly
        let l = label.to_lowercase();
        if l == "bug" {
            return RequirementType::Bug;
        }
        if l == "enhancement" || l == "feature" {
            return RequirementType::Story;
        }
    }
    RequirementType::Task // default
}

/// Determine AIDA priority from GitHub labels.
fn determine_priority_from_labels(
    labels: &[&str],
    label_config: &aida_core::GitHubLabelConfig,
) -> RequirementPriority {
    for label in labels {
        for (priority_name, mapped_label) in &label_config.priorities {
            if label.eq_ignore_ascii_case(mapped_label) {
                return match priority_name.as_str() {
                    "High" => RequirementPriority::High,
                    "Low" => RequirementPriority::Low,
                    _ => RequirementPriority::Medium,
                };
            }
        }
    }
    RequirementPriority::Medium // default
}

fn truncate_str(s: &str, max: usize) -> String {
    if s.len() <= max {
        s.to_string()
    } else {
        format!("{}...", &s[..max.saturating_sub(3)])
    }
}

// trace:STORY-0321 | ai:claude
/// Handle GitLab integration commands
fn handle_gitlab_command(cmd: &GitLabCommand, storage: &Storage) -> Result<()> {
    // Create tokio runtime for async operations
    let rt = tokio::runtime::Runtime::new()?;

    match cmd {
        GitLabCommand::Config {
            url,
            project,
            token,
            show,
        } => {
            if *show {
                // Show current configuration
                match GitLabConfig::load() {
                    Ok(Some(config)) => {
                        println!("{}", "GitLab Configuration:".bold());
                        println!("  URL:        {}", config.url);
                        println!("  Project ID: {}", config.project_id);
                        println!(
                            "  Enabled:    {}",
                            if config.enabled { "yes" } else { "no" }
                        );
                        if config.effective_token().is_some() {
                            println!("  Token:      {}", "(configured)".green());
                        } else {
                            println!("  Token:      {}", "(not set)".yellow());
                        }
                        println!("\nLabel prefix: {}", config.labels.prefix);
                        println!("Sync mode:    {:?}", config.sync.mode);
                    }
                    Ok(None) => {
                        println!("{}", "GitLab is not configured.".yellow());
                        println!("Use 'aida gitlab config --url <URL> --project <ID> --token <TOKEN>' to configure.");
                    }
                    Err(e) => {
                        println!("{}: {}", "Error loading config".red(), e);
                    }
                }
                return Ok(());
            }

            // Update configuration
            let mut config = GitLabConfig::load()?.unwrap_or_default();

            if let Some(u) = url {
                config.url = u.clone();
                println!("Set URL: {}", u);
            }
            if let Some(p) = project {
                config.project_id = *p;
                println!("Set project ID: {}", p);
            }
            if let Some(t) = token {
                // Store token in environment for this session
                // In production, would use keyring
                std::env::set_var("AIDA_GITLAB_TOKEN", t);
                config.token = Some(t.clone());
                println!("Set token: (hidden)");
            }

            // Save config (token excluded from file)
            config.save()?;
            println!("{}", "Configuration saved.".green());

            // Validate if we have enough config
            if let Err(e) = config.validate() {
                println!("{}: {}", "Warning".yellow(), e);
                println!("Run 'aida gitlab test' to verify connection.");
            }
        }

        GitLabCommand::Test => {
            // Test connection to GitLab
            let config = GitLabConfig::load()?.ok_or_else(|| {
                anyhow::anyhow!("GitLab not configured. Run 'aida gitlab config' first.")
            })?;

            println!("Testing connection to {}...", config.url);

            let client = GitLabClient::new(config)?;
            let project = rt.block_on(client.test_connection())?;

            println!("{}", "Connection successful!".green());
            println!("  Project: {}", project.name_with_namespace);
            println!("  URL:     {}", project.web_url);
            if let Some(desc) = &project.description {
                if !desc.is_empty() {
                    println!("  Desc:    {}", desc);
                }
            }
        }

        GitLabCommand::List {
            state,
            labels,
            search,
            limit,
        } => {
            let config = GitLabConfig::load()?.ok_or_else(|| {
                anyhow::anyhow!("GitLab not configured. Run 'aida gitlab config' first.")
            })?;

            let client = GitLabClient::new(config)?;

            // Build filter
            let mut filter = match state.as_str() {
                "opened" => IssueFilter::open(),
                "closed" => IssueFilter {
                    state: Some(IssueState::Closed),
                    ..Default::default()
                },
                _ => IssueFilter::default(),
            };

            if let Some(l) = labels {
                filter = filter.with_labels(l.split(',').map(|s| s.trim().to_string()).collect());
            }

            if let Some(s) = search {
                filter.search = Some(s.clone());
            }

            filter.per_page = Some(*limit);

            let issues = rt.block_on(client.list_issues(Some(filter)))?;

            if issues.is_empty() {
                println!("{}", "No issues found.".yellow());
                return Ok(());
            }

            println!("{}", format!("Found {} issues:", issues.len()).bold());
            println!();

            for issue in &issues {
                let state_indicator = if issue.is_open() {
                    "●".green()
                } else {
                    "○".bright_black()
                };

                println!(
                    "{} {} {}",
                    state_indicator,
                    format!("GL-{}", issue.iid).cyan(),
                    issue.title
                );

                if !issue.labels.is_empty() {
                    println!("    Labels: {}", issue.labels.join(", ").bright_black());
                }
            }
        }

        GitLabCommand::Show { iid } => {
            let config = GitLabConfig::load()?.ok_or_else(|| {
                anyhow::anyhow!("GitLab not configured. Run 'aida gitlab config' first.")
            })?;

            let client = GitLabClient::new(config)?;

            // Parse IID (handle "GL-123" or "123" format)
            let iid_num: u64 = iid
                .strip_prefix("GL-")
                .unwrap_or(iid)
                .parse()
                .map_err(|_| anyhow::anyhow!("Invalid issue IID: {}", iid))?;

            let issue = rt.block_on(client.get_issue(iid_num))?;

            println!("{}", format!("GL-{}: {}", issue.iid, issue.title).bold());
            println!();

            let state_str = if issue.is_open() {
                "Open".green()
            } else {
                "Closed".bright_black()
            };
            println!("State:    {}", state_str);
            println!("Author:   {}", issue.author.username);
            if let Some(assignee) = issue.assignee_username() {
                println!("Assignee: {}", assignee);
            }
            if !issue.labels.is_empty() {
                println!("Labels:   {}", issue.labels.join(", "));
            }
            if let Some(milestone) = &issue.milestone {
                println!("Milestone: {}", milestone.title);
            }
            println!("URL:      {}", issue.web_url);
            println!();

            if let Some(desc) = &issue.description {
                if !desc.is_empty() {
                    println!("{}", "Description:".bold());
                    println!("{}", desc);
                }
            }
        }

        // trace:STORY-0325 | ai:claude
        GitLabCommand::Status { id, diverged } => {
            use aida_core::{LinkOrigin, SyncStatus};

            // Check if storage is SQLite (sync state only works with SQLite)
            if !storage.is_sqlite() {
                println!(
                    "{}",
                    "GitLab sync status is only available for SQLite databases.".yellow()
                );
                return Ok(());
            }

            let store = storage.load()?;

            // Load sync states based on filter
            let sync_states = if let Some(req_id) = id {
                // Find the requirement by spec_id or UUID
                let requirement = store.requirements.iter().find(|r| {
                    r.spec_id
                        .as_deref()
                        .is_some_and(|s| s.eq_ignore_ascii_case(req_id))
                        || r.id.to_string() == *req_id
                });

                if let Some(req) = requirement {
                    storage.load_sync_states_for_requirement(req.id)?
                } else {
                    println!("{} {}", "Requirement not found:".red(), req_id);
                    return Ok(());
                }
            } else {
                storage.load_all_sync_states()?
            };

            // Filter by diverged if requested
            let sync_states: Vec<_> = if *diverged {
                sync_states
                    .into_iter()
                    .filter(|s| !matches!(s.sync_status, SyncStatus::InSync))
                    .collect()
            } else {
                sync_states
            };

            if sync_states.is_empty() {
                if *diverged {
                    println!("{}", "No diverged GitLab links found.".green());
                } else {
                    println!("{}", "No GitLab sync states found.".yellow());
                    println!("Link requirements to GitLab issues using the GUI or create issues from requirements.");
                }
                return Ok(());
            }

            // Display sync states
            println!("{}", "GitLab Sync Status".bold());
            println!("{}", "─".repeat(60));

            for state in &sync_states {
                // Find the requirement for this sync state
                let req = store
                    .requirements
                    .iter()
                    .find(|r| r.id == state.requirement_id);

                let req_display = if let Some(r) = req {
                    r.spec_id.clone().unwrap_or_else(|| r.id.to_string())
                } else {
                    state.spec_id.clone()
                };

                // Status icon and color
                let (status_icon, _status_color) = match state.sync_status {
                    SyncStatus::InSync => (crate::glyph(crate::glyphs::Glyph::Check), "green"),
                    SyncStatus::AidaModified => ("△", "yellow"),
                    SyncStatus::GitLabModified => ("▽", "cyan"),
                    SyncStatus::Conflict => (crate::glyph(crate::glyphs::Glyph::Warning), "red"),
                    SyncStatus::Error => (crate::glyph(crate::glyphs::Glyph::Cross), "red"),
                    SyncStatus::Untracked => ("?", "dimmed"),
                };

                let status_text = match state.sync_status {
                    SyncStatus::InSync => "In Sync".green(),
                    SyncStatus::AidaModified => "AIDA Modified".yellow(),
                    SyncStatus::GitLabModified => "GitLab Modified".cyan(),
                    SyncStatus::Conflict => "Conflict".red(),
                    SyncStatus::Error => "Error".red(),
                    SyncStatus::Untracked => "Untracked".dimmed(),
                };

                let origin_text = match state.link_origin {
                    LinkOrigin::CreatedFromAida => "→GL",
                    LinkOrigin::ImportedFromGitLab => "←GL",
                    LinkOrigin::ManualLink => "↔GL",
                };

                println!(
                    "{} {} {} GL-{} [{}] {}",
                    status_icon,
                    req_display.bold(),
                    origin_text.dimmed(),
                    state.gitlab_issue_iid,
                    status_text,
                    state
                        .last_sync
                        .with_timezone(&chrono::Local)
                        .format("%Y-%m-%d %H:%M")
                        .to_string()
                        .dimmed()
                );

                if let Some(error) = &state.last_error {
                    println!("    {} {}", "Error:".red(), error);
                }
            }

            println!("{}", "─".repeat(60));
            println!(
                "Total: {} links ({} in sync, {} diverged)",
                sync_states.len(),
                sync_states
                    .iter()
                    .filter(|s| matches!(s.sync_status, SyncStatus::InSync))
                    .count(),
                sync_states
                    .iter()
                    .filter(|s| !matches!(s.sync_status, SyncStatus::InSync))
                    .count()
            );
        }

        // trace:STORY-0326 | ai:claude
        GitLabCommand::Labels {
            validate,
            create_missing,
            init,
        } => {
            // Load or create config
            let mut config = GitLabConfig::load()?.unwrap_or_default();

            // Initialize with defaults if requested
            if *init {
                config.labels = config.labels.with_defaults();
                config.save()?;
                println!("{}", "Label mappings initialized with defaults.".green());
            }

            // Show current label configuration
            println!("{}", "GitLab Label Mappings".bold());
            println!("{}", "─".repeat(50));

            if !config.labels.prefix.is_empty() {
                println!("Prefix: {}", config.labels.prefix.cyan());
            }

            println!("\n{}", "Type Mappings:".bold());
            if config.labels.types.is_empty() {
                println!(
                    "  {} (use --init to set defaults)",
                    "(none configured)".dimmed()
                );
            } else {
                for (aida_type, gitlab_label) in &config.labels.types {
                    println!("  {} → {}", aida_type, gitlab_label.cyan());
                }
            }

            println!("\n{}", "Priority Mappings:".bold());
            if config.labels.priorities.is_empty() {
                println!(
                    "  {} (use --init to set defaults)",
                    "(none configured)".dimmed()
                );
            } else {
                for (priority, gitlab_label) in &config.labels.priorities {
                    println!("  {} → {}", priority, gitlab_label.cyan());
                }
            }

            println!("\n{}", "Status Mappings:".bold());
            if config.labels.statuses.is_empty() {
                println!(
                    "  {} (use --init to set defaults)",
                    "(none configured)".dimmed()
                );
            } else {
                for (status, gitlab_label) in &config.labels.statuses {
                    println!("  {} → {}", status, gitlab_label.cyan());
                }
            }

            println!(
                "\nAuto-create labels: {}",
                if config.labels.auto_create_labels {
                    "yes".green()
                } else {
                    "no".dimmed()
                }
            );

            // Validate labels if requested
            if *validate || *create_missing {
                let Some(token) = config.effective_token() else {
                    return Err(anyhow::anyhow!("GitLab token required. Set AIDA_GITLAB_TOKEN or run 'aida gitlab config --token <TOKEN>'"));
                };

                let mut config_with_token = config.clone();
                config_with_token.token = Some(token);
                let client = GitLabClient::new(config_with_token)?;

                println!("\n{}", "Validating labels in GitLab...".dimmed());

                // Get all labels from GitLab project
                let gitlab_labels = rt.block_on(client.list_labels())?;
                let gitlab_label_names: std::collections::HashSet<_> =
                    gitlab_labels.iter().map(|l| l.name.clone()).collect();

                // Get all mapped labels
                let mapped_labels = config.labels.all_labels();
                let mut missing_labels = Vec::new();
                let mut found_labels = Vec::new();

                for label in &mapped_labels {
                    if gitlab_label_names.contains(label) {
                        found_labels.push(label.clone());
                    } else {
                        missing_labels.push(label.clone());
                    }
                }

                println!("\n{}", "Validation Results:".bold());
                println!(
                    "  {} labels found in GitLab",
                    found_labels.len().to_string().green()
                );
                if !missing_labels.is_empty() {
                    println!(
                        "  {} labels missing:",
                        missing_labels.len().to_string().yellow()
                    );
                    for label in &missing_labels {
                        println!("    - {}", label.yellow());
                    }
                }

                // Create missing labels if requested
                if *create_missing && !missing_labels.is_empty() {
                    println!("\n{}", "Creating missing labels...".dimmed());
                    for label in &missing_labels {
                        // Determine label color based on type
                        let color = if label.starts_with("type::") {
                            "#428BCA" // Blue for types
                        } else if label.starts_with("priority::") {
                            if label.contains("high") {
                                "#DC3545"
                            } else if label.contains("low") {
                                "#28A745"
                            } else {
                                "#FFC107"
                            }
                        } else if label.starts_with("status::") {
                            "#6C757D" // Gray for status
                        } else {
                            "#7950F2" // Purple default
                        };

                        match rt.block_on(client.create_label(label, color, None)) {
                            Ok(_) => println!(
                                "  {} Created: {}",
                                crate::glyph(crate::glyphs::Glyph::Check).green(),
                                label
                            ),
                            Err(e) => println!(
                                "  {} Failed to create {}: {}",
                                crate::glyph(crate::glyphs::Glyph::Cross).red(),
                                label,
                                e
                            ),
                        }
                    }
                }
            }
        }

        // trace:STORY-0327 | ai:claude
        GitLabCommand::Refresh { id, force } => {
            use aida_core::{GitLabSyncState, IssueFilter, SyncStatus};

            // Check if storage is SQLite (sync state only works with SQLite)
            if !storage.is_sqlite() {
                println!(
                    "{}",
                    "GitLab refresh is only available for SQLite databases.".yellow()
                );
                return Ok(());
            }

            // Load GitLab config
            let config = GitLabConfig::load()?.ok_or_else(|| {
                anyhow::anyhow!("GitLab not configured. Run 'aida gitlab config' first.")
            })?;

            let Some(token) = config.effective_token() else {
                return Err(anyhow::anyhow!("GitLab token required. Set AIDA_GITLAB_TOKEN or run 'aida gitlab config --token <TOKEN>'"));
            };

            let mut config_with_token = config.clone();
            config_with_token.token = Some(token);
            let client = GitLabClient::new(config_with_token)?;

            let store = storage.load()?;

            // Get sync states to refresh
            let sync_states = if let Some(req_id) = id {
                // Find the requirement by spec_id or UUID
                let requirement = store.requirements.iter().find(|r| {
                    r.spec_id
                        .as_deref()
                        .is_some_and(|s| s.eq_ignore_ascii_case(req_id))
                        || r.id.to_string() == *req_id
                });

                if let Some(req) = requirement {
                    storage.load_sync_states_for_requirement(req.id)?
                } else {
                    println!("{} {}", "Requirement not found:".red(), req_id);
                    return Ok(());
                }
            } else {
                storage.load_all_sync_states()?
            };

            if sync_states.is_empty() {
                println!("{}", "No GitLab sync states found to refresh.".yellow());
                println!("Link requirements to GitLab issues first.");
                return Ok(());
            }

            println!("{}", "Refreshing GitLab sync states...".dimmed());
            println!("{}", "─".repeat(60));

            // Collect all issue IIDs to fetch
            let iids: Vec<u64> = sync_states.iter().map(|s| s.gitlab_issue_iid).collect();

            // Fetch issues from GitLab
            let filter = IssueFilter::default().with_iids(iids);
            let issues = rt.block_on(client.list_issues(Some(filter)))?;

            // Create a map of IID -> Issue for quick lookup
            let issue_map: std::collections::HashMap<u64, _> =
                issues.into_iter().map(|i| (i.iid, i)).collect();

            let mut updated_count = 0;
            let mut error_count = 0;

            for mut state in sync_states {
                // Find the requirement
                let req = store
                    .requirements
                    .iter()
                    .find(|r| r.id == state.requirement_id);

                let req_display = if let Some(r) = req {
                    r.spec_id.clone().unwrap_or_else(|| r.id.to_string())
                } else {
                    state.spec_id.clone()
                };

                // Get the GitLab issue
                if let Some(issue) = issue_map.get(&state.gitlab_issue_iid) {
                    // Calculate current hashes
                    let current_gitlab_hash = GitLabSyncState::hash_gitlab_issue(issue);
                    let current_aida_hash = if let Some(r) = req {
                        GitLabSyncState::hash_requirement(r)
                    } else {
                        state.aida_content_hash.clone()
                    };

                    // Determine new sync status
                    let old_status = state.sync_status.clone();
                    let aida_changed = current_aida_hash != state.aida_content_hash;
                    let gitlab_changed = current_gitlab_hash != state.gitlab_content_hash;

                    let new_status = match (aida_changed, gitlab_changed) {
                        (false, false) => SyncStatus::InSync,
                        (true, false) => SyncStatus::AidaModified,
                        (false, true) => SyncStatus::GitLabModified,
                        (true, true) => SyncStatus::Conflict,
                    };

                    // Update if changed or forced
                    if *force || new_status != old_status {
                        state.sync_status = new_status.clone();
                        state.last_sync = chrono::Utc::now();
                        state.last_error = None;

                        // Update stored hashes if this is a fresh sync
                        if state.aida_content_hash.is_empty() {
                            state.aida_content_hash = current_aida_hash;
                        }
                        if state.gitlab_content_hash.is_empty() {
                            state.gitlab_content_hash = current_gitlab_hash;
                        }

                        if let Err(e) = storage.save_sync_state(&state) {
                            println!(
                                "  {} {} GL-{}: {}",
                                crate::glyph(crate::glyphs::Glyph::Cross).red(),
                                req_display,
                                state.gitlab_issue_iid,
                                e
                            );
                            error_count += 1;
                        } else {
                            let status_indicator = match new_status {
                                SyncStatus::InSync => {
                                    crate::glyph(crate::glyphs::Glyph::Check).green()
                                }
                                SyncStatus::AidaModified => "△".yellow(),
                                SyncStatus::GitLabModified => "▽".cyan(),
                                SyncStatus::Conflict => {
                                    crate::glyph(crate::glyphs::Glyph::Warning).red()
                                }
                                _ => "?".dimmed(),
                            };
                            println!(
                                "  {} {} GL-{}: {}",
                                status_indicator, req_display, state.gitlab_issue_iid, new_status
                            );
                            updated_count += 1;
                        }
                    } else {
                        println!(
                            "  {} {} GL-{}: {} (unchanged)",
                            "·".dimmed(),
                            req_display,
                            state.gitlab_issue_iid,
                            old_status
                        );
                    }
                } else {
                    println!(
                        "  {} {} GL-{}: Issue not found in GitLab",
                        "?".yellow(),
                        req_display,
                        state.gitlab_issue_iid
                    );
                    error_count += 1;
                }
            }

            println!("{}", "─".repeat(60));
            println!(
                "Refreshed: {} updated, {} errors",
                updated_count.to_string().green(),
                if error_count > 0 {
                    error_count.to_string().red()
                } else {
                    "0".dimmed()
                }
            );
        }

        // trace:STORY-0327 | ai:claude
        GitLabCommand::Poll { action, interval } => match action.to_lowercase().as_str() {
            "status" => {
                let config = GitLabConfig::load()?;
                if let Some(config) = config {
                    println!("{}", "GitLab Polling Configuration".bold());
                    println!("{}", "─".repeat(40));
                    println!(
                        "Polling enabled: {}",
                        if config.polling.enabled {
                            "yes".green()
                        } else {
                            "no".dimmed()
                        }
                    );
                    println!(
                        "Interval: {} seconds ({} minutes)",
                        config.polling.interval_seconds,
                        config.polling.interval_seconds / 60
                    );
                    println!("Batch size: {}", config.polling.batch_size);
                    println!("Max concurrent: {}", config.polling.max_concurrent);
                    println!();
                    println!(
                        "{}",
                        "Note: Background polling runs in the AIDA GUI.".dimmed()
                    );
                    println!("{}", "Use 'aida gitlab refresh' for manual sync.".dimmed());
                } else {
                    println!("{}", "GitLab not configured.".yellow());
                }
            }
            "start" => {
                println!(
                    "{}",
                    "Background polling is managed by the AIDA GUI.".yellow()
                );
                println!();
                println!("To enable polling:");
                println!("  1. Open AIDA GUI");
                println!("  2. Go to Settings > GitLab");
                println!("  3. Enable 'Background Polling'");
                println!();
                println!("For CLI-based polling, use a cron job or scheduled task:");
                println!(
                    "  {} aida gitlab refresh",
                    format!("*/{} * * * *", interval / 60).dimmed()
                );
            }
            "stop" => {
                println!(
                    "{}",
                    "Background polling is managed by the AIDA GUI.".yellow()
                );
                println!();
                println!("To disable polling:");
                println!("  1. Open AIDA GUI");
                println!("  2. Go to Settings > GitLab");
                println!("  3. Disable 'Background Polling'");
            }
            _ => {
                println!(
                    "{}: Unknown action '{}'. Use: status, start, stop",
                    "Error".red(),
                    action
                );
            }
        },
    }

    Ok(())
}

#[cfg(test)]
mod story_255_discipline_pack_tests {
    //! Starter discipline pack — `docs/aida/discipline/` + the opt-in
    //! memory pack scaffolded by `aida init --with-memories`.
    //! trace:STORY-255 | STORY-443 | ai:claude
    use super::*;

    /// Verifies the embedded discipline pack scaffolds the full set of canonical
    /// files into a new project's docs/aida/discipline/ directory.
    ///
    /// TASK-465: STRUCTURAL, not count-based. The expected file set is derived
    /// from the SAME single source `ensure_discipline_pack_scaffold` writes from
    /// — the `docs/aida/discipline/` keys in `EMBEDDED_TEMPLATES` — so adding a
    /// doc to the master template can never break this test (the prior hardcoded
    /// `assert_eq!(written, 16)` + hand-maintained file list broke on every pack
    /// addition, e.g. PR-193). trace:TASK-465 | ai:claude
    #[test]
    fn discipline_pack_scaffolds_full_set() {
        use aida_core::templates::EMBEDDED_TEMPLATES;
        // Single source of truth: every embedded `docs/aida/discipline/<file>`.
        let expected: Vec<String> = EMBEDDED_TEMPLATES
            .keys()
            .filter_map(|k| k.strip_prefix("docs/aida/discipline/"))
            .filter(|n| !n.is_empty())
            .map(|n| n.to_string())
            .collect();
        assert!(
            expected.len() >= 10,
            "sanity: expected a populated discipline pack, found {}",
            expected.len()
        );

        let root = tempfile::tempdir().unwrap();
        let written = ensure_discipline_pack_scaffold(root.path(), false).unwrap();
        assert_eq!(
            written,
            expected.len(),
            "scaffolded count must match the embedded discipline pack"
        );

        let dir = root.path().join("docs/aida/discipline");
        for f in &expected {
            assert!(dir.join(f).is_file(), "missing discipline doc: {f}");
        }

        // Idempotent: a second call without --force writes nothing.
        assert_eq!(
            ensure_discipline_pack_scaffold(root.path(), false).unwrap(),
            0
        );
        // --force re-writes them all.
        assert_eq!(
            ensure_discipline_pack_scaffold(root.path(), true).unwrap(),
            expected.len()
        );
    }

    #[test]
    fn ecosystem_watch_scaffold_writes_with_todays_date_and_is_idempotent() {
        // trace:TASK-126 — fresh init must plant docs/competitive-analysis/
        // ecosystem-watch.md with today's local date in the `Last updated`
        // line so `scripts/release.sh`'s ecosystem-watch verification has a
        // file to read on a fresh project's first major/minor cut.
        let root = tempfile::tempdir().unwrap();
        let written = ensure_ecosystem_watch_scaffold(root.path(), false).unwrap();
        assert!(written, "expected the starter file to be written");

        let dest = root
            .path()
            .join("docs/competitive-analysis/ecosystem-watch.md");
        assert!(dest.is_file(), "missing ecosystem-watch.md");
        let body = std::fs::read_to_string(&dest).unwrap();
        let today = chrono::Local::now().format("%Y-%m-%d").to_string();
        assert!(
            body.contains(&format!("**Last updated**: {today}")),
            "expected today's date in Last updated line; got:\n{body}"
        );
        assert!(
            !body.contains("{{LAST_UPDATED}}"),
            "placeholder must be substituted"
        );

        // Idempotent: a second call without --force leaves the file alone.
        assert!(
            !ensure_ecosystem_watch_scaffold(root.path(), false).unwrap(),
            "second call without --force must not overwrite"
        );

        // --force re-writes.
        assert!(
            ensure_ecosystem_watch_scaffold(root.path(), true).unwrap(),
            "--force must re-write"
        );
    }

    #[test]
    fn discipline_pack_lands_under_docs_aida_namespace() {
        // trace:STORY-443 — pack must land at docs/aida/discipline/, not the
        // historical docs/aida-discipline/. Guards against accidental
        // fallback during the namespace reshape.
        let root = tempfile::tempdir().unwrap();
        ensure_discipline_pack_scaffold(root.path(), false).unwrap();
        assert!(
            root.path().join("docs/aida/discipline/README.md").is_file(),
            "discipline pack must land at docs/aida/discipline/"
        );
        assert!(
            !root.path().join("docs/aida-discipline").exists(),
            "historical docs/aida-discipline/ path must not be created"
        );
    }

    #[test]
    fn memory_pack_writes_marked_files_with_marker_and_checksum() {
        let dir = tempfile::tempdir().unwrap();
        let mem = dir.path().join("memory");
        let report = scaffold_memory_pack_into(&mem, false, None).unwrap();

        assert!(
            report.written >= 10,
            "expected the marker-driven pack (>= 10), got {}",
            report.written
        );
        assert_eq!(report.unchanged, 0);

        // Every memory file carries the scaffold marker + a checksum.
        let mut md_count = 0;
        for entry in std::fs::read_dir(&mem).unwrap() {
            let path = entry.unwrap().path();
            if path.file_name().unwrap() == "MEMORY.md" {
                continue;
            }
            md_count += 1;
            let body = std::fs::read_to_string(&path).unwrap();
            assert!(
                body.contains("originSessionId: aida-scaffold"),
                "{path:?} missing scaffold marker"
            );
            assert!(
                body.contains("scaffoldChecksum: "),
                "{path:?} missing checksum"
            );
        }
        assert_eq!(md_count, report.written);

        // A known generic memory is present.
        assert!(mem
            .join("feedback_run_help_before_suggesting_flags.md")
            .is_file());

        // MEMORY.md carries the generated index block.
        let index = std::fs::read_to_string(mem.join("MEMORY.md")).unwrap();
        assert!(index.contains("<!-- aida:scaffold-pack:start -->"));
        assert!(index.contains("<!-- aida:scaffold-pack:end -->"));
        assert!(index.contains("](feedback_run_help_before_suggesting_flags.md)"));
    }

    /// STORY-362: the `--focus <subsystem>` loading filter. A memory tagged
    /// `subsystem: X` loads only under `--focus X`; an untagged memory is
    /// universal and loads regardless of focus (or its absence).
    /// trace:STORY-362 | ai:claude
    #[test]
    fn memory_focus_filter_loads_universal_plus_matching_subsystem() {
        // Hand-built templates — fully isolated, no embedded pack, no $HOME,
        // no filesystem.
        let universal = "---\nname: universal_mem\ntype: feedback\n---\nBody.\n";
        let orchestrator = concat!(
            "---\nname: orch_mem\nsubsystem: orchestrator\ntype: feedback\n---\n",
            "Body.\n"
        );
        let storage = "---\nname: store_mem\nsubsystem: storage\ntype: feedback\n---\nBody.\n";

        // No focus → everything loads (full pack).
        assert!(memory_matches_focus(universal, None));
        assert!(memory_matches_focus(orchestrator, None));
        assert!(memory_matches_focus(storage, None));

        // --focus orchestrator → universal + the orchestrator memory load;
        // the storage-tagged memory does not.
        assert!(
            memory_matches_focus(universal, Some("orchestrator")),
            "untagged memory must be universal under any focus"
        );
        assert!(
            memory_matches_focus(orchestrator, Some("orchestrator")),
            "subsystem-matching memory must load under its focus"
        );
        assert!(
            !memory_matches_focus(storage, Some("orchestrator")),
            "non-matching subsystem memory must NOT load under a different focus"
        );

        // Match is case-insensitive on the subsystem value.
        assert!(memory_matches_focus(orchestrator, Some("Orchestrator")));

        // Malformed / frontmatter-less content is treated as universal.
        assert!(memory_matches_focus("no frontmatter here", Some("storage")));
    }

    /// STORY-362: end-to-end through the scaffold writer — only universal +
    /// matching-subsystem memories land on disk under `--focus`.
    /// trace:STORY-362 | ai:claude
    #[test]
    fn memory_pack_focus_scopes_written_files() {
        let dir = tempfile::tempdir().unwrap();
        let mem = dir.path().join("memory");
        // The embedded pack is currently all-universal (untagged), so a focus
        // on any subsystem still writes the full universal set — and crucially
        // no fewer than the unfocused run for the universal members. Compare a
        // focused run against an unfocused baseline: every file the focused run
        // wrote must be one the baseline also wrote (subset), and every member
        // it kept is universal.
        let focused =
            scaffold_memory_pack_into(&mem, false, Some("nonexistent-subsystem")).unwrap();
        // All embedded members are untagged today → all universal → all written.
        assert!(
            focused.written >= 10,
            "untagged (universal) memories must always load under any focus, got {}",
            focused.written
        );
        // Every written file is genuinely universal (no subsystem tag).
        for entry in std::fs::read_dir(&mem).unwrap() {
            let path = entry.unwrap().path();
            if path.file_name().unwrap() == "MEMORY.md" {
                continue;
            }
            let body = std::fs::read_to_string(&path).unwrap();
            let (fm, _) = split_md_frontmatter(&body).unwrap();
            assert!(
                frontmatter_field(fm, "subsystem").is_none(),
                "{path:?} carries a subsystem tag but was written under a non-matching focus"
            );
        }
    }

    #[test]
    fn memory_pack_refresh_overlays_pristine_skips_edited() {
        let dir = tempfile::tempdir().unwrap();
        let mem = dir.path().join("memory");
        let first = scaffold_memory_pack_into(&mem, false, None).unwrap();
        assert!(first.written >= 10);

        // (a) User-edit one file's body — must be kept on refresh.
        let edited = mem.join("feedback_verify_before_filing.md");
        let mut edited_content = std::fs::read_to_string(&edited).unwrap();
        edited_content.push_str("\n\nUSER EDIT — do not clobber.\n");
        std::fs::write(&edited, &edited_content).unwrap();

        // (b) Replace one file with a user-owned file (no scaffold marker).
        let user_owned = mem.join("feedback_goal_prompt_phrasing.md");
        std::fs::write(&user_owned, "---\nname: mine\n---\n\nmy own memory\n").unwrap();

        // (c) Make one pristine file look like an older scaffold version: a
        //     benign extra frontmatter line, body untouched → still Pristine
        //     but != the current scaffold, so refresh overlays it.
        let stale = mem.join("feedback_pause_for_design_input.md");
        let stale_v1 =
            std::fs::read_to_string(&stale)
                .unwrap()
                .replacen("---\n", "---\nstaleField: x\n", 1);
        std::fs::write(&stale, &stale_v1).unwrap();

        let report = scaffold_memory_pack_into(&mem, true, None).unwrap();
        assert_eq!(report.written, 0, "all files already exist on refresh");
        assert_eq!(report.kept_edited, 1, "the body-edited file is kept");
        assert_eq!(report.kept_user, 1, "the unmarked user file is kept");
        assert_eq!(
            report.refreshed, 1,
            "the stale-but-pristine file is overlaid"
        );

        // The user edit survived.
        assert!(std::fs::read_to_string(&edited)
            .unwrap()
            .contains("USER EDIT"));
        // The user-owned file survived.
        assert!(std::fs::read_to_string(&user_owned)
            .unwrap()
            .contains("my own memory"));
        // The stale file was overlaid — the benign line is gone.
        assert!(!std::fs::read_to_string(&stale)
            .unwrap()
            .contains("staleField"));
    }

    #[test]
    fn memory_disposition_classifies_pristine_edited_and_user() {
        let template =
            "---\nname: t\ndescription: d\nmetadata:\n  type: feedback\n---\n\nbody text\n";
        let scaffolded = build_scaffolded_memory(template).unwrap();
        assert!(scaffolded.contains("originSessionId: aida-scaffold"));
        assert_eq!(
            memory_refresh_disposition(&scaffolded),
            MemoryDisposition::Pristine
        );

        // A user file with no scaffold marker.
        assert_eq!(
            memory_refresh_disposition("---\nname: x\n---\n\nmine\n"),
            MemoryDisposition::UserOwned
        );

        // Scaffolded but the body was edited → checksum mismatch.
        let edited = scaffolded.replace("body text", "body text — changed");
        assert_eq!(
            memory_refresh_disposition(&edited),
            MemoryDisposition::Edited
        );
    }

    #[test]
    fn parser_is_line_ending_agnostic_crlf_and_cr() {
        // The embedded memory templates are checked out as CRLF on a Windows
        // box with git autocrlf, then embedded verbatim by build.rs. The
        // frontmatter parser must not assume LF — and the scaffolded output
        // (hence its checksum) must be byte-identical across platforms.
        // Regression for BUG-244. trace:BUG-244 | ai:claude
        let lf = "---\nname: t\ndescription: d\nmetadata:\n  type: feedback\n---\n\nbody text\n";
        let crlf = lf.replace('\n', "\r\n");
        let cr = lf.replace('\n', "\r");

        let from_lf = build_scaffolded_memory(lf).expect("LF template parses");
        let from_crlf = build_scaffolded_memory(&crlf).expect("CRLF template parses");
        let from_cr = build_scaffolded_memory(&cr).expect("bare-CR template parses");

        assert_eq!(
            from_lf, from_crlf,
            "CRLF input must scaffold identically to LF"
        );
        assert_eq!(
            from_lf, from_cr,
            "bare-CR input must scaffold identically to LF"
        );
        assert!(
            !from_crlf.contains('\r'),
            "scaffolded output must be LF-only regardless of input line endings"
        );
        assert!(from_crlf.contains("scaffoldChecksum: "));

        // A CRLF-on-disk copy of a pristine scaffold still classifies as
        // Pristine — the refresh check is line-ending-agnostic too.
        let crlf_scaffolded = from_lf.replace('\n', "\r\n");
        assert_eq!(
            memory_refresh_disposition(&crlf_scaffolded),
            MemoryDisposition::Pristine,
            "a CRLF copy of a pristine scaffold must still be Pristine"
        );
    }

    // ── STORY-410: existing-project substrate-drift discovery ──────────────

    /// A fresh dir that never scaffolded the pack reports every master member
    /// as Missing — `behind()` equals the full master count and nothing is
    /// up-to-date / edited / user-owned. trace:STORY-410 | ai:claude
    #[test]
    fn drift_empty_dir_reports_all_missing() {
        let dir = tempfile::tempdir().unwrap();
        let mem = dir.path().join("memory"); // does not exist
        let report = compute_memory_drift_into(&mem).unwrap();

        assert!(
            report.rows.len() >= 10,
            "sanity: a populated master pack, got {}",
            report.rows.len()
        );
        assert_eq!(report.missing(), report.rows.len());
        assert_eq!(report.behind(), report.rows.len());
        assert_eq!(report.up_to_date(), 0);
        assert_eq!(report.stale(), 0);
        assert_eq!(report.edited(), 0);
        assert_eq!(report.user_owned(), 0);
    }

    /// A freshly-scaffolded dir is fully up to date: zero drift, every member
    /// matches the master byte-for-byte. trace:STORY-410 | ai:claude
    #[test]
    fn drift_freshly_scaffolded_dir_is_current() {
        let dir = tempfile::tempdir().unwrap();
        let mem = dir.path().join("memory");
        let written = scaffold_memory_pack_into(&mem, false, None).unwrap();
        assert!(written.written >= 10);

        let report = compute_memory_drift_into(&mem).unwrap();
        assert_eq!(report.behind(), 0, "a fresh scaffold must not be behind");
        assert_eq!(report.missing(), 0);
        assert_eq!(report.stale(), 0);
        assert_eq!(
            report.up_to_date(),
            report.rows.len(),
            "every member matches master"
        );
    }

    /// The three drift dispositions are classified correctly: a deleted file
    /// → Missing, a body-edited file → Edited (kept by refresh), an unmarked
    /// user file → UserOwned, a benign-frontmatter-mutated pristine file →
    /// Stale (refresh would overlay it). trace:STORY-410 | ai:claude
    #[test]
    fn drift_classifies_missing_stale_edited_and_user_owned() {
        let dir = tempfile::tempdir().unwrap();
        let mem = dir.path().join("memory");
        scaffold_memory_pack_into(&mem, false, None).unwrap();

        // (a) Missing: delete one scaffolded file.
        let missing = mem.join("feedback_run_help_before_suggesting_flags.md");
        std::fs::remove_file(&missing).unwrap();

        // (b) Edited: change a scaffolded file's body → checksum mismatch.
        let edited = mem.join("feedback_verify_before_filing.md");
        let mut body = std::fs::read_to_string(&edited).unwrap();
        body.push_str("\n\nUSER EDIT.\n");
        std::fs::write(&edited, &body).unwrap();

        // (c) UserOwned: replace a file with an unmarked one.
        let user_owned = mem.join("feedback_goal_prompt_phrasing.md");
        std::fs::write(&user_owned, "---\nname: mine\n---\n\nmine\n").unwrap();

        // (d) Stale: pristine body, but a benign extra frontmatter line makes
        //     the on-disk bytes differ from the current master scaffold.
        let stale = mem.join("feedback_pause_for_design_input.md");
        let stale_v1 =
            std::fs::read_to_string(&stale)
                .unwrap()
                .replacen("---\n", "---\nstaleField: x\n", 1);
        std::fs::write(&stale, &stale_v1).unwrap();

        let report = compute_memory_drift_into(&mem).unwrap();

        let find = |name: &str| {
            report
                .rows
                .iter()
                .find(|r| r.name == name)
                .unwrap_or_else(|| panic!("row {name} present"))
                .state
        };
        assert_eq!(
            find("feedback_run_help_before_suggesting_flags.md"),
            MemoryDriftState::Missing
        );
        assert_eq!(
            find("feedback_verify_before_filing.md"),
            MemoryDriftState::Edited
        );
        assert_eq!(
            find("feedback_goal_prompt_phrasing.md"),
            MemoryDriftState::UserOwned
        );
        assert_eq!(
            find("feedback_pause_for_design_input.md"),
            MemoryDriftState::Stale
        );

        // behind() counts only missing + stale; edited/user-owned are kept.
        assert_eq!(report.missing(), 1);
        assert_eq!(report.stale(), 1);
        assert_eq!(report.edited(), 1);
        assert_eq!(report.user_owned(), 1);
        assert_eq!(report.behind(), 2);
    }

    /// Every drift row carries a label + (usually) a description sourced from
    /// the master template's frontmatter, so the report is human-readable.
    /// trace:STORY-410 | ai:claude
    #[test]
    fn drift_rows_carry_labels_and_descriptions() {
        let dir = tempfile::tempdir().unwrap();
        let mem = dir.path().join("memory"); // empty → all missing
        let report = compute_memory_drift_into(&mem).unwrap();

        // Labels are never empty (fall back to filename).
        assert!(report.rows.iter().all(|r| !r.label.is_empty()));
        // The bundled memories carry descriptions, so most rows have one.
        let with_desc = report
            .rows
            .iter()
            .filter(|r| !r.description.is_empty())
            .count();
        assert!(
            with_desc >= report.rows.len() / 2,
            "expected most rows to carry a description, {with_desc}/{}",
            report.rows.len()
        );
    }
}

/// STORY-127: unit tests for the Scope-B runtime anti-pattern detector
/// predicates. Each predicate is pure over its inputs so the warning
/// conditions are exercised without git/forge/queue I/O.
/// trace:STORY-127 | ai:claude
#[cfg(test)]
mod story_127_antipattern_detectors {
    use super::*;
    use std::collections::HashMap;

    // ── Detector (1): aida pull no-op with a pending review ──────────────
    #[test]
    fn pull_noop_warns_loudly_when_reviewer_lease_on_unmerged_pr() {
        let msg = pull_noop_warning(true, Some("PR-27"))
            .expect("a no-op with a pending review should warn");
        assert!(msg.contains("PR-27"), "warning should name the PR: {msg}");
        assert!(
            msg.to_lowercase().contains("wait"),
            "warning should suggest waiting: {msg}"
        );
    }

    #[test]
    fn pull_noop_quiet_note_when_no_pending_review() {
        let msg = pull_noop_warning(true, None).expect("a no-op still gets a one-liner");
        assert!(
            msg.to_lowercase().contains("up to date"),
            "plain note should say up to date: {msg}"
        );
        // No PR alarm when there's no reviewer lease.
        assert!(!msg.contains("PR-"));
    }

    #[test]
    fn pull_that_advanced_never_warns() {
        assert!(pull_noop_warning(false, Some("PR-27")).is_none());
        assert!(pull_noop_warning(false, None).is_none());
    }

    // ── Detector (2): git pull no-op (local main == origin/main) ─────────
    #[test]
    fn local_main_at_origin_is_true_only_when_shas_match() {
        assert!(local_main_already_at_origin(Some("abc123"), Some("abc123")));
        assert!(!local_main_already_at_origin(
            Some("abc123"),
            Some("def456")
        ));
    }

    #[test]
    fn local_main_at_origin_is_false_when_a_sha_is_unknown_or_empty() {
        assert!(!local_main_already_at_origin(None, Some("abc123")));
        assert!(!local_main_already_at_origin(Some("abc123"), None));
        assert!(!local_main_already_at_origin(None, None));
        assert!(!local_main_already_at_origin(Some(""), Some("")));
    }

    // ── Detector (3): release with unmerged PRs ──────────────────────────
    #[test]
    fn release_warns_for_a_single_unmerged_pr() {
        let msg = release_unmerged_pr_warning(&[27]).expect("one open PR should warn");
        assert!(msg.contains("PR-27"), "should name the PR: {msg}");
        assert!(msg.contains("1 open PR "), "singular phrasing: {msg}");
        assert!(msg.contains(" is "), "singular verb: {msg}");
    }

    #[test]
    fn release_warns_for_multiple_unmerged_prs_sorted_and_deduped() {
        let msg = release_unmerged_pr_warning(&[31, 27, 27, 5]).expect("open PRs should warn");
        // sorted ascending + deduped
        assert!(msg.contains("PR-5, PR-27, PR-31"), "sorted+deduped: {msg}");
        assert!(msg.contains("3 open PRs"), "plural count: {msg}");
        assert!(msg.contains(" are "), "plural verb: {msg}");
    }

    #[test]
    fn release_does_not_warn_with_no_open_prs() {
        assert!(release_unmerged_pr_warning(&[]).is_none());
    }

    // ── Detector (4): session end with cross-role queue waiting ──────────
    fn counts(pairs: &[(&str, usize)]) -> HashMap<String, usize> {
        pairs.iter().map(|(r, c)| (r.to_string(), *c)).collect()
    }

    #[test]
    fn cross_role_lists_other_roles_with_waiting_work() {
        let c = counts(&[("reviewer", 3), ("implementer", 2), ("advisor", 0)]);
        let waiting = cross_role_queue_waiting(Some("reviewer"), &c);
        // reviewer (the ending role) and advisor (zero) excluded; implementer left.
        assert_eq!(waiting, vec![("implementer".to_string(), 2)]);
    }

    #[test]
    fn cross_role_excludes_only_the_ending_role() {
        let c = counts(&[("reviewer", 1), ("implementer", 4)]);
        let waiting = cross_role_queue_waiting(Some("implementer"), &c);
        assert_eq!(waiting, vec![("reviewer".to_string(), 1)]);
    }

    #[test]
    fn cross_role_is_sorted_by_role_name() {
        let c = counts(&[("reviewer", 1), ("advisor", 2)]);
        let waiting = cross_role_queue_waiting(Some("implementer"), &c);
        assert_eq!(
            waiting,
            vec![("advisor".to_string(), 2), ("reviewer".to_string(), 1)]
        );
    }

    #[test]
    fn cross_role_with_unknown_ending_role_includes_all_waiting() {
        let c = counts(&[("reviewer", 1), ("implementer", 2)]);
        let waiting = cross_role_queue_waiting(None, &c);
        assert_eq!(
            waiting,
            vec![("implementer".to_string(), 2), ("reviewer".to_string(), 1)]
        );
    }

    #[test]
    fn session_end_warning_renders_singular_and_plural() {
        let one = session_end_cross_role_warning(&[("reviewer".to_string(), 1)]).unwrap();
        assert!(one.contains("reviewer has 1 item"), "singular: {one}");
        assert!(!one.contains("1 items"));
        let many = session_end_cross_role_warning(&[("implementer".to_string(), 3)]).unwrap();
        assert!(many.contains("implementer has 3 items"), "plural: {many}");
    }

    #[test]
    fn session_end_warning_is_none_when_nothing_waiting() {
        assert!(session_end_cross_role_warning(&[]).is_none());
        let empty = cross_role_queue_waiting(Some("reviewer"), &counts(&[("reviewer", 5)]));
        assert!(session_end_cross_role_warning(&empty).is_none());
    }

    // ── PR-scope parsing for the reviewer-lease query ────────────────────
    #[test]
    fn pr_number_from_scope_parses_pr_and_mr_forms() {
        assert_eq!(pr_number_from_scope("PR-27"), Some(27));
        assert_eq!(pr_number_from_scope("pr-3"), Some(3));
        assert_eq!(pr_number_from_scope("MR-12"), Some(12));
        assert_eq!(pr_number_from_scope(" PR-99 "), Some(99));
        assert_eq!(pr_number_from_scope("STORY-127"), None);
        assert_eq!(pr_number_from_scope("PR-abc"), None);
        assert_eq!(pr_number_from_scope(""), None);
    }
}

// trace:TASK-0414 — opt-in statusline bootstrap.
#[cfg(test)]
mod task_0414_statusline_setup {
    use super::*;

    /// The Claude Code statusLine block uses the same command string the
    /// scaffolder writes (so init-scaffolded and setup-installed config
    /// agree) and contains no bashisms — Claude Code runs it under
    /// /bin/sh (dash).
    #[test]
    fn claude_block_command_is_posix_and_canonical() {
        let block = claude_statusline_block();
        let cmd = block["command"]
            .as_str()
            .expect("command should be a string");
        assert_eq!(cmd, STATUSLINE_SETUP_COMMAND);
        assert_eq!(block["type"], "command");
        // POSIX printf fallback + 2>/dev/null redirect; no bash-only `[[`,
        // `&>`, or `function` keyword.
        assert!(cmd.contains("aida statusline --color=always"));
        assert!(cmd.contains("printf"));
        assert!(!cmd.contains("[["));
        assert!(!cmd.contains("&>"));
    }

    /// Installing into a fresh project creates settings.json with only the
    /// statusLine key, and reports creation.
    #[test]
    fn install_creates_settings_when_absent() {
        let dir = tempfile::tempdir().expect("tempdir");
        let settings = dir.path().join(".claude").join("settings.json");

        let created = install_claude_statusline(&settings).expect("install should succeed");
        assert!(created, "should report file creation");
        assert!(settings.exists());

        let v: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&settings).unwrap()).unwrap();
        assert_eq!(v["statusLine"]["type"], "command");
        assert_eq!(v["statusLine"]["command"], STATUSLINE_SETUP_COMMAND);
    }

    /// Installing into an existing settings.json MERGES the statusLine key
    /// and preserves every pre-existing key (hooks, custom fields, etc.).
    #[test]
    fn install_merges_and_preserves_existing_keys() {
        let dir = tempfile::tempdir().expect("tempdir");
        let claude = dir.path().join(".claude");
        std::fs::create_dir_all(&claude).unwrap();
        let settings = claude.join("settings.json");
        std::fs::write(
            &settings,
            r#"{"hooks": {"PreToolUse": []}, "custom": "keep-me"}"#,
        )
        .unwrap();

        let created = install_claude_statusline(&settings).expect("install should succeed");
        assert!(!created, "should report a merge, not a creation");

        let v: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&settings).unwrap()).unwrap();
        // Pre-existing keys survive.
        assert_eq!(v["custom"], "keep-me");
        assert!(v["hooks"]["PreToolUse"].is_array());
        // statusLine added.
        assert_eq!(v["statusLine"]["command"], STATUSLINE_SETUP_COMMAND);
    }

    /// A corrupt (non-JSON) settings.json is reported, not silently
    /// clobbered — the user's hand-edited file is never overwritten blind.
    #[test]
    fn install_refuses_invalid_json() {
        let dir = tempfile::tempdir().expect("tempdir");
        let claude = dir.path().join(".claude");
        std::fs::create_dir_all(&claude).unwrap();
        let settings = claude.join("settings.json");
        std::fs::write(&settings, "{ not json").unwrap();

        let err = install_claude_statusline(&settings).expect_err("invalid JSON should error");
        assert!(err.to_string().contains("valid JSON"));
        // The original bytes are untouched.
        assert_eq!(std::fs::read_to_string(&settings).unwrap(), "{ not json");
    }

    // trace:TASK-896 — `--title` parity surface for clients (e.g. Codex CLI)
    // whose footer cannot run `aida statusline` as a command.

    /// `osc_terminal_title` wraps the line in `ESC ] 2 ; <text> BEL` so the
    /// AIDA segment lands in the terminal title bar / tmux window name.
    #[test]
    fn osc_title_wraps_in_set_window_title_escape() {
        let out = osc_terminal_title("aida \u{3b1}\u{3b9}\u{3b4}\u{3b1} role:advisor q:4 inbox:43");
        assert!(out.starts_with("\x1b]2;"), "must open with OSC 2: {out:?}");
        assert!(out.ends_with('\x07'), "must terminate with BEL: {out:?}");
        // The payload survives intact between the markers.
        assert!(out.contains("role:advisor q:4 inbox:43"));
        // No trailing newline — a prompt hook updates only the title.
        assert!(!out.ends_with('\n'));
    }

    /// Control chars (newlines, embedded ESC/BEL) are stripped so a crafted
    /// project name can't break out of the OSC string or corrupt the terminal.
    #[test]
    fn osc_title_strips_control_chars() {
        let out = osc_terminal_title("safe\nname\x07\x1b]0;evil\x07tail");
        // Exactly one opening OSC and one closing BEL — no smuggled escapes.
        assert_eq!(
            out.matches('\x07').count(),
            1,
            "only the closing BEL: {out:?}"
        );
        assert_eq!(
            out.matches('\x1b').count(),
            1,
            "only the opening ESC: {out:?}"
        );
        assert!(!out.contains('\n'));
        // Printable text is preserved (concatenated, control chars removed).
        assert!(out.contains("safename"));
        assert!(out.contains("0;eviltail"));
    }
}

/// trace:STORY-582 | ai:claude — durable processing-record audit trail.
#[cfg(test)]
mod story_582_processing_record_tests {
    use super::*;

    #[test]
    fn redact_secrets_collapses_known_token_shapes() {
        let cases = [
            "token is ghp_abcdEFGH1234567890abcdEFGH1234567890",
            "key sk-ABCdef0123456789ABCdef0123456789",
            "aws AKIAIOSFODNN7EXAMPLE here",
            "Authorization: Bearer eyJsupersecretvalue",
            "password=hunter2 in the log",
            "api_key = s3cr3tvalue trailing",
        ];
        for c in cases {
            let out = redact_secrets(c);
            assert!(
                out.contains("[REDACTED]"),
                "expected redaction in {c:?} → {out:?}"
            );
        }
        // A normal sentence + a short SHA is untouched.
        let clean = "Completed via merge a1b2c3d4 after reviewer approved";
        assert_eq!(redact_secrets(clean), clean);
    }

    #[test]
    fn parse_pr_number_from_url_github_and_gitlab() {
        assert_eq!(
            parse_pr_number_from_url("https://github.com/o/r/pull/123#issuecomment-9"),
            Some(123)
        );
        assert_eq!(
            parse_pr_number_from_url("https://gitlab.com/o/r/-/merge_requests/45"),
            Some(45)
        );
        assert_eq!(
            parse_pr_number_from_url("https://github.com/o/r/issues/7"),
            None
        );
        assert_eq!(parse_pr_number_from_url("not a url"), None);
    }

    #[test]
    fn add_processing_record_is_idempotent_on_commit_sha() {
        let mut req = aida_core::Requirement::new("Test".to_string(), "desc".to_string());
        let mut rec = aida_core::ProcessingRecord::new("claude".into(), "did the thing".into());
        rec.commit_sha = Some("deadbeef".into());
        assert!(req.add_processing_record(rec.clone()));
        // Same SHA → not duplicated.
        assert!(!req.add_processing_record(rec.clone()));
        assert_eq!(req.processing_record.len(), 1);
        // A different SHA → appended.
        let mut rec2 = rec.clone();
        rec2.commit_sha = Some("cafef00d".into());
        assert!(req.add_processing_record(rec2));
        assert_eq!(req.processing_record.len(), 2);
        // An empty/None SHA always appends (no idempotency key).
        let rec3 = aida_core::ProcessingRecord::new("claude".into(), "manual".into());
        assert!(req.add_processing_record(rec3.clone()));
        assert!(req.add_processing_record(rec3));
        assert_eq!(req.processing_record.len(), 4);
    }

    #[test]
    fn build_processing_record_falls_back_with_no_artifacts() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        // No brief, no verdict, no punts → agent "aida", summary from sha.
        let rec = build_processing_record(root, "STORY-582", "abcdef1234567890");
        assert_eq!(rec.agent, "aida");
        assert_eq!(rec.commit_sha.as_deref(), Some("abcdef1234567890"));
        assert!(rec.summary.contains("abcdef12"), "{}", rec.summary);
        assert!(rec.brief_ref.is_none());
        assert!(rec.review_verdict.is_none());
    }

    #[test]
    fn build_processing_record_promotes_verdict() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        let vdir = root.join(".aida").join("review-verdicts");
        std::fs::create_dir_all(&vdir).unwrap();
        std::fs::write(
            vdir.join("STORY-582.json"),
            r#"{"verdict":"Approved","summary":"clean diff, good tests","comment_url":"https://github.com/o/r/pull/811#c1"}"#,
        )
        .unwrap();
        let rec = build_processing_record(root, "STORY-582", "abcdef1234567890");
        assert_eq!(rec.review_verdict.as_deref(), Some("Approved"));
        assert_eq!(rec.summary, "clean diff, good tests");
        assert_eq!(rec.pr, Some(811));
    }

    #[test]
    fn latest_brief_for_spec_prefers_newest_and_reads_generated_by() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        let dir = root.join(".aida").join("agent-briefs").join("advisor");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(
            dir.join("STORY-582-20260101T000000Z.md"),
            "---\ngenerated_by: codex\n---\n",
        )
        .unwrap();
        std::fs::write(
            dir.join("STORY-582-20260612T120000Z.md"),
            "---\ngenerated_by: claude\n---\n",
        )
        .unwrap();
        let (rel, agent, gb) = latest_brief_for_spec(root, "STORY-582").unwrap();
        assert!(rel.ends_with("20260612T120000Z.md"), "{rel}");
        assert_eq!(agent, "advisor");
        assert_eq!(gb.as_deref(), Some("claude"));
    }
}

/// BUG-533: `aida config show` effective-policy renderer helpers.
#[cfg(test)]
mod bug_533_config_show_tests {
    use super::*;

    #[test]
    fn config_lookup_finds_nested_key() {
        let cfg: toml::Value = "[telemetry]\nenabled = false\n".parse().unwrap();
        let v = config_lookup(Some(&cfg), "telemetry", "enabled").and_then(|v| v.as_bool());
        assert_eq!(v, Some(false));
    }

    #[test]
    fn config_lookup_absent_section_is_none() {
        let cfg: toml::Value = "[other]\nx = 1\n".parse().unwrap();
        assert!(config_lookup(Some(&cfg), "telemetry", "enabled").is_none());
        assert!(config_lookup(None, "telemetry", "enabled").is_none());
    }

    #[test]
    fn read_project_config_value_missing_file_is_none() {
        let dir = tempfile::tempdir().unwrap();
        assert!(read_project_config_value(dir.path()).is_none());
    }

    #[test]
    fn read_project_config_value_parses_existing() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join(".aida")).unwrap();
        std::fs::write(
            dir.path().join(".aida/config.toml"),
            "[archive]\nauto_after_days = 30\n",
        )
        .unwrap();
        let cfg = read_project_config_value(dir.path()).unwrap();
        let days =
            config_lookup(Some(&cfg), "archive", "auto_after_days").and_then(|v| v.as_integer());
        assert_eq!(days, Some(30));
    }

    #[test]
    fn policy_source_labels_distinct() {
        // Labels carry ANSI color codes; assert the underlying text differs so
        // a default never reads the same as an env override.
        assert_ne!(
            PolicySource::Default.label(),
            PolicySource::ProjectConfig.label()
        );
        assert_ne!(
            PolicySource::ProjectConfig.label(),
            PolicySource::GlobalAgents.label()
        );
        assert!(PolicySource::Env("AIDA_TELEMETRY")
            .label()
            .contains("AIDA_TELEMETRY"));
    }

    // STORY-671 / TASK-793 anti-drift tests: `CONFIG_KNOBS` is the single source
    // of truth. `config show` (via policy_registry), `config menu` (default +
    // explanation + EditKind), and `config edit` validation all derive from it.
    // These assert the live-rendered registry stays in lockstep with the
    // declared knob table, so a knob added in code without a declaration — or a
    // declaration with no resolver — fails CI instead of silently vanishing (the
    // exact failure that produced BUG-533). trace:STORY-671 trace:TASK-793

    /// Every section a [`KnobSpec`] declares must be emitted by
    /// `policy_registry` — i.e. `aida config show` renders a live row for every
    /// declared section. A new section declared in `CONFIG_KNOBS` but with no
    /// resolution branch in the registry trips here.
    #[test]
    fn policy_registry_covers_known_sections() {
        let dir = tempfile::tempdir().unwrap();
        let rendered: std::collections::HashSet<&'static str> = policy_registry(dir.path())
            .iter()
            .map(|s| s.section)
            .collect();
        for section in known_config_sections() {
            assert!(
                rendered.contains(section),
                "config section `[{section}]` is declared in CONFIG_KNOBS but \
                 `policy_registry` does not emit it — add its resolution branch so \
                 `aida config show` renders it (anti-drift, STORY-671)"
            );
        }
    }

    /// The reverse guard: every section the registry emits must be declared in
    /// `CONFIG_KNOBS` (no stray/typo'd section name) AND the two section sets
    /// must be the same size, so neither can quietly drift out of sync. This is
    /// the true auto-discovery: a `[section]` resolved in `policy_registry` with
    /// no `KnobSpec` declaration fails CI.
    #[test]
    fn policy_registry_emits_only_known_sections() {
        let dir = tempfile::tempdir().unwrap();
        let sections = policy_registry(dir.path());
        let known: std::collections::HashSet<&'static str> =
            known_config_sections().into_iter().collect();
        for s in &sections {
            assert!(
                known.contains(s.section),
                "`policy_registry` emits section `[{}]` which is not declared in \
                 CONFIG_KNOBS — add a KnobSpec for it (anti-drift, STORY-671)",
                s.section
            );
        }
        // Each registered section appears exactly once and the counts match, so
        // neither set can carry an entry the other lacks.
        assert_eq!(
            sections.len(),
            known.len(),
            "policy_registry section count != CONFIG_KNOBS section count — \
             the registry and the declared knob table have diverged (STORY-671)"
        );
    }

    /// Every emitted section must carry at least one knob row — an empty section
    /// header in `config show` is a bug (the renderer would print a bare
    /// `[section]` with nothing under it). trace:TASK-793
    #[test]
    fn policy_registry_sections_have_rows() {
        let dir = tempfile::tempdir().unwrap();
        for s in policy_registry(dir.path()) {
            assert!(
                !s.rows.is_empty(),
                "config section `[{}]` rendered no knob rows",
                s.section
            );
        }
    }

    /// Per-knob anti-drift (STORY-671): every concrete row `policy_registry`
    /// renders must resolve to a `KnobSpec` declaration — directly or via the
    /// section wildcard. A knob rendered in `config show` (and therefore offered
    /// in `config menu`) with no declaration would carry no doc/default/edit
    /// metadata, which is exactly the per-knob drift STORY-671 closes.
    #[test]
    fn every_rendered_knob_has_a_declaration() {
        let dir = tempfile::tempdir().unwrap();
        for s in policy_registry(dir.path()) {
            for row in &s.rows {
                assert!(
                    config_knob_spec(s.section, row.key).is_some(),
                    "config knob `[{}] {}` is rendered by policy_registry but has \
                     no KnobSpec declaration — declare it in CONFIG_KNOBS so its \
                     doc/default/edit-kind are not generic placeholders (STORY-671)",
                    s.section,
                    row.key
                );
            }
        }
    }

    /// The formerly-drifted `[field_study] enabled` knob (SPIKE-67) must now
    /// appear in `aida config show` — regression guard for STORY-671 acceptance
    /// criterion 3. It was invisible before because it was never added to the
    /// old hand-maintained lists. trace:STORY-671
    #[test]
    fn field_study_enabled_appears_in_config_show() {
        let dir = tempfile::tempdir().unwrap();
        let found = policy_registry(dir.path())
            .iter()
            .any(|s| s.section == "field_study" && s.rows.iter().any(|r| r.key == "enabled"));
        assert!(
            found,
            "`[field_study] enabled` is declared in CONFIG_KNOBS but not rendered \
             by policy_registry — the SPIKE-67 knob regressed back to invisible \
             (STORY-671 acceptance #3)"
        );
    }

    /// The doc table is now a view over the registry (STORY-671): a declared
    /// knob's `(doc, default)` come straight from its `KnobSpec`, never the
    /// generic fallback. Spot-checks the consolidation kept the framing.
    #[test]
    fn config_knob_doc_derives_from_registry() {
        // A declared knob returns its own doc + default, not the placeholder.
        let (doc, default) = config_knob_doc("telemetry", "enabled");
        assert!(doc.contains("telemetry"), "doc should describe telemetry");
        assert_eq!(default, "enabled");
        // The section wildcard covers a data-driven key.
        let (seats_doc, _) = config_knob_doc("seats", "anything_at_all");
        assert!(seats_doc.contains("seat"), "seats.* wildcard should apply");
        // An undeclared section falls back to the placeholder.
        let (fallback, _) = config_knob_doc("no_such_section", "no_such_key");
        assert_eq!(fallback, "(no description available)");
    }
}

/// STORY-671: the menu/edit surfaces derive their editability from `CONFIG_KNOBS`
/// too — these guards live in a `tui`-gated module so they compile only with the
/// editor present.
#[cfg(all(test, feature = "tui"))]
mod story_671_edit_kind_tests {
    use super::*;

    /// `config_knob_edit_kind` must derive from the registry: every editable
    /// `EditSafety` variant maps to the matching `EditKind`, and read-only /
    /// undeclared knobs map to `ReadOnly`. trace:STORY-671
    #[test]
    fn edit_kind_derives_from_registry() {
        // Bool.
        assert_eq!(
            config_knob_edit_kind("telemetry", "enabled"),
            aida_tui::EditKind::Bool
        );
        // The formerly-drifted field_study knob is editable as a bool now.
        assert_eq!(
            config_knob_edit_kind("field_study", "enabled"),
            aida_tui::EditKind::Bool
        );
        // Enum carries its allowed set.
        assert_eq!(
            config_knob_edit_kind("ultraplan", "mode"),
            aida_tui::EditKind::Enum(vec![
                "never".to_string(),
                "on-demand".to_string(),
                "suggested".to_string(),
            ])
        );
        // Integer carries its range.
        assert_eq!(
            config_knob_edit_kind("archive", "auto_after_days"),
            aida_tui::EditKind::Integer { min: 7, max: 365 }
        );
        // Read-only declarations and undeclared knobs are not editable.
        assert_eq!(
            config_knob_edit_kind("agents", "bypass"),
            aida_tui::EditKind::ReadOnly
        );
        assert_eq!(
            config_knob_edit_kind("contained", "enable"),
            aida_tui::EditKind::ReadOnly
        );
        assert_eq!(
            config_knob_edit_kind("no_such", "knob"),
            aida_tui::EditKind::ReadOnly
        );
    }

    /// `config_knob_meta` (the editor's write-back gate) returns the editable
    /// variants only — a read-only declaration yields `None` so the editor
    /// refuses it, preserving the STORY-669/677 read-only set. trace:STORY-671
    #[test]
    fn config_knob_meta_filters_read_only() {
        assert!(matches!(
            config_knob_meta("telemetry", "enabled"),
            Some(EditSafety::Bool { default: true })
        ));
        assert!(matches!(
            config_knob_meta("archive", "auto_after_days"),
            Some(EditSafety::Integer { min: 7, max: 365 })
        ));
        // The read-only set stays read-only (no live edit).
        assert!(config_knob_meta("agents", "bypass").is_none());
        assert!(config_knob_meta("contained", "os_wrap").is_none());
        assert!(config_knob_meta("ui", "glyphs").is_none());
        assert!(config_knob_meta("seats", "anything").is_none());
    }
}

#[cfg(test)]
mod task_872_read_write_audit_tests {
    use super::*;
    use crate::usage::UsageEvent;

    fn ev(cmd: &str, ts: &str) -> UsageEvent {
        UsageEvent {
            ts: ts.to_string(),
            cmd: cmd.to_string(),
            args_count: 1,
            exit_code: 0,
            duration_ms: 5,
            binary_sha: None,
            role: None,
            scope: None,
        }
    }

    #[test]
    fn tally_counts_reads_writes_and_skips_neither() {
        // trace:TASK-872 | ai:claude
        let since = chrono::DateTime::parse_from_rfc3339("2026-01-01T00:00:00+00:00")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let events = vec![
            ev("list", "2026-02-01T00:00:00+00:00"),
            ev("show", "2026-02-01T00:00:00+00:00"),
            ev("queue list", "2026-02-01T00:00:00+00:00"),
            ev("add", "2026-02-01T00:00:00+00:00"),
            ev("pull", "2026-02-01T00:00:00+00:00"), // NEITHER — excluded
            ev("statusline", "2026-02-01T00:00:00+00:00"), // NEITHER — excluded
        ];
        let tally = tally_read_write(&events, since);
        assert_eq!(tally.reads, 3);
        assert_eq!(tally.writes, 1);
        assert_eq!(tally.ratio(), Some(3.0));
    }

    #[test]
    fn tally_windows_out_old_events() {
        // trace:TASK-872 | ai:claude
        let since = chrono::DateTime::parse_from_rfc3339("2026-06-01T00:00:00+00:00")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let events = vec![
            ev("list", "2026-01-01T00:00:00+00:00"), // before window — dropped
            ev("add", "2026-07-01T00:00:00+00:00"),  // in window
        ];
        let tally = tally_read_write(&events, since);
        assert_eq!(tally.reads, 0);
        assert_eq!(tally.writes, 1);
        assert_eq!(tally.ratio(), Some(0.0));
    }

    #[test]
    fn tally_ratio_is_none_when_no_writes() {
        // trace:TASK-872 | ai:claude
        let since = chrono::DateTime::parse_from_rfc3339("2026-01-01T00:00:00+00:00")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let events = vec![ev("list", "2026-02-01T00:00:00+00:00")];
        let tally = tally_read_write(&events, since);
        assert_eq!(tally.reads, 1);
        assert_eq!(tally.writes, 0);
        assert_eq!(tally.ratio(), None);
    }

    #[test]
    fn tally_empty_log_is_graceful() {
        // trace:TASK-872 | ai:claude
        let since = chrono::Utc::now() - chrono::Duration::days(30);
        let tally = tally_read_write(&[], since);
        assert_eq!(tally.reads, 0);
        assert_eq!(tally.writes, 0);
        assert_eq!(tally.ratio(), None);
    }
}

// BUG-618: lock the `aida queue list --json` shape — the TUI cockpit panel
// parses {spec_id,title,status,for_role}, so the cache-summary resolution must
// keep emitting exactly those keys in queue order. trace:BUG-618 | ai:claude
#[cfg(test)]
mod queue_json_rows_tests {
    use super::*;
    use uuid::Uuid;

    fn summary(
        id: Uuid,
        spec_id: Option<&str>,
        agreed_id: Option<&str>,
    ) -> aida_core::RequirementSummary {
        aida_core::RequirementSummary {
            id,
            spec_id: spec_id.map(|s| s.to_string()),
            agreed_id: agreed_id.map(|s| s.to_string()),
            title: format!("title for {id}"),
            description: String::new(),
            status: "approved".to_string(),
            priority: "medium".to_string(),
            owner: String::new(),
            assignee: None,
            feature: String::new(),
            req_type: "bug".to_string(),
            tags: Vec::new(),
            created_at: String::new(),
            modified_at: String::new(),
            archived: false,
            archived_at: None,
            deferred: false,
            deferred_at: None,
            deferred_until: None,
            in_degree: 0,
            out_degree: 0,
            heft: 0,
            // trace:TASK-902 | ai:claude
            blocked: false,
            yaml_path: String::new(),
        }
    }

    fn entry(requirement_id: Uuid, for_role: Option<&str>) -> aida_core::QueueEntry {
        aida_core::QueueEntry {
            user_id: "u".to_string(),
            requirement_id,
            position: 0,
            added_by: "u".to_string(),
            note: None,
            added_at: chrono::Utc::now(),
            for_role: for_role.map(|s| s.to_string()),
            for_scope: None,
            for_session: None,
            added_by_machine: None,
        }
    }

    #[test]
    fn emits_exact_keys_and_queue_order() {
        let a = Uuid::new_v4();
        let b = Uuid::new_v4();
        let summaries = vec![
            summary(b, Some("BUG-7-002"), None),
            summary(a, Some("BUG-7-001"), Some("BUG-2")),
        ];
        // Queue order is a, then b — the output must follow it, not the
        // summary order.
        let entries = vec![entry(a, Some("implementer")), entry(b, None)];

        let rows = queue_json_rows(&entries, &summaries);
        assert_eq!(rows.len(), 2);

        // Row 0 (entry a): agreed_id wins over spec_id; for_role carried.
        let r0 = &rows[0];
        // Exactly the four keys the TUI cockpit parser expects, no more.
        let mut keys: Vec<&str> = r0.as_object().unwrap().keys().map(|k| k.as_str()).collect();
        keys.sort_unstable();
        assert_eq!(keys, vec!["for_role", "spec_id", "status", "title"]);
        assert_eq!(r0["spec_id"], "BUG-2");
        assert_eq!(r0["title"], format!("title for {a}"));
        assert_eq!(r0["status"], "approved");
        assert_eq!(r0["for_role"], "implementer");

        // Row 1 (entry b): no agreed_id -> spec_id; for_role null.
        let r1 = &rows[1];
        assert_eq!(r1["spec_id"], "BUG-7-002");
        assert!(r1["for_role"].is_null());
    }

    #[test]
    fn drops_entries_with_no_matching_summary() {
        let known = Uuid::new_v4();
        let orphan = Uuid::new_v4();
        let summaries = vec![summary(known, Some("BUG-9-001"), None)];
        let entries = vec![entry(orphan, None), entry(known, None)];

        let rows = queue_json_rows(&entries, &summaries);
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0]["spec_id"], "BUG-9-001");
    }

    #[test]
    fn missing_both_ids_falls_back_to_question_mark() {
        let id = Uuid::new_v4();
        let summaries = vec![summary(id, None, None)];
        let rows = queue_json_rows(&[entry(id, None)], &summaries);
        assert_eq!(rows[0]["spec_id"], "?");
    }
}

#[cfg(test)]
mod merge_contiguous_blocks_tests {
    use super::*;

    fn block(
        node: &str,
        owner: &str,
        ty: &str,
        start: u32,
        end: u32,
        next: u32,
    ) -> aida_core::AgreedIdBlock {
        aida_core::AgreedIdBlock {
            node_id: node.to_string(),
            owner: owner.to_string(),
            hostname: "host".to_string(),
            type_prefix: ty.to_string(),
            range_start: start,
            range_end: end,
            next,
            allocated_at: chrono::Utc::now(),
        }
    }

    // Contiguous same-node/type/owner blocks fold into ONE row spanning the
    // full start..end; the live frontier supplies next/remaining.
    // trace:TASK-950 | ai:claude
    #[test]
    fn contiguous_blocks_merge_into_one_row() {
        // Mirrors the live store: node 1 BUG 317..916 across four exhausted
        // sub-blocks plus a live tail (next 632, remaining 285).
        let blocks = vec![
            block("1", "joe", "BUG", 317, 416, 417), // exhausted
            block("1", "joe", "BUG", 417, 516, 517), // exhausted
            block("1", "joe", "BUG", 517, 616, 617), // exhausted
            block("1", "joe", "BUG", 617, 916, 632), // live frontier
        ];
        let rows = merge_contiguous_blocks(&blocks);
        assert_eq!(rows.len(), 1);
        let r = &rows[0];
        assert_eq!(r.range_start, 317);
        assert_eq!(r.range_end, 916);
        assert_eq!(r.next, 632);
        assert_eq!(r.remaining, 285);
    }

    // A gap in the range starts a new row.
    // trace:TASK-950 | ai:claude
    #[test]
    fn non_contiguous_blocks_stay_separate() {
        // node 1 BUG 17..116 then 317..916 — gap 117..316 keeps them apart.
        let blocks = vec![
            block("1", "joe", "BUG", 17, 116, 117), // exhausted, isolated
            block("1", "joe", "BUG", 317, 416, 417),
            block("1", "joe", "BUG", 417, 916, 632),
        ];
        let rows = merge_contiguous_blocks(&blocks);
        assert_eq!(rows.len(), 2);
        assert_eq!((rows[0].range_start, rows[0].range_end), (17, 116));
        assert_eq!((rows[1].range_start, rows[1].range_end), (317, 916));
    }

    // Different owner / type / node never merge even when ranges touch.
    // trace:TASK-950 | ai:claude
    #[test]
    fn different_owner_type_or_node_do_not_merge() {
        let blocks = vec![
            // Same node+type, contiguous range, but DIFFERENT owner.
            block("1", "alice", "BUG", 1, 100, 50),
            block("1", "bob", "BUG", 101, 200, 150),
            // Same node+owner, contiguous range, but DIFFERENT type.
            block("2", "joe", "FR", 1, 100, 50),
            block("2", "joe", "TASK", 101, 200, 150),
            // Same owner+type, contiguous range, but DIFFERENT node.
            block("3", "joe", "EPIC", 1, 100, 50),
            block("4", "joe", "EPIC", 101, 200, 150),
        ];
        let rows = merge_contiguous_blocks(&blocks);
        // None of the three pairs may collapse.
        assert_eq!(rows.len(), 6);
    }

    // All sub-blocks exhausted => row is "full" (remaining 0); a live
    // frontier in the run => remaining from that frontier.
    // trace:TASK-950 | ai:claude
    #[test]
    fn full_vs_live_frontier_remaining() {
        // Every sub-block exhausted (next > range_end) -> full.
        let all_exhausted = vec![
            block("1", "joe", "TASK", 1, 100, 101),
            block("1", "joe", "TASK", 101, 200, 201),
        ];
        let rows = merge_contiguous_blocks(&all_exhausted);
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].remaining, 0, "all-exhausted run renders as full");
        assert_eq!(rows[0].range_end, 200);

        // First sub-block live -> frontier is the first, not the last.
        let live_front = vec![
            block("1", "joe", "STORY", 1, 100, 40), // live: remaining 61
            block("1", "joe", "STORY", 101, 200, 201), // exhausted
        ];
        let rows = merge_contiguous_blocks(&live_front);
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].next, 40);
        assert_eq!(rows[0].remaining, 61);
    }
}

// trace:STORY-716 | ai:claude
#[cfg(test)]
mod worktree_handler_tests {
    use super::*;

    fn git(path: &std::path::Path, args: &[&str]) {
        let out = std::process::Command::new("git")
            .arg("-C")
            .arg(path)
            .args(args)
            .output()
            .unwrap_or_else(|e| panic!("git {:?} failed to spawn: {e}", args));
        assert!(
            out.status.success(),
            "git {:?} failed\nstdout:\n{}\nstderr:\n{}",
            args,
            String::from_utf8_lossy(&out.stdout),
            String::from_utf8_lossy(&out.stderr)
        );
    }

    fn init_main_repo(path: &std::path::Path) {
        git(path, &["init", "-b", "main", "--quiet"]);
        git(path, &["config", "user.email", "aida@example.test"]);
        git(path, &["config", "user.name", "AIDA Test"]);
        git(path, &["commit", "--allow-empty", "-m", "base", "--quiet"]);
    }

    // The single shell line `worktree enter` emits — `cd '<escaped>'` — is the
    // contract the `aida()` wrapper auto-evals; assert its exact shape.
    #[test]
    fn enter_cd_line_is_single_quoted_cd() {
        let line = enter_cd_line(std::path::Path::new("/home/joe/ai/aida-epic54"));
        assert_eq!(line, "cd '/home/joe/ai/aida-epic54'");
    }

    #[test]
    fn enter_cd_line_escapes_apostrophes() {
        let line = enter_cd_line(std::path::Path::new("/tmp/o'brien/aida-epic1"));
        // The path's apostrophe must be escaped so the eval'd `cd` is one word.
        assert_eq!(line, "cd '/tmp/o'\\''brien/aida-epic1'");
    }

    #[test]
    fn add_creates_worktree_with_focus_then_is_idempotent() {
        let repo = tempfile::tempdir().unwrap();
        let home = tempfile::tempdir().unwrap();
        init_main_repo(repo.path());

        // First add: creates the worktree, branch, and focus marker.
        let out = ensure_epic_worktree_core(repo.path(), home.path(), "EPIC-54", None, None)
            .expect("first add succeeds");
        assert!(out.created, "first add reports created");
        assert_eq!(out.branch, "epic-54-work");
        assert_eq!(out.focus, "EPIC-54");
        assert_eq!(out.path, home.path().join("ai").join("aida-epic54"));
        assert!(out.path.exists(), "worktree dir exists");

        // Focus marker written INSIDE the new worktree.
        let focus = crate::focus::read_focus_marker(&out.path);
        assert_eq!(focus.as_deref(), Some("EPIC-54"));

        // The new worktree is on the derived branch.
        let head = std::process::Command::new("git")
            .arg("-C")
            .arg(&out.path)
            .args(["rev-parse", "--abbrev-ref", "HEAD"])
            .output()
            .unwrap();
        assert_eq!(String::from_utf8_lossy(&head.stdout).trim(), "epic-54-work");

        // Second add: idempotent — reports already-exists, focus re-affirmed.
        let again = ensure_epic_worktree_core(repo.path(), home.path(), "EPIC-54", None, None)
            .expect("second add succeeds");
        assert!(!again.created, "re-run reports not-created");
        assert_eq!(again.path, out.path);
        assert_eq!(
            crate::focus::read_focus_marker(&again.path).as_deref(),
            Some("EPIC-54")
        );
    }

    #[test]
    fn add_honors_path_and_branch_overrides() {
        let repo = tempfile::tempdir().unwrap();
        let home = tempfile::tempdir().unwrap();
        init_main_repo(repo.path());
        let custom = home.path().join("custom-tree");

        let out = ensure_epic_worktree_core(
            repo.path(),
            home.path(),
            "epic-7",
            Some(custom.to_str().unwrap()),
            Some("my-branch"),
        )
        .expect("override add succeeds");
        assert!(out.created);
        assert_eq!(out.path, custom);
        assert_eq!(out.branch, "my-branch");
        assert_eq!(out.focus, "EPIC-7");
        assert_eq!(
            crate::focus::read_focus_marker(&out.path).as_deref(),
            Some("EPIC-7")
        );
    }

    #[test]
    fn list_branches_parse_pairs_path_to_short_branch() {
        let porcelain = "\
worktree /home/joe/ai/aida
HEAD aaa
branch refs/heads/main

worktree /home/joe/ai/aida-epic54
HEAD bbb
branch refs/heads/epic-54-work

worktree /home/joe/ai/aida-detached
HEAD ccc
detached
";
        let map = parse_worktree_branches(porcelain);
        assert_eq!(
            map.get(std::path::Path::new("/home/joe/ai/aida"))
                .map(String::as_str),
            Some("main")
        );
        assert_eq!(
            map.get(std::path::Path::new("/home/joe/ai/aida-epic54"))
                .map(String::as_str),
            Some("epic-54-work")
        );
        // The detached worktree has no branch line → absent from the map.
        assert!(!map.contains_key(std::path::Path::new("/home/joe/ai/aida-detached")));
    }
}
